window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["财政部"] = {"guoyouzichanpingguweifaxingweichufabanfa":[{"i":1,"n":"第一条","txt":"为规范国有资产评估行为，加强国有资产评估管理，保障国有 资产权益，维护社会公共利益，根据《国有资产评估管理办法》、《国务院办公厅转发财政部<关于改革国有资产评估行政管理方式加强资产评估监督管理工作意见>的通知》（国办发[2001）102号）及其他有关法律、行政法规 的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"资产评估机构在国有资产评估活动中违反有关管律、法规和规章，应予行政处罚的，适用本办法。"},{"i":3,"n":"第三条","txt":"省级人民政府财政部门（国有资产管理部门，下同）负责对本 地区资产评估机构（包括设在本地区的资产评估分支机构）的违法行为实施处罚。 对严重评估违法行为，国务院财政部门可以直接进行处罚。"},{"i":4,"n":"第四条","txt":"资产评估机构违法行为的处罚种类： （一）警告； （二）罚款； （三）没收违法所得； （四）暂停执行部分或者全部业务，暂停执业的期限为三至十二个月； （五）吊销资产评估资格证书。"},{"i":5,"n":"第五条","txt":"资产评估机构与委托人或被评估单位串通作弊，故意出具虚假 报告的，没收违法所得，处以违法所得一倍以上五倍以下的罚款，并予以暂停执业；给利害关系人造成重大经济损失或者产生恶劣社会影响的，吊销资产评估资格证书。 笫六条　资产评估机构因过失出具有重大遗漏的报告的，责令改正，情 节较重的，处以所得收入一倍以上三倍以下的罚款，并予以暂停执业；"},{"i":6,"n":"第七条","txt":"资产评估机构冒用其他机构名义或者允许其他机构以本机构名 义执行评估业务的，责令改正，予以警告。"},{"i":7,"n":"第八条","txt":"资产评估机构向委托人或者被评估单位索取、收受业务约定书 约定以外的酬金或者其他财物，或者利用业务之便，谋取其他不正当利益的，责令改正，予以警告。"},{"i":8,"n":"第九条","txt":"资产评估机构有下列情形之一的；责令改正，并予以警告： （一）对其能力进行虚假广告宣传的； （二）向有关单位和个人支付回扣或者介绍费的； （三）对委托人、被评估单位或者其他单位和个人进行胁迫、欺诈、利诱的； （四）恶意降低收费的。"},{"i":9,"n":"第十条","txt":"资产评估机构与委托人或者被评估单位存在利害关系应当回避 没有回避的，责令改正，并予以警告。"},{"i":10,"n":"第十一条","txt":"资产评估机构泄露委托人或者被评估单位商业秘密的，予以 警告。"},{"i":11,"n":"第十二条","txt":"本办法第七条至十一条所列情形，有违法所得的，处以违法 所得三倍以下的罚款，但最高不得超过三万元；没有违法所得的，处以一万元以下的罚款。 笫十三条　资产评估机构不按照执业准则、职业道德准则的要求执业 的；予以警告。"},{"i":12,"n":"第十四条","txt":"资产评估机构拒绝、阻挠财政部门依法实施检查的，予以警告；"},{"i":13,"n":"第十五条","txt":"资产评估机构有下列情形之一的；，应当从轻、减轻处罚： （一）主动改正违法行为或主动消除、减轻违法行为危害后果的； （二）主动向有关部门报告其违法行为的； （三）主动配合查处违法行为的； （四）受他人胁迫有违法行为的； （五）其他应予从轻、减轻处罚的情形。"},{"i":14,"n":"第十六条","txt":"资产评估机构有下列情形之一的，应当从重处罚： （一）同时具有两种或两种以上应予处罚的行为的； （二）在两年内发生两次或两次以上同一性质的应予处罚的行为的； （三）对投诉人、举报人、证人等进行威胁、报复的； （四）违法行为发生后隐匿、销毁证据材料的； （五）其他应予从重处罚的情形。"},{"i":15,"n":"第十七条","txt":"省级人民政府财政部门作出本办法第四条第（二）至第 （五）项处罚决定的，应当在作出处罚决定之日起15日内报送国务院财政部门备案。"},{"i":16,"n":"第十八条","txt":"省级以上人民政府财政部门作出行政处罚决定之前，应当告 知资产评估机构作出行政处罚决定的事实、理由及依据，并告知当事人依法享有的权利；作出较大数额罚款、暂停执业和吊销资产评估资格证书的处罚决定之前，应当告知资产评估机 构有要求举行听证的权利。"},{"i":17,"n":"第十九条","txt":"资产评估机构要求听证的，拟作出行政处罚的省级以上人民政府财政部门应当按照《财政部门行政处罚听证程序实施办法》的有关规定组织听证。"},{"i":18,"n":"第二十条","txt":"资产评估机构对处罚决定不服的，可以依法申请行政复议或提起行政诉讼。"},{"i":19,"n":"第二十一条","txt":"注册资产评估师在国有资产评估中有违法行为的，按照有关规定处理。"},{"i":20,"n":"第二十二条","txt":"本办法自2002年1月1日起施行。"}],"zhongguoqingjiefazhanjizhijijinguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强和规范中国清洁发展机制基金（以下简称基金）的资金筹集、管理和使用，实现基金宗旨，制定本办法。"},{"i":2,"n":"第二条","txt":"基金是由国家批准设立的政策性基金，按照市场化模式进行运作。"},{"i":3,"n":"第三条","txt":"基金的宗旨是支持国家碳达峰碳中和、应对气候变化、污染防治和生态保护等绿色低碳领域活动，促进经济社会高质量发展。"},{"i":4,"n":"第四条","txt":"基金的筹集、管理和使用，应当遵循公开公正、安全规范、专款专用、注重绩效的原则。"},{"i":5,"n":"第五条","txt":"基金的组织架构由基金政策指导委员会和基金管理中心组成。"},{"i":6,"n":"第六条","txt":"基金政策指导委员会是基金事务的部际议事机构，负责对基金进行政策指导。 基金政策指导委员会由财政部、生态环境部、发展改革委、外交部、科技部、农业农村部和气象局的代表组成。 基金政策指导委员会设联合主席，由财政部、生态环境部和发展改革委的代表担任，负责召集和主持基金政策指导委员会会议。 基金政策指导委员会下设秘书处，由基金管理中心承担具体工作。"},{"i":7,"n":"第七条","txt":"基金政策指导委员会履行下列职责: （一）对制定基金基本管理制度提出指导意见； （二）对基金发展方向、中长期发展战略和业务发展给予政策性指导； （三）对基金赠款、有偿使用等的支持方向以及其他政策提出指导意见； （四）对影响基金发展的其他重大事项提出指导意见。"},{"i":8,"n":"第八条","txt":"基金管理中心是基金的管理机构，具体负责基金的筹集、管理和使用工作，由财政部归口管理。"},{"i":9,"n":"第九条","txt":"基金管理中心履行下列职责： （一）起草基金基本管理制度，制定基金具体运行管理规定； （二）筹集和管理基金资金； （三）组织开展基金赠款和有偿使用等业务； （四）对基金赠款和有偿使用等项目进行监督管理； （五）向基金政策指导委员会报告基金年度业务计划及其开展情况，以及其他重大事项； （六）履行基金政策指导委员会秘书处职责； （七）开展其他符合基金宗旨的活动。"},{"i":10,"n":"第十条","txt":"基金来源包括： （一）通过清洁发展机制项目转让温室气体减排量所获得收入中属于国家所有的部分； （二）基金运营收入； （三）国内外机构、组织和个人捐赠； （四）其他来源。"},{"i":11,"n":"第十一条","txt":"本办法所称减排量，是指经国家批准，通过清洁发展机制项目转让的温室气体减排量；减排量收入，是指转让减排量所获得的收入。 减排量收入由国家和实施清洁发展机制项目的企业按照规定的比例分别所有。减排量收入中属于国家所有的部分全额纳入基金。"},{"i":12,"n":"第十二条","txt":"本办法所称基金运营收入，是指在本办法规定的使用范围内，基金开展有偿使用等所获得的收入。"},{"i":13,"n":"第十三条","txt":"基金使用应当以保本微利、实现可持续发展为原则，采取赠款、有偿使用等方式。"},{"i":14,"n":"第十四条","txt":"基金通过安排一定规模赠款支持以下项目活动： （一）与碳达峰碳中和、应对气候变化相关的政策研究和学术活动； （二）与碳达峰碳中和、应对气候变化相关的国际合作和交流活动； （三）旨在加强碳达峰碳中和、应对气候变化能力建设的培训活动； （四）旨在提高公众碳达峰碳中和、应对气候变化意识的宣传和教育活动； （五）符合基金宗旨的其他项目。 基金赠款年度支出规模根据基金上年度收益情况和国家碳达峰碳中和、应对气候变化实际工作需要确定。"},{"i":15,"n":"第十五条","txt":"基金赠款项目申报单位应当是与碳达峰碳中和、应对气候变化工作相关的省级以上人民政府有关部门。省级生态环境部门负责地方赠款项目的组织申报工作。"},{"i":16,"n":"第十六条","txt":"基金赠款项目的申报、评审、管理和考核验收等应当按照基金赠款项目管理有关规定进行。 基金赠款项目管理办法由生态环境部、财政部另行制定。生态环境部据此牵头编制年度赠款项目指南。"},{"i":17,"n":"第十七条","txt":"基金通过有偿使用方式支持以下项目活动： （一）有利于实现碳达峰碳中和、产生应对气候变化效益的项目活动； （二）落实国家有关污染防治和生态保护重大决策部署的项目活动； （三）符合基金宗旨的其他项目活动。"},{"i":18,"n":"第十八条","txt":"基金有偿使用主要采取以下方式： （一）债权投资； （二）股权投资； （三）融资性担保； （四）符合国家规定的其他方式。"},{"i":19,"n":"第十九条","txt":"基金有偿使用依托专业机构开展，实行专业化管理。 基金有偿使用形成的各种资产和权益应当按照国家有关财务等规章制度进行管理。"},{"i":20,"n":"第二十条","txt":"基金有偿使用的组织与开展应当按照财政部有关基金有偿使用管理规定执行。"},{"i":21,"n":"第二十一条","txt":"基金支出包括赠款支出和基础管理费支出。 前款所称基础管理费支出，是指基金筹集、管理、使用过程中的相关费用，包括基金管理中心日常管理费、基金业务发展费以及其他费用。"},{"i":22,"n":"第二十二条","txt":"基金管理中心应当公开以下信息： （一）基金有关政策文件； （二）基金赠款项目的申报流程以及所需提供的材料清单； （三）基金赠款、有偿使用等业务开展情况，但涉及国家秘密、商业秘密的除外； （四）法律、法规规定应当公开的其他信息。"},{"i":23,"n":"第二十三条","txt":"基金与基金管理中心应当分别建账、分别核算，并按照财政部有关基金财务管理的规定加强监督管理，提高资金使用绩效，保障资金安全。"},{"i":24,"n":"第二十四条","txt":"基金管理中心应当加强对基金使用的风险管理，及时识别、分析、评价和处理相关风险。 基金不得用于不符合其宗旨的赞助和捐赠支出，不得从事房地产、股票、股票型证券投资基金以及期货等高风险金融衍生产品投资。"},{"i":25,"n":"第二十五条","txt":"财政部、生态环境部应当按照职责分工加强对基金有偿使用情况、赠款项目开展情况和会计资料等的监督检查，全链条规范基金运行管理。 基金管理中心应当会同有关单位对基金资金使用情况和产出成果进行监督和管理，并及时向基金政策指导委员会报告相关情况。"},{"i":26,"n":"第二十六条","txt":"基金及其管理中心应当接受国家审计机关依法实施的审计监督。"},{"i":27,"n":"第二十七条","txt":"基金管理中心应当聘请社会审计机构对基金收支规模、基金结余、基金运行情况以及基金管理中心的支出情况等进行审计。"},{"i":28,"n":"第二十八条","txt":"基金管理单位及其工作人员在基金赠款项目和有偿使用项目管理以及其他重大业务中，有违反本办法规定的行为，以及滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，依法依规追究相应责任；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"基金使用单位及其工作人员有违反本办法规定的基金使用行为的，应当由有关主管部门责令改正，依法依规追究相应责任；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本办法由财政部、生态环境部、发展改革委、外交部、科技部、农业农村部和气象局负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2022年8月1日起施行。2010年9月14日公布的《中国清洁发展机制基金管理办法》（财政部 国家发展改革委 外交部 科技部 环境保护部 农业部 中国气象局令第59号）同时废止。"}],"zhongwaihezuojingyingqiyewaiguohezuozhexianxinghui8fdb61":[{"i":1,"n":"第一条","txt":"为规范中外合作经营企业外国合作者先行回收投资（以下简称“先行回收投资”）的审批工作，根据《中华人民共和国中外合作经营企业法》、《中华人民共和国行政许可法》以及《中华人民共和国中外合作经营企业法实施细则》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立的中外合作经营企业外国合作者先行回收投资的相关事项适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称的先行回收投资，是指中外合作经营企业（以下简称“合作企业”）中的外国合作者按照法律规定以及合同的约定，以分取固定资产折旧、无形资产摊销等形成的资金以及其他方式，在合作期限内先行回收其投资的行为。"},{"i":4,"n":"第四条","txt":"合作企业申请先行回收投资应当符合下列条件： （一）中外合作者在合作企业合同中约定合作期满时，企业清算后的全部固定资产无偿归中国合作者所有； （二）合作企业出具承诺函承诺债务的偿付优先于投资的先行回收； （三）先行回收投资的外国合作者出具承诺函承诺在先行回收投资的范围内对合作企业的债务承担连带责任； （四）合作企业依据法律及合同约定出资到位； （五）合作企业经营和财务状况良好，没有未弥补亏损。"},{"i":5,"n":"第五条","txt":"先行回收投资的审批机构为企业所在地的省、自治区、直辖市及计划单列市的财政机关（以下简称“财政机关”）。"},{"i":6,"n":"第六条","txt":"合作企业申请先行回收投资的，应当向财政机关报送以下材料： （一）合作企业申请函，具体说明先行回收投资的总额、期限和方式； （二）外商投资企业批准证书、工商营业执照（原件、副本）及复印件； （三）合作企业合同和章程的复印件； （四）中国注册会计师出具的合作企业验资报告； （五）合作企业董事会或者联合管理机构关于本期先行回收投资方案的决议、合作企业拟进行回收投资当期经依法审计的财务会计报告、合作企业到期债务说明、合作企业及外国合作者债务承诺函等。"},{"i":7,"n":"第七条","txt":"财政机关应当对申请的合作企业报送的材料进行审查，对材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知申请人需要补正的全部材料和内容，逾期不告知的，自收到材料之日起即为受理。"},{"i":8,"n":"第八条","txt":"对报送材料齐全、符合法定形式，或者申请的合作企业按照要求提交全部补正材料的应当受理。 财政机关受理申请或者不予受理申请，应当向申请的合作企业出具加盖本财政机关专用印章和注明日期的书面凭证。"},{"i":9,"n":"第九条","txt":"财政机关应当在受理合作企业申请之日起二十日内作出审批决定。二十日内不能作出决定的，经财政机关负责人批准，可以适当延长，但最长不得超过十日，并将延长期限的理由告知申请的合作企业。 财政机关批准后，应将其批复及合作企业和外国投资者报送的承诺函抄送同级商务及外汇主管部门。"},{"i":10,"n":"第十条","txt":"合作企业的申请符合法定条件、标准的，财政机关应当依法作出准予先行回收投资的书面决定。 财政机关依法作出不予行政许可的书面决定的，应当说明理由，并告知申请的合作企业享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":11,"n":"第十一条","txt":"财政机关及其工作人员不依法履行职责的，按《中华人民共和国行政许可法》第七十二条、第七十三条和第七十四条及有关法律法规的规定，承担法律责任。"},{"i":12,"n":"第十二条","txt":"合作企业隐瞒有关情况或者提供虚假材料申请先行回收投资的，财政机关不予受理或者不予批准，并给予警告。"},{"i":13,"n":"第十三条","txt":"合作企业以欺骗、贿赂等不正当手段取得先行回收投资许可的，财政机关应当依法撤销其审批决定并给予行政处罚。"},{"i":14,"n":"第十四条","txt":"申请的合作企业对于财政机关不予受理、不予行政许可或行政处罚的决定有异议的，可以依法申请行政复议或者提起行政诉讼。"},{"i":15,"n":"第十五条","txt":"中国香港特别行政区、澳门特别行政区、台湾地区的公司、企业和其他经济组织或者个人以及在国外居住的中国公民举办合作企业先行回收投资的，参照本办法办理。"},{"i":16,"n":"第十六条","txt":"本办法自2005年9月1日起施行。"}],"shiyedanweikuaijizhunze":[{"i":1,"n":"第一条","txt":"为了规范事业单位的会计核算，保证会计信息质量，促进公益事业健康发展，根据《中华人民共和国会计法》等有关法律、行政法规，制定本准则。"},{"i":2,"n":"第二条","txt":"本准则适用于各级各类事业单位。"},{"i":3,"n":"第三条","txt":"事业单位会计制度、行业事业单位会计制度（以下统称会计制度）等，由财政部根据本准则制定。"},{"i":4,"n":"第四条","txt":"事业单位会计核算的目标是向会计信息使用者提供与事业单位财务状况、事业成果、预算执行等有关的会计信息，反映事业单位受托责任的履行情况，有助于会计信息使用者进行社会管理、作出经济决策。 事业单位会计信息使用者包括政府及其有关部门、举办（上级）单位、债权人、事业单位自身和其他利益相关者。"},{"i":5,"n":"第五条","txt":"事业单位应当对其自身发生的经济业务或者事项进行会计核算。"},{"i":6,"n":"第六条","txt":"事业单位会计核算应当以事业单位各项业务活动持续正常地进行为前提。"},{"i":7,"n":"第七条","txt":"事业单位应当划分会计期间，分期结算账目和编制财务会计报告（又称财务报告，下同）。 会计期间至少分为年度和月度。会计年度、月度等会计期间的起讫日期采用公历日期。"},{"i":8,"n":"第八条","txt":"事业单位会计核算应当以人民币作为记账本位币。发生外币业务时，应当将有关外币金额折算为人民币金额计量。"},{"i":9,"n":"第九条","txt":"事业单位会计核算一般采用收付实现制；部分经济业务或者事项采用权责发生制核算的，由财政部在会计制度中具体规定。 行业事业单位的会计核算采用权责发生制的，由财政部在相关会计制度中规定。"},{"i":10,"n":"第十条","txt":"事业单位会计要素包括资产、负债、净资产、收入、支出或者费用。"},{"i":11,"n":"第十一条","txt":"事业单位应当采用借贷记账法记账。"},{"i":12,"n":"第十二条","txt":"事业单位应当以实际发生的经济业务或者事项为依据进行会计核算，如实反映各项会计要素的情况和结果，保证会计信息真实可靠。"},{"i":13,"n":"第十三条","txt":"事业单位应当将发生的各项经济业务或者事项统一纳入会计核算，确保会计信息能够全面反映事业单位的财务状况、事业成果、预算执行等情况。"},{"i":14,"n":"第十四条","txt":"事业单位对于已经发生的经济业务或者事项，应当及时进行会计核算，不得提前或者延后。"},{"i":15,"n":"第十五条","txt":"事业单位提供的会计信息应当具有可比性。 同一事业单位不同时期发生的相同或者相似的经济业务或者事项，应当采用一致的会计政策，不得随意变更。确需变更的，应当将变更的内容、理由和对单位财务状况及事业成果的影响在附注中予以说明。 同类事业单位中不同单位发生的相同或者相似的经济业务或者事项，应当采用统一的会计政策，确保同类单位会计信息口径一致，相互可比。"},{"i":16,"n":"第十六条","txt":"事业单位提供的会计信息应当与事业单位受托责任履行情况的反映、会计信息使用者的管理、决策需要相关，有助于会计信息使用者对事业单位过去、现在或者未来的情况作出评价或者预测。"},{"i":17,"n":"第十七条","txt":"事业单位提供的会计信息应当清晰明了，便于会计信息使用者理解和使用。"},{"i":18,"n":"第十八条","txt":"资产是指事业单位占有或者使用的能以货币计量的经济资源，包括各种财产、债权和其他权利。"},{"i":19,"n":"第十九条","txt":"事业单位的资产按照流动性，分为流动资产和非流动资产。 流动资产是指预计在1年内（含1年）变现或者耗用的资产。 非流动资产是指流动资产以外的资产。"},{"i":20,"n":"第二十条","txt":"事业单位的流动资产包括货币资金、短期投资、应收及预付款项、存货等。 货币资金包括库存现金、银行存款、零余额账户用款额度等。 短期投资是指事业单位依法取得的，持有时间不超过1年（含1年）的投资。 应收及预付款项是指事业单位在开展业务活动中形成的各项债权，包括财政应返还额度、应收票据、应收账款、其他应收款等应收款项和预付账款。 存货是指事业单位在开展业务活动及其他活动中为耗用而储存的资产，包括材料、燃料、包装物和低值易耗品等。"},{"i":21,"n":"第二十一条","txt":"事业单位的非流动资产包括长期投资、在建工程、固定资产、无形资产等。 长期投资是指事业单位依法取得的，持有时间超过1年（不含1年）的各种股权和债权性质的投资。 在建工程是指事业单位已经发生必要支出，但尚未完工交付使用的各种建筑（包括新建、改建、扩建、修缮等）和设备安装工程。 固定资产是指事业单位持有的使用期限超过1年（不含1年），单位价值在规定标准以上，并在使用过程中基本保持原有物质形态的资产，包括房屋及构筑物、专用设备、通用设备等。单位价值虽未达到规定标准，但是耐用时间超过1年（不含1年）的大批同类物资，应当作为固定资产核算。 无形资产是指事业单位持有的没有实物形态的可辨认非货币性资产，包括专利权、商标权、著作权、土地使用权、非专利技术等。"},{"i":22,"n":"第二十二条","txt":"事业单位的资产应当按照取得时的实际成本进行计量。除国家另有规定外，事业单位不得自行调整其账面价值。 应收及预付款项应当按照实际发生额计量。 以支付对价方式取得的资产，应当按照取得资产时支付的现金或者现金等价物的金额，或者按照取得资产时所付出的非货币性资产的评估价值等金额计量。 取得资产时没有支付对价的，其计量金额应当按照有关凭据注明的金额加上相关税费、运输费等确定；没有相关凭据的，其计量金额比照同类或类似资产的市场价格加上相关税费、运输费等确定；没有相关凭据、同类或类似资产的市场价格也无法可靠取得的，所取得的资产应当按照名义金额入账。"},{"i":23,"n":"第二十三条","txt":"事业单位对固定资产计提折旧、对无形资产进行摊销的，由财政部在相关财务会计制度中规定。"},{"i":24,"n":"第二十四条","txt":"负债是指事业单位所承担的能以货币计量，需要以资产或者劳务偿还的债务。"},{"i":25,"n":"第二十五条","txt":"事业单位的负债按照流动性，分为流动负债和非流动负债。 流动负债是指预计在1年内（含1年）偿还的负债。 非流动负债是指流动负债以外的负债。"},{"i":26,"n":"第二十六条","txt":"事业单位的流动负债包括短期借款、应付及预收款项、应付职工薪酬、应缴款项等。 短期借款是指事业单位借入的期限在1年内（含1年）的各种借款。 应付及预收款项是指事业单位在开展业务活动中发生的各项债务，包括应付票据、应付账款、其他应付款等应付款项和预收账款。 应付职工薪酬是指事业单位应付未付的职工工资、津贴补贴等。 应缴款项是指事业单位应缴未缴的各种款项，包括应当上缴国库或者财政专户的款项、应缴税费，以及其他按照国家有关规定应当上缴的款项。"},{"i":27,"n":"第二十七条","txt":"事业单位的非流动负债包括长期借款、长期应付款等。 长期借款是指事业单位借入的期限超过1年（不含1年）的各种借款。 长期应付款是指事业单位发生的偿还期限超过1年（不含1年）的应付款项，主要指事业单位融资租入固定资产发生的应付租赁款。"},{"i":28,"n":"第二十八条","txt":"事业单位的负债应当按照合同金额或实际发生额进行计量。"},{"i":29,"n":"第二十九条","txt":"净资产是指事业单位资产扣除负债后的余额。"},{"i":30,"n":"第三十条","txt":"事业单位的净资产包括事业基金、非流动资产基金、专用基金、财政补助结转结余、非财政补助结转结余等。 事业基金是指事业单位拥有的非限定用途的净资产，其来源主要为非财政补助结余扣除结余分配后滚存的金额。 非流动资产基金是指事业单位非流动资产占用的金额。 专用基金是指事业单位按规定提取或者设置的具有专门用途的净资产。 财政补助结转结余是指事业单位各项财政补助收入与其相关支出相抵后剩余滚存的、须按规定管理和使用的结转和结余资金。 非财政补助结转结余是指事业单位除财政补助收支以外的各项收入与各项支出相抵后的余额。其中，非财政补助结转是指事业单位除财政补助收支以外的各专项资金收入与其相关支出相抵后剩余滚存的、须按规定用途使用的结转资金；非财政补助结余是指事业单位除财政补助收支以外的各非专项资金收入与各非专项资金支出相抵后的余额。"},{"i":31,"n":"第三十一条","txt":"事业基金、非流动资产基金、专用基金、财政补助结转结余、非财政补助结转结余等净资产项目应当分项列入资产负债表。"},{"i":32,"n":"第三十二条","txt":"收入是指事业单位开展业务及其他活动依法取得的非偿还性资金。"},{"i":33,"n":"第三十三条","txt":"事业单位的收入包括财政补助收入、事业收入、上级补助收入、附属单位上缴收入、经营收入和其他收入等。 财政补助收入是指事业单位从同级财政部门取得的各类财政拨款，包括基本支出补助和项目支出补助。 事业收入是指事业单位开展专业业务活动及其辅助活动取得的收入。其中：按照国家有关规定应当上缴国库或者财政专户的资金，不计入事业收入；从财政专户核拨给事业单位的资金和经核准不上缴国库或者财政专户的资金，计入事业收入。 上级补助收入是指事业单位从主管部门和上级单位取得的非财政补助收入。 附属单位上缴收入是指事业单位附属独立核算单位按照有关规定上缴的收入。 经营收入是指事业单位在专业业务活动及其辅助活动之外开展非独立核算经营活动取得的收入。 其他收入是指财政补助收入、事业收入、上级补助收入、附属单位上缴收入和经营收入以外的各项收入，包括投资收益、利息收入、捐赠收入等。"},{"i":34,"n":"第三十四条","txt":"事业单位的收入一般应当在收到款项时予以确认，并按照实际收到的金额进行计量。 采用权责发生制确认的收入，应当在提供服务或者发出存货，同时收讫价款或者取得索取价款的凭据时予以确认，并按照实际收到的金额或者有关凭据注明的金额进行计量。"},{"i":35,"n":"第三十五条","txt":"支出或者费用是指事业单位开展业务及其他活动发生的资金耗费和损失。"},{"i":36,"n":"第三十六条","txt":"事业单位的支出或者费用包括事业支出、对附属单位补助支出、上缴上级支出、经营支出和其他支出等。 事业支出是指事业单位开展专业业务活动及其辅助活动发生的基本支出和项目支出。 对附属单位补助支出是指事业单位用财政补助收入之外的收入对附属单位补助发生的支出。 上缴上级支出是指事业单位按照财政部门和主管部门的规定上缴上级单位的支出。 经营支出是指事业单位在专业业务活动及其辅助活动之外开展非独立核算经营活动发生的支出。 其他支出是指事业支出、对附属单位补助支出、上缴上级支出和经营支出以外的各项支出，包括利息支出、捐赠支出等。"},{"i":37,"n":"第三十七条","txt":"事业单位开展非独立核算经营活动的，应当正确归集开展经营活动发生的各项费用数；无法直接归集的，应当按照规定的标准或比例合理分摊。 事业单位的经营支出与经营收入应当配比。"},{"i":38,"n":"第三十八条","txt":"事业单位的支出一般应当在实际支付时予以确认，并按照实际支付金额进行计量。 采用权责发生制确认的支出或者费用，应当在其发生时予以确认，并按照实际发生额进行计量。"},{"i":39,"n":"第三十九条","txt":"财务会计报告是反映事业单位某一特定日期的财务状况和某一会计期间的事业成果、预算执行等会计信息的文件。"},{"i":40,"n":"第四十条","txt":"事业单位的财务会计报告包括财务报表和其他应当在财务会计报告中披露的相关信息和资料。"},{"i":41,"n":"第四十一条","txt":"财务报表是对事业单位财务状况、事业成果、预算执行情况等的结构性表述。财务报表由会计报表及其附注构成。 会计报表至少应当包括下列组成部分： （一）资产负债表； （二）收入支出表或者收入费用表； （三）财政补助收入支出表。"},{"i":42,"n":"第四十二条","txt":"资产负债表是指反映事业单位在某一特定日期的财务状况的报表。 资产负债表应当按照资产、负债和净资产分类列示。资产和负债应当分别流动资产和非流动资产、流动负债和非流动负债列示。"},{"i":43,"n":"第四十三条","txt":"收入支出表或者收入费用表是指反映事业单位在某一会计期间的事业成果及其分配情况的报表。 收入支出表或者收入费用表应当按照收入、支出或者费用的构成和非财政补助结余分配情况分项列示。"},{"i":44,"n":"第四十四条","txt":"财政补助收入支出表是指反映事业单位在某一会计期间财政补助收入、支出、结转及结余情况的报表。"},{"i":45,"n":"第四十五条","txt":"附注是指对在会计报表中列示项目的文字描述或明细资料，以及对未能在会计报表中列示项目的说明等。 附注至少应当包括下列内容： （一）遵循事业单位会计准则、事业单位会计制度（行业事业单位会计制度）的声明； （二）会计报表中列示的重要项目的进一步说明，包括其主要构成、增减变动情况等； （三）有助于理解和分析会计报表需要说明的其他事项。"},{"i":46,"n":"第四十六条","txt":"事业单位财务报表应当根据登记完整、核对无误的账簿记录和其他有关资料编制，做到数字真实、计算准确、内容完整、报送及时。"},{"i":47,"n":"第四十七条","txt":"纳入企业财务管理体系的事业单位执行企业会计准则或小企业会计准则。"},{"i":48,"n":"第四十八条","txt":"参照公务员法管理的事业单位对本准则的适用，由财政部另行规定。"},{"i":49,"n":"第四十九条","txt":"本准则自2013年1月1日起施行。1997年5月28日财政部印发的《事业单位会计准则（试行）》（财预字[1997]286号）同时废止。"}],"shiyedanweiguoyouzichanguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范和加强事业单位国有资产管理，维护国有资产的安全完整，合理配置和有效利用国有资产，保障和促进各项事业发展，建立适应社会主义市场经济和公共财政要求的事业单位国有资产管理体制，根据国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级各类事业单位的国有资产管理活动。"},{"i":3,"n":"第三条","txt":"本办法所称的事业单位国有资产，是指事业单位占有、使用的，依法确认为国家所有，能以货币计量的各种经济资源的总称，即事业单位的国有（公共）财产。 事业单位国有资产包括国家拨给事业单位的资产，事业单位按照国家规定运用国有资产组织收入形成的资产，以及接受捐赠和其他经法律确认为国家所有的资产，其表现形式为流动资产、固定资产、无形资产和对外投资等。"},{"i":4,"n":"第四条","txt":"事业单位国有资产管理活动，应当坚持资产管理与预算管理相结合的原则，推行实物费用定额制度，促进事业资产整合与共享共用，实现资产管理和预算管理的紧密统一;应当坚持所有权和使用权相分离的原则;应当坚持资产管理与财务管理、实物管理与价值管理相结合的原则。"},{"i":5,"n":"第五条","txt":"事业单位国有资产实行国家统一所有，政府分级监管，单位占有、使用的管理体制。"},{"i":6,"n":"第六条","txt":"各级财政部门是政府负责事业单位国有资产管理的职能部门，对事业单位的国有资产实施综合管理。其主要职责是: （一）根据国家有关国有资产管理的规定，制定事业单位国有资产管理的规章制度，并组织实施和监督检查; （二）研究制定本级事业单位实物资产配置标准和相关的费用标准，组织本级事业单位国有资产的产权登记、产权界定、产权纠纷调处、资产评估监管、资产清查和统计报告等基础管理工作; （三）按规定权限审批本级事业单位有关资产购置、处置和利用国有资产对外投资、出租、出借和担保等事项，组织事业单位长期闲置、低效运转和超标准配置资产的调剂工作，建立事业单位国有资产整合、共享、共用机制; （四）推进本级有条 件的事业单位实现国有资产的市场化、社会化，加强事业单位转企改制工作中国有资产的监督管理; （五）负责本级事业单位国有资产收益的监督管理; （六）建立和完善事业单位国有资产管理信息系统，对事业单位国有资产实"},{"i":7,"n":"第七条","txt":"事业单位的主管部门（以下简称主管部门）负责对本部门所属事业单位的国有资产实施监督管理。其主要职责是: （一）根据本级和上级财政部门有关国有资产管理的规定，制定本部门事业单位国有资产管理的实施办法，并组织实施和监督检查; （二）组织本部门事业单位国有资产的清查、登记、统计汇总及日常监督检查工作; （三）审核本部门所属事业单位利用国有资产对外投资、出租、出借和担保等事项，按规定权限审核或者审批有关资产购置、处置事项; （四）负责本部门所属事业单位长期闲置、低效运转和超标准配置资产的调剂工作，优化事业单位国有资产配置，推动事业单位国有资产共享、共用 ; （五）督促本部门所属事业单位按规定缴纳国有资产收益; （六）组织实施对本部门所属事业单位国有资产管理和使用情况的评价考核; （七）接受同级财政部门的监督、指导并向其报告有关事业单位国有资产管理工作。"},{"i":8,"n":"第八条","txt":"事业单位负责对本单位占有、使用的国有资产实施具体管理。其主要职责是: （一）根据事业单位国有资产管理的有关规定，制定本单位国有资产管理的具体办法并组织实施; （二）负责本单位资产购置、验收入库、维护保管等日常管理，负责本单位资产的账卡管理、清查登记、统计报告及日常监督检查工作; （三）办理本单位国有资产配置、处置和对外投资、出租、出借和担保等事项的报批手续; （四）负责本单位用于对外投资、出租、出借和担保的资产的保值增值，按照规定及时、足额缴纳国有资产收益; （五）负责本单位存量资产的有效利用，参与大型仪器、设备等资产的共享、共用和公共研究平台建设工作; （六）接受主管部门和同级财政部门的监督、指导并向其报告有关国有资产管理工作。"},{"i":9,"n":"第九条","txt":"各级财政部门、主管部门和事业单位应当按照本办法的规定，明确管理机构和人员，做好事业单位国有资产管理工作。"},{"i":10,"n":"第十条","txt":"财政部门根据工作需要，可以将国有资产管理的部分工作交由有关单位完成。"},{"i":11,"n":"第十一条","txt":"事业单位国有资产配置是指财政部门、主管部门、事业单位等根据事业单位履行职能的需要，按照国家有关法律、法规和规章制度规定的程序，通过购置或者调剂等方式为事业单位配备资产的行为。"},{"i":12,"n":"第十二条","txt":"事业单位国有资产配置应当符合以下条 件: （一）现有资产无法满足事业单位履行职能的需要; （二）难以与其他单位共享、共用相关资产; （三）难以通过市场购买产品或者服务的方式代替资产配置，或者采取市场购买方式的成本过高。"},{"i":13,"n":"第十三条","txt":"事业单位国有资产配置应当符合规定的配置标准;没有规定配置标准的，应当从严控制，合理配置。"},{"i":14,"n":"第十四条","txt":"对于事业单位长期闲置、低效运转或者超标准配置的资产，原则上由主管部门进行调剂，并报同级财政部门备案;跨部门、跨地区的资产调剂应当报同级或者共同上一级的财政部门批准。法律、行政法规另有规定的，依照其规定。"},{"i":15,"n":"第十五条","txt":"事业单位向财政部门申请用财政性资金购置规定限额以上资产的（包括事业单位申请用财政性资金举办大型会议、活动需要进行的购置），除国家另有规定外，按照下列程序报批: （一）年度部门预算编制前，事业单位资产管理部门会同财务部门审核资产存量，提出下一年度拟购置资产的品目、数量，测算经费额度，报主管部门审核 ; （二）主管部门根据事业单位资产存量状况和有关资产配置标准，审核、汇总事业单位资产购置计划，报同级财政部门审批; （三）同级财政部门根据主管部门的审核意见，对资产购置计划进行审批; （四）经同级财政部门批准的资产购置计划，事业单位应当列入年度部门预算，并在上报年度部门预算时附送批复文件等相关材料，作为财政部门批复部门预算的依据。"},{"i":16,"n":"第十六条","txt":"事业单位向主管部门或者其他部门申请项目经费的，有关部门在下达经费前，应当将所涉及的规定限额以上的资产购置事项报同级财政部门批准。"},{"i":17,"n":"第十七条","txt":"事业单位用其他资金购置规定限额以上资产的，报主管部门审批;主管部门应当将审批结果定期报同级财政部门备案。"},{"i":18,"n":"第十八条","txt":"事业单位购置纳入政府采购范围的资产，应当按照国家有关政府采购的规定执行。"},{"i":19,"n":"第十九条","txt":"事业单位国有资产的使用包括单位自用和对外投资、出租、出借、担保等方式。"},{"i":20,"n":"第二十条","txt":"事业单位应当建立健全资产购置、验收、保管、使用等内部管理制度。事业单位应当对实物资产进行定期清查，做到账账、账卡、账实相符，加强对本单位专利权、商标权、著作权、土地使用权、非专利技术、商誉等无形资产的管理，防止无形资产流失。"},{"i":21,"n":"第二十一条","txt":"事业单位利用国有资产对外投资、出租、出借和担保等应当进行必要的可行性论证，并提出申请，经主管部门审核同意后，报同级财政部门审批。法律、行政法规另有规定的，依照其规定。事业单位应当对本单位用于对外投资、出租和出借的资产实行专项管理，并在单位财务会计报告中对相关信息进行充分披露。"},{"i":22,"n":"第二十二条","txt":"财政部门和主管部门应当加强对事业单位利用国有资产对外投资、出租、出借和担保等行为的风险控制。"},{"i":23,"n":"第二十三条","txt":"事业单位对外投资收益以及利用国有资产出租、出借和担保等取得的收入应当纳入单位预算，统一核算，统一管理。国家另有规定的除外。"},{"i":24,"n":"第二十四条","txt":"事业单位国有资产处置，是指事业单位对其占有、使用的国有资产进行产权转让或者注销产权的行为。处置方式包括出售、出让、转让、对外捐赠、报废、报损以及货币性资产损失核销等。"},{"i":25,"n":"第二十五条","txt":"事业单位处置国有资产，应当严格履行审批手续，未经批准不得自行处置。"},{"i":26,"n":"第二十六条","txt":"事业单位占有、使用的房屋建筑物、土地和车辆的处置，货币性资产损失的核销，以及单位价值或者批量价值在规定限额以上的资产的处置，经主管部门审核后报同级财政部门审批;规定限额以下的资产的处置报主管部门审批，主管部门将审批结果定期报同级财政部门备案。法律、行政法规另有规定的，依照其规定。"},{"i":27,"n":"第二十七条","txt":"财政部门或者主管部门对事业单位国有资产处置事项的批复是财政部门重新安排事业单位有关资产配置预算项目的参考依据，是事业单位调整相关会计账目的凭证。"},{"i":28,"n":"第二十八条","txt":"事业单位国有资产处置应当遵循公开、公正、公平的原则。事业单位出售、出让、转让、变卖资产数量较多或者价值较高的，应当通过拍卖等市场竞价方式公开处置。"},{"i":29,"n":"第二十九条","txt":"事业单位国有资产处置收入属于国家所有，应当按照政府非税收入管理的规定，实行“收支两条 线”管理。"},{"i":30,"n":"第三十条","txt":"事业单位国有资产产权登记（以下简称产权登记）是国家对事业单位占有、使用的国有资产进行登记，依法确认国家对国有资产的所有权和事业单位对国有资产的占有、使用权的行为。"},{"i":31,"n":"第三十一条","txt":"事业单位应当向同级财政部门或者经同级财政部门授权的主管部门（以下简称授权部门）申报、办理产权登记，并由财政部门或者授权部门核发《事业单位国有资产产权登记证》（以下简称《产权登记证》）。"},{"i":32,"n":"第三十二条","txt":"《产权登记证》是国家对事业单位国有资产享有所有权，单位享有占有、使用权的法律凭证，由财政部统一印制。事业单位办理法人年检、改制、资产处置和利用国有资产对外投资、出租、出借、担保等事项时，应当出具《产权登记证》。"},{"i":33,"n":"第三十三条","txt":"事业单位国有资产产权登记的内容主要包括: （一）单位名称、住所、负责人及成立时间; （二）单位性质、主管部门; （三）单位资产总额、国有资产总额、主要实物资产额及其使用状况、对外投资情况; （四）其他需要登记的事项。"},{"i":34,"n":"第三十四条","txt":"事业单位应当按照以下规定进行国有资产产权登记: （一）新设立的事业单位，办理占有产权登记; （二）发生分立、合并、部分改制，以及隶属关系、单位名称、住所和单位负责人等产权登记内容发生变化的事业单位，办理变更产权登记 ; （三）因依法撤销或者整体改制等原因被清算、注销的事业单位，办理注销产权登记。"},{"i":35,"n":"第三十五条","txt":"各级财政部门应当在资产动态管理信息系统和变更产权登记的基础上，对事业单位国有资产产权登记实行定期检查。"},{"i":36,"n":"第三十六条","txt":"事业单位与其他国有单位之间发生国有资产产权纠纷的，由当事人协商解决。协商不能解决的，可以向同级或者共同上一级财政部门申请调解或者裁定，必要时报有管辖权的人民政府处理。"},{"i":37,"n":"第三十七条","txt":"事业单位与非国有单位或者个人之间发生产权纠纷的，事业单位应当提出拟处理意见，经主管部门审核并报同级财政部门批准后，与对方当事人协商解决。协商不能解决的，依照司法程序处理。"},{"i":38,"n":"第三十八条","txt":"事业单位有下列情形之一的，应当对相关国有资产进行评估: （一）整体或者部分改制为企业; （二）以非货币性资产对外投资; （三）合并、分立、清算; （四）资产拍卖、转让、置换; （五）整体或者部分资产租赁给非国有单位; （六）确定涉讼资产价值; （七）法律、行政法规规定的其他需要进行评估的事项。"},{"i":39,"n":"第三十九条","txt":"事业单位有下列情形之一的，可以不进行资产评估: （一）经批准事业单位整体或者部分资产无偿划转; （二）行政、事业单位下属的事业单位之间的合并、资产划转、置换和转让; （三）发生其他不影响国有资产权益的特殊产权变动行为，报经同级财政部门确认可以不进行资产评估的。第四十条 事业单位国有资产评估工作应当委托具有资产评估资质的评估机构进行。事业单位应当如实向资产评估机构提供有关情况和资料，并对所提供的情况和资料的客观性、真实性和合法性负责。事业单位不得以任何形式干预资产评估机构独立执业。"},{"i":40,"n":"第四十一条","txt":"事业单位国有资产评估项目实行核准制和备案制。核准和备案工作按照国家有关国有资产评估项目核准和备案管理的规定执行。"},{"i":41,"n":"第四十二条","txt":"事业单位有下列情形之一的，应当进行资产清查: （一）根据国家专项工作要求或者本级政府实际工作需要，被纳入统一组织的资产清查范围的; （二）进行重大改革或者整体、部分改制为企业的; （三）遭受重大自然灾害等不可抗力造成资产严重损失的; （四）会计信息严重失真或者国有资产出现重大流失的; （五）会计政策发生重大更改，涉及资产核算方法发生重要变化的; （六）同级财政部门认为应当进行资产清查的其他情形。"},{"i":42,"n":"第四十三条","txt":"事业单位进行资产清查，应当向主管部门提出申请，并按照规定程序报同级财政部门批准立项后组织实施，但根据国家专项工作要求或者本级政府工作需要进行的资产清查除外。"},{"i":43,"n":"第四十四条","txt":"事业单位资产清查工作的内容主要包括基本情况清理、账务清理、财产清查、损溢认定、资产核实和完善制度等。资产清查的具体办法由财政部另行制定。"},{"i":44,"n":"第四十五条","txt":"事业单位应当按照国有资产管理信息化的要求，及时将资产变动信息录入管理信息系统，对本单位资产实行动态管理，并在此基础上做好国有资产统计和信息报告工作。"},{"i":45,"n":"第四十六条","txt":"事业单位国有资产信息报告是事业单位财务会计报告的重要组成部分。事业单位应当按照财政部门规定的事业单位财务会计报告的格式、内容及要求，对其占有、使用的国有资产状况定期做出报告。"},{"i":46,"n":"第四十七条","txt":"事业单位国有资产占有、使用状况，是主管部门、财政部门编制和安排事业单位预算的重要参考依据。各级财政部门、主管部门应当充分利用资产管理信息系统和资产信息报告，全面、动态地掌握事业单位国有资产占有、使用状况，建立和完善资产与预算有效结合的激励和约束机制。"},{"i":47,"n":"第四十八条","txt":"财政部门、主管部门、事业单位及其工作人员，应当依法维护事业单位国有资产的安全完整，提高国有资产使用效益。"},{"i":48,"n":"第四十九条","txt":"财政部门、主管部门和事业单位应当建立健全科学合理的事业单位国有资产监督管理责任制，将资产监督、管理的责任落实到具体部门、单位和个人。"},{"i":49,"n":"第五十条","txt":"事业单位国有资产监督应当坚持单位内部监督与财政监督、审计监督、社会监督相结合，事前监督与事中监督、事后监督相结合，日常监督与专项检查相结合。"},{"i":50,"n":"第五十一条","txt":"事业单位及其工作人员违反本办法，有下列行为之一的，依据《财政违法行为处罚处分条 例》的规定进行处罚、处理、处分: （一）以虚报、冒领等手段骗取财政资金的; （二）擅自占有、使用和处置国有资产的; （三）擅自提供担保的; （四）未按规定缴纳国有资产收益的。"},{"i":51,"n":"第五十二条","txt":"财政部门、主管部门及其工作人员在上缴、管理国有资产收益，或者下拨财政资金时，违反本办法规定的，依据《财政违法行为处罚处分条 例》的规定进行处罚、处理、处分。"},{"i":52,"n":"第五十三条","txt":"主管部门在配置事业单位国有资产或者审核、批准国有资产使用、处置事项的工作中违反本办法规定的，财政部门可以责令其限期改正，逾期不改的予以警告。"},{"i":53,"n":"第五十四条","txt":"违反本办法有关事业单位国有资产管理规定的其他行为，依据国家有关法律、法规及规章制度进行处理。"},{"i":54,"n":"第五十五条","txt":"社会团体和民办非企业单位中占有、使用国有资产的，参照本办法执行。参照公务员制度管理的事业单位和社会团体，依照国家关于行政单位国有资产管理的有关规定执行。"},{"i":55,"n":"第五十六条","txt":"实行企业化管理并执行企业财务会计制度的事业单位，以及事业单位创办的具有法人资格的企业，由财政部门按照企业国有资产监督管理的有关规定实施监督管理。"},{"i":56,"n":"第五十七条","txt":"地方财政部门制定的本地区和本级事业单位的国有资产管理规章制度，应当报上一级财政部门备案。中央级事业单位的国有资产管理实施办法，由财政部会同有关部门根据本办法制定。"},{"i":57,"n":"第五十八条","txt":"境外事业单位国有资产管理办法由财政部另行制定。中国人民解放军、武装警察部队以及经国家批准的特定事业单位的国有资产管理办法，由解放军总后勤部、武装警察部队和有关主管部门会同财政部另行制定。行业特点突出，需要制定行业事业单位国有资产管理办法的，由财政部会同有关主管部门根据本办法制定。"},{"i":58,"n":"第五十九条","txt":"本办法中有关资产配置、处置事项的“规定限额”由省级以上财政部门另行确定。"},{"i":59,"n":"第六十条","txt":"本办法自2006年7月1日起施行。此前颁布的有关事业单位国有资产管理的规定与本办法相抵触的，按照本办法执行。"}],"shiyedanweicaiwuguize-2":[{"i":1,"n":"第一条","txt":"为了进一步规范事业单位的财务行为，加强事业单位财务管理和监督，提高资金使用效益，保障事业单位健康发展，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于各级各类事业单位（以下简称事业单位）的财务活动。"},{"i":3,"n":"第三条","txt":"事业单位财务管理的基本原则是：执行国家有关法律、法规和财务规章制度；坚持勤俭办事业的方针；正确处理事业发展需要和资金供给的关系，社会效益和经济效益的关系，国家、单位和个人三者利益的关系。"},{"i":4,"n":"第四条","txt":"事业单位财务管理的主要任务是：合理编制单位预算，严格预算执行，完整、准确编制单位决算，真实反映单位财务状况；依法组织收入，努力节约支出；建立健全财务制度，加强经济核算，实施绩效评价，提高资金使用效益；加强资产管理，合理配置和有效利用资产，防止资产流失；加强对单位经济活动的财务控制和监督，防范财务风险。"},{"i":5,"n":"第五条","txt":"事业单位的财务活动在单位负责人的领导下，由单位财务部门统一管理。"},{"i":6,"n":"第六条","txt":"事业单位预算是指事业单位根据事业发展目标和计划编制的年度财务收支计划。 事业单位预算由收入预算和支出预算组成。"},{"i":7,"n":"第七条","txt":"国家对事业单位实行核定收支、定额或者定项补助、超支不补、结转和结余按规定使用的预算管理办法。 定额或者定项补助根据国家有关政策和财力可能，结合事业特点、事业发展目标和计划、事业单位收支及资产状况等确定。定额或者定项补助可以为零。 非财政补助收入大于支出较多的事业单位，可以实行收入上缴办法。具体办法由财政部门会同有关主管部门制定。"},{"i":8,"n":"第八条","txt":"事业单位参考以前年度预算执行情况，根据预算年度的收入增减因素和措施，以及以前年度结转和结余情况，测算编制收入预算；根据事业发展需要与财力可能，测算编制支出预算。 事业单位预算应当自求收支平衡，不得编制赤字预算。"},{"i":9,"n":"第九条","txt":"事业单位根据年度事业发展目标和计划以及预算编制的规定，提出预算建议数，经主管部门审核汇总报财政部门（一级预算单位直接报财政部门，下同）。事业单位根据财政部门下达的预算控制数编制预算，由主管部门审核汇总报财政部门，经法定程序审核批复后执行。"},{"i":10,"n":"第十条","txt":"事业单位应当严格执行批准的预算。预算执行中，国家对财政补助收入和财政专户管理资金的预算一般不予调整。上级下达的事业计划有较大调整，或者根据国家有关政策增加或者减少支出，对预算执行影响较大时，事业单位应当报主管部门审核后报财政部门调整预算；财政补助收入和财政专户管理资金以外部分的预算需要调增或者调减的，由单位自行调整并报主管部门和财政部门备案。 收入预算调整后，相应调增或者调减支出预算。"},{"i":11,"n":"第十一条","txt":"事业单位决算是指事业单位根据预算执行结果编制的年度报告。"},{"i":12,"n":"第十二条","txt":"事业单位应当按照规定编制年度决算，由主管部门审核汇总后报财政部门审批。"},{"i":13,"n":"第十三条","txt":"事业单位应当加强决算审核和分析，保证决算数据的真实、准确，规范决算管理工作。"},{"i":14,"n":"第十四条","txt":"收入是指事业单位为开展业务及其他活动依法取得的非偿还性资金。"},{"i":15,"n":"第十五条","txt":"事业单位收入包括： （一）财政补助收入，即事业单位从同级财政部门取得的各类财政拨款。 （二）事业收入，即事业单位开展专业业务活动及其辅助活动取得的收入。其中：按照国家有关规定应当上缴国库或者财政专户的资金，不计入事业收入；从财政专户核拨给事业单位的资金和经核准不上缴国库或者财政专户的资金，计入事业收入。 （三）上级补助收入，即事业单位从主管部门和上级单位取得的非财政补助收入。 （四）附属单位上缴收入，即事业单位附属独立核算单位按照有关规定上缴的收入。 （五）经营收入，即事业单位在专业业务活动及其辅助活动之外开展非独立核算经营活动取得的收入。 （六）其他收入，即本条上述规定范围以外的各项收入，包括投资收益、利息收入、捐赠收入等。"},{"i":16,"n":"第十六条","txt":"事业单位应当将各项收入全部纳入单位预算，统一核算，统一管理。"},{"i":17,"n":"第十七条","txt":"事业单位对按照规定上缴国库或者财政专户的资金，应当按照国库集中收缴的有关规定及时足额上缴，不得隐瞒、滞留、截留、挪用和坐支。"},{"i":18,"n":"第十八条","txt":"支出是指事业单位开展业务及其他活动发生的资金耗费和损失。"},{"i":19,"n":"第十九条","txt":"事业单位支出包括： （一）事业支出，即事业单位开展专业业务活动及其辅助活动发生的基本支出和项目支出。基本支出是指事业单位为了保障其正常运转、完成日常工作任务而发生的人员支出和公用支出。项目支出是指事业单位为了完成特定工作任务和事业发展目标，在基本支出之外所发生的支出。 （二）经营支出，即事业单位在专业业务活动及其辅助活动之外开展非独立核算经营活动发生的支出。 （三）对附属单位补助支出，即事业单位用财政补助收入之外的收入对附属单位补助发生的支出。 （四）上缴上级支出，即事业单位按照财政部门和主管部门的规定上缴上级单位的支出。 （五）其他支出，即本条上述规定范围以外的各项支出，包括利息支出、捐赠支出等。"},{"i":20,"n":"第二十条","txt":"事业单位应当将各项支出全部纳入单位预算，建立健全支出管理制度。"},{"i":21,"n":"第二十一条","txt":"事业单位的支出应当严格执行国家有关财务规章制度规定的开支范围及开支标准；国家有关财务规章制度没有统一规定的，由事业单位规定，报主管部门和财政部门备案。事业单位的规定违反法律制度和国家政策的，主管部门和财政部门应当责令改正。"},{"i":22,"n":"第二十二条","txt":"事业单位在开展非独立核算经营活动中，应当正确归集实际发生的各项费用数；不能归集的，应当按照规定的比例合理分摊。 经营支出应当与经营收入配比。"},{"i":23,"n":"第二十三条","txt":"事业单位从财政部门和主管部门取得的有指定项目和用途的专项资金，应当专款专用、单独核算，并按照规定向财政部门或者主管部门报送专项资金使用情况；项目完成后，应当报送专项资金支出决算和使用效果的书面报告，接受财政部门或者主管部门的检查、验收。"},{"i":24,"n":"第二十四条","txt":"事业单位应当加强经济核算，可以根据开展业务活动及其他活动的实际需要，实行内部成本核算办法。"},{"i":25,"n":"第二十五条","txt":"事业单位应当严格执行国库集中支付制度和政府采购制度等有关规定。"},{"i":26,"n":"第二十六条","txt":"事业单位应当加强支出的绩效管理，提高资金使用的有效性。"},{"i":27,"n":"第二十七条","txt":"事业单位应当依法加强各类票据管理，确保票据来源合法、内容真实、使用正确，不得使用虚假票据。"},{"i":28,"n":"第二十八条","txt":"结转和结余是指事业单位年度收入与支出相抵后的余额。 结转资金是指当年预算已执行但未完成，或者因故未执行，下一年度需要按照原用途继续使用的资金。结余资金是指当年预算工作目标已完成，或者因故终止，当年剩余的资金。 经营收支结转和结余应当单独反映。"},{"i":29,"n":"第二十九条","txt":"财政拨款结转和结余的管理，应当按照同级财政部门的规定执行。"},{"i":30,"n":"第三十条","txt":"非财政拨款结转按照规定结转下一年度继续使用。非财政拨款结余可以按照国家有关规定提取职工福利基金，剩余部分作为事业基金用于弥补以后年度单位收支差额；国家另有规定的，从其规定。"},{"i":31,"n":"第三十一条","txt":"事业单位应当加强事业基金的管理，遵循收支平衡的原则，统筹安排、合理使用，支出不得超出基金规模。"},{"i":32,"n":"第三十二条","txt":"专用基金是指事业单位按照规定提取或者设置的有专门用途的资金。 专用基金管理应当遵循先提后用、收支平衡、专款专用的原则，支出不得超出基金规模。"},{"i":33,"n":"第三十三条","txt":"专用基金包括： （一）修购基金，即按照事业收入和经营收入的一定比例提取，并按照规定在相应的购置和修缮科目中列支（各列50%），以及按照其他规定转入，用于事业单位固定资产维修和购置的资金。事业收入和经营收入较少的事业单位可以不提取修购基金，实行固定资产折旧的事业单位不提取修购基金。 （二）职工福利基金，即按照非财政拨款结余的一定比例提取以及按照其他规定提取转入，用于单位职工的集体福利设施、集体福利待遇等的资金。 （三）其他基金，即按照其他有关规定提取或者设置的专用资金。"},{"i":34,"n":"第三十四条","txt":"各项基金的提取比例和管理办法，国家有统一规定的，按照统一规定执行；没有统一规定的，由主管部门会同同级财政部门确定。"},{"i":35,"n":"第三十五条","txt":"资产是指事业单位占有或者使用的能以货币计量的经济资源，包括各种财产、债权和其他权利。"},{"i":36,"n":"第三十六条","txt":"事业单位的资产包括流动资产、固定资产、在建工程、无形资产和对外投资等。"},{"i":37,"n":"第三十七条","txt":"事业单位应当建立健全单位资产管理制度，加强和规范资产配置、使用和处置管理，维护资产安全完整，保障事业健康发展。"},{"i":38,"n":"第三十八条","txt":"事业单位应当按照科学规范、从严控制、保障事业发展需要的原则合理配置资产。"},{"i":39,"n":"第三十九条","txt":"流动资产是指可以在一年以内变现或者耗用的资产，包括现金、各种存款、零余额账户用款额度、应收及预付款项、存货等。 前款所称存货是指事业单位在开展业务活动及其他活动中为耗用而储存的资产，包括材料、燃料、包装物和低值易耗品等。 事业单位应当建立健全现金及各种存款的内部管理制度，对存货进行定期或者不定期的清查盘点，保证账实相符。对存货盘盈、盘亏应当及时处理。"},{"i":40,"n":"第四十条","txt":"固定资产是指使用期限超过一年，单位价值在1000元以上（其中：专用设备单位价值在1500元以上），并在使用过程中基本保持原有物质形态的资产。单位价值虽未达到规定标准，但是耐用时间在一年以上的大批同类物资，作为固定资产管理。 固定资产一般分为六类：房屋及构筑物；专用设备；通用设备；文物和陈列品；图书、档案；家具、用具、装具及动植物。行业事业单位的固定资产明细目录由国务院主管部门制定，报国务院财政部门备案。"},{"i":41,"n":"第四十一条","txt":"事业单位应当对固定资产进行定期或者不定期的清查盘点。年度终了前应当进行一次全面清查盘点，保证账实相符。"},{"i":42,"n":"第四十二条","txt":"在建工程是指已经发生必要支出，但尚未达到交付使用状态的建设工程。 在建工程达到交付使用状态时，应当按照规定办理工程竣工财务决算和资产交付使用。"},{"i":43,"n":"第四十三条","txt":"无形资产是指不具有实物形态而能为使用者提供某种权利的资产，包括专利权、商标权、著作权、土地使用权、非专利技术、商誉以及其他财产权利。 事业单位转让无形资产，应当按照有关规定进行资产评估，取得的收入按照国家有关规定处理。事业单位取得无形资产发生的支出，应当计入事业支出。"},{"i":44,"n":"第四十四条","txt":"对外投资是指事业单位依法利用货币资金、实物、无形资产等方式向其他单位的投资。 事业单位应当严格控制对外投资。在保证单位正常运转和事业发展的前提下，按照国家有关规定可以对外投资的，应当履行相关审批程序。事业单位不得使用财政拨款及其结余进行对外投资，不得从事股票、期货、基金、企业债券等投资，国家另有规定的除外。 事业单位以非货币性资产对外投资的，应当按照国家有关规定进行资产评估，合理确定资产价值。"},{"i":45,"n":"第四十五条","txt":"事业单位资产处置应当遵循公开、公平、公正和竞争、择优的原则，严格履行相关审批程序。 事业单位出租、出借资产，应当按照国家有关规定经主管部门审核同意后报同级财政部门审批。"},{"i":46,"n":"第四十六条","txt":"事业单位应当提高资产使用效率，按照国家有关规定实行资产共享、共用。"},{"i":47,"n":"第四十七条","txt":"负债是指事业单位所承担的能以货币计量，需要以资产或者劳务偿还的债务。"},{"i":48,"n":"第四十八条","txt":"事业单位的负债包括借入款项、应付款项、暂存款项、应缴款项等。 应缴款项包括事业单位收取的应当上缴国库或者财政专户的资金、应缴税费，以及其他按照国家有关规定应当上缴的款项。"},{"i":49,"n":"第四十九条","txt":"事业单位应当对不同性质的负债分类管理，及时清理并按照规定办理结算，保证各项负债在规定期限内归还。"},{"i":50,"n":"第五十条","txt":"事业单位应当建立健全财务风险控制机制，规范和加强借入款项管理，严格执行审批程序，不得违反规定举借债务和提供担保。"},{"i":51,"n":"第五十一条","txt":"事业单位发生划转、撤销、合并、分立时，应当进行清算。"},{"i":52,"n":"第五十二条","txt":"事业单位清算，应当在主管部门和财政部门的监督指导下，对单位的财产、债权、债务等进行全面清理，编制财产目录和债权、债务清单，提出财产作价依据和债权、债务处理办法，做好资产的移交、接收、划转和管理工作，并妥善处理各项遗留问题。"},{"i":53,"n":"第五十三条","txt":"事业单位清算结束后，经主管部门审核并报财政部门批准，其资产分别按照下列办法处理： （一）因隶属关系改变，成建制划转的事业单位，全部资产无偿移交，并相应划转经费指标。 （二）转为企业管理的事业单位，全部资产扣除负债后，转作国家资本金。需要进行资产评估的，按照国家有关规定执行。 （三）撤销的事业单位，全部资产由主管部门和财政部门核准处理。 （四）合并的事业单位，全部资产移交接收单位或者新组建单位，合并后多余的资产由主管部门和财政部门核准处理。 （五）分立的事业单位，资产按照有关规定移交分立后的事业单位，并相应划转经费指标。"},{"i":54,"n":"第五十四条","txt":"财务报告是反映事业单位一定时期财务状况和事业成果的总结性书面文件。 事业单位应当定期向主管部门和财政部门以及其他有关的报表使用者提供财务报告。"},{"i":55,"n":"第五十五条","txt":"事业单位报送的年度财务报告包括资产负债表、收入支出表、财政拨款收入支出表、固定资产投资决算报表等主表，有关附表以及财务情况说明书等。"},{"i":56,"n":"第五十六条","txt":"财务情况说明书，主要说明事业单位收入及其支出、结转、结余及其分配、资产负债变动、对外投资、资产出租出借、资产处置、固定资产投资、绩效考评的情况，对本期或者下期财务状况发生重大影响的事项，以及需要说明的其他事项。"},{"i":57,"n":"第五十七条","txt":"财务分析的内容包括预算编制与执行、资产使用、收入支出状况等。 财务分析的指标包括预算收入和支出完成率、人员支出与公用支出分别占事业支出的比率、人均基本支出、资产负债率等。主管部门和事业单位可以根据本单位的业务特点增加财务分析指标。"},{"i":58,"n":"第五十八条","txt":"事业单位财务监督主要包括对预算管理、收入管理、支出管理、结转和结余管理、专用基金管理、资产管理、负债管理等的监督。"},{"i":59,"n":"第五十九条","txt":"事业单位财务监督应当实行事前监督、事中监督、事后监督相结合，日常监督与专项监督相结合。"},{"i":60,"n":"第六十条","txt":"事业单位应当建立健全内部控制制度、经济责任制度、财务信息披露制度等监督制度，依法公开财务信息。"},{"i":61,"n":"第六十一条","txt":"事业单位应当依法接受主管部门和财政、审计部门的监督。"},{"i":62,"n":"第六十二条","txt":"事业单位基本建设投资的财务管理，应当执行本规则，但国家基本建设投资财务管理制度另有规定的，从其规定。"},{"i":63,"n":"第六十三条","txt":"参照公务员法管理的事业单位财务制度的适用，由国务院财政部门另行规定。"},{"i":64,"n":"第六十四条","txt":"接受国家经常性资助的社会力量举办的公益服务性组织和社会团体，依照本规则执行；其他社会力量举办的公益服务性组织和社会团体，可以参照本规则执行。"},{"i":65,"n":"第六十五条","txt":"下列事业单位或者事业单位特定项目，执行企业财务制度，不执行本规则： （一）纳入企业财务管理体系的事业单位和事业单位附属独立核算的生产经营单位； （二）事业单位经营的接受外单位要求投资回报的项目； （三）经主管部门和财政部门批准的具备条件的其他事业单位。"},{"i":66,"n":"第六十六条","txt":"行业特点突出，需要制定行业事业单位财务管理制度的，由国务院财政部门会同有关主管部门根据本规则制定。 部分行业根据成本核算和绩效管理的需要，可以在行业事业单位财务管理制度中引入权责发生制。"},{"i":67,"n":"第六十七条","txt":"省、自治区、直辖市人民政府财政部门可以根据本规则结合本地区实际情况制定事业单位具体财务管理办法。"},{"i":68,"n":"第六十八条","txt":"本规则自2012年4月1日起施行。 附件：事业单位财务分析指标 事业单位财务分析指标 1.预算收入和支出完成率，衡量事业单位收入和支出总预算及分项预算完成的程度。计算公式为： 预算收入完成率＝年终执行数÷（年初预算数±年中预算调整数）×100% 年终执行数不含上年结转和结余收入数 预算支出完成率＝年终执行数÷（年初预算数±年中预算调整数）×100% 年终执行数不含上年结转和结余支出数 2.人员支出、公用支出占事业支出的比率，衡量事业单位事业支出结构。计算公式为： 人员支出比率＝人员支出÷事业支出×100% 公用支出比率＝公用支出÷事业支出×100% 3.人均基本支出，衡量事业单位按照实际在编人数平均的基本支出水平。计算公式为： 人均基本支出＝（基本支出-离退休人员支出）÷实际在编人数 4.资产负债率，衡量事业单位利用债权人提供资金开展业务活动的能力，以及反映债权人提供资金的安全保障程度"}],"shiyedanweicaiwuguize":[{"i":1,"n":"第一条","txt":"为了进一步规范事业单位的财务行为，加强事业单位财务管理和监督，提高资金使用效益，保障事业单位健康发展，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于各级各类事业单位（以下简称事业单位）的财务活动。"},{"i":3,"n":"第三条","txt":"事业单位财务管理的基本原则是：执行国家有关法律、法规和财务规章制度；坚持勤俭办一切事业的方针；正确处理事业发展需要和资金供给的关系，社会效益和经济效益的关系，国家、单位和个人三者利益的关系。"},{"i":4,"n":"第四条","txt":"事业单位财务管理的主要任务是：合理编制单位预算，严格预算执行，完整、准确编制单位决算报告和财务报告，真实反映单位预算执行情况、财务状况和运行情况；依法组织收入，努力节约支出；建立健全财务制度，加强经济核算，全面实施绩效管理，提高资金使用效益；加强资产管理，合理配置和有效利用资产，防止资产流失；加强对单位经济活动的财务控制和监督，防范财务风险。"},{"i":5,"n":"第五条","txt":"事业单位的财务活动在单位负责人的领导下，由单位财务部门统一管理。"},{"i":6,"n":"第六条","txt":"事业单位的各项经济业务事项按照国家统一的会计制度进行会计核算。"},{"i":7,"n":"第七条","txt":"事业单位预算是指事业单位根据事业发展目标和计划编制的年度财务收支计划。 事业单位预算由收入预算和支出预算组成。"},{"i":8,"n":"第八条","txt":"国家对事业单位实行核定收支、定额或者定项补助、超支不补、结转和结余按规定使用的预算管理办法。 定额或者定项补助根据国家有关政策和财力可能，结合事业单位改革要求、事业特点、事业发展目标和计划、事业单位收支及资产状况等确定。定额或者定项补助可以为零。 非财政补助收入大于支出较多的事业单位，可以实行收入上缴办法。具体办法由财政部门会同有关主管部门制定。"},{"i":9,"n":"第九条","txt":"事业单位参考以前年度预算执行情况，根据预算年度的收入增减因素和措施，以及以前年度结转和结余情况，测算编制收入预算草案；根据事业发展需要与财力可能，测算编制支出预算草案。 事业单位预算应当自求收支平衡，不得编制赤字预算。"},{"i":10,"n":"第十条","txt":"事业单位应当根据国家宏观调控总体要求、年度事业发展目标和计划以及预算编制的规定，提出预算建议数，经主管部门审核汇总报财政部门（一级预算单位直接报财政部门，下同）。事业单位根据财政部门下达的预算控制数编制预算草案，由主管部门审核汇总报财政部门，经法定程序审核批复后执行。"},{"i":11,"n":"第十一条","txt":"事业单位应当严格执行批准的预算。预算执行中，国家对财政补助收入和财政专户管理资金的预算一般不予调剂，确需调剂的，由事业单位报主管部门审核后报财政部门调剂；其他资金确需调剂的，按照国家有关规定办理。"},{"i":12,"n":"第十二条","txt":"事业单位决算是指事业单位预算收支和结余的年度执行结果。"},{"i":13,"n":"第十三条","txt":"事业单位应当按照规定编制年度决算草案，由主管部门审核汇总后报财政部门审批。"},{"i":14,"n":"第十四条","txt":"事业单位应当加强决算审核和分析，保证决算数据的真实、准确，规范决算管理工作。"},{"i":15,"n":"第十五条","txt":"事业单位应当全面加强预算绩效管理，提高资金使用效益。"},{"i":16,"n":"第十六条","txt":"收入是指事业单位为开展业务及其他活动依法取得的非偿还性资金。"},{"i":17,"n":"第十七条","txt":"事业单位收入包括： （一）财政补助收入，即事业单位从本级财政部门取得的各类财政拨款。 （二）事业收入，即事业单位开展专业业务活动及其辅助活动取得的收入。其中：按照国家有关规定应当上缴国库或者财政专户的资金，不计入事业收入；从财政专户核拨给事业单位的资金和经核准不上缴国库或者财政专户的资金，计入事业收入。 （三）上级补助收入，即事业单位从主管部门和上级单位取得的非财政补助收入。 （四）附属单位上缴收入，即事业单位附属独立核算单位按照有关规定上缴的收入。 （五）经营收入，即事业单位在专业业务活动及其辅助活动之外开展非独立核算经营活动取得的收入。 （六）其他收入，即本条上述规定范围以外的各项收入，包括投资收益、利息收入、捐赠收入、非本级财政补助收入、租金收入等。"},{"i":18,"n":"第十八条","txt":"事业单位应当将各项收入全部纳入单位预算，统一核算，统一管理，未纳入预算的收入不得安排支出。"},{"i":19,"n":"第十九条","txt":"事业单位对按照规定上缴国库或者财政专户的资金，应当按照国库集中收缴的有关规定及时足额上缴，不得隐瞒、滞留、截留、占用、挪用、拖欠或坐支。"},{"i":20,"n":"第二十条","txt":"支出是指事业单位开展业务及其他活动发生的资金耗费和损失。"},{"i":21,"n":"第二十一条","txt":"事业单位支出包括： （一）事业支出，即事业单位开展专业业务活动及其辅助活动发生的基本支出和项目支出。基本支出，是指事业单位为保障其单位正常运转、完成日常工作任务所发生的支出，包括人员经费和公用经费；项目支出，是指事业单位为完成其特定的工作任务和事业发展目标所发生的支出。 （二）经营支出，即事业单位在专业业务活动及其辅助活动之外开展非独立核算经营活动发生的支出。 （三）对附属单位补助支出，即事业单位用财政补助收入之外的收入对附属单位补助发生的支出。 （四）上缴上级支出，即事业单位按照财政部门和主管部门的规定上缴上级单位的支出。 （五）其他支出，即本条上述规定范围以外的各项支出，包括利息支出、捐赠支出等。"},{"i":22,"n":"第二十二条","txt":"事业单位应当将各项支出全部纳入单位预算，实行项目库管理，建立健全支出管理制度。"},{"i":23,"n":"第二十三条","txt":"事业单位的支出应当厉行节约，严格执行国家有关财务规章制度规定的开支范围及开支标准；国家有关财务规章制度没有统一规定的，由事业单位规定，报主管部门和财政部门备案。事业单位的规定违反法律制度和国家政策的，主管部门和财政部门应当责令改正。"},{"i":24,"n":"第二十四条","txt":"事业单位从财政部门和主管部门取得的有指定项目和用途的专项资金，应当专款专用、单独核算，并按照规定报送专项资金使用情况的报告，接受财政部门或者主管部门的检查、验收。"},{"i":25,"n":"第二十五条","txt":"事业单位应当加强经济核算，可以根据开展业务活动及其他活动的实际需要，实行成本核算。成本核算的具体办法按照国务院财政部门相关规定执行。"},{"i":26,"n":"第二十六条","txt":"事业单位应当严格执行国库集中支付制度和政府采购制度等有关规定。"},{"i":27,"n":"第二十七条","txt":"事业单位应当依法加强各类票据管理，确保票据来源合法、内容真实、使用正确，不得使用虚假票据。"},{"i":28,"n":"第二十八条","txt":"结转和结余是指事业单位年度收入与支出相抵后的余额。 结转资金是指当年预算已执行但未完成，或者因故未执行，下一年度需要按照原用途继续使用的资金。结余资金是指当年预算工作目标已完成，或者因故终止，当年剩余的资金。 经营收支结转和结余应当单独反映。"},{"i":29,"n":"第二十九条","txt":"财政拨款结转和结余的管理，应当按照国家有关规定执行。"},{"i":30,"n":"第三十条","txt":"非财政拨款结转按照规定结转下一年度继续使用。非财政拨款结余可以按照国家有关规定提取职工福利基金，剩余部分用于弥补以后年度单位收支差额；国家另有规定的，从其规定。"},{"i":31,"n":"第三十一条","txt":"事业单位应当加强非财政拨款结余的管理，盘活存量，统筹安排、合理使用，支出不得超出非财政拨款结余规模。"},{"i":32,"n":"第三十二条","txt":"专用基金是指事业单位按照规定提取或者设置的有专门用途的资金。 专用基金管理应当遵循先提后用、专款专用的原则，支出不得超出基金规模。"},{"i":33,"n":"第三十三条","txt":"专用基金包括职工福利基金和其他专用基金。 职工福利基金是指按照非财政拨款结余的一定比例提取以及按照其他规定提取转入，用于单位职工的集体福利设施、集体福利待遇等的资金。 其他专用基金是指除职工福利基金外，按照有关规定提取或者设置的专用资金。"},{"i":34,"n":"第三十四条","txt":"事业单位应当将专用基金纳入预算管理，结合实际需要按照规定提取，保持合理规模，提高使用效益。专用基金余额较多的，应当降低提取比例或者暂停提取；确需调整用途的，由主管部门会同本级财政部门确定。"},{"i":35,"n":"第三十五条","txt":"各项基金的提取比例和管理办法，国家有统一规定的，按照统一规定执行；没有统一规定的，由主管部门会同本级财政部门确定。"},{"i":36,"n":"第三十六条","txt":"资产是指事业单位依法直接支配的各类经济资源。"},{"i":37,"n":"第三十七条","txt":"事业单位的资产包括流动资产、固定资产、在建工程、无形资产、对外投资、公共基础设施、政府储备物资、文物文化资产、保障性住房等。"},{"i":38,"n":"第三十八条","txt":"事业单位应当建立健全单位资产管理制度，明确资产使用人和管理人的岗位责任，按照国家规定设置国有资产台账，加强和规范资产配置、使用和处置管理，维护资产安全完整，提高资产使用效率。涉及资产评估的，按照国家有关规定执行。 事业单位应当汇总编制本单位行政事业性国有资产管理情况报告。 事业单位应当定期或者不定期对资产进行盘点、对账。出现资产盘盈盘亏的，应当按照财务、会计和资产管理制度有关规定处理，做到账实相符和账账相符。 事业单位对需要办理权属登记的资产应当依法及时办理。"},{"i":39,"n":"第三十九条","txt":"事业单位应当根据依法履行职能和事业发展的需要，结合资产存量、资产配置标准、绩效目标和财政承受能力配置资产。优先通过调剂方式配置资产。不能调剂的，可以采用购置、建设、租用等方式。"},{"i":40,"n":"第四十条","txt":"流动资产是指可以在一年以内变现或者耗用的资产，包括现金、各种存款、应收及预付款项、存货等。 前款所称存货是指事业单位在开展业务活动及其他活动中为耗用或出售而储存的资产，包括材料、燃料、包装物和低值易耗品以及未达到固定资产标准的用具、装具、动植物等。 事业单位货币性资产损失核销，应当经主管部门审核同意后报本级财政部门审批。"},{"i":41,"n":"第四十一条","txt":"固定资产是指使用期限超过一年，单位价值在1000元以上，并在使用过程中基本保持原有物质形态的资产。单位价值虽未达到规定标准，但是耐用时间在一年以上的大批同类物资，作为固定资产管理。 行业事业单位的固定资产明细目录由国务院主管部门制定，报国务院财政部门备案。"},{"i":42,"n":"第四十二条","txt":"在建工程是指已经发生必要支出，但尚未达到交付使用状态的建设工程。 在建工程达到交付使用状态时，应当按照规定办理工程竣工财务决算和资产交付使用，期限最长不得超过1年。"},{"i":43,"n":"第四十三条","txt":"无形资产是指不具有实物形态而能为使用者提供某种权利的资产，包括专利权、商标权、著作权、土地使用权、非专利技术以及其他财产权利。 事业单位转让无形资产取得的收入、取得无形资产发生的支出，应当按照国家有关规定处理。"},{"i":44,"n":"第四十四条","txt":"对外投资是指事业单位依法利用货币资金、实物、无形资产等方式向其他单位的投资。 事业单位应当严格控制对外投资。利用国有资产对外投资应当有利于事业发展和实现国有资产保值增值，符合国家有关规定，经可行性研究和集体决策，按照规定的权限和程序进行。事业单位不得使用财政拨款及其结余进行对外投资，不得从事股票、期货、基金、企业债券等投资，国家另有规定的除外。 事业单位应当明确对外投资形成的股权及其相关权益管理责任，按照国家有关规定将对外投资形成的股权纳入经营性国有资产集中统一监管体系。"},{"i":45,"n":"第四十五条","txt":"公共基础设施、政府储备物资、文物文化资产、保障性住房等资产管理的具体办法，由国务院财政部门会同有关部门制定。"},{"i":46,"n":"第四十六条","txt":"事业单位资产处置应当遵循公开、公平、公正和竞争、择优的原则，严格履行相关审批程序。 事业单位出租、出借资产应当严格履行相关审批程序。"},{"i":47,"n":"第四十七条","txt":"事业单位应当在确保安全使用的前提下，推进本单位大型设备等国有资产共享共用工作，可以对提供方给予合理补偿。"},{"i":48,"n":"第四十八条","txt":"负债是指事业单位所承担的能以货币计量，需要以资产或者劳务偿还的债务。"},{"i":49,"n":"第四十九条","txt":"事业单位的负债包括借入款项、应付款项、暂存款项、应缴款项等。 应缴款项包括事业单位按照国家有关规定收取的应当上缴国库或者财政专户的资金、应缴税费，以及其他应当上缴的款项。"},{"i":50,"n":"第五十条","txt":"事业单位应当对不同性质的负债分类管理，及时清理并按照规定办理结算，保证各项负债在规定期限内偿还。"},{"i":51,"n":"第五十一条","txt":"事业单位应当建立健全财务风险预警和控制机制，规范和加强借入款项管理，如实反映依法举借债务情况，严格执行审批程序，不得违反规定融资或者提供担保。"},{"i":52,"n":"第五十二条","txt":"事业单位发生划转、改制、撤销、合并、分立时，应当进行清算。"},{"i":53,"n":"第五十三条","txt":"事业单位清算，应当在主管部门和财政部门的监督指导下，对单位的财产、债权、债务等进行全面清理，编制财产目录和债权、债务清单，提出财产作价依据和债权、债务处理办法，做好资产和负债的移交、接收、划转和管理工作，并妥善处理各项遗留问题。"},{"i":54,"n":"第五十四条","txt":"事业单位清算结束后，经主管部门审核并报财政部门批准，其资产和负债分别按照下列办法处理： （一）因隶属关系改变，成建制划转的事业单位，全部资产和负债无偿移交，并相应划转经费指标。 （二）转为企业的事业单位，全部资产扣除负债后，转作国家资本金。 （三）撤销的事业单位，全部资产和负债由主管部门和财政部门核准处理。 （四）合并的事业单位，全部资产和负债移交接收单位或者新组建单位，合并后多余的资产由主管部门和财政部门核准处理。 （五）分立的事业单位，全部资产和负债按照有关规定移交分立后的事业单位，并相应划转经费指标。"},{"i":55,"n":"第五十五条","txt":"事业单位应当按国家有关规定向主管部门和财政部门以及其他有关的报告使用者提供财务报告、决算报告。 事业单位财务会计和预算会计要素的确认、计量、记录、报告应当遵循政府会计准则制度的规定。"},{"i":56,"n":"第五十六条","txt":"财务报告主要以权责发生制为基础编制，综合反映事业单位特定日期财务状况和一定时期运行情况等信息。"},{"i":57,"n":"第五十七条","txt":"财务报告由财务报表和财务分析两部分组成。财务报表主要包括资产负债表、收入费用表等会计报表和报表附注。财务分析的内容主要包括财务状况分析、运行情况分析和财务管理情况等。"},{"i":58,"n":"第五十八条","txt":"决算报告主要以收付实现制为基础编制，综合反映事业单位年度预算收支执行结果等信息。"},{"i":59,"n":"第五十九条","txt":"决算报告由决算报表和决算分析两部分组成。决算报表主要包括收入支出表、财政拨款收入支出表等。决算分析的内容主要包括收支预算执行分析、资金使用效益分析和机构人员情况等。"},{"i":60,"n":"第六十条","txt":"事业单位财务监督主要包括对预算管理、收入管理、支出管理、结转和结余管理、专用基金管理、资产管理、负债管理等的监督。"},{"i":61,"n":"第六十一条","txt":"事业单位财务监督应当实行事前监督、事中监督、事后监督相结合，日常监督与专项监督相结合。"},{"i":62,"n":"第六十二条","txt":"事业单位应当建立健全内部控制制度、经济责任制度、财务信息披露制度等监督制度，依法公开财务信息。"},{"i":63,"n":"第六十三条","txt":"事业单位应当遵守财经纪律和财务制度，依法接受主管部门和财政、审计部门的监督。"},{"i":64,"n":"第六十四条","txt":"各级事业单位、主管部门和财政部门及其工作人员存在违反本规则规定的行为，以及其他滥用职权、玩忽职守、徇私舞弊等违法违规行为的，依法追究相应责任。"},{"i":65,"n":"第六十五条","txt":"事业单位基本建设投资的财务管理，应当执行本规则，但国家基本建设投资财务管理制度另有规定的，从其规定。"},{"i":66,"n":"第六十六条","txt":"参照公务员法管理的事业单位财务制度的适用，由国务院财政部门另行规定。"},{"i":67,"n":"第六十七条","txt":"接受国家经常性资助的社会力量举办的公益服务性组织和社会团体，依照本规则执行；其他社会力量举办的公益服务性组织和社会团体，可以参照本规则执行。"},{"i":68,"n":"第六十八条","txt":"下列事业单位或者事业单位特定项目，执行企业财务制度，不执行本规则： （一）纳入企业财务管理体系的事业单位和事业单位附属独立核算的生产经营单位； （二）事业单位经营的接受外单位要求投资回报的项目； （三）经主管部门和财政部门批准的具备条件的其他事业单位。"},{"i":69,"n":"第六十九条","txt":"行业特点突出，需要制定行业事业单位财务管理制度的，由国务院财政部门会同有关主管部门根据本规则制定。"},{"i":70,"n":"第七十条","txt":"省、自治区、直辖市人民政府财政部门可以根据本规则结合本地区实际情况制定事业单位具体财务管理办法。"},{"i":71,"n":"第七十一条","txt":"本规则自2022年3月1日起施行。《事业单位财务规则》（财政部令第68号）同时废止。"}],"dailijizhangguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了加强代理记账机构的管理，规范代理记账业务， 促进代理记账行业的健康发展，根据《中华人民共和国会计法》及其他法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"设立代理记账机构，以及委托人委托代理记账机构办 理代理记账业务，适用本办法。 本办法所称代理记账机构是指从事代理记账业务的中介机构。 本办法所称委托人是指委托代理记账机构办理会计业务的单位。 本办法所称代理记账是指代理记账机构接受委托办理会计业务。"},{"i":3,"n":"第三条","txt":"申请设立除会计师事务所以外的代理记账机构，应当 经所在地的县级以上人民政府财政部门（以下简称审批机关）批准，并领取由财政部统一印制的代理记账许可证书。具体审批机关由省、自治区、直辖市、计划单列市人民政府财政部 门确定。"},{"i":4,"n":"第四条","txt":"设立代理记账机构，除国家法律、行政法规另有规定外，应当符合下列条件： (一) 3名以上持有会计从业资格证书的专职从业人员； (二) 主管代理记账业务的负责人具有会计师以上专业技术职务资格； (三) 有固定的办公场所； (四) 有健全的代理记账业务规范和财务会计管理制度。"},{"i":5,"n":"第五条","txt":"申请代理记账资格，应当向审批机关提交申请报告并附送下列材料： (一) 机构的协议或者章程； (二) 从业人员身份证明、会计从业资格证书，主管代理记账业务的负责人具备会计师以上专业技术职务资格的证明材料； (三) 主管代理记账业务的负责人、持有会计从业资格证书的专职从业人员在机构专职从业的书面承诺； (四) 办公地址及办公用房产权或者使用权证明； (五) 代理记账业务规范和财务会计管理制度； (六) 工商行政管理部门核准机构名称的有关材料。"},{"i":6,"n":"第六条","txt":"审批机关应当自受理申请之日起20日内决定批准或 者不批准。20日内不能作出决定的，经审批机关负责人批准可延长10日，并应当将延长期限的理由告知申请人。"},{"i":7,"n":"第七条","txt":"审批机关经审查符合法定条件的，应当自作出批准决 定之日起10日内向申请人下达批准文件、颁发代理记账许可证书。审批机关决定不予批准的，应当向申请人下达书面决定，说明理由，并告知申请人享有依法申请行政复议或者提起 行政诉讼的权利。 省级以下人民政府财政部门作出批准决定的，审批机关应当将批准文件抄送所在地省级人民政府财政部门。"},{"i":8,"n":"第八条","txt":"申请人经批准取得代理记账许可证书后，应当依法办 理工商登记。"},{"i":9,"n":"第九条","txt":"代理记账机构应当在办公场所的显著位置放置代理记 账许可证书。"},{"i":10,"n":"第十条","txt":"代理记账机构名称、主管代理记账业务负责人、办公地点发生变更的，应当依法向审批机关办理变更登记。"},{"i":11,"n":"第十一条","txt":"依法应当设置会计账簿但不具备设置会计机构或会计人员条件的单位，应当委托代理记账机构办理会计业务。"},{"i":12,"n":"第十二条","txt":"代理记账机构可以接受委托，受托办理委托人的下 列业务： (一) 根据委托人提供的原始凭证和其他资料，按照国家统一的会计制度的规定进行会计核算，包括审核原始凭证、填制记账 凭证、登记会计账簿、编制财务会计报告等； (二) 对外提供财务会计报告； (三) 向税务机关提供税务资料； (四) 委托人委托的其他会计业务。"},{"i":13,"n":"第十三条","txt":"委托人委托代理记账机构代理记账，应当在相互协 商的基础上，订立书面委托合同。委托合同除应具备法律规定的基本条款外，应当明确下列内容： (一) 委托人、受托人对会计资料真实性、完整性承担的责任； (二) 会计资料传递程序和签收手续； (三) 编制和提供财务会计报告的要求； (四) 会计档案的保管要求及相应责任； (五) 委托人、受托人终止委托合同应当办理的会计交接事宜。"},{"i":14,"n":"第十四条","txt":"委托代理记账的委托人应当履行下列义务： (一) 对本单位发生的经济业务事项，应当填制或者取得符合国家统一的会计制度规定的原始凭证； (二) 应当配备专人负责日常货币收支和保管； (三) 及时向代理记账机构提供真实、完整的原始凭证和其他相关资料； (四) 对于代理记账机构退回的要求按照国家统一的会计制度规定进行更正、补充的原始凭证，应当及时予以更正、补充。"},{"i":15,"n":"第十五条","txt":"代理记账机构及其从业人员应当履行下列义务： (一) 按照委托合同办理代理记账业务，遵守有关法律、行政法规和国家统一的会计制度的规定； (二) 对在执行业务中知悉的商业秘密应当保密； (三) 对委托人示意其作出不当的会计处理，提供不实的会计资料，以及其他不符合法律、行政法规和国家统一的会计制度规 定的要求，应当拒绝； (四) 对委托人提出的有关会计处理原则问题应当予以解释。"},{"i":16,"n":"第十六条","txt":"代理记账机构为委托人编制的财务会计报告，经代 理记账机构负责人和委托人签名并盖章后，按照有关法律、行政法规和国家统一的会计制度的规定对外提供。"},{"i":17,"n":"第十七条","txt":"委托人对代理记账机构在委托合同约定范围内的行 为承担责任。 代理记账机构对其专职从业人员和兼职从业人员的业务活动承担责任。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府财政部门对代理记账机构及其从 事代理记账业务情况实施监督检查。"},{"i":19,"n":"第十九条","txt":"代理记账机构应当于每年4月30日之前，向审批 机关报送下列材料： (一) 代理记账机构基本情况表(附表)； (二) 营业执照、办公用房产权或者使用权证明； (三) 专职及兼职从业人员身份证明、会计从业资格证书、会计专业技术职务资格证书。"},{"i":20,"n":"第二十条","txt":"代理记账机构采取欺骗手段获得代理记账许可证书 的，由审批机关撤销其代理记账资格。 代理记账机构在经营期间达不到本办法规定的设立条件的，由县级以上人民政府财政部门责令其在不超过2个月的 期限内整改；逾期仍达不到规定条件的，由审批机关撤回代理记账资格。"},{"i":21,"n":"第二十一条","txt":"代理记账机构有下列情形之一的，审批机关应当 办理注销手续，并收回批准证书或予以公告： （一）代理记账机构依法终止的； （二）代理记账机构的行政许可被依法撤销或撤回的； （三）法律、法规规定的应当注销行政许可的其他情形。"},{"i":22,"n":"第二十二条","txt":"代理记账机构有下列情形之一的，由县级以上人 民政府财政部门责令其改正，拒不改正的，予以公告： (一) 违反本办法第九条、第十条规定的； (二) 违反本办法第十五条、第十九条规定又不向审批机关说明原因的。"},{"i":23,"n":"第二十三条","txt":"代理记账机构及其从事代理记账业务人员在办理 业务中违反会计法律、行政法规和国家统一的会计制度规定的，由县级以上人民政府财政部门依据《中华人民共和国会计法》及相关法规的规定处理。 代理记账机构违反本办法和国家有关规定造成委托人会计核算混乱、损害国家和委托人利益，委托人故意向代理记账机构隐瞒真实情况或者委托人会同代理记 账机构共同提供不真实会计资料的，应当承担相应法律责任。"},{"i":24,"n":"第二十四条","txt":"对于未经批准从事代理记账业务的，由县级以上 人民政府财政部门责令其改正，并予以公告。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府财政部门及其工作人员在实施 行政管理过程中，滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"本办法规定的审批期限均以工作日计算，不含法 定节假日。"},{"i":27,"n":"第二十七条","txt":"省级人民政府财政部门可以根据本办法制定具体实施办法，报财政部备案。"},{"i":28,"n":"第二十八条","txt":"外商投资代理记账机构的申请按照本办法和其他 有关规定办理。"},{"i":29,"n":"第二十九条","txt":"本办法自2005年3月1日起施行，财政部 1994年6月23日发布的《代理记账管理暂行办法》[（94）财会字第24号]同时废止。 附表： 代理记账机构基本情况表 　　　　　　年度 机 构名称 组 织形式 成 立日期 批 准文号 代 理记账许可证编号 注 册资本（出资总额） 机 构负责人姓名 主 管代理记账业务负责人姓名 股 东（合伙人）总数 专 职从业人员数量 本 年度业务总收入 其 中：代理记账业务收入 从 业 人 员 简 历 姓 名 会 计从业资格 证书编号 是 否专职人员 （专职/兼职） 人 事档案存放单位 办 公场所 通 讯地址 邮 编 联 系人 电 子邮件 联 系电话 传 真 上一年度有 无受过何种处罚 我机构保证 本表所填内容全部属实。 　　　　　　　　　代理记账机构负责人签名并盖章： 　　　　　　　　　代理记账机构（盖章） 　　　　　　　　　　　　　　　　　　年　　月"}],"dailijizhangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强代理记账资格管理，规范代理记账活动，促进代理记账行业健康发展，根据《中华人民共和国会计法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"代理记账资格的申请、取得和管理，以及代理记账机构从事代理记账业务，适用本办法。 本办法所称代理记账机构是指依法取得代理记账资格，从事代理记账业务的机构。 本办法所称代理记账是指代理记账机构接受委托办理会计业务。"},{"i":3,"n":"第三条","txt":"除会计师事务所以外的机构从事代理记账业务应当经县级以上地方人民政府财政部门（以下简称审批机关）批准，领取由财政部统一规定样式的代理记账许可证书。具体审批机关由省、自治区、直辖市、计划单列市人民政府财政部门确定。 会计师事务所及其分所可以依法从事代理记账业务。"},{"i":4,"n":"第四条","txt":"符合下列条件的机构可以申请代理记账资格： （一）为依法设立的企业； （二）持有会计从业资格证书的专职从业人员不少于3名； （三）主管代理记账业务的负责人具有会计师以上专业技术职务资格且为专职从业人员； （四）有健全的代理记账业务内部规范。"},{"i":5,"n":"第五条","txt":"申请代理记账资格的机构，应当向所在地的审批机关提交申请报告并附送下列材料： （一）营业执照复印件； （二）从业人员会计从业资格证书，主管代理记账业务的负责人具备会计师以上专业技术职务资格的证明； （三）专职从业人员在本机构专职从业的书面承诺； （四）代理记账业务内部规范。"},{"i":6,"n":"第六条","txt":"审批机关审批代理记账资格应当按照下列程序办理： （一）申请人提交的申请材料不齐全或不符合规定形式的，应当在5日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即视为受理；申请人提交的申请材料齐全、符合规定形式的，或者申请人按照要求提交全部补正申请材料的，应当受理申请。 （二）受理申请后应当按照规定对申请材料进行审核，并自受理申请之日起20日内作出批准或者不予批准的决定。20日内不能作出决定的，经本审批机关负责人批准可延长10日，并应当将延长期限的理由告知申请人。 （三）作出批准决定的，应当自作出决定之日起10日内向申请人发放代理记账许可证书，并向社会公示。 （四）作出不予批准决定的，应当自作出决定之日起10日内书面通知申请人。书面通知应当说明不予批准的理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":7,"n":"第七条","txt":"申请人应当自取得代理记账许可证书之日起20日内通过企业信用信息公示系统向社会公示。"},{"i":8,"n":"第八条","txt":"代理记账机构名称、主管代理记账业务的负责人发生变更，设立或撤销分支机构，跨原审批机关管辖地迁移办公地点的，应当自作出变更决定或变更之日起30日内依法向审批机关办理变更登记，并应当自变更登记完成之日起20日内通过企业信用信息公示系统向社会公示。 代理记账机构变更名称的，应当向审批机关提交营业执照复印件，领取新的代理记账许可证书，并同时交回原代理记账许可证书。 代理记账机构跨原审批机关管辖地迁移办公地点的，迁出地审批机关应当及时将代理记账机构的相关信息及材料移交迁入地审批机关。"},{"i":9,"n":"第九条","txt":"代理记账机构设立分支机构的，分支机构应当及时向其所在地的审批机关办理备案登记。 分支机构名称、主管代理记账业务的负责人发生变更的，分支机构应当按照要求向其所在地的审批机关办理变更登记。 代理记账机构应当在人事、财务、业务、技术标准、信息管理等方面对其设立的分支机构进行实质性的统一管理，并对分支机构的业务活动、执业质量和债务承担法律责任。"},{"i":10,"n":"第十条","txt":"未设置会计机构或配备会计人员的单位，应当委托代理记账机构办理会计业务。"},{"i":11,"n":"第十一条","txt":"代理记账机构可以接受委托办理下列业务： （一）根据委托人提供的原始凭证和其他相关资料，按照国家统一的会计制度的规定进行会计核算，包括审核原始凭证、填制记账凭证、登记会计账簿、编制财务会计报告等； （二）对外提供财务会计报告； （三）向税务机关提供税务资料； （四）委托人委托的其他会计业务。"},{"i":12,"n":"第十二条","txt":"委托人委托代理记账机构代理记账，应当在相互协商的基础上，订立书面委托合同。委托合同除应具备法律规定的基本条款外，应当明确下列内容： （一）双方对会计资料真实性、完整性各自应当承担的责任； （二）会计资料传递程序和签收手续； （三）编制和提供财务会计报告的要求； （四）会计档案的保管要求及相应的责任； （五）终止委托合同应当办理的会计业务交接事宜。"},{"i":13,"n":"第十三条","txt":"委托人应当履行下列义务： （一）对本单位发生的经济业务事项，应当填制或者取得符合国家统一的会计制度规定的原始凭证； （二）应当配备专人负责日常货币收支和保管； （三）及时向代理记账机构提供真实、完整的原始凭证和其他相关资料； （四）对于代理记账机构退回的，要求按照国家统一的会计制度的规定进行更正、补充的原始凭证，应当及时予以更正、补充。"},{"i":14,"n":"第十四条","txt":"代理记账机构及其从业人员应当履行下列义务： （一）遵守有关法律、法规和国家统一的会计制度的规定，按照委托合同办理代理记账业务； （二）对在执行业务中知悉的商业秘密予以保密； （三）对委托人要求其作出不当的会计处理，提供不实的会计资料，以及其他不符合法律、法规和国家统一的会计制度行为的，予以拒绝； （四）对委托人提出的有关会计处理相关问题予以解释。"},{"i":15,"n":"第十五条","txt":"代理记账机构为委托人编制的财务会计报告，经代理记账机构负责人和委托人负责人签名并盖章后，按照有关法律、法规和国家统一的会计制度的规定对外提供。"},{"i":16,"n":"第十六条","txt":"县级以上人民政府财政部门对代理记账机构及其从事代理记账业务情况实施监督检查。"},{"i":17,"n":"第十七条","txt":"代理记账机构应当于每年4月30日之前，向审批机关报送下列材料： （一）代理记账机构基本情况表（附表）； （二）专职从业人员变动情况。 代理记账机构设立分支机构的，分支机构应当于每年4月30日之前向其所在地的审批机关报送上述材料。"},{"i":18,"n":"第十八条","txt":"代理记账机构采取欺骗、贿赂等不正当手段取得代理记账资格的，由审批机关撤销其资格。"},{"i":19,"n":"第十九条","txt":"代理记账机构在经营期间达不到本办法规定的资格条件的，审批机关发现后，应当责令其在60日内整改；逾期仍达不到规定条件的，由审批机关撤销其代理记账资格。"},{"i":20,"n":"第二十条","txt":"代理记账机构有下列情形之一的，审批机关应当办理注销手续，收回代理记账许可证书并予以公告： （一）代理记账机构依法终止的； （二）代理记账资格被依法撤销或撤回的； （三）法律、法规规定的应当注销的其他情形。"},{"i":21,"n":"第二十一条","txt":"代理记账机构违反本办法第七条、第八条、第九条、第十四条、第十七条规定，以及违反第五条第三项规定、作出不实承诺的，由县级以上人民政府财政部门责令其限期改正，拒不改正的，列入重点关注名单，并向社会公示，提醒其履行有关义务；情节严重的，由县级以上人民政府财政部门按照有关法律、法规给予行政处罚，并向社会公示。"},{"i":22,"n":"第二十二条","txt":"代理记账机构从业人员在办理业务中违反会计法律、法规和国家统一的会计制度的规定，造成委托人会计核算混乱、损害国家和委托人利益的，由县级以上人民政府财政部门依据《中华人民共和国会计法》等有关法律、法规的规定处理。 代理记账机构有前款行为的，县级以上人民政府财政部门应当责令其限期改正，并给予警告；有违法所得的，可以处违法所得3倍以下罚款，但最高不得超过3万元；没有违法所得的，可以处1万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"委托人故意向代理记账机构隐瞒真实情况或者委托人会同代理记账机构共同提供虚假会计资料的，应当承担相应法律责任。"},{"i":24,"n":"第二十四条","txt":"未经批准从事代理记账业务的，由县级以上人民政府财政部门按照有关法律、法规予以查处。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府财政部门及其工作人员在代理记账资格管理过程中，滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分；涉嫌犯罪的，移送司法机关处理。"},{"i":26,"n":"第二十六条","txt":"代理记账机构依法成立的行业组织，应当维护会员合法权益，建立会员诚信档案，规范会员代理记账行为，推动代理记账信息化建设。 代理记账行业组织应当接受县级以上人民政府财政部门的指导和监督。"},{"i":27,"n":"第二十七条","txt":"本办法规定的“5日”、“10日”、“20日”、“30日”均指工作日。"},{"i":28,"n":"第二十八条","txt":"省级人民政府财政部门可以根据本办法制定具体实施办法，报财政部备案。"},{"i":29,"n":"第二十九条","txt":"外商投资企业申请代理记账资格，从事代理记账业务按照本办法和其他有关规定办理。"},{"i":30,"n":"第三十条","txt":"本办法自2016年5月1日起施行，财政部2005年1月22日发布的《代理记账管理办法》（财政部令第27号）同时废止。"}],"qiyekuaijizhunzejibenzhunze":[{"i":1,"n":"第一条","txt":"为了规范企业会计确认、计量和报告行为，保证会计信息质量，根据《中华人民共和国会计法》和其他有关法律、行政法规，制定本准则。"},{"i":2,"n":"第二条","txt":"本准则适用于在中华人民共和国境内设立的企业（包括公司，下同）。"},{"i":3,"n":"第三条","txt":"企业会计准则包括基本准则和具体准则，具体准则的制定应当遵循本准则。"},{"i":4,"n":"第四条","txt":"企业应当编制财务会计报告（又称财务报告，下同）。财务会计报告的目标是向财务会计报告使用者提供与企业财务状况、经营成果和现金流量等有关的会计信息，反映企业管理层受托责任履行情况，有助于财务会计报告使用者做出经济决策。财务会计报告使用者包括投资者、债权人、政府及其有关部门和社会公众等。"},{"i":5,"n":"第五条","txt":"企业应当对其本身发生的交易或者事项进行会计确认、计量和报告。"},{"i":6,"n":"第六条","txt":"企业会计确认、计量和报告应当以持续经营为前提。"},{"i":7,"n":"第七条","txt":"企业应当划分会计期间，分期结算账目和编制财务会计报告。会计期间分为年度和中期。中期是指短于一个完整的会计年度的报告期间。"},{"i":8,"n":"第八条","txt":"企业会计应当以货币计量。"},{"i":9,"n":"第九条","txt":"企业应当以权责发生制为基础进行会计确认、计量和报告。"},{"i":10,"n":"第十条","txt":"企业应当按照交易或者事项的经济特征确定会计要素。会计要素包括资产、负债、所有者权益、收入、费用和利润。"},{"i":11,"n":"第十一条","txt":"企业应当采用借贷记账法记账。"},{"i":12,"n":"第十二条","txt":"企业应当以实际发生的交易或者事项为依据进行会计确认、计量和报告，如实反映符合确认和计量要求的各项会计要素及其他相关信息，保证会计信息真实可靠、内容完整。"},{"i":13,"n":"第十三条","txt":"企业提供的会计信息应当与财务会计报告使用者的经济决策需要相关，有助于财务会计报告使用者对企业过去、现在或者未来的情况做出评价或者预测。"},{"i":14,"n":"第十四条","txt":"企业提供的会计信息应当清晰明了，便于财务会计报告使用者理解和使用。"},{"i":15,"n":"第十五条","txt":"企业提供的会计信息应当具有可比性。 同一企业不同时期发生的相同或者相似的交易或者事项，应当采用一致的会计政策，不得随意变更。确需变更的，应当在附注中说明。 不同企业发生的相同或者相似的交易或者事项，应当采用规定的会计政策，确保会计信息口径一致、相互可比。"},{"i":16,"n":"第十六条","txt":"企业应当按照交易或者事项的经济实质进行会计确认、计量和报告，不应仅以交易或者事项的法律形式为依据。"},{"i":17,"n":"第十七条","txt":"企业提供的会计信息应当反映与企业财务状况、经营成果和现金流量等有关的所有重要交易或者事项。"},{"i":18,"n":"第十八条","txt":"企业对交易或者事项进行会计确认、计量和报告应当保持应有的谨慎，不应高估资产或者收益、低估负债或者费用。"},{"i":19,"n":"第十九条","txt":"企业对于已经发生的交易或者事项，应当及时进行会计确认、计量和报告，不得提前或者延后。"},{"i":20,"n":"第二十条","txt":"资产是指企业过去的交易或者事项形成的、由企业拥有或者控制的、预期会给企业带来经济利益的资源。 前款所指的企业过去的交易或者事项包括购买、生产、建造行为或其他交易或者事项。预期在未来发生的交易或者事项不形成资产。由企业拥有或者控制，是指企业享有某项资源的所有权，或者虽然不享有某项资源的所有权，但该资源能被企业所控制。预期会给企业带来经济利益，是指直接或者间接导致现金和现金等价物流入企业的潜力。"},{"i":21,"n":"第二十一条","txt":"符合本准则第二十条规定的资产定义的资源，在同时满足以下条件时，确认为资产: （一）与该资源有关的经济利益很可能流入企业; （二）该资源的成本或者价值能够可靠地计量。"},{"i":22,"n":"第二十二条","txt":"符合资产定义和资产确认条件的项目，应当列入资产负债表;符合资产定义、但不符合资产确认条件的项目，不应当列入资产负债表。"},{"i":23,"n":"第二十三条","txt":"负债是指企业过去的交易或者事项形成的、预期会导致经济利益流出企业的现时义务。现时义务是指企业在现行条件下已承担的义务。未来发生的交易或者事项形成的义务，不属于现时义务，不应当确认为负债。"},{"i":24,"n":"第二十四条","txt":"符合本准则第二十三条规定的负债定义的义务，在同时满足以下条件时，确认为负债: （一）与该义务有关的经济利益很可能流出企业; （二）未来流出的经济利益的金额能够可靠地计量。"},{"i":25,"n":"第二十五条","txt":"符合负债定义和负债确认条件的项目，应当列入资产负债表;符合负债定义、但不符合负债确认条件的项目，不应当列入资产负债表。"},{"i":26,"n":"第二十六条","txt":"所有者权益是指企业资产扣除负债后由所有者享有的剩余权益。公司的所有者权益又称为股东权益。"},{"i":27,"n":"第二十七条","txt":"所有者权益的来源包括所有者投入的资本、直接计入所有者权益的利得和损失、留存收益等。直接计入所有者权益的利得和损失，是指不应计入当期损益、会导致所有者权益发生增减变动的、与所有者投入资本或者向所有者分配利润无关的利得或者损失。 利得是指由企业非日常活动所形成的、会导致所有者权益增加的、与所有者投入资本无关的经济利益的流入。 损失是指由企业非日常活动所发生的、会导致所有者权益减少的、与向所有者分配利润无关的经济利益的流出。"},{"i":28,"n":"第二十八条","txt":"所有者权益金额取决于资产和负债的计量。"},{"i":29,"n":"第二十九条","txt":"所有者权益项目应当列入资产负债表。"},{"i":30,"n":"第三十条","txt":"收入是指企业在日常活动中形成的、会导致所有者权益增加的、与所有者投入资本无关的经济利益的总流入。"},{"i":31,"n":"第三十一条","txt":"收入只有在经济利益很可能流入从而导致企业资产增加或者负债减少、且经济利益的流入额能够可靠计量时才能予以确认。"},{"i":32,"n":"第三十二条","txt":"符合收入定义和收入确认条件的项目，应当列入利润表。"},{"i":33,"n":"第三十三条","txt":"费用是指企业在日常活动中发生的、会导致所有者权益减少的、与向所有者分配利润无关的经济利益的总流出。"},{"i":34,"n":"第三十四条","txt":"费用只有在经济利益很可能流出从而导致企业资产减少或者负债增加、且经济利益的流出额能够可靠计量时才能予以确认。"},{"i":35,"n":"第三十五条","txt":"企业为生产产品、提供劳务等发生的可归属于产品成本、劳务成本等的费用，应当在确认产品销售收入、劳务收入等时，将已销售产品、已提供劳务的成本等计入当期损益。企业发生的支出不产生经济利益的，或者即使能够产生经济利益但不符合或者不再符合资产确认条件的，应当在发生时确认为费用，计入当期损益。企业发生的交易或者事项导致其承担了一项负债而又不确认为一项资产的，应当在发生时确认为费用，计入当期损益。"},{"i":36,"n":"第三十六条","txt":"符合费用定义和费用确认条件的项目，应当列入利润表。"},{"i":37,"n":"第三十七条","txt":"利润是指企业在一定会计期间的经营成果。利润包括收入减去费用后的净额、直接计入当期利润的利得和损失等。"},{"i":38,"n":"第三十八条","txt":"直接计入当期利润的利得和损失，是指应当计入当期损益、会导致所有者权益发生增减变动的、与所有者投入资本或者向所有者分配利润无关的利得或者损失。"},{"i":39,"n":"第三十九条","txt":"利润金额取决于收入和费用、直接计入当期利润的利得和损失金额的计量。"},{"i":40,"n":"第四十条","txt":"利润项目应当列入利润表。"},{"i":41,"n":"第四十一条","txt":"企业在将符合确认条件的会计要素登记入账并列报于会计报表及其附注（又称财务报表，下同）时，应当按照规定的会计计量属性进行计量，确定其金额。"},{"i":42,"n":"第四十二条","txt":"会计计量属性主要包括: （一）历史成本。在历史成本计量下，资产按照购置时支付的现金或者现金等价物的金额，或者按照购置资产时所付出的对价的公允价值计量。负债按照因承担现时义务而实际收到的款项或者资产的金额，或者承担现时义务的合同金额，或者按照日常活动中为偿还负债预期需要支付的现金或者现金等价物的金额计量。 （二）重置成本。在重置成本计量下，资产按照现在购买相同或者相似资产所需支付的现金或者现金等价物的金额计量。负债按照现在偿付该项债务所需支付的现金或者现金等价物的金额计量。 （三）可变现净值。在可变现净值计量下，资产按照其正常对外销售所能收到现金或者现金等价物的金额扣减该资产至完工时估计将要发生的成本、估计的销售费用以及相关税费后的金额计量。 （四）现值。在现值计量下，资产按照预计从其持续使用和最终处置中所产生的未来净现金流入量的折现金额计量。负债按照预计期限内需要偿还的未来净现金流出量"},{"i":43,"n":"第四十三条","txt":"企业在对会计要素进行计量时，一般应当采用历史成本，采用重置成本、可变现净值、现值、公允价值计量的，应当保证所确定的会计要素金额能够取得并可靠计量。"},{"i":44,"n":"第四十四条","txt":"财务会计报告是指企业对外提供的反映企业某一特定日期的财务状况和某一会计期间的经营成果、现金流量等会计信息的文件。财务会计报告包括会计报表及其附注和其他应当在财务会计报告中披露的相关信息和资料。会计报表至少应当包括资产负债表、利润表、现金流量表等报表。小企业编制的会计报表可以不包括现金流量表。"},{"i":45,"n":"第四十五条","txt":"资产负债表是指反映企业在某一特定日期的财务状况的会计报表。"},{"i":46,"n":"第四十六条","txt":"利润表是指反映企业在一定会计期间的经营成果的会计报表。"},{"i":47,"n":"第四十七条","txt":"现金流量表是指反映企业在一定会计期间的现金和现金等价物流入和流出的会计报表。"},{"i":48,"n":"第四十八条","txt":"附注是指对在会计报表中列示项目所作的进一步说明，以及对未能在这些报表中列示项目的说明等。"},{"i":49,"n":"第四十九条","txt":"本准则由财政部负责解释。"},{"i":50,"n":"第五十条","txt":"本准则自2007年1月1日起执行。"}],"qiyecaiwutongze":[{"i":1,"n":"第一条","txt":"为了加强企业财务管理，规范企业财务行为，保护企业及其相关方的合法权益，推进现代企业制度建设，根据有关法律、行政法规的规定，制定本通则。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内依法设立的具备法人资格的国有及国有控股企业适用本通则。金融企业除外。其他企业参照执行。"},{"i":3,"n":"第三条","txt":"国有及国有控股企业（以下简称企业）应当确定内部财务管理体制，建立健全财务管理制度，控制财务风险。 企业财务管理应当按照制定的财务战略，合理筹集资金，有效营运资产，控制成本费用，规范收益分配及重组清算财务行为，加强财务监督和财务信息管理。"},{"i":4,"n":"第四条","txt":"财政部负责制定企业财务规章制度。 各级财政部门（以下通称主管财政机关）应当加强对企业财务的指导、管理、监督，其主要职责包括： （一）监督执行企业财务规章制度，按照财务关系指导企业建立健全内部财务制度。 （二）制定促进企业改革发展的财政财务政策，建立健全支持企业发展的财政资金管理制度。 （三）建立健全企业年度财务会计报告审计制度，检查企业财务会计报告质量。 （四）实施企业财务评价，监测企业财务运行状况。 （五）研究、拟订企业国有资本收益分配和国有资本经营预算的制度。 （六）参与审核属于本级人民政府及其有关部门、机构出资的企业重要改革、改制方案。 （七）根据企业财务管理的需要提供必要的帮助、服务。"},{"i":5,"n":"第五条","txt":"各级人民政府及其部门、机构，企业法人、其他组织或者自然人等企业投资者（以下通称投资者），企业经理、厂长或者实际负责经营管理的其他领导成员（以下通称经营者），依照法律、法规、本通则和企业章程的规定，履行企业内部财务管理职责。"},{"i":6,"n":"第六条","txt":"企业应当依法纳税。企业财务处理与税收法律、行政法规规定不一致的，纳税时应当依法进行调整。"},{"i":7,"n":"第七条","txt":"各级人民政府及其部门、机构出资的企业，其财务关系隶属同级财政机关。"},{"i":8,"n":"第八条","txt":"企业实行资本权属清晰、财务关系明确、符合法人治理结构要求的财务管理体制。 企业应当按照国家有关规定建立有效的内部财务管理级次。企业集团公司自行决定集团内部财务管理体制。"},{"i":9,"n":"第九条","txt":"企业应当建立财务决策制度，明确决策规则、程序、权限和责任等。法律、行政法规规定应当通过职工（代表）大会审议或者听取职工、相关组织意见的财务事项，依照其规定执行。 企业应当建立财务决策回避制度。对投资者、经营者个人与企业利益有冲突的财务决策事项，相关投资者、经营者应当回避。"},{"i":10,"n":"第十条","txt":"企业应当建立财务风险管理制度，明确经营者、投资者及其他相关人员的管理权限和责任，按照风险与收益均衡、不相容职务分离等原则，控制财务风险。"},{"i":11,"n":"第十一条","txt":"企业应当建立财务预算管理制度，以现金流为核心，按照实现企业价值最大化等财务目标的要求，对资金筹集、资产营运、成本控制、收益分配、重组清算等财务活动，实施全面预算管理。"},{"i":12,"n":"第十二条","txt":"投资者的财务管理职责主要包括： （一）审议批准企业内部财务管理制度、企业财务战略、财务规划和财务预算。 （二）决定企业的筹资、投资、担保、捐赠、重组、经营者报酬、利润分配等重大财务事项。 （三）决定企业聘请或者解聘会计师事务所、资产评估机构等中介机构事项。 （四）对经营者实施财务监督和财务考核。 （五）按照规定向全资或者控股企业委派或者推荐财务总监。投资者应当通过股东（大）会、董事会或者其他形式的内部机构履行财务管理职责，可以通过企业章程、内部制度、合同约定等方式将部分财务管理职责授予经营者。"},{"i":13,"n":"第十三条","txt":"经营者的财务管理职责主要包括： （一）拟订企业内部财务管理制度、财务战略、财务规划，编制财务预算。 （二）组织实施企业筹资、投资、担保、捐赠、重组和利润分配等财务方案，诚信履行企业偿债义务。 （三）执行国家有关职工劳动报酬和劳动保护的规定，依法缴纳社会保险费、住房公积金等，保障职工合法权益。 （四）组织财务预测和财务分析，实施财务控制。 （五）编制并提供企业财务会计报告，如实反映财务信息和有关情况。 （六）配合有关机构依法进行审计、评估、财务监督等工作。"},{"i":14,"n":"第十四条","txt":"企业可以接受投资者以货币资金、实物、无形资产、股权、特定债权等形式的出资。其中，特定债权是指企业依法发行的可转换债券、符合有关规定转作股权的债权等。 企业接受投资者非货币资产出资时，法律、行政法规对出资形式、程序和评估作价等有规定的，依照其规定执行。 企业接受投资者商标权、著作权、专利权及其他专有技术等无形资产出资的，应当符合法律、行政法规规定的比例。"},{"i":15,"n":"第十五条","txt":"企业依法以吸收直接投资、发行股份等方式筹集权益资金的，应当拟订筹资方案，确定筹资规模，履行内部决策程序和必要的报批手续，控制筹资成本。 企业筹集的实收资本，应当依法委托法定验资机构验资并出具验资报告。"},{"i":16,"n":"第十六条","txt":"企业应当执行国家有关资本管理制度，在获准工商登记后30日内，依据验资报告等向投资者出具出资证明书，确定投资者的合法权益。 企业筹集的实收资本，在持续经营期间可以由投资者依照法律、行政法规以及企业章程的规定转让或者减少，投资者不得抽逃或者变相抽回出资。 除《公司法》等有关法律、行政法规另有规定外，企业不得回购本企业发行的股份。企业依法回购股份，应当符合有关条件和财务处理办法，并经投资者决议。"},{"i":17,"n":"第十七条","txt":"对投资者实际缴付的出资超出注册资本的差额（包括股票溢价），企业应当作为资本公积管理。 经投资者审议决定后，资本公积用于转增资本。国家另有规定的，从其规定。"},{"i":18,"n":"第十八条","txt":"企业从税后利润中提取的盈余公积包括法定公积金和任意公积金，可以用于弥补企业亏损或者转增资本。法定公积金转增资本后留存企业的部分，以不少于转增前注册资本的25%为限。"},{"i":19,"n":"第十九条","txt":"企业增加实收资本或者以资本公积、盈余公积转增实收资本，由投资者履行财务决策程序后，办理相关财务事项和工商变更登记。"},{"i":20,"n":"第二十条","txt":"企业取得的各类财政资金，区分以下情况处理： （一）属于国家直接投资、资本注入的，按照国家有关规定增加国家资本或者国有资本公积。 （二）属于投资补助的，增加资本公积或者实收资本。国家拨款时对权属有规定的，按规定执行；没有规定的，由全体投资者共同享有。 （三）属于贷款贴息、专项经费补助的，作为企业收益处理。 （四）属于政府转贷、偿还性资助的，作为企业负债管理。 （五）属于弥补亏损、救助损失或者其他用途的，作为企业收益处理。"},{"i":21,"n":"第二十一条","txt":"企业依法以借款、发行债券、融资租赁等方式筹集债务资金的，应当明确筹资目的，根据资金成本、债务风险和合理的资金需求，进行必要的资本结构决策，并签订书面合同。 企业筹集资金用于固定资产投资项目的，应当遵守国家产业政策、行业规划、自有资本比例及其他规定。 企业筹集资金，应当按规定核算和使用，并诚信履行合同，依法接受监督。"},{"i":22,"n":"第二十二条","txt":"企业应当根据风险与收益均衡等原则和经营需要，确定合理的资产结构，并实施资产结构动态管理。"},{"i":23,"n":"第二十三条","txt":"企业应当建立内部资金调度控制制度，明确资金调度的条件、权限和程序，统一筹集、使用和管理资金。企业支付、调度资金，应当按照内部财务管理制度的规定，依据有效合同、合法凭证，办理相关手续。 企业向境外支付、调度资金应当符合国家有关外汇管理的规定。 企业集团可以实行内部资金集中统一管理，但应当符合国家有关金融管理等法律、行政法规规定，并不得损害成员企业的利益。"},{"i":24,"n":"第二十四条","txt":"企业应当建立合同的财务审核制度，明确业务流程和审批权限，实行财务监控。 企业应当加强应收款项的管理，评估客户信用风险，跟踪客户履约情况，落实收账责任，减少坏账损失。"},{"i":25,"n":"第二十五条","txt":"企业应当建立健全存货管理制度，规范存货采购审批、执行程序，根据合同的约定以及内部审批制度支付货款。 企业选择供货商以及实施大宗采购，可以采取招标等方式进行。"},{"i":26,"n":"第二十六条","txt":"企业应当建立固定资产购建、使用、处置制度。 企业自行选择、确定固定资产折旧办法，可以征询中介机构、有关专家的意见，并由投资者审议批准。固定资产折旧办法一经选用，不得随意变更。确需变更的，应当说明理由，经投资者审议批准。 企业购建重要的固定资产、进行重大技术改造，应当经过可行性研究，按照内部审批制度履行财务决策程序，落实决策和执行责任。 企业在建工程项目交付使用后，应当在一个年度内办理竣工决算。"},{"i":27,"n":"第二十七条","txt":"企业对外投资应当遵守法律、行政法规和国家有关政策的规定，符合企业发展战略的要求，进行可行性研究，按照内部审批制度履行批准程序，落实决策和执行的责任。 企业对外投资应当签订书面合同，明确企业投资权益，实施财务监管。依据合同支付投资款项，应当按照企业内部审批制度执行。 企业向境外投资的，还应当经投资者审议批准，并遵守国家境外投资项目核准和外汇管理等相关规定。"},{"i":28,"n":"第二十八条","txt":"企业通过自创、购买、接受投资等方式取得的无形资产，应当依法明确权属，落实有关经营、管理的财务责任。 无形资产出现转让、租赁、质押、授权经营、连锁经营、对外投资等情形时，企业应当签订书面合同，明确双方的权利义务，合理确定交易价格。"},{"i":29,"n":"第二十九条","txt":"企业对外担保应当符合法律、行政法规及有关规定，根据被担保单位的资信及偿债能力，按照内部审批制度采取相应的风险控制措施，并设立备查账簿登记，实行跟踪监督。 企业对外捐赠应当符合法律、行政法规及有关财务规定，制定实施方案，明确捐赠的范围和条件，落实执行责任，严格办理捐赠资产的交接手续。"},{"i":30,"n":"第三十条","txt":"企业从事期货、期权、证券、外汇交易等业务或者委托其他机构理财，不得影响主营业务的正常开展，并应当签订书面合同，建立交易报告制度，定期对账，控制风险。"},{"i":31,"n":"第三十一条","txt":"企业从事代理业务，应当严格履行合同，实行代理业务与自营业务分账管理，不得挪用客户资金、互相转嫁经营风险。"},{"i":32,"n":"第三十二条","txt":"企业应当建立各项资产损失或者减值准备管理制度。各项资产损失或者减值准备的计提标准，一经选用，不得随意变更。企业在制订计提标准时可以征询中介机构、有关专家的意见。 对计提损失或者减值准备后的资产，企业应当落实监管责任。能够收回或者继续使用以及没有证据证明实际损失的资产，不得核销。"},{"i":33,"n":"第三十三条","txt":"企业发生的资产损失，应当及时予以核实、查清责任，追偿损失，按照规定程序处理。 企业重组中清查出的资产损失，经批准后依次冲减未分配利润、盈余公积、资本公积和实收资本。"},{"i":34,"n":"第三十四条","txt":"企业以出售、抵押、置换、报废等方式处理资产时，应当按照国家有关规定和企业内部财务管理制度规定的权限和程序进行。其中，处理主要固定资产涉及企业经营业务调整或者资产重组的，应当根据投资者审议通过的业务调整或者资产重组方案实施。"},{"i":35,"n":"第三十五条","txt":"企业发生关联交易的，应当遵守国家有关规定，按照独立企业之间的交易计价结算。投资者或者经营者不得利用关联交易非法转移企业经济利益或者操纵关联企业的利润。"},{"i":36,"n":"第三十六条","txt":"企业应当建立成本控制系统，强化成本预算约束，推行质量成本控制办法，实行成本定额管理、全员管理和全过程控制。"},{"i":37,"n":"第三十七条","txt":"企业实行费用归口、分级管理和预算控制，应当建立必要的费用开支范围、标准和报销审批制度。"},{"i":38,"n":"第三十八条","txt":"企业技术研发和科技成果转化项目所需经费，可以通过建立研发准备金筹措，据实列入相关资产成本或者当期费用。 符合国家规定条件的企业集团，可以集中使用研发费用，用于企业主导产品和核心技术的自主研发。"},{"i":39,"n":"第三十九条","txt":"企业依法实施安全生产、清洁生产、污染治理、地质灾害防治、生态恢复和环境保护等所需经费，按照国家有关标准列入相关资产成本或者当期费用。"},{"i":40,"n":"第四十条","txt":"企业发生销售折扣、折让以及支付必要的佣金、回扣、手续费、劳务费、提成、返利、进场费、业务奖励等支出的，应当签订相关合同，履行内部审批手续。 企业开展进出口业务收取或者支付的佣金、保险费、运费，按照合同规定的价格条件处理。 企业向个人以及非经营单位支付费用的，应当严格履行内部审批及支付的手续。"},{"i":41,"n":"第四十一条","txt":"企业可以根据法律、法规和国家有关规定，对经营者和核心技术人员实行与其他职工不同的薪酬办法，属于本级人民政府及其部门、机构出资的企业，应当将薪酬办法报主管财政机关备案。"},{"i":42,"n":"第四十二条","txt":"企业应当按照劳动合同及国家有关规定支付职工报酬，并为从事高危作业的职工缴纳团体人身意外伤害保险费，所需费用直接作为成本（费用）列支。 经营者可以在工资计划中安排一定数额，对企业技术研发、降低能源消耗、治理“三废”、促进安全生产、开拓市场等作出突出贡献的职工给予奖励。"},{"i":43,"n":"第四十三条","txt":"企业应当依法为职工支付基本医疗、基本养老、失业、工伤等社会保险费，所需费用直接作为成本（费用）列支。 已参加基本医疗、基本养老保险的企业，具有持续盈利能力和支付能力的，可以为职工建立补充医疗保险和补充养老保险，所需费用按照省级以上人民政府规定的比例从成本（费用）中提取。超出规定比例的部分，由职工个人负担。"},{"i":44,"n":"第四十四条","txt":"企业为职工缴纳住房公积金以及职工住房货币化分配的财务处理，按照国家有关规定执行。 职工教育经费按照国家规定的比例提取，专项用于企业职工后续职业教育和职业培训。 工会经费按照国家规定比例提取并拨缴工会。"},{"i":45,"n":"第四十五条","txt":"企业应当依法缴纳行政事业性收费、政府性基金以及使用或者占用国有资源的费用等。 企业对没有法律法规依据或者超过法律法规规定范围和标准的各种摊派、收费、集资，有权拒绝。"},{"i":46,"n":"第四十六条","txt":"企业不得承担属于个人的下列支出： （一）娱乐、健身、旅游、招待、购物、馈赠等支出。 （二）购买商业保险、证券、股权、收藏品等支出。 （三）个人行为导致的罚款、赔偿等支出。 （四）购买住房、支付物业管理费等支出。 （五）应由个人承担的其他支出。"},{"i":47,"n":"第四十七条","txt":"投资者、经营者及其他职工履行本企业职务或者以企业名义开展业务所得的收入，包括销售收入以及对方给予的销售折扣、折让、佣金、回扣、手续费、劳务费、提成、返利、进场费、业务奖励等收入，全部属于企业。 企业应当建立销售价格管理制度，明确产品或者劳务的定价和销售价格调整的权限、程序与方法，根据预期收益、资金周转、市场竞争、法律规范约束等要求，采取相应的价格策略，防范销售风险。"},{"i":48,"n":"第四十八条","txt":"企业出售股权投资，应当按照规定的程序和方式进行。股权投资出售底价，参照资产评估结果确定，并按照合同约定收取所得价款。在履行交割时，对尚未收款部分的股权投资，应当按照合同的约定结算，取得受让方提供的有效担保。上市公司国有股减持所得收益，按照国务院的规定处理。"},{"i":49,"n":"第四十九条","txt":"企业发生的年度经营亏损，依照税法的规定弥补。税法规定年限内的税前利润不足弥补的，用以后年度的税后利润弥补，或者经投资者审议后用盈余公积弥补。"},{"i":50,"n":"第五十条","txt":"企业年度净利润，除法律、行政法规另有规定外，按照以下顺序分配： （一）弥补以前年度亏损。 （二）提取10%法定公积金。法定公积金累计额达到注册资本50%以后，可以不再提取。 （三）提取任意公积金。任意公积金提取比例由投资者决议。 （四）向投资者分配利润。企业以前年度未分配的利润，并入本年度利润，在充分考虑现金流量状况后，向投资者分配。属于各级人民政府及其部门、机构出资的企业，应当将应付国有利润上缴财政。 国有企业可以将任意公积金与法定公积金合并提取。股份有限公司依法回购后暂未转让或者注销的股份，不得参与利润分配；以回购股份对经营者及其他职工实施股权激励的，在拟订利润分配方案时，应当预留回购股份所需利润。"},{"i":51,"n":"第五十一条","txt":"企业弥补以前年度亏损和提取盈余公积后，当年没有可供分配的利润时，不得向投资者分配利润，但法律、行政法规另有规定的除外。"},{"i":52,"n":"第五十二条","txt":"企业经营者和其他职工以管理、技术等要素参与企业收益分配的，应当按照国家有关规定在企业章程或者有关合同中对分配办法作出规定，并区别以下情况处理： （一）取得企业股权的，与其他投资者一同进行企业利润分配。 （二）没有取得企业股权的，在相关业务实现的利润限额和分配标准内，从当期费用中列支。"},{"i":53,"n":"第五十三条","txt":"企业通过改制、产权转让、合并、分立、托管等方式实施重组，对涉及资本权益的事项，应当由投资者或者授权机构进行可行性研究，履行内部财务决策程序，并组织开展以下工作： （一）清查财产，核实债务，委托会计师事务所审计。 （二）制订职工安置方案，听取重组企业的职工、职工代表大会的意见或者提交职工代表大会审议。 （三）与债权人协商，制订债务处置或者承继方案。 （四）委托评估机构进行资产评估，并以评估价值作为净资产作价或者折股的参考依据。 （五）拟订股权设置方案和资本重组实施方案，经过审议后履行报批手续。"},{"i":54,"n":"第五十四条","txt":"企业采取分立方式进行重组，应当明晰分立后的企业产权关系。 企业划分各项资产、债务以及经营业务，应当按照业务相关性或者资产相关性原则制订分割方案。对不能分割的整体资产，在评估机构评估价值的基础上，经分立各方协商，由拥有整体资产的一方给予他方适当经济补偿。"},{"i":55,"n":"第五十五条","txt":"企业可以采取新设或者吸收方式进行合并重组。企业合并前的各项资产、债务以及经营业务，由合并后的企业承继，并应当明确合并后企业的产权关系以及各投资者的出资比例。 企业合并的资产税收处理应当符合国家有关税法的规定，合并后净资产超出注册资本的部分，作为资本公积；少于注册资本的部分，应当变更注册资本或者由投资者补足出资。 对资不抵债的企业以承担债务方式合并的，合并方应当制定企业重整措施，按照合并方案履行偿还债务责任，整合财务资源。"},{"i":56,"n":"第五十六条","txt":"企业实行托管经营，应当由投资者决定，并签订托管协议，明确托管经营的资产负债状况、托管经营目标、托管资产处置权限以及收益分配办法等，并落实财务监管措施。受托企业应当根据托管协议制订相关方案，重组托管企业的资产与债务。未经托管企业投资者同意，不得改组、改制托管企业，不得转让托管企业及转移托管资产、经营业务，不得以托管企业名义或者以托管资产对外担保。"},{"i":57,"n":"第五十七条","txt":"企业进行重组时，对已占用的国有划拨土地应当按照有关规定进行评估，履行相关手续，并区别以下情况处理： （一）继续采取划拨方式的，可以不纳入企业资产管理，但企业应当明确划拨土地使用权权益，并按规定用途使用，设立备查账簿登记。国家另有规定的除外。 （二）采取作价入股方式的，将应缴纳的土地出让金转作国家资本，形成的国有股权由企业重组前的国有资本持有单位或者主管财政机关确认的单位持有。 （三）采取出让方式的，由企业购买土地使用权，支付出让费用。 （四）采取租赁方式的，由企业租赁使用，租金水平参照银行同期贷款利率确定，并在租赁合同中约定。 企业进行重组时，对已占用的水域、探矿权、采矿权、特许经营权等国有资源，依法可以转让的，比照前款处理。"},{"i":58,"n":"第五十八条","txt":"企业重组过程中，对拖欠职工的工资和医疗、伤残补助、抚恤费用以及欠缴的基本社会保险费、住房公积金，应当以企业现有资产优先清偿。"},{"i":59,"n":"第五十九条","txt":"企业被责令关闭、依法破产、经营期限届满而终止经营的，或者经投资者决议解散的，应当按照法律、法规和企业章程的规定实施清算。清算财产变卖底价，参照资产评估结果确定。国家另有规定的，从其规定。 企业清算结束，应当编制清算报告，委托会计师事务所审计，报投资者或者人民法院确认后，向相关部门、债权人以及其他的利益相关人通告。其中，属于各级人民政府及其部门、机构出资的企业，其清算报告应当报送主管财政机关。"},{"i":60,"n":"第六十条","txt":"企业解除职工劳动关系，按照国家有关规定支付的经济补偿金或者安置费，除正常经营期间发生的列入当期费用以外，应当区别以下情况处理： （一）企业重组中发生的，依次从未分配利润、盈余公积、资本公积、实收资本中支付。 （二）企业清算时发生的，以企业扣除清算费用后的清算财产优先清偿。"},{"i":61,"n":"第六十一条","txt":"企业可以结合经营特点，优化业务流程，建立财务和业务一体化的信息处理系统，逐步实现财务、业务相关信息一次性处理和实时共享。"},{"i":62,"n":"第六十二条","txt":"企业应当逐步创造条件，实行统筹企业资源计划，全面整合和规范财务、业务流程，对企业物流、资金流、信息流进行一体化管理和集成运作。"},{"i":63,"n":"第六十三条","txt":"企业应当建立财务预警机制，自行确定财务危机警戒标准，重点监测经营性净现金流量与到期债务、企业资产与负债的适配性，及时沟通企业有关财务危机预警的信息，提出解决财务危机的措施和方案。"},{"i":64,"n":"第六十四条","txt":"企业应当按照有关法律、行政法规和国家统一的会计制度的规定，按时编制财务会计报告，经营者或者投资者不得拖延、阻挠。"},{"i":65,"n":"第六十五条","txt":"企业应当按照规定向主管财政机关报送月份、季度、年度财务会计报告等材料，不得在报送的财务会计报告等材料上作虚假记载或者隐瞒重要事实。主管财政机关应当根据企业的需要提供必要的培训和技术支持。 企业对外提供的年度财务会计报告，应当依法经过会计师事务所审计。国家另有规定的，从其规定。"},{"i":66,"n":"第六十六条","txt":"企业应当在年度内定期向职工公开以下信息： （一）职工劳动报酬、养老、医疗、工伤、住房、培训、休假等信息。 （二）经营者报酬实施方案。 （三）年度财务会计报告审计情况。 （四）企业重组涉及的资产评估及处置情况。 （五）其他依法应当公开的信息。"},{"i":67,"n":"第六十七条","txt":"主管财政机关应当建立健全企业财务评价体系，主要评估企业内部财务控制的有效性，评价企业的偿债能力、盈利能力、资产营运能力、发展能力和社会贡献。评估和评价的结果可以通过适当方式向社会发布。"},{"i":68,"n":"第六十八条","txt":"主管财政机关及其工作人员应当恰当使用所掌握的企业财务信息，并依法履行保密义务，不得利用企业的财务信息谋取私利或者损害企业利益。"},{"i":69,"n":"第六十九条","txt":"企业应当依法接受主管财政机关的财务监督和国家审计机关的财务审计。"},{"i":70,"n":"第七十条","txt":"经营者在经营过程中违反本通则有关规定的，投资者可以依法追究经营者的责任。"},{"i":71,"n":"第七十一条","txt":"企业应当建立、健全内部财务监督制度。 企业设立监事会或者监事人员的，监事会或者监事人员依照法律、行政法规、本通则和企业章程的规定，履行企业内部财务监督职责。 经营者应当实施内部财务控制，配合投资者或者企业监事会以及中介机构的检查、审计工作。"},{"i":72,"n":"第七十二条","txt":"企业和企业负有直接责任的主管人员和其他人员有以下行为之一的，县级以上主管财政机关可以责令限期改正、予以警告，有违法所得的，没收违法所得，并可以处以不超过违法所得3倍、但最高不超过3万元的罚款；没有违法所得的，可以处以1万元以下的罚款。 （一）违反本通则第三十九条、四十条、四十二条第一款、四十三条、四十六条规定列支成本费用的。 （二）违反本通则第四十七条第一款规定截留、隐瞒、侵占企业收入的。 （三）违反本通则第五十条、五十一条、五十二条规定进行利润分配的。但依照《公司法》设立的企业不按本通则第五十条第一款第二项规定提取法定公积金的，依照《公司法》的规定予以处罚。 （四）违反本通则第五十七条规定处理国有资源的。 （五）不按本通则第五十八条规定清偿职工债务的。"},{"i":73,"n":"第七十三条","txt":"企业和企业负有直接责任的主管人员和其他人员有以下行为之一的，县级以上主管财政机关可以责令限期改正、予以警告。 （一）未按本通则规定建立健全各项内部财务管理制度的。 （二）内部财务管理制度明显与法律、行政法规和通用的企业财务规章制度相抵触，且不按主管财政机关要求修正的。"},{"i":74,"n":"第七十四条","txt":"企业和企业负有直接责任的主管人员和其他人员不按本通则第六十四条、第六十五条规定编制、报送财务会计报告等材料的，县级以上主管财政机关可以依照《公司法》、《企业财务会计报告条例》的规定予以处罚。"},{"i":75,"n":"第七十五条","txt":"企业在财务活动中违反财政、税收等法律、行政法规的，依照《财政违法行为处罚处分条例》（国务院令第427号）及有关税收法律、行政法规的规定予以处理、处罚。"},{"i":76,"n":"第七十六条","txt":"主管财政机关以及政府其他部门、机构有关工作人员，在企业财务管理中滥用职权、玩忽职守、徇私舞弊或者泄露国家机密、企业商业秘密的，依法进行处理。"},{"i":77,"n":"第七十七条","txt":"实行企业化管理的事业单位比照适用本通则。"},{"i":78,"n":"第七十八条","txt":"本通则自2007年1月1日起施行。"}],"kuaijicongyezigeguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了加强会计从业资格管理，规范会计人员行为，根据《中华人民共和国会计法》（以下简称《会计法》）及相关法律的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"申请取得会计从业资格证书适用本办法。 在国家机关、社会团体、公司、企业、事业单位和其他组织（以下统称单位）从事下列会计工作的人员必须取得会计从业资格： （一）会计机构负责人（会计主管人员）； （二）出纳； （三）稽核； （四）资本、基金核算； （五）收入、支出、债权债务核算； （六）工资、成本费用、财务成果核算； （七）财产物资的收发、增减核算； （八）总账； （九）财务会计报告编制； （十）会计机构内会计档案管理。"},{"i":3,"n":"第三条","txt":"各单位不得任用（聘用）不具备会计从业资格的人员从事会计工作。 不具备会计从业资格的人员，不得从事会计工作，不得参加会计专业技术资格考试或评审、会计专业职务的聘任，不得申请取得会计人员荣誉证书。"},{"i":4,"n":"第四条","txt":"除本办法另有规定外，县级以上地方人民政府财政部门负责本行政区域内的会计从业资格管理。"},{"i":5,"n":"第五条","txt":"财政部委托中共中央直属机关事务管理局、国务院机关事务管理局按照各自权限分别负责中央在京单位的会计从业资格的管理。 新疆生产建设兵团财务局负责所属单位的会计从业资格的管理。 财政部委托铁道部负责铁路系统的会计从业资格的管理。"},{"i":6,"n":"第六条","txt":"财政部委托中国人民武装警察部队后勤部和中国人民解放军总后勤部分别负责中国人民武装警察部队、中国人民解放军系统的会计从业资格的管理。"},{"i":7,"n":"第七条","txt":"国家实行会计从业资格考试制度。"},{"i":8,"n":"第八条","txt":"申请参加会计从业资格考试的人员，应当符合下列基本条件： （一）遵守会计和其他财经法律、法规； （二）具备良好的道德品质； （三）具备会计专业基础知识和技能。 因有《会计法》第四十二条、第四十三条、第四十四条所列违法情形，被依法吊销会计从业资格证书的人员，自被吊销之日起5年内（含5年）不得参加会计 从业资格考试，不得重新取得会计从业资格证书。 因有提供虚假财务会计报告，做假账，隐匿或者故意销毁会计凭证、会计账簿、财务会计报告，贪污、挪用公款，职务侵占等与会计职务有关的违法行为，被 依法追究刑事责任的人员，不得参加会计从业资格考试，不得取得或者重新取得会计从业资格证书。"},{"i":9,"n":"第九条","txt":"会计从业资格考试科目为：财经法规与会计职业道德、会计基础、初级会计电算化（或者珠算五级）。 会计从业资格考试大纲由财政部统一制定并公布。"},{"i":10,"n":"第十条","txt":"申请人符合本办法第八条规定且具备国家教育行政主管部门认可的中专以上（含中专，下同）会计类专业学历（或学位）的，自毕业之日起2年内（含2年），免试会 计基础、初级会计电算化（或者珠算五级）。 前款所称会计类专业包括： （一）会计学； （二）会计电算化； （三）注册会计师专门化； （四）审计学； （五）财务管理； （六）理财学。"},{"i":11,"n":"第十一条","txt":"省、 自治区、直辖市、计划单列市财政厅（局），新疆生产建设兵团财务局，中共中央直属机关事务管理局、国务院机关事务管理局、铁道部、中国人民武装警察部队后 勤部和中国人民解放军总后勤部（以下简称中央主管单位），按照本办法第四条、第五条、第六条规定的管理范围负责组织实施会计从业资格考试的下列事项： （一）制定会计从业资格考试考务规则； （二）组织会计从业资格考试命题； （三）实施考试考务工作； （四）监督检查会计从业资格考试考风、考纪。 省、自治区、直辖市、计划单列市财政厅（局），新疆生产建设兵团财务局和中央主管单位应当公布会计从业资格考试的报名条件、报考办法、考试科目、考 务规则及考试相关要求,并将会计从业资格考试试题于考试结束后30日内报财政部备案。"},{"i":12,"n":"第十二条","txt":"会计从业资格考试收费标准按照国家物价管理部门的有关规定执行。"},{"i":13,"n":"第十三条","txt":"会计从业资格考试全科合格的申请人，可以向会计从业资格考试所在地的县级以上地方财政部门、新疆生产建设兵团财务局和中央主管单位（以下简称 “会计从 业资格管理机构” ）申请会计从业资格证 书。县级以上地方财政部门会计从业资格证书的颁发权限由各省、自治区、直辖市、计划单列市财政部门确定。 申请会计从业资格证书时，应当填写《会计从业资格证书申请表》，并持下列材料： （一）考试成绩合格证明； （二）有效身份证件原件； （三）近期同一底片一寸免冠证件照两张。 符合本办法第十条规定条件，且财经法规与会计职业道德考试成绩合格的申请人，还需持学历或学位证书原件（香港特别行政区、澳门特别行政区、台湾地区 居民及外国居民的学历或学位须经中华人民共和国教育行政主管部门认可）。"},{"i":14,"n":"第十四条","txt":"申请人可以通过委托代理人申请会计 从业资格证书。 申请人应当对其申请材料实质内容的真实性负责。"},{"i":15,"n":"第十五条","txt":"申请人的申请材料齐全、符合规定形式的，会计从业资格管理机构应当当场受理；申请材料不齐全或者不符合规定形式的，会计从业资格管理机构应当当场或者5日内 一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理。 会计从业资格管理机构受理或者不予受理会计从业资格证书申请，应当出具书面证明，同时注明日期，并加盖本机构专用印章。"},{"i":16,"n":"第十六条","txt":"会 计从业资格管理机构能够当场作出决定的，应当当场作出颁发会计从业资格证书的书面决定；不能当场作出决定的，应当自受理之日起20日内对申请人提交的申请 材料进行审查，并作出是否颁发会计从业资格证书的决定；20日内不能作出决定的，经会计从业资格管理机构负责人批准，可以延长10日，并应当将延长期限的 理由告知申请人。"},{"i":17,"n":"第十七条","txt":"会计从业资格管理机构作出准予颁发会计从业资格证书的决定，应当自作出决定之日起10日内向申请人颁发会计从业资格证书。 会计从业资格管理机构作出不予颁发会计从业资格证书的决定，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":18,"n":"第十八条","txt":"财政部统一规定会计从业资格证书样式和编号规则。 省、自治区、直辖市、计划单列市财政厅（局）和新疆生产建设兵团财务局、中央主管单位负责会计从业资格证书的印制、编号和颁发,并于年度终了后 30日内将上年度会计从业资格证书颁发情况报财政部备案。"},{"i":19,"n":"第十九条","txt":"会计从业资格证书是具备会计从业资格的证明文件，在全国范围内有效。持有会计从业资格证书的人员（以下简称“持证人员”）不得涂改、转让会计从业资格证书。"},{"i":20,"n":"第二十条","txt":"持证人员应当接受继续教育，提高业务素质和会计职业道德水平。 持证人员每年参加继续教育不得少于24小时。"},{"i":21,"n":"第二十一条","txt":"财政部负责制定并公布持证人员继续教育大纲。 省、自治区、直辖市、计划单列市财政厅（局）和新疆生产建设兵团财务局、中央主管单位负责制定持证人员继续教育培训规划并组织实施。"},{"i":22,"n":"第二十二条","txt":"会计从业资格管理机构应当加强对持证人员继续教育工作的监督、指导。 各单位应鼓励持证人员参加继续教育，保证学习时间，提供必要的学习条件。"},{"i":23,"n":"第二十三条","txt":"会计从业资格证书实行注册登记制度。 持 证人员从事会计工作，应当自从事会计工作之日起90日内，填写注册登记表，并持会计从业资格证书和所在单位出具的从事会计工作的证明，向单位所在地或所属 部门、系统的会计从业资格管理机构办理注册登记。持证人员离开会计工作岗位超过6个月的，应当填写注册登记表，并持会计从业资格证书，向原注册登记的会计 从业资格管理机构备案。"},{"i":24,"n":"第二十四条","txt":"持证人员在同一会计从业资格管理机构管辖范围内调转工作单位，且继续从事会计工作的，应当自离开原工作单位之日起90日内，填写调转 登记表，持会计从业资格证书及调入单位开具的从事会计工作的证明，办理调转登记。 持 证人员在不同会计从业资格管理机构管辖范围调转工作单位，且继续从事会计工作的，应当填写调转登记表，持会计从业资格证书，及时向原注册登记的会计从业资 格管理机构办理调出手续；并自办理调出手续之日起90日内，持会计从业资格证书、调转登记表和调入单位开具的从事会计工作证明，向调入单位所在地区的会计 从业资格管理机构办理调入手续。"},{"i":25,"n":"第二十五条","txt":"会计从业资格管理机构应当建立持证人员从业档案信息系统，及时记载、更新持证人员下列信息： （一）持证人员相关 基础信息和注册、变更、调转登记情况； （二）持证人员从事 会计工作情况； （三）持证人员接受 继续教育情况； （四）持证人员受到 表彰奖励情况； （五）持证人员因违反会计法律、法规、规章和会计职业道德被处罚情况。 持证人员的学历或学位、会计专业技术职务资格以及前款第（一）至第（五）项内容发生变更的，可以持相关有效证明和会计从业资格证书，向所属会计从业 资格管理机构办理从业档案信息变更。"},{"i":26,"n":"第二十六条","txt":"会 计从业资格管理机构应当将申请会计从业资格证书和办理会计从业资格证书注册、变更、调转登记的条件、程序、期限以及需要提交的材料和相关申请登记表格示范 文本等在办公场所公示。相关申请登记表格应当置放于会计从业资格管理机构办公场所，免费提供。申请人也可以从会计从业资格管理机构指定网站下载。"},{"i":27,"n":"第二十七条","txt":"会计从业资格管理机构应当对下列情况实施监督检查: (一)从事会计工作的人员持有会计从业资格证书并注册登记情况; (二)持证人员从事会计工作和执行国家统一的会计制度情况; (三) 持证人员遵 守会计职业道德情况; (四)持证人员接受 继续教育情况。 会计从业资格管理机构在实施监督检查时,持证人员应当如实提供有关情况和材料,各有关单位应当予以配合。"},{"i":28,"n":"第二十八条","txt":"会计从业资格管理机构应当对开展会计人员继续教育培训单位进行监督和指导，规范培训市场，确保培训质量。"},{"i":29,"n":"第二十九条","txt":"单位和个人对违反本办法规定的行为有权检举，会计从业资格管理机构应当及时核实、处理，并为检举人保密。"},{"i":30,"n":"第三十条","txt":"参加会计从业资格考试舞弊的，由会计从业资格管理机构取消其该科目的考试成绩；情节严重的，取消其全部考试成绩。"},{"i":31,"n":"第三十一条","txt":"用假学历、假证书等手段得以免试考试科目并取得会计从业资格证书的，由会计从业资格管理部门撤销其 会计从业资格。"},{"i":32,"n":"第三十二条","txt":"持证人员未按照本办法规定办理注册、调转登记的，会计从业资格管理机构责令其限期改正；逾期不改正的，予以公告。"},{"i":33,"n":"第三十三条","txt":"持证人员有《会计法》第四十二条、第四十三条、第四十四条所列违法违纪情形之一，由会计从业资格管理机构按照《会计法》的规定予以处 理并向社会公告。"},{"i":34,"n":"第三十四条","txt":"会计从业资格管理机构发现单位任用（聘用）未经注册、调转登记的人员从事会计工作的，应责令其限期改正；逾期不改正的，予以公告。 单位任用（聘用）没有会计从业资格证书人员从事会计工作的，由会计从业资格管理机构依据《会计法》第四十二条的规定处理。"},{"i":35,"n":"第三十五条","txt":"会计从业资格管理机构及其工作人员在实施会计从业资格管理中滥用职权、玩忽职守、循私舞弊的，依法给予行政处分。"},{"i":36,"n":"第三十六条","txt":"会计从业资格管理机构工作人员违反本办法第二十九条规定，将检举人姓名和检举材料转给被检举单位和被检举人个人的，由所在单位或者有 关单位依法给予行政处分。"},{"i":37,"n":"第三十七条","txt":"省、自治区、直辖市、计划单列市财政厅（局）、新疆生产建设兵团财务局和中央主管单位可以根据本办法制定具体实施办法，报财政部备 案。"},{"i":38,"n":"第三十八条","txt":"香港特别行政区、澳门特别行政区、台湾地区居民及外国居民申请取得会计从业资格证书，适用本办法。"},{"i":39,"n":"第三十九条","txt":"农村集体经济组织会计从业资格的管理可参照本办法执行。"},{"i":40,"n":"第四十条","txt":"本 办法自2005年3月1日起施行。财政部2000年5月8日发布的《会计从业资格管理办法》（财会字[2000]5号）、2000年9月13日发布的 《〈会计从业资格管理办法〉若干问题解答（一）》（财会[2000]13号）、2002年7月25日发布的《〈会计从业资格管理办法〉若干问题解答 （二）》（财办会[2002]28号）同时废止. 附表1： 中华人民共和国会计从业资 格证书申请表 编号: 姓 名 　 民 族 　 性 别 　 一寸免冠照片 身份证号 　 出生日期 年 月 日 发证时间 年 月 日 最高学历 1.初中 及以下 2.高中 3.中专 4.大专 5.本科 6.硕士 7.博士 毕业院校 　 毕业时间 　 所学专业 1.会计学 2.会计电算化 3.注册会计师专门化 4.审计 5.财务管理 6.理财学 7.其它 珠算等级 1.一级以上 2.普一 3.普二 4.普三 5.普四 6.普五"}],"kuaijicongyezigeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强会计从业资格管理，规范会计人员行为，根据《中华人民共和国会计法》（以下简称《会计法》）及相关法律的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"会计从业资格的取得和管理适用本办法。"},{"i":3,"n":"第三条","txt":"在国家机关、社会团体、企业、事业单位和其他组织（以下统称单位）中担任会计机构负责人（会计主管）的人员，以及从事下列会计工作的人员应当取得会计从业资格： （一）出纳； （二）稽核； （三）资本、基金核算； （四）收入、支出、债权债务核算； （五）职工薪酬、成本费用、财务成果核算； （六）财产物资的收发、增减核算； （七）总账； （八）财务会计报告编制； （九）会计机构内会计档案管理； （十）其他会计工作。"},{"i":4,"n":"第四条","txt":"单位不得任用（聘用）不具备会计从业资格的人员从事会计工作。 不具备会计从业资格的人员，不得从事会计工作，不得参加会计专业技术资格考试或评审、会计专业技术职务的聘任，不得申请取得会计人员荣誉证书。"},{"i":5,"n":"第五条","txt":"除本办法另有规定外，县级以上地方人民政府财政部门负责本行政区域内的会计从业资格管理。"},{"i":6,"n":"第六条","txt":"财政部委托中共中央直属机关事务管理局、国务院机关事务管理局按照各自权限分别负责中央在京单位的会计从业资格的管理。 新疆生产建设兵团财务局负责所属单位的会计从业资格的管理。 财政部委托铁道部负责铁路系统的会计从业资格的管理。 财政部委托中国人民解放军总后勤部、中国人民武装警察部队后勤部分别负责中国人民解放军、中国人民武装警察部队系统的会计从业资格的管理。"},{"i":7,"n":"第七条","txt":"国家实行会计从业资格考试制度。"},{"i":8,"n":"第八条","txt":"符合下列条件的人员，可以申请参加会计从业资格考试： （一）遵守会计和其他财经法律、法规； （二）具备良好的道德品质； （三）具备会计专业基础知识和技能。 因有《会计法》第四十二条、第四十三条、第四十四条所列违法情形，被依法吊销会计从业资格证书的人员，自被吊销之日起5年以内不得参加会计从业资格考试，不得重新取得会计从业资格证书。 因有提供虚假财务会计报告，做假账，隐匿或者故意销毁会计凭证、会计账簿、财务会计报告，贪污、挪用公款，职务侵占等与会计职务有关的违法行为，被依法追究刑事责任的人员，不得参加会计从业资格考试，不得取得或者重新取得会计从业资格证书。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府财政部门、新疆生产建设兵团财务局、中共中央直属机关事务管理局、国务院机关事务管理局、铁道部、中国人民解放军总后勤部、中国人民武装警察部队后勤部（以下简称会计从业资格管理机构）应当对申请参加会计从业资格考试人员的条件进行审核，符合条件的，允许其参加会计从业资格考试。"},{"i":10,"n":"第十条","txt":"会计从业资格考试科目为：财经法规与会计职业道德、会计基础、会计电算化（或者珠算）。 会计从业资格考试大纲、考试合格标准由财政部统一制定和公布。 会计从业资格考试科目实行无纸化考试，无纸化考试题库由财政部统一组织建设。会计从业资格无纸化考试管理相关规定由财政部另行制定。"},{"i":11,"n":"第十一条","txt":"会计从业资格各考试科目应当一次性通过。 会计从业资格管理机构应当在考试结束后及时公布考试结果，通知考试通过人员在考试结果公布之日起6个月内，到指定的会计从业资格管理机构领取会计从业资格证书。 通过会计从业资格考试的人员，应当持本人有效身份证件原件，在规定的期限内，到指定的地点领取会计从业资格证书。 通过会计从业资格考试的人员，可以委托代理人领取会计从业资格证书。代理人领取会计从业资格证书时，应当持本人和委托人的有效身份证件原件。"},{"i":12,"n":"第十二条","txt":"各省、自治区、直辖市、计划单列市财政厅（局）（以下简称省级财政部门），新疆生产建设兵团财务局，中共中央直属机关事务管理局、国务院机关事务管理局、铁道部、中国人民解放军总后勤部、中国人民武装警察部队后勤部（以下简称中央主管单位），应当按照本办法第五条、第六条规定的管理范围，负责组织实施会计从业资格考试的下列事项： （一）制定会计从业资格考试考务规则； （二）组织会计从业资格考试软件系统的建设及管理； （三）接收并管理财政部下发的会计从业资格无纸化考试题库； （四）组织开展会计从业资格考试； （五）监督检查会计从业资格考试考风、考纪，并依法对违规违纪行为进行处理处罚。 省级财政部门、新疆生产建设兵团财务局和中央主管单位应当根据本办法制定、公布会计从业资格考试的报考办法、考务规则、考试相关要求、报名条件和考试科目。"},{"i":13,"n":"第十三条","txt":"会计从业资格考试收费标准按照国家物价管理部门的有关规定执行。"},{"i":14,"n":"第十四条","txt":"财政部统一规定会计从业资格证书样式和编号规则。 省级财政部门负责本地区会计从业资格证书的印制；新疆生产建设兵团财务局和中央主管单位分别负责本部门、本系统会计从业资格证书的印制。"},{"i":15,"n":"第十五条","txt":"会计从业资格证书是具备会计从业资格的证明文件，在全国范围内有效。 持有会计从业资格证书的人员（以下简称持证人员）不得涂改、出借会计从业资格证书。"},{"i":16,"n":"第十六条","txt":"持证人员应当接受继续教育，提高业务素质和会计职业道德水平。 持证人员参加继续教育采取学分制管理制度。持证人员继续教育相关规定由财政部另行制定。"},{"i":17,"n":"第十七条","txt":"会计从业资格管理机构应当加强对持证人员继续教育工作的监督、指导。 单位应当鼓励和支持持证人员参加继续教育，保证学习时间，提供必要的学习条件。"},{"i":18,"n":"第十八条","txt":"会计从业资格管理机构应当对开展会计人员继续教育的培训机构进行监督和指导，规范培训市场，确保培训质量。"},{"i":19,"n":"第十九条","txt":"会计从业资格实行信息化管理。会计从业资格管理机构应当建立持证人员从业档案信息系统，及时记载、更新持证人员下列信息： （一）持证人员的相关基础信息； （二）持证人员从事会计工作情况； （三）持证人员的变更、调转登记情况； （四）持证人员换发会计从业资格证书情况； （五）持证人员接受继续教育情况； （六）持证人员受到表彰奖励情况； （七）持证人员因违反会计法律、法规、规章和会计职业道德被处罚情况。"},{"i":20,"n":"第二十条","txt":"持证人员的姓名、有效身份证件及号码、照片、学历或学位、会计专业技术职务资格、开始从事会计工作时间等基础信息，以及第十九条第（五）和第（六）项内容发生变化的，应当持相关有效证明和会计从业资格证书，到所属会计从业资格管理机构办理从业档案信息变更。会计从业资格管理机构应当在核实相关信息后，为持证人员办理从业档案信息变更。 持证人员的其他相关信息发生变化的，应当登陆所属会计从业资格管理机构指定网站进行信息变更，也可以到所属会计从业资格管理机构办理。"},{"i":21,"n":"第二十一条","txt":"持证人员所属会计从业资格管理机构发生变化的，应当及时办理调转登记手续。 持证人员所属会计从业资格管理机构在各省级财政部门、新疆生产建设兵团财务局、中央主管单位各自管辖范围内发生变化的，应当持会计从业资格证书、工作证明（或户籍证明、居住证明）到调入地所属会计从业资格管理机构办理调转登记。 持证人员所属会计从业资格管理机构在各省级财政部门、新疆生产建设兵团财务局、中央主管单位管辖范围之间发生变化的，应当及时填写调转登记表，持会计从业资格证书，到原会计从业资格管理机构办理调出手续。持证人员应当自办理调出手续之日起3个月内，持会计从业资格证书、调转登记表和在调入地的工作证明（或户籍证明、居住证明），到调入地会计从业资格管理机构办理调入手续。"},{"i":22,"n":"第二十二条","txt":"持证人员应当妥善保管会计从业资格证书。如有遗失，持证人员应当在履行公告程序后，填写补发申请表，持有关证明材料，向所属会计从业资格管理机构申请补发会计从业资格证书。会计从业资格管理机构核实无误后，应当自受理之日起20个工作日内予以补发。 如有毁损，持证人员应当填写补发申请表，持毁损证书原件，向所属会计从业资格管理机构申请补发会计从业资格证书。会计从业资格管理机构核实无误后，应当自受理之日起 20个工作日内予以补发。"},{"i":23,"n":"第二十三条","txt":"会计从业资格证书实行6年定期换证制度。 持证人员应当在会计从业资格证书到期前6个月内，填写定期换证登记表，持有效身份证件原件和会计从业资格证书，到所属会计从业资格管理机构办理换证手续。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，会计从业资格管理机构可以撤销持证人员的会计从业资格： （一）会计从业资格管理机构工作人员滥用职权、玩忽职守，作出给予持证人员会计从业资格决定的； （二）超越法定职权或者违反法定程序，作出给予持证人员会计从业资格决定的； （三）对不具备会计从业资格的人员，作出给予会计从业资格决定的。 持证人员以欺骗、贿赂、舞弊等不正当手段取得会计从业资格的，会计从业资格管理机构应当撤销其会计从业资格。"},{"i":25,"n":"第二十五条","txt":"持证人员具有下列情形之一的，会计从业资格管理机构应当注销其会计从业资格： （一）死亡或者丧失行为能力的； （二）会计从业资格被依法吊销的。"},{"i":26,"n":"第二十六条","txt":"会计从业资格管理机构应当将领取会计从业资格证书和办理会计从业资格证书换发、调转、变更登记的条件、程序、期限以及需要提交的材料和相关申请登记表格示范文本等在办公场所公示，或者在会计从业资格管理机构指定网站进行公示。相关申请登记表格示范文本应当置放于会计从业资格管理机构办公场所，免费提供，或者由申请人从会计从业资格管理机构指定网站下载。"},{"i":27,"n":"第二十七条","txt":"会计从业资格管理机构应当对下列情况实施监督检查： （一）从事会计工作的人员持有会计从业资格证书情况； （二）持证人员换发、调转、变更登记会计从业资格证书情况； （三）持证人员从事会计工作和执行国家统一的会计制度情况； （四）持证人员遵守会计职业道德情况； （五）持证人员接受继续教育情况。 会计从业资格管理机构在实施监督检查时，持证人员应当如实提供有关情况和材料，有关单位应当予以配合。"},{"i":28,"n":"第二十八条","txt":"单位和个人对违反本办法规定的行为有权检举，会计从业资格管理机构应当及时核实、处理，并为检举人保密。"},{"i":29,"n":"第二十九条","txt":"持证人员对会计从业资格管理机构的处理处罚决定，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼。"},{"i":30,"n":"第三十条","txt":"参加会计从业资格考试舞弊的，2年内不得参加会计从业资格考试，由会计从业资格管理机构取消其考试成绩，已取得会计从业资格的，由会计从业资格管理机构撤销其会计从业资格。"},{"i":31,"n":"第三十一条","txt":"持证人员具有下列情形之一的，由会计从业资格管理机构责令其限期改正： （一）不参加继续教育或参加继续教育未取得规定学分的； （二）未按照本办法规定办理调转登记的； （三）未按照本办法规定进行信息更新的。"},{"i":32,"n":"第三十二条","txt":"会计从业资格管理机构及其工作人员在实施会计从业资格管理中滥用职权、玩忽职守、循私舞弊的，依法给予处分。构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"会计从业资格管理机构工作人员违反本办法第二十八条规定，将检举人姓名和检举材料转给被检举单位或个人，或者将应当保密的检举信息对外泄露的，由所在单位或者有关单位依法给予处分。构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"省级财政部门、新疆生产建设兵团财务局和中央主管单位可以根据本办法制定具体实施办法，报财政部备案。"},{"i":35,"n":"第三十五条","txt":"香港特别行政区、澳门特别行政区、台湾地区居民和外国居民在境内取得会计从业资格及相关管理适用本办法。"},{"i":36,"n":"第三十六条","txt":"本办法施行之日前已被聘任为高级会计师或者从事会计工作满20年，且年满50周岁、目前尚在从事会计工作的，经本人申请并提供单位证明等相关材料，会计从业资格管理机构核实无误后，发给会计从业资格证书。 取得注册会计师证书，目前尚在从事会计工作的，经本人申请并提供单位证明等相关材料，会计从业资格管理机构核实无误后，发给会计从业资格证书。"},{"i":37,"n":"第三十七条","txt":"本办法自2013年7月1日起施行。财政部2005年1月22日发布的《会计从业资格管理办法》（财政部令第26号）同时废止。"}],"kuaijishishiwusuoshenpihejianduzanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范会计师事务所的审批，加强对会计师事务所的监督，促进注册会计师行业健康发展，根据《中华人民 共和国注册会计师法》及相关法律，制定本办法。"},{"i":2,"n":"第二条","txt":"财政部和省、自治区、直辖市人民政府财政部门（以下简称“省级财政部门”）审批和监督会计师事务所， 适用本办法。"},{"i":3,"n":"第三条","txt":"财政部和省级财政部门应当遵循公 开、公平、公正、便民、高效的原则，依法审批会计师事务所，监督会计师事务所的业务活动。"},{"i":4,"n":"第四条","txt":"会计师事务所、注册会计师应当遵守法律、行政法规，恪守职业道德，遵循执业规范。"},{"i":5,"n":"第五条","txt":"会计师事务所、注册会计师依法独立、客观、公正执业，受法律保护，任何单位和个人不得违法干预。"},{"i":6,"n":"第六条","txt":"注册会计师可以申请设立合伙会计师事务所或者有限责任会计师事务所。"},{"i":7,"n":"第七条","txt":"设立合伙会计师事务所，应当具备下列条件： （一）有2名以上的合伙人； （二）有书面合伙协议； （三）有会计师事务所的名称； （四）有固定的办公场所。"},{"i":8,"n":"第八条","txt":"设立有限责任会计师事务所，应当具备下列条件： （一）有5名以上的股东； （二）有一定数量的专职从业人员； （三）有不少于人民币30万元的注册资本； （四）有股东共同制定的章程； （五）有会计师事务所的名称； （六）有固定的办公场所。"},{"i":9,"n":"第九条","txt":"会计师事务所的合伙人或者股东，应当具备下列条件： （一）持有中华人民共和国注册会计师证书（以下简称“注册会计师证书”）； （二）在会计师事务所专职执业； （三）成为合伙人或者股东前3年内没有因为执业行为受到行政处罚； （四）有取得注册会计师证书后最近连续5年在会计师事务所从事下列审计业务的经历， 其中在境内会计师事务所的经历不少于3年： 1、审查企业会计报表，出具审计报告； 2、验证企业资本，出具验资报告； 3、办理企业合并、分立、清算事宜中的审计业务，出具有关的报告； 4、法律、行政法规规定的其他审计业务。 （五）成为合伙人或者股东前1年内没有因采取隐瞒或提供虚假材料、欺骗、贿赂等不正 当手段申请设立会计师事务所而被省级财政部门作出不予受理、不予批准或者撤销会计师事务所的决定。"},{"i":10,"n":"第十条","txt":"会计师事务所应当设立主任会计师。 合伙会计师事务所的主任会计师由执行会计师事务所事务的合伙人担任。 有限责任会计师事务所的主任会计师由法定代表人担任，法定代表人由股东担任。"},{"i":11,"n":"第十一条","txt":"注册会计师在成为会计师事务所的合伙人或者股东之前，应当在省、自治区、直辖市注册会计师协会（以下简称“省级注册会计师协会”）办理完从原会计师事务所 转出的手续。若为原会计师事务所合伙人或者股东，还应当按照有关法律、行政法规，以及合伙协议或者章程办理完退伙或者股权转让手续。"},{"i":12,"n":"第十二条","txt":"会计师事务所的名称应当符合国家有关规定。未经同意，会计师事务所不得使用包含其他会计师事务所字 号的名称。"},{"i":13,"n":"第十三条","txt":"设立会计师事务所，应当由全体合伙人或者全体股东提出申请，由拟设立的会计师事务所所在地的省级财 政部门批准。"},{"i":14,"n":"第十四条","txt":"申请设立会计师事务所，应当向省级财政部门提交下列材料： （一）设立会计师事务所申请表（附表1）； （二）会计师事务所合伙人或者股东情况汇总表（附表2）； （三）注册会计师情况汇总表（附表3）； （四）工商行政管理部门出具的企业名称预先核准通知书复印件； （五）全体合伙人或者全体股东现所在的省级注册会计师协会为其出具的从事本办法第九条第（四）项规定的审计业务情况的证明、 已转出原会计师事务所证明，若合伙人或者股东为原会计师事务所合伙人或者股东的，还应提交退伙或者股权转让证明； （六）会计师事务所注册会计师的注册会计师证书复印件； （七）书面合伙协议或者股东共同制定的章程； （八）办公场所的产权或者使用权的有效证明复印件。 设立有限责任会计师事务所，还应当提交验资证明。 因合并或者分立新设会计师事务所的，还应当提交合并协议或者分立协议。 申请人应当对申请材料内容的真实性负责。"},{"i":15,"n":"第十五条","txt":"省级财政部门批准设立会计师事务所，应当按照下列程序办理： （一）对申请人提交的申请材料进行审查，并核对有关复印件与原件是否相符。对申请材料不齐全或者不符合法定形式的，应当当场 或者在5日内一次告知申请人需要补正的全部内容。对申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的应当受 理。受理申请或者不予受理申请，应当向申请人出具加盖本行政机关专用印章和注明日期的书面凭证。 （二）对申请材料的内容进行审查，并将申请材料中有关会计师事务所名称以及合伙人或者股东执业资格及执业时间等情况予以公 示。 （三）自受理申请之日起30日内作出批准或者不予批准设立会计师事务所的决定。 （四）作出批准设立会计师事务所决定的，应当自作出批准决定之日起10日内向申请人 下达批准文件、颁发会计师事务所执业证书，并予以公告。批准文件中应当载明下列事项： 1、会计师事务所的名称和组织形式； 2、会计"},{"i":16,"n":"第十六条","txt":"省级财政部门作出批准设立会计师事务所决定的，应当自作出批准决定之日起30日内将批准文件连同下列材料报送财政部、中国注册会计师协会： （一）批准设立会计师事务所有关情况表（附表4）； （二）会计师事务所合伙人或者股东情况汇总表（附表2）。 财政部发现批准不当的，应当自收到备案材料之日起30日内书面通知省级财政部门重新 审查。"},{"i":17,"n":"第十七条","txt":"经省级财政部门批准设立的会计师事务所，应当依法办理工商登记手续。"},{"i":18,"n":"第十八条","txt":"会计师事务所的合伙人或者股东应当自会计师事务所办理完工商登记手续之日起60日内办理完转入该会计师事务所的手续。 注册会计师在未办理完转入手续以前，不得在新设立的会计师事务所执业。"},{"i":19,"n":"第十九条","txt":"因合并或者分立新设会计师事务所，按照本办法设立会计师事务所有关规定办理。"},{"i":20,"n":"第二十条","txt":"会计师事务所设立分支机构应当按照本办法规定设立分所。"},{"i":21,"n":"第二十一条","txt":"会计师事务所应当在人事、财务、执业标准、质量控制等方面对其设立的分 所进行统一管理，并对分所的业务活动和债务承担法律责任。"},{"i":22,"n":"第二十二条","txt":"会计师事务所设立分所，应当由分所所在地的省级财政部门批准。"},{"i":23,"n":"第二十三条","txt":"设立分所的会计师事务所，应当具备下列条件： （一）依法成立3年以上，内部管理制度健全； （二）注册会计师数量（不包括拟到分所执业的注册会计师）不低于50名； （三）有限责任会计师事务所上年末的净资产和职业风险基金总额不低于人民币300万 元，合伙会计师事务所上年末的净资产和职业风险基金总额不低于人民币150万元； （四）申请设立分所前3年内该会计师事务所及其已设立的分所没有因为执业行为受到行 政处罚。 因合并或者分立新设的会计师事务所申请设立分所的，其成立时间可以合并或者分立前会计师事务所的成立时间为准。"},{"i":24,"n":"第二十四条","txt":"会计师事务所设立的分所，应当具备下列条件： （一）分所负责人为会计师事务所的合伙人或者股东； （二）至少有5名注册会计师（含分所负责人）； （三）有固定的办公场所。"},{"i":25,"n":"第二十五条","txt":"分所的名称应当采用“会计师事务所名称＋分所所在行政区划名＋分所”的 形式。"},{"i":26,"n":"第二十六条","txt":"会计师事务所申请设立分所，应当向拟设立分所所在地的省级财政部门提交 下列材料： （一）会计师事务所设立分所申请表（附表5）； （二）会计师事务所全体合伙人或者股东会作出的设立分所的决议； （三）注册会计师情况汇总表（附表3）； （四）会计师事务所上年度资产负债表； （五）会计师事务所拟设立的分所注册会计师的注册会计师证书复印件； （六）会计师事务所对分所的管理办法； （七）分所办公场所的产权或者使用权的有效证明复印件。 合并后的会计师事务所于合并当年提出设立分所的，不需要提交前款第（四）项规定的材料，但应当提交合并协议和合并基准日的资 产负债表。"},{"i":27,"n":"第二十七条","txt":"省级财政部门批准会计师事务所设立分所的程序比照本办法第十五条规定办 理。 跨省级行政区划设立分所的，分所所在地的省级财政部门应当就设立该分所的会计师事务所是否符合本办法第二十三条规定的条件， 征求该会计师事务所所在地的省级财政部门的意见。该会计师事务所所在地的省级财政部门应当在10日内回复意见。 省级财政部门应当自受理设立分所申请之日起20日内作出是否批准的决定。批准设立会 计师事务所分所的，应当向申请人下达批准文件、颁发会计师事务所分所执业证书，并将批准文件抄报财政部、中国注册会计师协会。 会计师事务所跨省级行政区划设立分所的，批准设立分所的省级财政部门还应当将批准文件抄送会计师事务所所在地的省级财政部门 及省级注册会计师协会。"},{"i":28,"n":"第二十八条","txt":"会计师事务所设立的分所经省级财政部门批准后，应当依法办理分所工商登 记手续。"},{"i":29,"n":"第二十九条","txt":"会计师事务所发生下列事项之一的，应当自作出决议之日起20日内向所在地的省级财政部门备案： （一）变更会计师事务所名称、办公场所（在省级行政区划内）、主任会计师； （二）变更合伙会计师事务所合伙人； （三）变更有限责任会计师事务所注册资本、股东。 会计师事务所变更分所名称、负责人、办公场所，或者撤销已设立的分所，应当自作出决议之日起20日内同时向会计师事务所和分所所在地的省级财政部门备案。"},{"i":30,"n":"第三十条","txt":"会计师事务所及其分所发生本办法第二十九条所列变更事项之一的，应当向所在地的省级财政部门报送下 列备案材料： （一）会计师事务所变更事项情况表（附表6）或者会计师事务所分所变更事项情况表 （附表7）； （二）变更后的情况符合本办法第七条至第十二条、第二十四条和第二十五条规定的证明材料。"},{"i":31,"n":"第三十一条","txt":"会计师事务所及其设立的分所变更名称的，应当同时向会计师事务所及其分所所在地的省级财政部门备案，提交工商行政管理部门出具的企业名称预先核准通知书复 印件，交回原会计师事务所执业证书或者原会计师事务所分所执业证书，换取新的会计师事务所执业证书或者会计师事务所分所执业证书。 会计师事务所撤销已设立的分所，应当向会计师事务所及其分所所在地省级财政部门报送会计师事务所撤销分所情况表（附表 8），并交回会计师事务所分所执业证书。 省级财政部门收到会计师事务所撤销分所情况表或者换发执业证书后，应当将有关情况予以公告。"},{"i":32,"n":"第三十二条","txt":"因合并或者分立存续的会计师事务所，应当按照本办法第二十九条至第三十 一条的规定向所在地的省级财政部门备案。"},{"i":33,"n":"第三十三条","txt":"会计师事务所跨省级行政区划迁移办公场所，应当由迁入地的省级财政部门 批准。"},{"i":34,"n":"第三十四条","txt":"会计师事务所跨省级行政区划迁移办公场所，应当具备下列条件： （一）符合法定设立条件； （二）申请迁移时未正在接受财政部或省级财政部门检查，或者中国注册会计师协会或省级注册会计师协会调查。"},{"i":35,"n":"第三十五条","txt":"会计师事务所跨省级行政区划迁移办公场所， 应当向迁入地省级财政部门 提交下列材料： （一）会计师事务所跨省级行政区划迁移申请表（附表9）； （二）会计师事务所合伙人或者股东情况汇总表（附表2）； （三）注册会计师情况汇总表（附表3）； （四）书面合伙协议或者股东共同制定的章程； （五）全体合伙人或者股东的注册会计师证书复印件； （六）迁入地办公场所的产权或者使用权的有效证明复印件； （七）全体合伙人或者股东会作出的迁移办公场所决议。 迁移同时需要变更会计师事务所名称的，还应当提交迁入地的工商行政管理部门出具的企业名称预先核准通知书复印件。"},{"i":36,"n":"第三十六条","txt":"省级财政部门批准会计师事务所跨省级行政区划迁移办公场所的程序比照本 办法第十五条规定办理。 迁入地的省级财政部门应当就该会计师事务所是否符合本办法第三十四条规定的条件，征求迁出地的省级财政部门的意见。迁出地的 省级财政部门应当在10日内回复意见。 省级财政部门应当自受理申请之日起20日内作出决定。批准会计师事务所迁入的，应当 向申请人下达批准文件、换发会计师事务所执业证书，并在30日内与迁出地的省级财政部门办理该会计师事务所档案材料的移交手续。 省级财政部门下达的批准文件还应当抄报财政部、中国注册会计师协会，抄送迁出地的省级财政部门和省级注册会计师协会。"},{"i":37,"n":"第三十七条","txt":"经批准跨省级行政区划迁移办公场所的会计师事务所设有分所的，应当向其 分所所在地的省级财政部门备案，并交回原会计师事务所分所执业证书。省级财政部门应当为其换发新的会计师事务所分所执业证书。"},{"i":38,"n":"第三十八条","txt":"省级财政部门应当在受理申请的办公场所将申请设立会计师事务所、会计师 事务所分所和跨省级行政区划迁移办公场所的条件、应当提交的材料目录及要求、批准的程序及期限予以公示。"},{"i":39,"n":"第三十九条","txt":"会计师事务所与境外会计师事务所签订协议，建立成员所或者联系所关系 的，应当自签订协议之日起20日内，通过所在地的省级财政部门向财政部、中国注册会计师协会报送会计师事务所与境外会计师事务所建 立合作关系情况表（附表10 ）以及会计师事务所与境外会计师事务所签定的协议复印件。"},{"i":40,"n":"第四十条","txt":"会计师事务所有下列情形之一的，应当终止： （一）合伙协议或者章程规定的解散事由出现，自愿解散； （二）全体合伙人或者股东会决议解散； （三）因合并或者分立解散； （四）被依法宣告破产； （五）被依法注销、撤销或者吊销营业执照； （六）被依法撤销或者撤回会计师事务所执业证书； （七）法律、行政法规规定的其他终止情形。"},{"i":41,"n":"第四十一条","txt":"会计师事务所发生应当终止的情形时，应当分别向会计师事务所及其分所所 在地的省级财政部门备案，报送会计师事务所终止情况表（附表11），同时交回会计师事务所执业证书和会计师事务所分所执业证书。 会计师事务所终止，应当按照有关法律、行政法规的规定进行清算。"},{"i":42,"n":"第四十二条","txt":"省级财政部门收到会计师事务所报送的会计师事务所终止情况表并收回会计 师事务所执业证书或者会计师事务所分所执业证书后，应当将会计师事务所或者分所终止的有关情况予以公告。"},{"i":43,"n":"第四十三条","txt":"财政部和省级 财政部门依法对下列事项实施监督检查： （一）会计师事务所保持设立条件的情况； （二）会计师事务所应当向财政部和省级财政部门备案事项的报备情况； （三）会计师事务所和注册会计师的执业情况； （四）会计师事务所的质量控制制度； （五）法律、行政法规规定的其他监督检查事项。"},{"i":44,"n":"第四十四条","txt":"财政部和省级 财政部门在实施监督检查过程中应当严格遵守财政检查工作的有关规定，不得妨碍会计师事务所的正常经营活动，不得索取或者收受财物，不得谋取其他利益；应当在认定事实清楚、 证据确凿、定性准确、法律依据充分的情况下依法处理。"},{"i":45,"n":"第四十五条","txt":"财政部和省级财政部门在开展检查过程中，可以根据工作需要，聘用一定数 量的专业人员协助检查。"},{"i":46,"n":"第四十六条","txt":"财政部和省级财政部门及被聘用的专业人员对检查工作中知悉的国家秘密和 商业秘密负有保密义务。"},{"i":47,"n":"第四十七条","txt":"财政部应当加强对省级财政部 门监督、指导注册会计师、会计师事务所工作的监督检查。 省级财政部门应当建 立信息报告制度，对会计师事务所、注册会计师发生的重大违法违规案件及时上报财政部。"},{"i":48,"n":"第四十八条","txt":"会计师事务所及其分所未保持设立条件的，应在20日内向所在地的省级财政部门备案，由所在地的省级财政部门责令其在60日内整改。未在规定期限内备案或者整改期满仍未达到设立条件的，由所 在地的省级财政部门撤回设立许可。"},{"i":49,"n":"第四十九条","txt":"会计师事务所和注册会计师存在下列情形之一的，财政部和省级财政部门应 当进行重点监督检查： （一）被投诉或者举报的； （二）未保持设立条件的； （三）在执业中有不良记录的； （四）采取不正当竞争手段承接业务的。"},{"i":50,"n":"第五十条","txt":"财政部和省级财政部门可以对会计师事务所依法进行实地检查，或者将有关材料调到本机关或检查人员办公地点进行核查。 调阅的有关材料应当 在3个月内送还并保持完整。"},{"i":51,"n":"第五十一条","txt":"财政部和省级财政部门在实施监督检查过程中，可以要求会计师事务所和注 册会计师说明有关情况，调阅会计师事务所工作底稿及相关资料，向相关单位和人员调查、询问、取证和核实有关情况。"},{"i":52,"n":"第五十二条","txt":"会计师事务所和注册会计师必 须接受财政部和省级财政部门依法实施的监督检查，如实提供中文工作底稿以及有关资料，不得拒绝、阻挠、逃避检查，不得谎报、隐匿、销毁相关证据材料。 会计师事务所或者注册会计师有明显转移、隐匿有关证据材料迹象的，财政部和省级财政部门可以对证据材料先行登记保存。"},{"i":53,"n":"第五十三条","txt":"对会计师事务所和注册 会计师的违法违规行为，财政部和省级财政部门可以在作出行政处罚决定后予以公告。"},{"i":54,"n":"第五十四条","txt":"会计师事务所 应当于每年5月31日之前，向所在地的省级财政部门报送下列材料： （一）会计师事务所基本情况表（附表12）和会计师事务所分所基本情况表（附表 13）； （二）会计师事务所上年末资产负债表和上年度利润表； （三）会计师事务所合伙人或者股东情况汇总表（附表2）； （四）对分所的业务管理和执业质量控制情况的说明； （五）会计师事务所出具审计报告情况表（附表14）； （六）会计师事务所及其注册会计师接受业务检查、被处罚情况； （七）会计师事务所由于执行业务涉及法律诉讼情况。 会计师事务所与境外会计师事务所有成员所或者联系所合作关系的，还应当报送上年度与境外会计师事务所、境外会计师事务所其他 成员所或者联系所合作开展业务的情况。 会计师事务所跨省级行政区划设有分所的，还应当将该分所有关材料报送分所所在地的省级财政部门。"},{"i":55,"n":"第五十五条","txt":"省级财政部门收到会计师事务所按照本办法第五十四条的规定报送的材料 后，应当对会计师事务所及其分所保持设立条件等情况进行汇总，并于6月30日之前报财政部、中国注册会计师协会。"},{"i":56,"n":"第五十六条","txt":"会计师事务所和注册会计师必须按照执业准则、规则的要求，在实施必要的 审计程序后，以经过核实的审计证据为依据，形成审计意见，出具审计报告，不得有下列行为： （一）在未履行必要的审计程序，未获取充分适当的审计证据的情况下出具审计报告； （二）对同一委托单位的同一事项，依据相同的审计证据出具不同结论的审计报告； （三）隐瞒审计中发现的问题，发表不恰当的审计意见； （四）未实施严格的逐级复核制度，未按规定编制和保存审计工作底稿； （五）违反执业准则、规则的其他行为。 会计师事务所和注册会计师执行审计业务，遇到下列情形之一的，应当拒绝出具有关报告： （一）委托人示意其作不实或者不当证明的； （二）委托人故意不提供有关会计资料和文件的； （三）因委托人有其他不合理要求，致使其出具的报告不能对财务会计的重要事项作出正确表述的。"},{"i":57,"n":"第五十七条","txt":"注册会计师不得有下列行为： （一）在执行审计业务期间，在法律、行政法规规定不得买卖被审计单位的股票、债券或者不得购买被审计 单位或者个人的其他财产的期限内，买卖被审计单位的股票、债券或者购买被审计单位或者个人所拥有的其他财产； （二）索取、收受委托合同约定以外的酬金或者其他财物，或者利用执行业务之便，谋取其他不正当利益； （三）接受委托催收债款； （四）允许他人以本人名义执行业务； （五）同时在两个或者两个以上的会计师事务所执行业务； （六）对其能力进行广告宣传以招揽业务； （七）违反法律、行政法规的其他行为。"},{"i":58,"n":"第五十八条","txt":"会计师事务所不得有下列行为： （一）未经批准设立分所； （二）向省级以上财政部门提供虚假材料或者不及时报送相关材料； （三）雇用正在其他会计师事务所执业的注册会计师，或者明知本所的注册会计师在其他会计师事务所执业而不予制止； （四）允许本所注册会计师只在本所挂名而不在本所执行业务，或者明知本所注册会计师在其他单位从事获取工资性收入的工作而不 予制止； （五）允许其他单位或者个人以本所名义承办业务； （六）采取强迫、欺诈等不正当方式招揽业务； （七）承办与自身规模、执业能力、承担风险能力不匹配的业务； （八）违反法律、行政法规的其他行为。"},{"i":59,"n":"第五十九条","txt":"会计师事务所或者注册会计师违反本办法规定的，由财政部或者省级财政部门依法给 予行政处罚；违法情节轻微，没有造成危害后果的，可以采取下达关注函等方式进行处理或移送注册会计师协会处理。"},{"i":60,"n":"第六十条","txt":"申请人隐瞒有关情况或者提供虚假材料提出申请的，省级财政部门不予受理或者不予批准，并给予警告。"},{"i":61,"n":"第六十一条","txt":"会计师事务所及其分所采取欺骗、贿赂等不正当手段获得批准设立的，由所 在地的省级财政部门予以撤销。"},{"i":62,"n":"第六十二条","txt":"会计师事务所有下列情形之一的，责令限期改正，逾期不改正的予以公告： （一）会计师事务所设立后合伙人或者股东未在规定时间内办理完转入该所手续的； （二）未按照本办法规定办理有关事项备案手续的； （三）对分所的人事、财务、执业标准、质量控制等不实施统一管理的； （四）违反《中华人民共和国注册会计师法》第三十二条规定的； （五）违反本办法第十条、第五十八条规定的。"},{"i":63,"n":"第六十三条","txt":"会计师事务所向财政部或者省级财政部门隐瞒有关情况、提供虚假材料或者 拒绝提供反映其活动情况的真实材料的，给予警告。"},{"i":64,"n":"第六十四条","txt":"会计师事务所违反本办法第五十六条规定的，给予警告，没收违法所得，可 并处违法所得1倍以上5倍以下的罚款；情节严重的，可以暂停其经营业务或者予 以撤销。"},{"i":65,"n":"第六十五条","txt":"注册会计师违反本办法第五十六条规定的，给予警告；情节严重 的，可以暂停其执行业务或者吊销注册会计师证书。 注册会计师违反本办法第五十七条规定的，责令限期改正，逾期不改正的予以公告。"},{"i":66,"n":"第六十六条","txt":"会计师事务所或者注册会计师违反本办法第五十六条的规定，故意出具虚假 的审计报告、验资报告，构成犯罪的，依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"公民、法人或者其他组织未经批准，擅自从事注册会计师法第十四条规定的 注册会计师业务的，给予警告，并责令其停止违法活动，没收违法所得；情节严重的，可以并处1倍以上5倍以下的罚款。"},{"i":68,"n":"第六十八条","txt":"财政部或者省级财政部门在作出较大数额罚款、暂停执业、吊销注 册会计师证书或者撤销会计师事务所的决 定之前，应当告知当事人有要求听证的权利；当事人要求听证的，应当按照《财政部行政处罚听证实施办法》的规定组织听证。"},{"i":69,"n":"第六十九条","txt":"当事人对财政部或者省级财政部门审批和监督行为不服的，可依法申请行政 复议或者提起行政诉讼。"},{"i":70,"n":"第七十条","txt":"财政部或者省级财政部门的工作人员在实施审批和监督过程中，滥用职权、玩 忽职守、徇私舞弊或者泄露国家秘密、商业秘密的，依法给予行政处分。"},{"i":71,"n":"第七十一条","txt":"本办法规定的批准、备案期限均以工作日计算，不含法定节假日。"},{"i":72,"n":"第七十二条","txt":"本办法有关申请材料规定中所指的“注册会计师证书复印件”均包括所有记 录页的复印件。"},{"i":73,"n":"第七十三条","txt":"境外人员申请设立会计师事务所适用本办法。"},{"i":74,"n":"第七十四条","txt":"本办法施行前批准设立的会计师事务所及其分所发生变更事项，其变更后的 情况应当符合本办法的规定。"},{"i":75,"n":"第七十五条","txt":"本办法自2005年3月1日起 施行。 自本办法施行之日起，以下文件同时废止：《合伙会计师事务所设立及审批试 行办法》[（93） 财会协字第110号]、《财政部关于明确合伙会计师事务所审批权限的通知》（财会协字[1997]46号）、《违反注册会计师法处罚暂行办法》（财法字 [1998]1号）、《财政部关于会计师（审计）事务所终止的若干事项的通知》（财会协字[1998]23号）、《有限责任会计师事务所审批办法》（财会 协字[1998]55号）、《注册会计师证书及事务所执业证书管理暂行办法》（财协字[1998]35号）、《财政部关于有限责任会计师事务所出资人资格 有关问题的复函》（财协字[1999]140号）、《会计师事务所合并审批管理暂行办法》（财协字[2000]27号）、《会计师事务所分所审批管理暂行 办法》（财协字[2000]28号）、《财政部关于会计师事务所设立分所有关问题的通知》（"}],"kuaijishishiwusuozhiyexukehejianduguanlibanfa":[{"i":1,"n":"第二条","txt":"财政部和省、自治区、直辖市人民政府财政部门（以下简称省级财政部门）对会计师事务所和注册会计师进行管理、监督和指导，适用本办法。 财政部和省级财政部门应当加强对会计师事务所和注册会计师的政策指导，营造公平的会计市场环境，引导和鼓励会计师事务所不断完善内部治理，实现有序发展。"},{"i":2,"n":"第四条","txt":"会计师事务所、注册会计师应当遵守法律、行政法规，恪守职业道德，遵循执业准则、规则。"},{"i":3,"n":"第六条","txt":"会计师事务所可以采用普通合伙、特殊普通合伙或者有限责任公司形式。"},{"i":4,"n":"第十一条","txt":"除本办法第十二条规定外，会计师事务所的合伙人（股东），应当具备下列条件： （二）成为合伙人（股东）前3年内没有因为执业行为受到行政处罚； （四）成为合伙人（股东）前3年内没有因欺骗、贿赂等不正当手段申请会计师事务所执业许可而被省级财政部门作出不予受理、不予批准或者撤销会计师事务所执业许可的决定； 因受行政处罚、刑事处罚被吊销、撤销注册会计师执业资格的，其被吊销、撤销执业资格之前在会计师事务所从事审计业务的年限，不得计入本条第一款第三项规定的累计年限。"},{"i":5,"n":"第十三条","txt":"普通合伙会计师事务所和特殊普通合伙会计师事务所应当设立首席合伙人，由执行合伙事务的合伙人担任。 首席合伙人（主任会计师）应当符合下列条件： （二）具有代表会计师事务所履行合伙协议或者公司章程授予的管理职权的能力和经验。 首席合伙人（主任会计师）对会计师事务所的执业质量负主体责任。审计业务主管合伙人（股东）、质量控制主管合伙人（股东）对会计师事务所的审计业务质量负直接主管责任。审计业务项目合伙人（股东）对组织承办的具体业务项目的审计质量负直接责任。"},{"i":6,"n":"第十六条","txt":"会计师事务所的名称应当符合国家有关规定。未经同意，会计师事务所不得使用包含其他已取得执业许可的会计师事务所字号的名称。 （一）会计师事务所执业许可申请表； （三）拟在该会计师事务所执业的注册会计师情况汇总表； （五）书面合伙协议或者公司章程复印件； 合伙人（股东）是境外人员或移居境外人员的，还应当提交符合本办法第十一条第一款第五项、第十三条第三款第一项条件的住所有效证明和居留时间有效证明及承诺函。 申请人应当对申请材料内容的真实性、准确性、完整性负责。 省级财政部门受理申请的，应当将申请材料中有关会计师事务所名称以及合伙人（股东）执业资格及执业时间等情况在5日内予以公示。"},{"i":7,"n":"第二十条","txt":"省级财政部门作出准予会计师事务所执业许可决定的，应当自作出准予决定之日起10日内向申请人出具准予行政许可的书面决定、颁发会计师事务所执业证书，并予以公告。准予许可决定应当载明下列事项： （二）会计师事务所合伙人（股东）的姓名； （四）会计师事务所的业务范围。 财政部发现准予许可不当的，应当自收到准予许可决定之日起30日内通知省级财政部门重新审查。"},{"i":8,"n":"第二十二条","txt":"省级财政部门作出不予会计师事务所执业许可决定的，应当自作出决定之日起10日内向申请人出具书面决定，并通知工商行政管理部门。 会计师事务所执业许可申请未予准许，企业主体继续存续的，不得从事注册会计师法定业务，企业名称中不得继续使用“会计师事务所”字样，申请人应当自收到不予许可决定之日起20日内办理工商变更登记。 注册会计师在未办理完成转入手续以前，不得在拟转入的会计师事务所执业。 特殊普通合伙会计师事务所的合伙人按照《合伙企业法》等法律法规的规定及合伙协议的约定，对会计师事务所的债务承担相应责任。"},{"i":9,"n":"第二十五条","txt":"会计师事务所设立分支机构应当依照本办法规定申请分所执业许可。"},{"i":10,"n":"第二十七条","txt":"会计师事务所应当在人事、财务、业务、技术标准、信息管理等方面对其设立的分所进行实质性的统一管理，并对分所的业务活动、执业质量和债务承担法律责任。"},{"i":11,"n":"第二十九条","txt":"申请分所执业许可的会计师事务所，应当具备下列条件： （二）不少于50名注册会计师（已到和拟到分所执业的注册会计师除外）； 跨省级行政区划申请分所执业许可的，会计师事务所上一年度业务收入应当达到2000万元以上。"},{"i":12,"n":"第三十条","txt":"会计师事务所申请分所执业许可，该分所应当具备下列条件： （二）不少于5名注册会计师，且注册会计师的执业关系应当转入分所所在地省级注册会计师协会；由总所人员兼任分所负责人的，其执业关系可以不作变动，但不计入本项规定的5名注册会计师；"},{"i":13,"n":"第三十一条","txt":"会计师事务所申请分所执业许可，应当向分所所在地的省级财政部门提交下列材料： （二）会计师事务所合伙人会议或者股东会作出的设立分所的书面决议； （四）分所营业执照复印件； （六）经营场所产权证明或者使用权证明复印件。"},{"i":14,"n":"第三十二条","txt":"省级财政部门审批分所执业许可的程序比照本办法第十八条至第二十二条第二款的规定办理。 省级财政部门作出不予分所执业许可决定的，会计师事务所应当自收到不予许可决定之日起20日内办理该分所的工商注销手续。"},{"i":15,"n":"第三十三条","txt":"会计师事务所下列事项发生变更的，应当自作出决议之日起20日内向所在地的省级财政部门备案；涉及工商变更登记的，应当自办理完工商变更登记之日起20日内向所在地的省级财政部门备案： （二）首席合伙人（主任会计师）； （四）经营场所； 分所的名称、负责人或者经营场所发生变更的，该会计师事务所应当同时向会计师事务所和分所所在地的省级财政部门备案。"},{"i":16,"n":"第三十五条","txt":"会计师事务所及其分所变更名称的，应当同时向会计师事务所和分所所在地的省级财政部门提交营业执照复印件，交回原会计师事务所执业证书或者分所执业证书，换取新的会计师事务所执业证书或者分所执业证书。"},{"i":17,"n":"第三十六条","txt":"会计师事务所跨省级行政区划迁移经营场所的，应当在办理完迁入地工商登记手续后10日内向迁出地省级财政部门办理迁出手续。会计师事务所应当提交迁入地的营业执照复印件，并由迁出地省级财政部门在一式两份的会计师事务所跨省级行政区划迁移表上盖章确认。 迁入地省级财政部门应当在收到备案材料后10日内，收回原会计师事务所执业证书，换发新的会计师事务所执业证书，并予以公告，同时通知迁出地省级财政部门。"},{"i":18,"n":"第三十七条","txt":"迁入地省级财政部门应当对迁入的会计师事务所持续符合执业许可条件的情况予以审查。未持续符合执业许可条件的，责令其在60日内整改，未在规定期限内整改或者整改期满仍未达到执业许可条件的，由迁入地省级财政部门撤销执业许可，并予以公告。"},{"i":19,"n":"第三十九条","txt":"会计师事务所未在规定时间内办理迁出和迁入备案手续的，由迁出地省级财政部门自发现之日起15日内公告该会计师事务所执业许可失效。"},{"i":20,"n":"第四十一条","txt":"会计师事务所发生下列情形之一的，省级财政部门应当办理会计师事务所执业许可注销手续，收回会计师事务所执业许可证书： （二）会计师事务所执业许可被依法撤销、撤回或者执业许可证书依法被吊销的； 会计师事务所分所执业许可注销的，比照本条第一款规定办理。"},{"i":21,"n":"第四十二条","txt":"会计师事务所执业许可被依法注销，企业主体继续存续的，不得从事注册会计师法定业务，企业名称中不得继续使用“会计师事务所”字样，并应当自执业许可被注销之日起10日内，办理工商变更登记。"},{"i":22,"n":"第四十三条","txt":"省级财政部门应当将注销会计师事务所或者分所执业许可的有关情况予以公告，并通知工商行政管理部门。 （一）首席合伙人（主任会计师）、审计业务主管合伙人（股东）、质量控制主管合伙人（股东）和相关签字注册会计师的离职、退伙（转股）或者转所；"},{"i":23,"n":"第四十六条","txt":"省级以上财政部门依法对会计师事务所实施全面或者专项监督检查。 省级以上财政部门在开展检查过程中，可以根据工作需要，聘用一定数量的专业人员协助检查。"},{"i":24,"n":"第四十八条","txt":"财政部应当加强对省级财政部门监督、指导会计师事务所和注册会计师工作的监督检查。"},{"i":25,"n":"第四十九条","txt":"省级以上财政部门在开展会计师事务所监督检查时，要采取随机抽取检查对象、随机选派执法检查人员并及时公开抽查情况和查处结果。"},{"i":26,"n":"第五十条","txt":"省级以上财政部门应当将发生以下情形的会计师事务所列为重点检查对象，实施严格监管： （二）会计师事务所对分所实施实质性统一管理薄弱的； （四）有不良执业记录的； （六）业务报告数量明显超出服务能力的； （八）需要实施严格监管的其他情形。 会计师事务所应当在出具审计报告后60日内，通过财政会计行业管理系统报备其出具的年度财务报表审计报告，省级财政部门不得自行增加报备信息，不得要求会计师事务所报送纸质材料，并与注册会计师协会等实行信息共享。 调阅的有关材料应当在检查工作结束后1个月内送还并保持完整。"},{"i":27,"n":"第五十四条","txt":"会计师事务所和注册会计师应当接受省级以上财政部门依法实施的监督检查，如实提供中文工作底稿及相关资料，不得拒绝、延误、阻挠、逃避检查，不得谎报、隐匿、销毁相关证据材料。"},{"i":28,"n":"第五十五条","txt":"对会计师事务所和注册会计师的违法违规行为，省级以上财政部门依法作出行政处罚决定的，应当自作出处罚决定之日起10日内将相关信息录入财政会计行业管理系统，并及时予以公告。 （一）持续符合执业许可条件的相关信息； （三）内部治理及会计师事务所对分所实施实质性统一管理情况； 会计师事务所与境外会计师事务所有成员所、联系所或者业务合作关系的，应当同时报送相关信息，说明上一年度与境外会计师事务所合作开展业务的情况。 会计师事务所跨省级行政区划设有分所的，应当同时将分所有关材料报送分所所在地的省级财政部门。"},{"i":29,"n":"第五十八条","txt":"会计师事务所未按照本办法第五十一条、第五十六条规定报备的，省级以上财政部门应当责令限期补交报备材料、约谈首席合伙人（主任会计师），并视补交报备材料和约谈情况组织核查。 省级财政部门在日常管理、监督检查中发现会计师事务所及其分所未持续符合执业许可条件的，应当责令其在60日内整改。"},{"i":30,"n":"第六十条","txt":"会计师事务所和注册会计师必须按照执业准则、规则的要求，在实施必要的审计程序后，以经过核实的审计证据为依据，形成审计意见，出具审计报告，不得有下列行为： （二）对同一委托单位的同一事项，依据相同的审计证据出具不同结论的审计报告； （四）为被审计单位编造或者伪造事由，出具虚假或者不实的审计报告； （六）未保持形式上和实质上的独立；"},{"i":31,"n":"第六十一条","txt":"注册会计师不得有下列行为： （二）索取、收受委托合同约定以外的酬金或者其他财物，或者利用执行业务之便，谋取其他不正当利益； （四）允许他人以本人名义执行业务； （六）同时为被审计单位编制财务会计报告； （八）违反法律、行政法规的其他行为。 （一）分支机构未取得执业许可； （三）向省级以上财政部门提供虚假材料或者不及时报送相关材料； （五）允许注册会计师在本所挂名而不在本所执行业务，或者明知本所注册会计师在其他单位从事获取工资性收入的工作而不予制止； （七）允许其他单位或者个人以本所名义承办业务； （九）承办与自身规模、执业能力、风险承担能力不匹配的业务；"},{"i":32,"n":"第六十六条","txt":"会计师事务所有下列情形之一的，由省级以上财政部门责令限期改正，逾期不改正的可以按照本办法第六十三条第二款的规定进行处理： （二）分所名称不符合本办法第二十六条规定的；"},{"i":33,"n":"第六十七条","txt":"会计师事务所违反本办法第六十条第一项至第四项规定的，由省级以上财政部门给予警告，没收违法所得，可以并处违法所得1倍以上5倍以下的罚款；情节严重的，并可以由省级以上财政部门暂停其执业1个月到1年或者吊销执业许可。"},{"i":34,"n":"第六十八条","txt":"会计师事务所违反本办法第二十四条、第六十二条第二项至第十项规定的，由省级以上财政部门责令限期整改，未按规定期限整改的，对会计师事务所给予警告，有违法所得的，可以并处违法所得1倍以上3倍以下罚款，最高不超过3万元；没有违法所得的，可以并处以1万元以下的罚款。对会计师事务所首席合伙人（主任会计师）等相关管理人员和直接责任人员可以给予警告，情节严重的，可以并处1万元以下罚款；涉嫌犯罪的，移送司法机关，依法追究刑事责任。"},{"i":35,"n":"第七十条","txt":"注册会计师违反本办法第六十条第一项至第四项规定的，由省级以上财政部门给予警告；情节严重的，可以由省级以上财政部门暂停其执行业务1个月至1年或者吊销注册会计师证书。"},{"i":36,"n":"第七十一条","txt":"注册会计师违反本办法第六十一条规定，情节轻微，没有造成危害后果的，按照本办法第六十三条第二款的规定进行处理；情节严重的，由省级以上财政部门给予警告，有违法所得的，可以并处违法所得1倍以上3倍以下的罚款，最高不超过3万元；没有违法所得的，可以并处以1万元以下罚款。 会计师事务所违反本办法第六条第二款规定的，适用前款规定处理。"},{"i":37,"n":"第七十四条","txt":"省级以上财政部门在作出较大数额罚款、暂停执业、吊销注册会计师证书或者会计师事务所执业许可的决定之前，应当告知当事人有要求听证的权利；当事人要求听证的，应当按规定组织听证。"},{"i":38,"n":"第七十六条","txt":"省级以上财政部门的工作人员在实施审批和监督过程中，滥用职权、玩忽职守、徇私舞弊或者泄露国家秘密、商业秘密的，按照《公务员法》等国家有关规定追究相应责任；涉嫌犯罪的，移送司法机关，依法追究刑事责任。"},{"i":39,"n":"第七十七条","txt":"本办法所称“注册会计师”是指中国注册会计师；所称“注册会计师执业资格”是指中国注册会计师执业资格。"},{"i":40,"n":"第七十八条","txt":"具有注册会计师执业资格的境外人员可以依据本办法申请担任会计师事务所合伙人（股东）。"},{"i":41,"n":"第七十九条","txt":"本办法施行前已经取得的会计师事务所及其分所执业许可继续有效，发生变更事项的，其变更后的情况应当符合本办法的规定。"},{"i":42,"n":"第八十条","txt":"注册会计师协会是由会计师事务所和注册会计师组成的社会团体，依照《注册会计师法》履行相关职责，接受财政部和省级财政部门的监督、指导。"}],"kuaijidanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强会计档案管理,有效保护和利用会计档案,根据《中华人民共和国会计法》《中华人民共和国档案法》等有关法律和行政法规,制定本办法。"},{"i":2,"n":"第二条","txt":"国家机关、社会团体、企业、事业单位和其他组织(以下统称单位)管理会计档案适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称会计档案是指单位在进行会计核算等过程中接收或形成的,记录和反映单位经济业务事项的,具有保存价值的文字、图表等各种形式的会计资料,包括通过计算机等电子设备形成、传输和存储的电子会计档案。"},{"i":4,"n":"第四条","txt":"财政部和国家档案局主管全国会计档案工作,共同制定全国统一的会计档案工作制度,对全国会计档案工作实行监督和指导。 县级以上地方人民政府财政部门和档案行政管理部门管理本行政区域内的会计档案工作,并对本行政区域内会计档案工作实行监督和指导。"},{"i":5,"n":"第五条","txt":"单位应当加强会计档案管理工作,建立和完善会计档案的收集、整理、保管、利用和鉴定销毁等管理制度,采取可靠的安全防护技术和措施,保证会计档案的真实、完整、可用、安全。 单位的档案机构或者档案工作人员所属机构(以下统称单位档案管理机构)负责管理本单位的会计档案。单位也可以委托具备档案管理条件的机构代为管理会计档案。"},{"i":6,"n":"第六条","txt":"下列会计资料应当进行归档: (一)会计凭证,包括原始凭证、记账凭证; (二)会计账簿,包括总账、明细账、日记账、固定资产卡片及其他辅助性账簿; (三)财务会计报告,包括月度、季度、半年度、年度财务会计报告; (四)其他会计资料,包括银行存款余额调节表、银行对账单、纳税申报表、会计档案移交清册、会计档案保管清册、会计档案销毁清册、会计档案鉴定意见书及其他具有保存价值的会计资料。"},{"i":7,"n":"第七条","txt":"单位可以利用计算机、网络通信等信息技术手段管理会计档案。"},{"i":8,"n":"第八条","txt":"同时满足下列条件的,单位内部形成的属于归档范围的电子会计资料可仅以电子形式保存,形成电子会计档案: (一)形成的电子会计资料来源真实有效,由计算机等电子设备形成和传输; (二)使用的会计核算系统能够准确、完整、有效接收和读取电子会计资料,能够输出符合国家标准归档格式的会计凭证、会计账簿、财务会计报表等会计资料,设定了经办、审核、审批等必要的审签程序; (三)使用的电子档案管理系统能够有效接收、管理、利用电子会计档案,符合电子档案的长期保管要求,并建立了电子会计档案与相关联的其他纸质会计档案的检索关系; (四)采取有效措施,防止电子会计档案被篡改; (五)建立电子会计档案备份制度,能够有效防范自然灾害、意外事故和人为破坏的影响; (六)形成的电子会计资料不属于具有永久保存价值或者其他重要保存价值的会计档案。"},{"i":9,"n":"第九条","txt":"满足本办法第八条规定条件,单位从外部接收的电子会计资料附有符合《中华人民共和国电子签名法》规定的电子签名的,可仅以电子形式归档保存,形成电子会计档案。"},{"i":10,"n":"第十条","txt":"单位的会计机构或会计人员所属机构(以下统称单位会计管理机构)按照归档范围和归档要求,负责定期将应当归档的会计资料整理立卷,编制会计档案保管清册。"},{"i":11,"n":"第十一条","txt":"当年形成的会计档案,在会计年度终了后,可由单位会计管理机构临时保管一年,再移交单位档案管理机构保管。因工作需要确需推迟移交的,应当经单位档案管理机构同意。 单位会计管理机构临时保管会计档案最长不超过三年。临时保管期间,会计档案的保管应当符合国家档案管理的有关规定,且出纳人员不得兼管会计档案。"},{"i":12,"n":"第十二条","txt":"单位会计管理机构在办理会计档案移交时,应当编制会计档案移交清册,并按照国家档案管理的有关规定办理移交手续。 纸质会计档案移交时应当保持原卷的封装。电子会计档案移交时应当将电子会计档案及其元数据一并移交,且文件格式应当符合国家档案管理的有关规定。特殊格式的电子会计档案应当与其读取平台一并移交。 单位档案管理机构接收电子会计档案时,应当对电子会计档案的准确性、完整性、可用性、安全性进行检测,符合要求的才能接收。"},{"i":13,"n":"第十三条","txt":"单位应当严格按照相关制度利用会计档案,在进行会计档案查阅、复制、借出时履行登记手续,严禁篡改和损坏。 单位保存的会计档案一般不得对外借出。确因工作需要且根据国家有关规定必须借出的,应当严格按照规定办理相关手续。 会计档案借用单位应当妥善保管和利用借入的会计档案,确保借入会计档案的安全完整,并在规定时间内归还。"},{"i":14,"n":"第十四条","txt":"会计档案的保管期限分为永久、定期两类。定期保管期限一般分为10年和30年。 会计档案的保管期限,从会计年度终了后的第一天算起。"},{"i":15,"n":"第十五条","txt":"各类会计档案的保管期限原则上应当按照本办法附表执行,本办法规定的会计档案保管期限为最低保管期限。 单位会计档案的具体名称如有同本办法附表所列档案名称不相符的,应当比照类似档案的保管期限办理。"},{"i":16,"n":"第十六条","txt":"单位应当定期对已到保管期限的会计档案进行鉴定,并形成会计档案鉴定意见书。经鉴定,仍需继续保存的会计档案,应当重新划定保管期限;对保管期满,确无保存价值的会计档案,可以销毁。"},{"i":17,"n":"第十七条","txt":"会计档案鉴定工作应当由单位档案管理机构牵头,组织单位会计、审计、纪检监察等机构或人员共同进行。"},{"i":18,"n":"第十八条","txt":"经鉴定可以销毁的会计档案,应当按照以下程序销毁: (一)单位档案管理机构编制会计档案销毁清册,列明拟销毁会计档案的名称、卷号、册数、起止年度、档案编号、应保管期限、已保管期限和销毁时间等内容。 (二)单位负责人、档案管理机构负责人、会计管理机构负责人、档案管理机构经办人、会计管理机构经办人在会计档案销毁清册上签署意见。 (三)单位档案管理机构负责组织会计档案销毁工作,并与会计管理机构共同派员监销。监销人在会计档案销毁前,应当按照会计档案销毁清册所列内容进行清点核对;在会计档案销毁后,应当在会计档案销毁清册上签名或盖章。 电子会计档案的销毁还应当符合国家有关电子档案的规定,并由单位档案管理机构、会计管理机构和信息系统管理机构共同派员监销。"},{"i":19,"n":"第十九条","txt":"保管期满但未结清的债权债务会计凭证和涉及其他未了事项的会计凭证不得销毁,纸质会计档案应当单独抽出立卷,电子会计档案单独转存,保管到未了事项完结时为止。 单独抽出立卷或转存的会计档案,应当在会计档案鉴定意见书、会计档案销毁清册和会计档案保管清册中列明。"},{"i":20,"n":"第二十条","txt":"单位因撤销、解散、破产或其他原因而终止的,在终止或办理注销登记手续之前形成的会计档案,按照国家档案管理的有关规定处置。"},{"i":21,"n":"第二十一条","txt":"单位分立后原单位存续的,其会计档案应当由分立后的存续方统一保管,其他方可以查阅、复制与其业务相关的会计档案。 单位分立后原单位解散的,其会计档案应当经各方协商后由其中一方代管或按照国家档案管理的有关规定处置,各方可以查阅、复制与其业务相关的会计档案。 单位分立中未结清的会计事项所涉及的会计凭证,应当单独抽出由业务相关方保存,并按照规定办理交接手续。 单位因业务移交其他单位办理所涉及的会计档案,应当由原单位保管,承接业务单位可以查阅、复制与其业务相关的会计档案。对其中未结清的会计事项所涉及的会计凭证,应当单独抽出由承接业务单位保存,并按照规定办理交接手续。"},{"i":22,"n":"第二十二条","txt":"单位合并后原各单位解散或者一方存续其他方解散的,原各单位的会计档案应当由合并后的单位统一保管。单位合并后原各单位仍存续的,其会计档案仍应当由原各单位保管。"},{"i":23,"n":"第二十三条","txt":"建设单位在项目建设期间形成的会计档案,需要移交给建设项目接受单位的,应当在办理竣工财务决算后及时移交,并按照规定办理交接手续。"},{"i":24,"n":"第二十四条","txt":"单位之间交接会计档案时,交接双方应当办理会计档案交接手续。 移交会计档案的单位,应当编制会计档案移交清册,列明应当移交的会计档案名称、卷号、册数、起止年度、档案编号、应保管期限和已保管期限等内容。 交接会计档案时,交接双方应当按照会计档案移交清册所列内容逐项交接,并由交接双方的单位有关负责人负责监督。交接完毕后,交接双方经办人和监督人应当在会计档案移交清册上签名或盖章。 电子会计档案应当与其元数据一并移交,特殊格式的电子会计档案应当与其读取平台一并移交。档案接受单位应当对保存电子会计档案的载体及其技术环境进行检验,确保所接收电子会计档案的准确、完整、可用和安全。"},{"i":25,"n":"第二十五条","txt":"单位的会计档案及其复制件需要携带、寄运或者传输至境外的,应当按照国家有关规定执行。"},{"i":26,"n":"第二十六条","txt":"单位委托中介机构代理记账的,应当在签订的书面委托合同中,明确会计档案的管理要求及相应责任。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定的单位和个人,由县级以上人民政府财政部门、档案行政管理部门依据《中华人民共和国会计法》《中华人民共和国档案法》等法律法规处理处罚。"},{"i":28,"n":"第二十八条","txt":"预算、计划、制度等文件材料,应当执行文书档案管理规定,不适用本办法。"},{"i":29,"n":"第二十九条","txt":"不具备设立档案机构或配备档案工作人员条件的单位和依法建账的个体工商户,其会计档案的收集、整理、保管、利用和鉴定销毁等参照本办法执行。"},{"i":30,"n":"第三十条","txt":"各省、自治区、直辖市、计划单列市人民政府财政部门、档案行政管理部门,新疆生产建设兵团财务局、档案局,国务院各业务主管部门,中国人民解放军总后勤部,可以根据本办法制定具体实施办法。"},{"i":31,"n":"第三十一条","txt":"本办法由财政部、国家档案局负责解释,自2016年1月1日起施行。1998年8月21日财政部、国家档案局发布的《会计档案管理办法》(财会字〔1998〕32号)同时废止。"}],"guojiaxuzhihongquyunyongcaizhengbuchangzijinguanlidc6c06-2":[{"i":1,"n":"第一条","txt":"为了加强蓄滞洪区运用财政补偿资金的使用和管理，确保资金及时到位和合理、有效地使用，根据《蓄滞 洪区运用补偿暂行办法》（以下简称《暂行办法》），制定本规定。"},{"i":2,"n":"第二条","txt":"国家蓄滞洪区是指《暂行办法》附录中所列的蓄滞洪区，其运用是根据批准的洪水调度运用方案，按照调度权限，由防汛指挥机构发布的分洪命令所实施的分洪运用。"},{"i":3,"n":"第三条","txt":"国家蓄滞洪区运用财政补偿资金（以下简称补偿资金）是政府为了保障蓄滞洪区居民的基本生活、尽快恢复农业生产所设立的专项资金。国家蓄滞洪区运用损失由中央财政和省级财政共同给予补偿，其他蓄滞洪区运用损失由地方财政给予补偿。"},{"i":4,"n":"第四条","txt":"国家蓄滞洪区运用补偿资金由中央财政和省级财政专项安排。"},{"i":5,"n":"第五条","txt":"本规定适用于国家蓄滞洪区运用财政补偿资金的使用和管理。其他蓄滞洪区运用补偿资金的使用和管理可参照本规定执行。"},{"i":6,"n":"第六条","txt":"蓄滞洪区内具有常住户口的居民（以下简称区内居民），在蓄滞洪区运用后依照《暂行办法》和本规定获得补偿。 区内居民同时根据国家规定享受与其他洪水灾区灾民同样的政府救助和社会捐助。 蓄滞洪区运用时，蓄滞洪区所在地县级以上人民政府应及时组织有关部门对蓄滞洪区的淹没范围加以界定。"},{"i":7,"n":"第七条","txt":"蓄滞洪区所在地县级人民政府应组织有关部门，根据当地物价水平和财产新旧程度，合理确定区内居民补偿项目的水毁损失价值。"},{"i":8,"n":"第八条","txt":"蓄滞洪区运用后，对区内居民遭受的下列损失给予补偿： （一）计税农作物、专业养殖和经济林水毁损失； （二）住房水毁损失； （三）无法转移的家庭农业生产机械、役畜和家庭主要耐用消费品水毁损失。"},{"i":9,"n":"第九条","txt":"农作物补偿包括粮食、蔬菜、油料和经济类作物的水毁损失。专业养殖主要补偿以养殖业为主业的家禽家畜以及水产养殖的水毁损失。经济林主要补偿果树类、苗圃等水毁损失。具体补偿项目 及标准如下： （一）农作物。补偿标准按当地统计部门统计上报的蓄滞洪前三年（不含分洪年份，下同）同季平均产值的５０—７０％，并按类和实际生长期实行亩均定值补偿。 １．粮食类作物主要包括：水稻、玉米、高梁、小麦、豆类、薯类等。 ２．蔬菜类作物主要包括：各种蔬菜、瓜果等。 ３．油料类作物主要包括：花生、芝麻、油菜等。 ４．经济类作物主要包括：烟叶、甘蔗、麻类、药材、棉花、花卉等。 （二）专业养殖。主要补偿以养殖业为主业的水毁损失，主要包括：猪、牛、羊、鸡、鸭、鹅等家禽家畜的专业养殖，水面精养、普养鱼类及其他水产养殖等。补偿标准按前三年同期平均产值的４０—５０％，并按实际生长期实行定值补偿。 １．家禽家畜的专业养殖：依据省级统"},{"i":10,"n":"第十条","txt":"居民住房只补偿主体部分的水毁损失，其他搭建的非居住附属房屋不属于补偿范围。居民住房按损失价值的７０％予以补偿。"},{"i":11,"n":"第十一条","txt":"无法转移的农业生产机械、役畜和家庭主要耐用消费品主要补偿因受转移时间等限制没有转移到安全区域而造成的水毁损失。 （一）家庭农业生产机械。主要包括：电（动）机、柴油机等农用生产机械。 （二）役畜。主要包括：牛、马、骡、驴等从事农役的牲畜（不含幼畜）。 （三）家庭主要耐用消费品。主要包括：空调、电视机、电冰箱、洗衣机等主要家用电器。 以上三项按水毁损失的５０％补偿。其中：登记总价值在２０００元以下的，按照水毁损失的１００％补偿；水毁损失超过２０００元不足４０００元的，按照２０００元补偿。"},{"i":12,"n":"第十二条","txt":"蓄滞洪区分洪运用后，区内行政事业、公益事业单位的公共财产和设备的水毁损失，以及区内各类企业和公共设施的水毁损失不属于补偿范围。"},{"i":13,"n":"第十三条","txt":"已下达分洪运用命令，但未实施分洪，因此而造成的农业生产等方面损失，应当给予适当的补偿。"},{"i":14,"n":"第十四条","txt":"蓄滞洪区所在地的县级人民政府应按照《暂行办法》的规定，组织有关部门和乡（镇）人民政府（含街道办事处，下同）对区内居民的财产逐户进行登记，并填写水利部制定的《蓄滞洪区居民财产登记及变更登记（汇总）表》，由村（居）民委员会张榜公布；在规定时间内村（居）民无异议的，由县、乡（镇）、村分级建档立卡。 以村或者居民委员会为单位进行财产登记时，应有村（居）民委员会干部、村（居）民代表参加。"},{"i":15,"n":"第十五条","txt":"已登记公布的区内居民的承包土地、住房或者其他财产发生变更时，村（居）民委员会应当于每年汛前汇总，并向乡（镇）人民政府提出财产变更登记申请，由乡（镇）人民政府核实登记后，报蓄滞洪区所在地的县级人民政府指定的部门备案。"},{"i":16,"n":"第十六条","txt":"蓄滞洪 区所在地的县级人民政府应当及时将区内居民的财产登记情况及变更情况汇总后逐级上报省级水利主管部门。由省级水利主管部门核查汇总后，上报水利部，同时抄送省级财政部门和 所在江河的流域管理机构备案。 流域管理机构应根据每年的汛期预报对上报的蓄滞洪区财产登记及变更登记情况进行必要的抽查。对抽查中发现的问题应要求有关市县予以纠正。"},{"i":17,"n":"第十七条","txt":"蓄滞洪区分洪运用后，所在地的县级人民政府应及时组织有关部门和乡镇人民政府核查区内居民的水毁损失情况，填写水利部制定的《蓄滞洪区居民财产损失核查（汇总）表》、《蓄滞洪区居民财产损失补偿（汇总申报）表》，并按照《暂行办法》和本规定所确定的补偿标准提出补偿具体方案，逐级上报省级人民政府或其授权的部门。 以村（居）民委员会为单位核查损失时，应当有村（居）民委员会干部、村（居）民代表参加，并对损失情况张榜公布。"},{"i":18,"n":"第十八条","txt":"省级人民政府应及时组织有关部门核实蓄滞洪区内居民水毁损失情况，并提出补偿意见。"},{"i":19,"n":"第十九条","txt":"流域管理机构应及时对省级人民政府提出的蓄滞洪区运用补偿意见进行核查，并提出核查意见。"},{"i":20,"n":"第二十条","txt":"省级人民政府应及时将所提出的蓄滞洪区运用补偿方案，连同流域机构出具的核查意见上报国务院，并抄送财政部和水利部。 财政部和水利部对省级人民政府提出的补偿方案进行审查和核定后，提出补偿意见。由财政部拟定补偿资金总额，上报国务院批准后，下达给省级财政。"},{"i":21,"n":"第二十一条","txt":"国家根据蓄滞洪区在流域防洪调度中所承担的防洪任务的重要程度、所在省（自治区、直辖市）的财政状况以及区内居民恢复生产的难易程度等因素，核定中央财政与省级财政补偿资金的分摊比例。中央财政一般分担国家蓄滞洪区运用后应补偿资金总额的４０—７０％。"},{"i":22,"n":"第二十二条","txt":"国务院批准蓄滞洪区运用补偿方案后，中央财政将负担的补偿资金下拨给蓄滞洪区所在省级财政。省级财政将其本级财政承担的补偿资金和中央补偿资金一并及时、足额下拨给蓄滞洪区所在市级或者县级财政，并抄报财政部、水利部和有关流域管理机构。"},{"i":23,"n":"第二十三条","txt":"蓄滞洪区运用财政补偿资金由财政部门统一管理，实行专帐核算，任何单位或个人不得以任何理由改变资金用途。"},{"i":24,"n":"第二十四条","txt":"居民财产登记与变更、损失核查以及补偿资金发放等工作经费不列入补偿资金使用范围，所需经费由地方财政列入预算，专项解决。"},{"i":25,"n":"第二十五条","txt":"蓄滞洪区所在地县级人民政府根据国务院批准的补偿方案，组织财政、水利等部门尽快制定出补偿资金具体发放方案，乡（镇）人民政府据此逐户确定具体补偿金额，并由村（居）民委员 会张榜公布。 补偿金额张榜公布３—５日，无异议，由乡（镇）人民政府组织发放补偿凭证，区内居民持补偿凭证、村（居）民委员会出具的证明和身份证明到县级财政主管部门指定的机构领取补偿金。"},{"i":26,"n":"第二十六条","txt":"蓄滞洪区所在地县级财政部门统一负责补偿资金的发放工作，不得滞留补偿资金，不得把补偿资金划拨到乡（镇）、村。"},{"i":27,"n":"第二十七条","txt":"各级财政部门应加强对财政补偿资金的管理，严格资金的发放手续，定期向上级财政部门报告资金使用情况，并认真做好补偿资金的财务决算工作。 补偿资金发放完毕后，应及时对补偿资金的发放情况进行总结，并逐级上报。"},{"i":28,"n":"第二十八条","txt":"蓄滞洪区所在地各级人民政府应组织各级财政、水利等部门加强对补偿资金的监督、审计稽查工作。"},{"i":29,"n":"第二十九条","txt":"流域管理机构应当加强对所辖区内蓄滞洪区运用补偿资金的发放情况的监督，必要时应会同省级人民政府或者其授权的主管部门进行调查，并将调查的情况上报财政部和水利部，同时抄送 省级人民政府。"},{"i":30,"n":"第三十条","txt":"有下列行为之一的，由县级以上财政部门责令改正，及时追加资金，并对有关单位予以警告、罚款： （一）在财产登记工作中弄虚作假的； （二）在蓄滞洪区运用补偿过程中谎报、虚报损失的； （三）在补偿资金发放过程中，收取各种手续费和代收代扣其他费用的； （四）截留、挤占财政补偿资金的； （五）骗取、挪用、侵吞财政补偿资金的。 对有以上违法行为的单位直接负责的主管人员和其他直接责任人员处以警告和罚款，并建议有关部门予以行政处分，构成犯罪的，移交司法部门依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"省级财政主管部门可根据本规定会同本级水利主管部门制定具体实施细则，并上报财政部备案。"},{"i":32,"n":"第三十二条","txt":"本规定由财政部负责解释。"},{"i":33,"n":"第三十三条","txt":"本规定自２００２年１月１日起施行。"}],"guojiaxuzhihongquyunyongcaizhengbuchangzijinguanlidc6c06":[{"i":1,"n":"第一条","txt":"为了规范和加强国家蓄滞洪区运用财政补偿资金的管理，确保资金合理有效使用，根据国务院《蓄滞洪区运用补偿暂行办法》（以下简称《暂行办法》）制定本规定。"},{"i":2,"n":"第二条","txt":"国家蓄滞洪区是指《暂行办法》附录中所列的蓄滞洪区。国家蓄滞洪区运用是指防汛指挥机构根据批准的洪水调度运用方案，按照调度权限发布分洪命令后所实施的蓄滞洪水行为。"},{"i":3,"n":"第三条","txt":"本规定适用于国家蓄滞洪区运用财政补偿资金的使用和管理。"},{"i":4,"n":"第四条","txt":"国家蓄滞洪区运用财政补偿资金（以下简称补偿资金）是政府为了保障蓄滞洪区居民的基本生活、尽快恢复农业生产所设立的专项资金。国家蓄滞洪区运用后造成的损失由中央财政和省级财政共同给予补偿。"},{"i":5,"n":"第五条","txt":"补偿资金的管理应当遵循公开、公正、及时、便民的原则。"},{"i":6,"n":"第六条","txt":"国家蓄滞洪区内具有常住户口的居民（以下简称区内居民），在蓄滞洪区运用后依照《暂行办法》和本规定获得补偿。国家蓄滞洪区所在地县级以上人民政府应当及时组织有关部门对国家蓄滞洪区运用的淹没范围予以界定。"},{"i":7,"n":"第七条","txt":"国家蓄滞洪区运用后区内居民遭受的下列损失，在淹没范围内的给予补偿: （一）承包土地上的农作物、专业养殖和经济林水毁损失; （二）住房水毁损失; （三）无法转移的家庭农业生产机械、役畜和家庭主要耐用消费品水毁损失。"},{"i":8,"n":"第八条","txt":"农作物、专业养殖、经济林具体补偿标准如下: （一）农作物实行亩均定值补偿。补偿标准由所在地省级人民政府按当地统计部门统计上报的蓄滞洪前三年（不含分洪年份，下同）同季主要农作物平均产值的 50%～70%确定。 （二）专业养殖实行分类定值补偿。专业养殖的种类和规模，由省级行业主管部门依据相关规定予以认定。补偿标准由省级人民政府按蓄滞洪前三年相同生长期平均产值的40%～50%确定。 （三）经济林实行亩均定值补偿。经济林的种类和规模，由省级行业主管部门依据相关规定予以认定。补偿标准由省级人民政府按蓄滞洪前三年相同生长期平均产值的40%～50%确定。"},{"i":9,"n":"第九条","txt":"居民住房只补偿主体部分的水毁损失，其他搭建的附属建筑物不属于补偿范围。居民住房按损失价值的70%予以补偿，损失价值由国家蓄滞洪区所在地县级以上人民政府或其授权的部门确定。灾后享受国家统一建房补助政策的区内居民，其房屋损失不予重复补偿。"},{"i":10,"n":"第十条","txt":"无法转移的家庭农业生产机械、役畜和家庭主要耐用消费品主要补偿因受转移时间等限制没有转移到安全区域而造成的水毁损失。 （一）家庭农业生产机械。主要包括:电（动）机、柴油机等农用生产机械。 （二）役畜。主要包括:牛、马、骡、驴等从事农役的牲畜（不含幼畜）。 （三）家庭主要耐用消费品。主要包括:空调、电视机、电冰箱、洗衣机等主要家用电器。 以上三项按水毁损失的50%补偿。但登记总价值在2 000元以下的，按照水毁损失的100%补偿;水毁损失超过2 000元不足4 000元的，按照2 000元补偿。"},{"i":11,"n":"第十一条","txt":"已下达蓄滞洪转移命令，因情况变化未实施蓄滞洪造成的损失，给予适当补偿。省级人民政府依据损失的具体情况，拟定人均补偿标准，报财政部、水利部审定。"},{"i":12,"n":"第十二条","txt":"国家蓄滞洪区运用后，区内行政事业、公益事业单位的公共财产和设备的水毁损失，以及区内各类企业和公共设施的水毁损失不属于本规定的补偿范围。"},{"i":13,"n":"第十三条","txt":"国家蓄滞洪区所在地的县级人民政府应按照《暂行办法》的规定，组织有关部门和乡（镇）人民政府（含街道办事处，下同）对区内居民的承包土地、住房、家庭农业生产机械和役畜以及家庭主要耐用消费品（以下简称居民财产）逐户进行登记，并填写水利部制定的《蓄滞洪区居民财产登记及变更登记（汇总）表》，由村（居）民委员会张榜公布;在规定时间内村（居）民无异议的，由县、乡（镇）、村分级建档立卡。以村或者居民委员会为单位进行财产登记时，应有村（居）民委员会干部、村（居）民代表参加。"},{"i":14,"n":"第十四条","txt":"已登记公布的区内居民财产发生变更时，村（居）民委员会应当于每年汛前汇总，并向乡（镇）人民政府提出财产变更登记申请，由乡（镇）人民政府核实登记后，报蓄滞洪区所在地的县级人民政府指定的部门备案。"},{"i":15,"n":"第十五条","txt":"国家蓄滞洪区所在地的县级人民政府应当及时将区内居民财产登记情况及变更情况汇总后逐级上报省级水行政主管部门。由省级水行政主管部门核查汇总后，上报水利部，同时抄送省级财政部门和所在江河的流域管理机构备案。"},{"i":16,"n":"第十六条","txt":"国家蓄滞洪区运用后，所在地的县级人民政府应及时组织有关部门和乡（镇）人民政府核查区内居民的水毁损失情况，填写水利部制定的《蓄滞洪区居民财产损失核查（汇总）表》、《蓄滞洪区居民财产损失补偿（汇总申报）表》，逐级上报省级人民政府或其授权的部门。以村（居）民委员会为单位核查损失时，应当有乡（镇）、村（居）民委员会干部和村（居）民代表参加，并对损失情况张榜公布。"},{"i":17,"n":"第十七条","txt":"省级人民政府或其授权的部门应及时核实蓄滞洪区内居民水毁损失情况，提出补偿方案，并报流域管理机构核查。"},{"i":18,"n":"第十八条","txt":"流域管理机构应及时对省级人民政府或其授权的部门提出的蓄滞洪区运用补偿方案进行核查，并提出核查意见。"},{"i":19,"n":"第十九条","txt":"省级人民政府应及时将蓄滞洪区运用补偿方案，连同流域管理机构出具的核查意见上报国务院，并抄送财政部和水利部。财政部和水利部对补偿方案及核查意见进行审查和核定后，提出补偿意见，财政部拟定补偿资金总额，上报国务院批准后实施。"},{"i":20,"n":"第二十条","txt":"财政部根据蓄滞洪区在流域防洪调度中所承担的防洪任务的重要程度、所在省（自治区、直辖市）的财政状况以及区内居民恢复生产的难易程度等因素，拟定中央财政与省级财政补偿资金的分摊比例。中央财政一般分担国家蓄滞洪区运用后应补偿资金总额的40%～70%。"},{"i":21,"n":"第二十一条","txt":"国务院批准蓄滞洪区运用补偿方案后，财政部应将分担的补偿资金下拨给蓄滞洪区所在地省级财政部门。省级财政部门将其本级财政分担的补偿资金和中央补偿资金一并及时、足额下拨给蓄滞洪区所在地市级或者县级财政部门，并将资金下拨情况抄送财政部、水利部和有关流域管理机构。"},{"i":22,"n":"第二十二条","txt":"补偿资金由财政部门统一管理，实行专账核算，任何单位或个人不得改变资金用途。"},{"i":23,"n":"第二十三条","txt":"居民财产登记与变更、损失核查以及补偿资金发放等工作经费不列入补偿资金使用范围，所需经费由地方财政负担。"},{"i":24,"n":"第二十四条","txt":"补偿资金的发放工作由国家蓄滞洪区所在地县级人民政府或其授权的部门负责。国家蓄滞洪区所在地县级人民政府应当根据国务院批准的补偿方案，组织财政、水利等部门制定补偿资金具体发放方案，乡（镇）人民政府据此逐户确定具体补偿金额，并由村（居）民委员会张榜公布。具体补偿金额张榜公布5日后无异议的，由乡（镇）人民政府组织发放补偿凭证，区内居民持补偿凭证、村（居）民委员会出具的证明和身份证明到县级财政部门指定的机构领取补偿金。张榜公布后有异议的，村（居）民委员会应及时核实。经县级以上人民政府或其授权的部门核查认定，不应发放的补偿资金应全部返还财政部门。"},{"i":25,"n":"第二十五条","txt":"地方各级财政部门应加强对补偿资金的管理，严格资金的发放手续，定期向上级财政部门报告资金使用情况，并认真做好补偿资金的财务决算工作。国家蓄滞洪区所在地县级人民政府或其授权的部门在补偿资金发放完毕后，应及时对补偿资金的发放情况进行总结，并逐级上报财政部、水利部。"},{"i":26,"n":"第二十六条","txt":"国家蓄滞洪区所在地县级人民政府或其授权的部门不得滞留、挪用、抵扣补偿资金，不得把补偿资金划拨到乡（镇）、村。"},{"i":27,"n":"第二十七条","txt":"国家蓄滞洪区所在地各级人民政府应组织有关部门加强对补偿资金的监督、检查。"},{"i":28,"n":"第二十八条","txt":"流域管理机构应当加强对所辖区内蓄滞洪区运用补偿资金发放情况的监督，必要时应会同省级人民政府或其授权的部门进行调查，并将调查的情况上报财政部和水利部，同时抄送省级人民政府或其授权的部门。"},{"i":29,"n":"第二十九条","txt":"在补偿资金管理过程中，对违反《暂行办法》和本规定的行为，依照《财政违法行为处罚处分条例》给予处罚、处理、处分。"},{"i":30,"n":"第三十条","txt":"其他蓄滞洪区运用后造成的损失，其财政补偿资金的管理参照本规定执行。"},{"i":31,"n":"第三十一条","txt":"省级财政部门可根据本规定会同本级水行政主管部门制定具体实施细则，并上报财政部、水利部备案。"},{"i":32,"n":"第三十二条","txt":"本规定由财政部负责解释。"},{"i":33,"n":"第三十三条","txt":"本规定自2006年7月1日起施行。2001年12月31日发布的《国家蓄滞洪区运用财政补偿资金管理规定》（财政部令第 13号）同时废止。"}],"guojijinrongzuzhihewaiguozhengfudaikuanzengkuanguae90365-2":[{"i":1,"n":"第一条","txt":"为了进一步规范和加强国际金融组织和外国政府贷款、赠款管理，合理、有效地使用资金，根据国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国际金融组织和外国政府贷款（以下简称贷款）以及赠款的管理工作适用本办法。"},{"i":3,"n":"第三条","txt":"财政部负责贷款、赠款的管理工作，是政府外债的统一管理部门。"},{"i":4,"n":"第四条","txt":"贷款、赠款的使用应当符合国民经济和社会发展战略，体现公共财政职能，促进经济社会和城乡区域协调发展。"},{"i":5,"n":"第五条","txt":"贷款的筹借、使用、偿还应当体现责权利相统一的原则，实现债务可持续性和良性循环，有效防范和化解债务风险。"},{"i":6,"n":"第六条","txt":"本办法下列用语的含义: （一）贷款，是指国际金融组织贷款和外国政府贷款; （二）国际金融组织贷款，是指财政部经国务院批准代表国家向世界银行、亚洲开发银行、国际农业发展基金、欧洲投资银行等国际金融组织统一筹借并形成政府外债的贷款，以及与上述贷款搭配使用的联合融资; （三）外国政府贷款，是指财政部经国务院批准代表国家向外国政府、北欧投资银行等统一筹借并形成政府外债的贷款，国务院批准的参照外国政府贷款管理的其他国外贷款，以及与上述贷款搭配使用的联合融资; （四）赠款，是指财政部或者财政部经国务院批准代表国家作为受赠方接受的、不以与贷款搭配使用为前提条件的国际赠款。"},{"i":7,"n":"第七条","txt":"财政部对贷款、赠款实行统一管理，履行下列工作职责 : （一）研究确定贷款、赠款的管理原则，制定基本规章制度 ; （二）会同国务院有关部门研究拟定贷款规划; （三）统筹开展贷款、赠款的对外工作，与国际金融组织和外国政府等进行磋商谈判并签订法律文件; （四）负责贷款、赠款的转贷、转赠、资金使用、偿还、统计、监测等 ; （五）对贷款、赠款活动进行政策指导、协调与监督。"},{"i":8,"n":"第八条","txt":"地方财政部门是本级政府贷款的债权、债务代表和贷款、赠款归口管理机构，统一负责本地区贷款、赠款的全过程管理。"},{"i":9,"n":"第九条","txt":"财政部直接转贷、转赠给国务院有关部门的项目，国务院有关部门应当确定中央项目执行机构，由其具体负责项目的组织实施。"},{"i":10,"n":"第十条","txt":"财政部直接转贷、转赠给地方政府的跨省、自治区、直辖市的联合项目，需要国务院有关部门组织或者协调的，国务院有关部门应当确定中央项目协调机构，由其统一负责项目的指导、组织与协调工作。"},{"i":11,"n":"第十一条","txt":"地方政府承担债务的贷款项目或者接受赠款的项目，地方政府应当确定地方项目执行机构，由其具体负责项目的组织实施。"},{"i":12,"n":"第十二条","txt":"中央项目执行机构、中央项目协调机构和地方项目执行机构，在业务上接受同级财政部门的指导和监督，有关经费开支计划应当报同级财政部门审批或者备案。"},{"i":13,"n":"第十三条","txt":"贷款的筹借工作包括贷款申请、评审与评估、对外磋商与谈判、贷款法律文件签署与生效、转贷关系确定以及还款责任落实等。"},{"i":14,"n":"第十四条","txt":"拟利用国际金融组织贷款的地方应当由省、自治区、直辖市、计划单列市财政部门以及新疆生产建设兵团财政局（以下简称省级财政部门）代表本级政府向财政部提交贷款申请书。 拟利用国际金融组织贷款的国务院有关部门和其他机构应当向财政部提交贷款申请书。凡债务由地方承担的，还应当附送省级财政部门出具的还款承诺函。 贷款申请书包括以下主要内容: （一）贷款的目的和必要性; （二）贷款项目主要内容; （三）贷款资金及配套资金来源; （四）转贷及债务偿还安排。"},{"i":15,"n":"第十五条","txt":"财政部应当对贷款申请书进行审查，并根据本办法第四条、第五条的规定以及贷款方的要求等决定是否将贷款申请列入国际金融组织贷款规划。"},{"i":16,"n":"第十六条","txt":"省级财政部门对已列入国际金融组织贷款规划的有关项目应当组织评审，并向财政部提交评审意见书。财政部根据评审意见书决定是否安排对外磋商谈判。评审事项主要包括: （一）省级政府的债务负担和财政承受能力; （二）贷款项目的财务效益、经济效益和社会效益; （三）项目单位的财务状况和配套资金的落实情况; （四）转贷安排、还款责任和还款资金来源等。"},{"i":17,"n":"第十七条","txt":"按照不同的还款责任，外国政府贷款项目分为以下三类 : （一）省级财政部门或者国务院有关部门作为债务人并承担还款责任的项目 ; （二）项目单位作为债务人并承担还款责任，省级财政部门或者国务院有关部门提供还款保证的项目; （三）项目单位作为债务人并承担还款责任，转贷机构作为对外最终还款人的项目。在此类项目中，省级财政部门或者国务院有关部门既不作为债务人也不提供还款保证。"},{"i":18,"n":"第十八条","txt":"省级财政部门对拟利用外国政府贷款的项目应当组织评审。评审事项按照本办法第十六条 的规定确定。"},{"i":19,"n":"第十九条","txt":"省级财政部门应当就评审后符合要求的、拟利用外国政府贷款的项目向财政部提出申请，并提交以下材料: （一）与债务人有关政府的债务负担情况; （二）省级财政部门利用外国政府贷款申请书。贷款申请书应当说明项目简要情况、贷款项目的贷款来源、贷款金额、债务人、转贷机构、转贷类型和配套资金来源等情况; （三）根据贷款方的要求需要提供的项目环境影响评估报告和英文可行性研究报告。"},{"i":20,"n":"第二十条","txt":"财政部对省级财政部门提交的外国政府贷款申请材料予以审核确认后，应当根据贷款方的发展援助政策要求以及资金承诺情况，统一对外提出备选项目。"},{"i":21,"n":"第二十一条","txt":"需要改变贷款国别和增加贷款金额的外国政府贷款项目，省级财政部门应当向财政部提出书面申请，并由财政部统筹考虑贷款方要求、项目实际需要及其他情况后确定。"},{"i":22,"n":"第二十二条","txt":"财政部负责就符合条件的贷款项目与国际金融组织或者外国政府等进行贷款磋商谈判、组织签署贷款法律文件并办理生效事宜。其他部门应当协助财政部做好相关工作。"},{"i":23,"n":"第二十三条","txt":"财政部负责根据外国政府贷款项目类型委托或者通知转贷机构及时办理评估等相关转贷手续。"},{"i":24,"n":"第二十四条","txt":"外国政府贷款的转贷机构应当按有关规定与国外金融机构签定贷款法律文件、与债务人签署转贷协议，确保对外还本付息和资金垫付。"},{"i":25,"n":"第二十五条","txt":"贷款使用主要包括贷款项目的采购、贷款资金支付、技术援助与人员培训、项目实施进度监测和报告等。 项目单位应当按照国家法律法规和贷款法律文件的规定，组织实施贷款项目。"},{"i":26,"n":"第二十六条","txt":"地方政府承担债务的国际金融组织贷款项目，其出国计划、采购计划、采购代理机构的选择等事项，应当经省级财政部门审核确认后执行。 其他国际金融组织贷款项目的出国计划应当经财政部审核确认后执行。采购计划、采购代理机构的选择应当报财政部备案。 经财政部审核确认的外国政府贷款项目，省级财政部门应当按照财政部有关规定组织或者指导、监督项目单位确定采购代理机构，并将结果报财政部备案。"},{"i":27,"n":"第二十七条","txt":"采购代理机构应当根据委托代理协议，按照贷款方的要求对外国政府贷款项目依法开展采购工作。"},{"i":28,"n":"第二十八条","txt":"贷款资金的使用应当符合贷款法律文件的规定，任何单位和个人均不得以虚报、冒领或者其他手段骗取贷款资金，不得以任何理由和形式滞留、截留、挪用贷款资金或者擅自改变贷款资金用途。"},{"i":29,"n":"第二十九条","txt":"省级财政部门应当加强对国际金融组织贷款项目的管理与监督，有关工作事项主要包括: （一）组织制定贷款项目管理制度，对贷款项目的资金、财务、债务管理工作进行指导与监督; （二）监督贷款资金、配套资金的落实与使用;根据财政部的委托负责贷款资金的支付以及专用账户管理;负责贷款资金的债务分割以及贷款的还本付息付费; （三）会同其他有关部门对贷款项目采购工作进行指导与监督 ; （四）其他与项目实施有关的监督和管理工作。"},{"i":30,"n":"第三十条","txt":"地方、中央项目单位应当按照有关贷款法律文件的要求，分别经由省级财政部门或者直接向财政部及贷款方报送项目进度报告、财务报表及审计报告。"},{"i":31,"n":"第三十一条","txt":"各级财政部门应当对项目执行情况实施监督检查，对发现的问题，应当责令项目单位采取有效措施，限期加以解决和纠正。"},{"i":32,"n":"第三十二条","txt":"贷款项目完工后，项目单位应当及时办理竣工决算，对实施情况进行全面评价和总结，并根据有关规定编制、提交项目竣工报告，办理资产移交和登记手续。 各级财政部门应当指导和督促项目单位做好项目的后评价与总结。"},{"i":33,"n":"第三十三条","txt":"贷款项目完工前，项目单位应当及时制订项目未来运营计划，监测项目的实际运行情况。 在还清贷款前，各级财政部门应当负责对项目运营计划的实施情况进行监督检查，并对项目的效益情况及时进行了解和分析。"},{"i":34,"n":"第三十四条","txt":"国际金融组织贷款项目实施期间，项目单位应当按照国家财务会计制度和具体的贷款项目财务会计管理规定，对贷款项目进行独立的财务管理和会计核算，建立、健全内部财务会计制度。"},{"i":35,"n":"第三十五条","txt":"贷款法律文件签署后，转贷机构以及债务人应当按照国家有关外债管理规定办理外债登记手续。"},{"i":36,"n":"第三十六条","txt":"债务人应当严格遵守转贷协议，制定贷款项目到期本金、利息、承诺费及其他相关费用的偿还计划，保证按时足额偿还。"},{"i":37,"n":"第三十七条","txt":"国际金融组织贷款项目的债务人应当按照财政部的有关规定，进行贷款债务会计核算和债务统计，及时编制本地区、本单位完整、准确的债权债务总体情况报告，并定期报送上级主管部门及同级地方政府。 外国政府贷款项目的转贷机构应当根据财政部和有关省级财政部门的要求及时提供债权债务统计信息和资料。"},{"i":38,"n":"第三十八条","txt":"债务人应当按照财政部有关规定设立贷款还贷准备金，专项用于垫付国际金融组织和外国政府贷款到期债务。各级政府的贷款还贷准备金由同级财政部门设立并管理。"},{"i":39,"n":"第三十九条","txt":"各级财政部门应当建立政府外债的统计、监测、预警体系，防范和化解债务风险。"},{"i":40,"n":"第四十条","txt":"债务人在遵循审慎原则和建立健全内部控制机制的基础上，可以根据法律、法规的规定运用金融工具保值避险。 债务人在选择交易对象时应当遵循竞争原则，在进行交易时避免损失本金。交易结束后，债务人应当将交易有关文件送财政部备案。"},{"i":41,"n":"第四十一条","txt":"贷款项目竣工验收时，应当明晰产权关系和债权债务关系，防止国有资产流失和债务逃废。"},{"i":42,"n":"第四十二条","txt":"债务人实行资产重组、企业改制等产权变更或者破产时，应当事先征得转贷机构和财政部的同意，必要时还需要征得贷款方的同意，并就有关债务偿还安排达成协议，保证优先偿还政府外债。"},{"i":43,"n":"第四十三条","txt":"赠款管理包括赠款项目的前期工作、资金使用、完工评价与总结、资产管理等。"},{"i":44,"n":"第四十四条","txt":"赠款项目的前期工作包括提出赠款申请、编制项目建议书、磋商与谈判、法律文件签署与生效、转赠关系的确立等内容。 地方财政部门应当加强对本地区赠款前期工作的协调与管理。"},{"i":45,"n":"第四十五条","txt":"申请赠款的项目单位应当提出赠款申请，并附送项目概要。 中央项目单位应当直接向财政部申请并报送项目概要，地方项目单位应当通过省级财政部门向财政部申请并报送项目概要。项目概要内容主要包括: （一）项目背景; （二）项目目标; （三）项目内容; （四）项目预算; （五）项目可持续性与示范作用; （六）项目风险。"},{"i":46,"n":"第四十六条","txt":"在财政部审查同意赠款申请以及项目概要后，中央项目单位应当直接向财政部报送项目建议书，地方项目单位通过省级财政部门向财政部报送项目建议书。项目建议书的内容主要包括: （一）项目目标; （二）项目必要性和可行性; （三）项目活动; （四）项目实施计划和组织安排; （五）项目预算; （六）项目质量和风险控制; （七）项目成果应用及推广; （八）监测与评估。"},{"i":47,"n":"第四十七条","txt":"财政部根据审核通过的项目建议书，负责与国际金融组织或者外国政府进行磋商谈判、组织签署赠款法律文件并办理生效事宜。其他部门应当协助财政部做好相关工作。"},{"i":48,"n":"第四十八条","txt":"财政部可以直接或者委托其他机构与国内受赠方签署转赠协议或者执行协议，规范双方的权利和义务，并根据财政部有关规定收取赠款总额1%的有偿使用费。 与贷款搭配使用的联合融资中的赠款的有偿使用费的收取按照前款规定办理。"},{"i":49,"n":"第四十九条","txt":"赠款资金的使用应当符合赠款法律文件的规定，任何单位和个人均不得以虚报、冒领或者其他手段骗取赠款资金，不得以任何理由和形式滞留、截留、挪用赠款资金或者擅自改变赠款资金用途。"},{"i":50,"n":"第五十条","txt":"赠款项目单位应当建立、健全内部财务会计监督制度 ;按照财政部有关赠款项目财务与会计管理的规定，对项目进行独立的财务管理和会计核算;按照赠款法律文件的要求，制定项目实施计划、组织项目实施、办理竣工决算、编制报送完工报告;向财政部门及赠款方报送项目实施情况报告和审计报告。"},{"i":51,"n":"第五十一条","txt":"赠款项目完工前，财政部应当根据国家有关规定与赠款法律文件的要求明确赠款形成资产的所有权归属和处置方式。 赠款形成的资产为国有资产的，有关单位应当参照本办法第四十一条及其他国家有关规定防止国有资产流失。"},{"i":52,"n":"第五十二条","txt":"项目单位违反本办法第三十一条的规定，没有解决和纠正监督检查中所发现问题的，财政部门可以对其采取暂停贷款资金支付、要求退回已支付资金、暂停出国计划审批等措施。"},{"i":53,"n":"第五十三条","txt":"项目单位违反本办法第三十四条、第五十条规定的，由财政部门责令限期改正，并可以依照国家有关会计管理的法律、法规规定进行处罚。"},{"i":54,"n":"第五十四条","txt":"债务人违反本办法第三十六条规定，没有按时足额偿还贷款项目到期本金、利息、承诺费及其他相关费用的，财政部门可以采取以下措施: （一）收取资金占用费或者违约金; （二）暂停新贷款项目的准备工作; （三）暂停贷款项目出国计划的审批和执行; （四）暂停贷款项目的资金支付; （五）加速贷款项目未到期债务的偿还; （六）通过预算扣款或者其他方式依法予以清收。"},{"i":55,"n":"第五十五条","txt":"违反本办法规定，以虚报、冒领或者其他手段骗取贷款资金的，或者滞留、截留、挪用及其他违反规定使用贷款资金的，或者从政府承贷或者担保的贷款中非法获益的，依照《财政违法行为处罚处分条例》以及相关法律、法规规定处理。"},{"i":56,"n":"第五十六条","txt":"对于违反本办法第四十九条规定的，由财政部门责令限期改正，情节严重的，予以警告，并可以采取暂停赠款资金支付、暂停出国计划审批等措施。"},{"i":57,"n":"第五十七条","txt":"财政部门、项目主管部门的工作人员在贷款、赠款的管理、资金使用和偿还过程中，贪污受贿、滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分。"},{"i":58,"n":"第五十八条","txt":"国务院有关部门、计划单列企业集团以及中央管理企业拟利用外国政府贷款、赠款项目的，参照本办法执行。"},{"i":59,"n":"第五十九条","txt":"转贷机构可以根据本办法制定具体的实施办法。"},{"i":60,"n":"第六十条","txt":"本办法自2006年9月1日起施行。"}],"guojijinrongzuzhihewaiguozhengfudaikuanzengkuanguae90365":[{"i":1,"n":"第一条","txt":"为了规范国际金融组织和外国政府贷款、赠款管理，防范政府债务风险，提高资金使用效益，根据《中华人民共和国预算法》等相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国际金融组织和外国政府贷款、赠款的管理工作适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称贷款是指财政部经国务院批准代表国家统一筹借并形成政府外债的贷款，以及与上述贷款搭配使用的联合融资。 本办法所称赠款是指财政部或者经国务院批准由财政部代表国家作为受赠方接受的、不以与贷款搭配使用为前提条　件的国际赠款。"},{"i":4,"n":"第四条","txt":"财政部作为政府外债的统一管理部门，负责全国贷款、赠款的统一管理工作。 地方财政部门作为地方政府性债务归口管理部门，负责本地区贷款、赠款的管理工作。"},{"i":5,"n":"第五条","txt":"贷款、赠款的使用应当坚持创新、协调、绿色、开放、共享的发展理念，符合国民经济和社会发展战略，遵循中期财政规划，体现公共财政职能，促进可持续发展。 贷款、赠款的使用包括项目投融资、能力建设、政策咨询等多种形式。"},{"i":6,"n":"第六条","txt":"贷款、赠款的管理应当遵循统一筹措、规模适度，分类管理、责权明晰，讲求绩效、风险可控的原则。"},{"i":7,"n":"第七条","txt":"按照政府承担还款责任的不同，贷款分为政府负有偿还责任贷款和政府负有担保责任贷款。 政府负有偿还责任贷款，应当纳入本级政府的预算管理和债务限额管理，其收入、支出、还本付息纳入一般公共预算管理。 政府负有担保责任贷款，不纳入政府债务限额管理。政府依法承担并实际履行担保责任时，应当从本级政府预算安排还贷资金，纳入一般公共预算管理。"},{"i":8,"n":"第八条","txt":"赠款纳入中央一般公共预算管理。其中：对于赠款方有指定用途的赠款，按预算管理程序审核后相应列入中央部门预算或中央对地方转移支付；对于赠款方无指定用途的赠款，由财政统筹安排使用。"},{"i":9,"n":"第九条","txt":"财政部可以将贷款拨付给省级政府（包括计划单列市，下同）或国务院有关部门（含直属单位，下同）等使用。省级财政部门可以将财政部拨付的贷款逐级拨付给下级政府或者有关部门和单位使用。 财政部可以将贷款转贷给省级政府、国务院有关部门、中央企业、金融机构等使用。省级财政部门可以将转贷的贷款拨付给下级政府或者有关部门和单位使用；省级财政部门也可以将转贷的贷款逐级转贷给下级政府或者有关部门和单位使用。 财政部可以将接受的赠款拨付给省级政府、国务院有关部门、中央企业等机构使用。"},{"i":10,"n":"第十条","txt":"财政部履行下列职责： （一）统一对外筹借贷款、接受赠款； （二）制定贷款、赠款的管理制度； （三）与国务院有关部门研究编制贷款规划； （四）指导、协调、监督贷款和赠款的立项申报、前期准备、贷款划拨或转贷、赠款分配、资金使用、项目采购、统计监测、债务偿还、绩效管理、成果总结和推广等； （五）统筹开展贷款、赠款的对外工作，协调推进项目准备，对外磋商谈判，签署相关法律文件，办理生效手续； （六）将政府负有偿还责任贷款纳入预算管理和债务限额管理，加强对政府负有担保责任贷款的监控，建立债务风险预警和应急处置机制，防范和化解债务风险； （七）财政部应当履行的其他职责。"},{"i":11,"n":"第十一条","txt":"地方财政部门履行下列职责： （一）制定本地区利用贷款、赠款的管理制度； （二）组织、征集、评审本地区贷款、赠款申请，向上级财政部门申报备选项目； （三）组织和协调本地区贷款、赠款对外工作，参与项目准备和磋商谈判，协助办理法律文件签署和生效手续； （四）监督项目实施单位和有关机构按照贷款、赠款法律文件的规定履行相应职责，及时采取有效措施处理项目出现的问题，并报告上级财政部门； （五）办理贷款、赠款资金的支付和提取，监督项目实施单位和有关机构贷款资金使用、项目采购等情况，保障资金使用的安全、规范、有效； （六）确定转贷或担保机制，落实还款责任，督促并确保贷款按时足额偿还； （七）将本地区政府负有偿还责任贷款纳入本级预算管理和债务限额管理，加强对本地区政府负有担保责任贷款的监控，建立风险应急处置机制和防控措施，防范和化解债务风险； （八）组织和实施本地区贷款赠款项目的绩效管理工作，总结和推广"},{"i":12,"n":"第十二条","txt":"项目实施单位履行下列职责： （一）按照贷款方或赠款方及国内相关制度要求，开展贷款和赠款项目的准备工作，办理相关审核、审批手续，并按照财政部门要求提供担保或反担保； （二）按照贷款、赠款法律文件和国内相关规定，落实项目配套资金，组织项目采购，开展项目活动，推进项目进度，监测项目绩效等； （三）制定并落实贷款、赠款项目的各项管理规定，安全、规范、有效地使用资金； （四）及时编制和提交项目进度报告、财务报告和完工报告等，全面、客观、真实地反映项目进展情况； （五）制定贷款偿还计划，筹措和落实还贷资金，按时足额偿还贷款； （六）建立项目风险应急处置机制和防控措施，防范和化解债务风险； （七）配合和协助贷款方或赠款方以及国内相关部门开展项目检查、绩效管理和审计等工作； （八）项目实施单位应当履行的其他职责。"},{"i":13,"n":"第十三条","txt":"跨省、自治区、直辖市、计划单列市的联合执行项目应当由国务院行业主管部门协商财政部等管理部门确定项目协调机构；省内跨地区、跨行业的联合执行项目应当由省级政府确定项目协调机构。 项目协调机构主要履行下列职责： （一）参与项目立项研究论证，就项目内容、规模、技术、市场等为同级财政部门提供立项咨询意见； （二）按照贷款方或赠款方及国内相关制度要求，统一组织项目实施单位进行项目准备，协调解决有关问题，开展政策指导和专项业务培训； （三）按照贷款方或赠款方及国内相关制度要求，协调推进项目执行，定期向同级财政部门汇总报送项目进度报告、财务报告和完工报告； （四）组织开展项目绩效评价，总结推广项目先进技术、创新模式和管理经验； （五）配合协助贷款方或赠款方及国内相关部门开展项目检查、绩效管理等工作； （六）项目协调机构应当履行的其他职责。 贷款项目协调机构项目管理经费预算应当报同级财政部门审批并纳入同"},{"i":14,"n":"第十四条","txt":"财政部门可以按照国内相关制度规定选择具有专业能力的机构提供项目评审、到货核查、绩效评价、监督检查等服务。 项目实施单位可以与财政部门共同选择具有专业能力和相关资质的金融机构，委托其办理贷款资金的提取支付，债务的分割、回收、偿还和统计等业务。"},{"i":15,"n":"第十五条","txt":"贷款筹借包括贷款申请、前期准备、对外磋商与谈判、法律文件签署与生效、执行或转贷及担保协议签署等。"},{"i":16,"n":"第十六条","txt":"财政部定期发布贷款信息公告，公布贷款方提供贷款的规模、领域、条　件等。"},{"i":17,"n":"第十七条","txt":"省级财政部门和国务院有关部门、中央企业、金融机构应当根据本办法的规定以及贷款方的要求，组织、征集贷款备选项目。 省级财政部门应当组织专家或委托第三方机构对本地区贷款备选项目的投入领域、贷款方式、融资安排、执行机构能力、绩效目标、偿债机制和债务风险等进行评审，并会同相关部门向财政部报送项目贷款申请书以及具有项目建议书深度的项目文件、还款承诺函、评审报告等配套文件。 国务院有关部门、中央企业、金融机构申报项目的应当向财政部报送项目贷款申请书以及具有项目建议书深度的项目文件、还款承诺函等配套文件。"},{"i":18,"n":"第十八条","txt":"财政部对贷款申请进行审查，并在中央政府和地方政府债务限额内，根据国家重大战略规划、优先发展和改革的重点领域、贷款方的资金使用政策、可用资金额度，结合有关项目绩效评价结果和项目所在地的债务风险情况等，与有关部门研究编制贷款备选项目规划。"},{"i":19,"n":"第十九条","txt":"已列入贷款备选项目规划的，项目实施单位或者项目协调机构应当配合贷款方做好贷款项目前期准备工作并及时办理国内相关审批手续。 各级财政部门应当加强协调和指导，督促项目实施单位按照贷款方的要求完成各项准备工作。"},{"i":20,"n":"第二十条","txt":"在贷款磋商谈判前，有关单位应当完成以下工作： （一）对于项目贷款来源、金额、内容、实施主体等拟进行重大调整的，应当获得财政部与有关部门确认；对于本地区的项目，省级财政部门应当在报财政部审核确认前重新组织评审； （二）对于贷款法律文件谈判草本，省级财政部门、中央项目实施单位或中央项目协调机构应当提出修改或确认意见； （三）对于政府负有担保责任的贷款，项目实施单位应当以财政部门可接受的方式向财政部门提供反担保； （四）财政部或贷款方要求的其他事项。"},{"i":21,"n":"第二十一条","txt":"财政部根据贷款项目准备情况与贷款方开展贷款磋商谈判。"},{"i":22,"n":"第二十二条","txt":"在贷款方批准贷款后，财政部组织签署贷款法律文件并办理生效事宜。"},{"i":23,"n":"第二十三条","txt":"财政部拨付贷款时，应当与省级政府或者国务院有关部门等签署执行协议。 财政部转贷贷款时，应当与省级政府、国务院有关部门、中央企业或者金融机构等签署转贷协议。"},{"i":24,"n":"第二十四条","txt":"对于财政部拨付的贷款，省级财政部门应当与下级政府或者有关部门和单位签署执行协议。 对于财政部转贷的贷款，省级政府负有偿还责任的，省级财政部门应当与下级政府或者有关部门和单位签署执行协议；省级政府负有担保责任的，省级财政部门应当与下级政府或者有关部门和单位签署转贷协议。 省级以下（不含省级）政府接受上级政府转贷，比照前款规定签署执行协议或者转贷协议。"},{"i":25,"n":"第二十五条","txt":"贷款使用包括年度计划及预算编制、项目采购、资金支付、财务管理、项目调整、绩效监测及其相关的管理工作等。"},{"i":26,"n":"第二十六条","txt":"项目实施单位或者项目协调机构应当按照有关规定将年度贷款资金和配套资金使用计划、采购计划、出国（境）团组计划等报同级财政部门审核确认或备案。"},{"i":27,"n":"第二十七条","txt":"项目实施单位按照有关规定应当编制部门预算或者单位预算的，应当将其接受的贷款资金全额编入其部门预算或者单位预算管理。 各级财政部门、有关部门和单位应当按照预算管理有关规定做好贷款的预算编制、执行和决算工作。"},{"i":28,"n":"第二十八条","txt":"项目实施单位负责采购代理机构的选择和开展项目采购活动，并接受同级财政部门的监督。"},{"i":29,"n":"第二十九条","txt":"财政部门和中央项目实施单位应当按照贷款法律文件、财政专户和预算单位银行账户管理等有关规定开设和管理贷款指定账户，并按照贷款方要求及国内有关规定进行贷款资金支付和债务分割等。"},{"i":30,"n":"第三十条","txt":"项目实施单位应当按照国家财务会计制度和具体的贷款项目财务会计管理规定，负责贷款项目的财务管理和会计核算，建立健全内部财务会计制度，定期直接向同级财政部门或者通过项目协调机构汇总报送项目进度报告、财务报告等。"},{"i":31,"n":"第三十一条","txt":"贷款使用过程中，有关调整贷款规模、变更项目目标和内容、改变贷款资金用途和支付比例、延长贷款期限等涉及贷款法律文件内容变更的，项目实施单位或者项目协调机构应当通过同级财政部门逐级向财政部提出申请，由财政部与贷款方协商后办理贷款法律文件的变更手续。"},{"i":32,"n":"第三十二条","txt":"贷款项目执行期间如需进行期中调整，省级财政部门、中央项目实施单位或者中央项目协调机构应当在调整前组织开展在建项目绩效评价，根据绩效评价结果提出期中调整方案建议和项目管理整改意见。"},{"i":33,"n":"第三十三条","txt":"省级财政部门、中央项目实施单位或者中央项目协调机构应当在项目完工后适时开展完工项目绩效评价，并做好评价结果的公开与应用工作。"},{"i":34,"n":"第三十四条","txt":"贷款项目完工后，项目实施单位或者项目协调机构应当对项目实施情况进行全面总结和评价，准备项目竣工验收、办理竣工财务决算、提交项目完工报告，明晰产权关系和债权债务关系，做好资产债务移交和登记等工作。 贷款形成国有资产的，其产权管理、核算、评估、处置、收益分配、统计、报告等工作应当按照有关规定进行。"},{"i":35,"n":"第三十五条","txt":"财政部门、项目协调机构和项目实施单位应当及时总结技术、管理、制度、理念等方面的创新成果和经验，并进行推广宣传。"},{"i":36,"n":"第三十六条","txt":"债务偿还包括还款计划制定、还款安排、欠款回收、还贷准备金管理、影响贷款偿还事项的处理等。"},{"i":37,"n":"第三十七条","txt":"还款责任人应当制定还款计划，落实还款资金来源，保证按时足额还款。"},{"i":38,"n":"第三十八条","txt":"政府负有偿还责任的贷款，财政部门应当按照预算安排及时足额履行还款责任。"},{"i":39,"n":"第三十九条","txt":"政府负有担保责任的贷款，财政部门应当向上一级财政部门提供担保，并督促还款责任人制定还款计划，按时足额还款；必要时，财政部门可以要求企业还款责任人与金融机构就临时性垫付达成信贷服务协议，以确保按时足额还款。 还款责任人未按时还款的，财政部门应当从本级政府还贷准备金中调剂资金用于临时性垫款。 已确定还款责任人无法履行债务的，财政部门应当依法在本级一般公共预算中足额安排资金用于还款。"},{"i":40,"n":"第四十条","txt":"未能履行还款义务的，财政部可以采取财政预算扣款、加收罚息等有效措施以保证欠款回收。地方财政部门可以按照转贷协议约定采取有效措施以保证欠款回收。"},{"i":41,"n":"第四十一条","txt":"县级以上地方政府可以设立贷款还贷准备金，由同级财政部门管理。"},{"i":42,"n":"第四十二条","txt":"还款责任人在遵循审慎原则和建立健全内部控制机制的基础上，可以运用金融工具保值避险。"},{"i":43,"n":"第四十三条","txt":"在债务存续期间，还款责任人如因实行资产重组、企业改制等可能导致产权变更、债权变更或者债务转移等行为将会影响到贷款偿还的，应当事先征得同级财政部门的同意，并就有关债务偿还安排与同级财政部门达成书面协议，保证按时偿还贷款，防止债务逃废。"},{"i":44,"n":"第四十四条","txt":"赠款管理包括赠款接受、赠款使用、绩效评价与总结、资产管理等。"},{"i":45,"n":"第四十五条","txt":"省级财政部门、国务院有关部门和中央企业等机构应当根据财政部以及赠款方的要求，向财政部报送赠款申请及其项目概念书。 财政部对赠款申请进行审核，并与赠款方磋商制定赠款项目清单。"},{"i":46,"n":"第四十六条","txt":"财政部负责与赠款方进行磋商谈判、组织签署赠款法律文件并办理生效等事宜。 赠款方有要求的，省级财政部门或中央项目实施单位应当在赠款磋商谈判前出具赠款联合融资承诺函。 财政部应当与省级政府、国务院有关部门和中央企业等机构签署赠款执行协议。"},{"i":47,"n":"第四十七条","txt":"项目实施单位应当按照有关规定将赠款年度资金使用计划、采购计划、出国（境）团组计划等报同级财政部门审核确认或备案。"},{"i":48,"n":"第四十八条","txt":"财政部门和中央项目实施单位应当按照赠款法律文件、财政专户和预算单位银行账户管理等有关规定开设和管理赠款指定账户，并按照赠款方要求及国内有关规定进行赠款资金支付。"},{"i":49,"n":"第四十九条","txt":"项目实施单位应当按照国家财务会计制度和具体的赠款项目财务会计管理规定，负责赠款项目的财务管理和会计核算，建立健全内部财务会计制度，定期向同级财政部门报送项目进度报告、财务报告等。"},{"i":50,"n":"第五十条","txt":"赠款使用过程中，有关调整赠款规模、变更项目内容、改变赠款资金用途和支付比例、延长赠款期限等涉及赠款法律文件内容变更的，项目实施单位应当通过同级财政部门逐级提出申请，由财政部与赠款方协商后办理赠款法律文件的变更手续。"},{"i":51,"n":"第五十一条","txt":"省级财政部门和中央项目实施单位应当在项目完工后适时开展赠款项目绩效评价，并做好评价结果的公开与应用工作。"},{"i":52,"n":"第五十二条","txt":"赠款项目完工前，财政部门应当根据有关规定与赠款法律文件的要求明确赠款形成资产的所有权归属。 赠款形成国有资产的，其产权管理、核算、评估、处置、收益分配、统计、报告等工作应当按照有关规定进行。"},{"i":53,"n":"第五十三条","txt":"各级财政部门应当对贷款、赠款项目执行情况实施监督。发现问题的，应当责令项目实施单位采取有效措施，限期加以解决和纠正。"},{"i":54,"n":"第五十四条","txt":"地方财政部门未按本办法第十一条　履行相应职责的，财政部可以予以通报批评，在有关问题得到妥善处理前暂停新的贷款赠款安排。"},{"i":55,"n":"第五十五条","txt":"项目实施单位未按本办法第十二条　履行相应职责的，财政部门可以采取暂停贷款赠款资金支付、加速未到期贷款债务的偿还、追回已支付资金及其形成的资产、收取贷款违约金等措施。 财政部门可以通过企业信用信息公示系统等平台公示项目实施单位、采购代理机构或者金融机构在贷款赠款使用过程中的失信、违约等行为。"},{"i":56,"n":"第五十六条","txt":"项目实施单位、项目协调机构及财政部门和个人存在以虚报、冒领等手段骗取贷款赠款资金，或者滞留、截留、挪用等违反规定使用贷款赠款资金，或者从中非法获益等行为的，依照相关法律法规的规定处理。"},{"i":57,"n":"第五十七条","txt":"各级财政部门、项目实施单位和项目协调机构的工作人员在贷款、赠款的管理、资金使用和偿还过程中，贪污受贿、滥用职权、玩忽职守、徇私舞弊的，依照相关法律法规的规定处理。"},{"i":58,"n":"第五十八条","txt":"省级财政部门可以依照本办法制定本地区贷款、赠款管理的实施办法。"},{"i":59,"n":"第五十九条","txt":"项目实施单位依法直接向国际金融组织和外国政府举借，并经国务院批准由财政部代表中央政府为其提供担保的贷款，参照本办法管理。"},{"i":60,"n":"第六十条","txt":"本办法自2017年1月1日起施行。2006年9月1日发布的《国际金融组织和外国政府贷款赠款管理办法》同时废止。"}],"jibenjianshecaiwuguize":[{"i":1,"n":"第一条","txt":"为了规范基本建设财务行为，加强基本建设财务管理，提高财政资金使用效益，保障财政资金安全，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于行政事业单位的基本建设财务行为，以及国有和国有控股企业使用财政资金的基本建设财务行为。 基本建设是指以新增工程效益或者扩大生产能力为主要目的的新建、续建、改扩建、迁建、大型维修改造工程及相关工作。"},{"i":3,"n":"第三条","txt":"基本建设财务管理应当严格执行国家有关法律、行政法规和财务规章制度，坚持勤俭节约、量力而行、讲求实效，正确处理资金使用效益与资金供给的关系。"},{"i":4,"n":"第四条","txt":"基本建设财务管理的主要任务是： （一）依法筹集和使用基本建设项目（以下简称项目）建设资金，防范财务风险； （二）合理编制项目资金预算，加强预算审核，严格预算执行； （三）加强项目核算管理，规范和控制建设成本； （四）及时准确编制项目竣工财务决算，全面反映基本建设财务状况； （五）加强对基本建设活动的财务控制和监督，实施绩效评价。"},{"i":5,"n":"第五条","txt":"财政部负责制定并指导实施基本建设财务管理制度。 各级财政部门负责对基本建设财务活动实施全过程管理和监督。"},{"i":6,"n":"第六条","txt":"各级项目主管部门（含一级预算单位，下同）应当会同财政部门，加强本部门或者本行业基本建设财务管理和监督，指导和督促项目建设单位做好基本建设财务管理的基础工作。"},{"i":7,"n":"第七条","txt":"项目建设单位应当做好以下基本建设财务管理的基础工作： （一）建立、健全本单位基本建设财务管理制度和内部控制制度； （二）按项目单独核算，按照规定将核算情况纳入单位账簿和财务报表； （三）按照规定编制项目资金预算，根据批准的项目概(预)算做好核算管理，及时掌握建设进度，定期进行财产物资清查，做好核算资料档案管理； （四）按照规定向财政部门、项目主管部门报送基本建设财务报表和资料； （五）及时办理工程价款结算，编报项目竣工财务决算，办理资产交付使用手续； （六）财政部门和项目主管部门要求的其他工作。 按照规定实行代理记账和项目代建制的，代理记账单位和代建单位应当配合项目建设单位做好项目财务管理的基础工作。"},{"i":8,"n":"第八条","txt":"建设资金是指为满足项目建设需要筹集和使用的资金,按照来源分为财政资金和自筹资金。其中，财政资金包括一般公共预算安排的基本建设投资资金和其他专项建设资金，政府性基金预算安排的建设资金，政府依法举债取得的建设资金，以及国有资本经营预算安排的基本建设项目资金。"},{"i":9,"n":"第九条","txt":"财政资金管理应当遵循专款专用原则，严格按照批准的项目预算执行，不得挤占挪用。 财政部门应当会同项目主管部门加强项目财政资金的监督管理。"},{"i":10,"n":"第十条","txt":"财政资金的支付，按照国库集中支付制度有关规定和合同约定，综合考虑项目财政资金预算、建设进度等因素执行。"},{"i":11,"n":"第十一条","txt":"项目建设单位应当根据批准的项目概（预）算、年度投资计划和预算、建设进度等控制项目投资规模。"},{"i":12,"n":"第十二条","txt":"项目建设单位在决策阶段应当明确建设资金来源，落实建设资金，合理控制筹资成本。非经营性项目建设资金按照国家有关规定筹集；经营性项目在防范风险的前提下，可以多渠道筹集。 具体项目的经营性和非经营性性质划分，由项目主管部门会同财政部门根据项目建设目的、运营模式和盈利能力等因素核定。"},{"i":13,"n":"第十三条","txt":"核定为经营性项目的，项目建设单位应当按照国家有关固定资产投资项目资本管理的规定，筹集一定比例的非债务性资金作为项目资本。 在项目建设期间，项目资本的投资者除依法转让、依法终止外，不得以任何方式抽走出资。 经营性项目的投资者以实物、知识产权、土地使用权等非货币财产作价出资的，应当委托具有专业能力的资产评估机构依法评估作价。"},{"i":14,"n":"第十四条","txt":"项目建设单位取得的财政资金，区分以下情况处理： 经营性项目具备企业法人资格的，按照国家有关企业财务规定处理。不具备企业法人资格的，属于国家直接投资的，作为项目国家资本管理；属于投资补助的，国家拨款时对权属有规定的，按照规定执行，没有规定的，由项目投资者享有；属于有偿性资助的，作为项目负债管理。 经营性项目取得的财政贴息，项目建设期间收到的，冲减项目建设成本；项目竣工后收到的，按照国家财务、会计制度的有关规定处理。 非经营性项目取得的财政资金，按照国家行政、事业单位财务、会计制度的有关规定处理。"},{"i":15,"n":"第十五条","txt":"项目收到的社会捐赠，有捐赠协议或者捐赠者有指定要求的，按照协议或者要求处理；无协议和要求的，按照国家财务、会计制度的有关规定处理。"},{"i":16,"n":"第十六条","txt":"项目建设单位编制项目预算应当以批准的概算为基础, 按照项目实际建设资金需求编制，并控制在批准的概算总投资规模、范围和标准以内。 项目建设单位应当细化项目预算,分解项目各年度预算和财政资金预算需求。涉及政府采购的，应当按照规定编制政府采购预算。 项目资金预算应当纳入项目主管部门的部门预算或者国有资本经营预算统一管理。列入部门预算的项目，一般应当从项目库中产生。"},{"i":17,"n":"第十七条","txt":"项目建设单位应当根据项目概算、建设工期、年度投资和自筹资金计划、以前年度项目各类资金结转情况等，提出项目财政资金预算建议数，按照规定程序经项目主管部门审核汇总报财政部门。 项目建设单位根据财政部门下达的预算控制数编制预算，由项目主管部门审核汇总报财政部门，经法定程序审核批复后执行。"},{"i":18,"n":"第十八条","txt":"项目建设单位应当严格执行项目财政资金预算。对发生停建、缓建、迁移、合并、分立、重大设计变更等变动事项和其他特殊情况确需调整的项目，项目建设单位应当按照规定程序报项目主管部门审核后，向财政部门申请调整项目财政资金预算。"},{"i":19,"n":"第十九条","txt":"财政部门应当加强财政资金预算审核和执行管理，严格预算约束。 财政资金预算安排应当以项目以前年度财政资金预算执行情况、项目预算评审意见和绩效评价结果作为重要依据。项目财政资金未按预算要求执行的，按照有关规定调减或者收回。"},{"i":20,"n":"第二十条","txt":"项目主管部门应当按照预算管理规定,督促和指导项目建设单位做好项目财政资金预算编制、执行和调整，严格审核项目财政资金预算、细化预算和预算调整的申请，及时掌握项目预算执行动态，跟踪分析项目进度，按照要求向财政部门报送执行情况。"},{"i":21,"n":"第二十一条","txt":"建设成本是指按照批准的建设内容由项目建设资金安排的各项支出，包括建筑安装工程投资支出、设备投资支出、待摊投资支出和其他投资支出。 建筑安装工程投资支出是指项目建设单位按照批准的建设内容发生的建筑工程和安装工程的实际成本。 设备投资支出是指项目建设单位按照批准的建设内容发生的各种设备的实际成本。 待摊投资支出是指项目建设单位按照批准的建设内容发生的，应当分摊计入相关资产价值的各项费用和税金支出。 其他投资支出是指项目建设单位按照批准的建设内容发生的房屋购置支出，基本畜禽、林木等的购置、饲养、培育支出，办公生活用家具、器具购置支出，软件研发和不能计入设备投资的软件购置等支出。"},{"i":22,"n":"第二十二条","txt":"项目建设单位应当严格控制建设成本的范围、标准和支出责任，以下支出不得列入项目建设成本： （一）超过批准建设内容发生的支出； （二）不符合合同协议的支出； （三）非法收费和摊派； （四）无发票或者发票项目不全、无审批手续、无责任人员签字的支出； （五）因设计单位、施工单位、供货单位等原因造成的工程报废等损失，以及未按照规定报经批准的损失； （六）项目符合规定的验收条件之日起3个月后发生的支出； （七）其他不属于本项目应当负担的支出。"},{"i":23,"n":"第二十三条","txt":"财政资金用于项目前期工作经费部分，在项目批准建设后，列入项目建设成本。 没有被批准或者批准后又被取消的项目，财政资金如有结余，全部缴回国库。"},{"i":24,"n":"第二十四条","txt":"基建收入是指在基本建设过程中形成的各项工程建设副产品变价收入、负荷试车和试运行收入以及其他收入。 工程建设副产品变价收入包括矿山建设中的矿产品收入，油气、油田钻井建设中的原油气收入，林业工程建设中的路影材收入，以及其他项目建设过程中产生或者伴生的副产品、试验产品的变价收入。 负荷试车和试运行收入包括水利、电力建设移交生产前的供水、供电、供热收入，原材料、机电轻纺、农林建设移交生产前的产品收入，交通临时运营收入等。 其他收入包括项目总体建设尚未完成或者移交生产，但其中部分工程简易投产而发生的经营性收入等。 符合验收条件而未按照规定及时办理竣工验收的经营性项目所实现的收入，不得作为项目基建收入管理。"},{"i":25,"n":"第二十五条","txt":"项目所取得的基建收入扣除相关费用并依法纳税后，其净收入按照国家财务、会计制度的有关规定处理。"},{"i":26,"n":"第二十六条","txt":"项目发生的各项索赔、违约金等收入，首先用于弥补工程损失，结余部分按照国家财务、会计制度的有关规定处理。"},{"i":27,"n":"第二十七条","txt":"工程价款结算是指依据基本建设工程发承包合同等进行工程预付款、进度款、竣工价款结算的活动。"},{"i":28,"n":"第二十八条","txt":"项目建设单位应当严格按照合同约定和工程价款结算程序支付工程款。竣工价款结算一般应当在项目竣工验收后2个月内完成，大型项目一般不得超过3个月。"},{"i":29,"n":"第二十九条","txt":"项目建设单位可以与施工单位在合同中约定按照不超过工程价款结算总额的5%预留工程质量保证金，待工程交付使用缺陷责任期满后清算。资信好的施工单位可以用银行保函替代工程质量保证金。"},{"i":30,"n":"第三十条","txt":"项目主管部门应当会同财政部门加强工程价款结算的监督，重点审查工程招投标文件、工程量及各项费用的计取、合同协议、施工变更签证、人工和材料价差、工程索赔等。"},{"i":31,"n":"第三十一条","txt":"项目竣工财务决算是正确核定项目资产价值、反映竣工项目建设成果的文件，是办理资产移交和产权登记的依据，包括竣工财务决算报表、竣工财务决算说明书以及相关材料。 项目竣工财务决算应当数字准确、内容完整。竣工财务决算的编制要求另行规定。"},{"i":32,"n":"第三十二条","txt":"项目年度资金使用情况应当按照要求编入部门决算或者国有资本经营决算。"},{"i":33,"n":"第三十三条","txt":"项目建设单位在项目竣工后，应当及时编制项目竣工财务决算，并按照规定报送项目主管部门。 项目设计、施工、监理等单位应当配合项目建设单位做好相关工作。 建设周期长、建设内容多的大型项目，单项工程竣工具备交付使用条件的，可以编报单项工程竣工财务决算，项目全部竣工后应当编报竣工财务总决算。"},{"i":34,"n":"第三十四条","txt":"在编制项目竣工财务决算前，项目建设单位应当认真做好各项清理工作，包括账目核对及账务调整、财产物资核实处理、债权实现和债务清偿、档案资料归集整理等。"},{"i":35,"n":"第三十五条","txt":"在编制项目竣工财务决算时，项目建设单位应当按照规定将待摊投资支出按合理比例分摊计入交付使用资产价值、转出投资价值和待核销基建支出。"},{"i":36,"n":"第三十六条","txt":"项目竣工财务决算审核、批复管理职责和程序要求由同级财政部门确定。"},{"i":37,"n":"第三十七条","txt":"财政部门和项目主管部门对项目竣工财务决算实行先审核、后批复的办法，可以委托预算评审机构或者有专业能力的社会中介机构进行审核。对符合条件的，应当在6个月内批复"},{"i":38,"n":"第三十八条","txt":"项目一般不得预留尾工工程，确需预留尾工工程的，尾工工程投资不得超过批准的项目概（预）算总投资的5%。 项目主管部门应当督促项目建设单位抓紧实施项目尾工工程，加强对尾工工程资金使用的监督管理。"},{"i":39,"n":"第三十九条","txt":"已具备竣工验收条件的项目，应当及时组织验收，移交生产和使用。"},{"i":40,"n":"第四十条","txt":"项目隶属关系发生变化时，应当按照规定及时办理财务关系划转，主要包括各项资金来源、已交付使用资产、在建工程、结余资金、各项债权及债务等的清理交接。"},{"i":41,"n":"第四十一条","txt":"资产交付是指项目竣工验收合格后，将形成的资产交付或者转交生产使用单位的行为。 交付使用的资产包括固定资产、流动资产、无形资产等。"},{"i":42,"n":"第四十二条","txt":"项目竣工验收合格后应当及时办理资产交付使用手续，并依据批复的项目竣工财务决算进行账务调整。"},{"i":43,"n":"第四十三条","txt":"非经营性项目发生的江河清障疏浚、航道整治、飞播造林、退耕还林(草)、封山(沙)育林(草)、水土保持、城市绿化、毁损道路修复、护坡及清理等不能形成资产的支出，以及项目未被批准、项目取消和项目报废前已发生的支出，作为待核销基建支出处理；形成资产产权归属本单位的，计入交付使用资产价值；形成资产产权不归属本单位的，作为转出投资处理。 非经营性项目发生的农村沼气工程、农村安全饮水工程、农村危房改造工程、游牧民定居工程、渔民上岸工程等涉及家庭或者个人的支出，形成资产产权归属家庭或者个人的，作为待核销基建支出处理；形成资产产权归属本单位的，计入交付使用资产价值；形成资产产权归属其他单位的，作为转出投资处理。"},{"i":44,"n":"第四十四条","txt":"非经营性项目为项目配套建设的专用设施，包括专用道路、专用通讯设施、专用电力设施、地下管道等，产权归属本单位的，计入交付使用资产价值；产权不归属本单位的，作为转出投资处理。 非经营性项目移民安置补偿中由项目建设单位负责建设并形成的实物资产，产权归属集体或者单位的，作为转出投资处理；产权归属移民的，作为待核销基建支出处理。"},{"i":45,"n":"第四十五条","txt":"经营性项目发生的项目取消和报废等不能形成资产的支出，以及设备采购和系统集成（软件）中包含的交付使用后运行维护等费用，按照国家财务、会计制度的有关规定处理。"},{"i":46,"n":"第四十六条","txt":"经营性项目为项目配套建设的专用设施，包括专用铁路线、专用道路、专用通讯设施、专用电力设施、地下管道、专用码头等，项目建设单位应当与有关部门明确产权关系，并按照国家财务、会计制度的有关规定处理。"},{"i":47,"n":"第四十七条","txt":"结余资金是指项目竣工结余的建设资金，不包括工程抵扣的增值税进项税额资金。"},{"i":48,"n":"第四十八条","txt":"经营性项目结余资金，转入单位的相关资产。 非经营性项目结余资金，首先用于归还项目贷款。如有结余，按照项目资金来源属于财政资金的部分，应当在项目竣工验收合格后3个月内，按照预算管理制度有关规定收回财政。"},{"i":49,"n":"第四十九条","txt":"项目终止、报废或者未按照批准的建设内容建设形成的剩余建设资金中，按照项目实际资金来源比例确认的财政资金应当收回财政。"},{"i":50,"n":"第五十条","txt":"项目绩效评价是指财政部门、项目主管部门根据设定的项目绩效目标，运用科学合理的评价方法和评价标准，对项目建设全过程中资金筹集、使用及核算的规范性、有效性，以及投入运营效果等进行评价的活动。"},{"i":51,"n":"第五十一条","txt":"项目绩效评价应当坚持科学规范、公正公开、分级分类和绩效相关的原则，坚持经济效益、社会效益和生态效益相结合的原则。"},{"i":52,"n":"第五十二条","txt":"项目绩效评价应当重点对项目建设成本、工程造价、投资控制、达产能力与设计能力差异、偿债能力、持续经营能力等实施绩效评价，根据管理需要和项目特点选用社会效益指标、财务效益指标、工程质量指标、建设工期指标、资金来源指标、资金使用指标、实际投资回收期指标、实际单位生产（营运）能力投资指标等评价指标。"},{"i":53,"n":"第五十三条","txt":"财政部门负责制定项目绩效评价管理办法，对项目绩效评价工作进行指导和监督，选择部分项目开展重点绩效评价，依法公开绩效评价结果。绩效评价结果作为项目财政资金预算安排和资金拨付的重要依据。"},{"i":54,"n":"第五十四条","txt":"项目主管部门会同财政部门按照有关规定，制定本部门或者本行业项目绩效评价具体实施办法，建立具体的绩效评价指标体系，确定项目绩效目标，具体组织实施本部门或者本行业绩效评价工作，并向财政部门报送绩效评价结果。"},{"i":55,"n":"第五十五条","txt":"项目监督管理主要包括对项目资金筹集与使用、预算编制与执行、建设成本控制、工程价款结算、竣工财务决算编报审核、资产交付等的监督管理。"},{"i":56,"n":"第五十六条","txt":"项目建设单位应当建立、健全内部控制和项目财务信息报告制度，依法接受财政部门和项目主管部门等的财务监督管理。"},{"i":57,"n":"第五十七条","txt":"财政部门和项目主管部门应当加强项目的监督管理，采取事前、事中、事后相结合，日常监督与专项监督相结合的方式，对项目财务行为实施全过程监督管理。"},{"i":58,"n":"第五十八条","txt":"财政部门应当加强对基本建设财政资金形成的资产的管理，按照规定对项目资产开展登记、核算、评估、处置、统计、报告等资产管理基础工作。"},{"i":59,"n":"第五十九条","txt":"对于违反本规则的基本建设财务行为，依照《预算法》、《财政违法行为处罚处分条例》等有关规定追究责任。"},{"i":60,"n":"第六十条","txt":"接受国家经常性资助的社会力量举办的公益服务性组织和社会团体的基本建设财务行为，以及非国有企业使用财政资金的基本建设财务行为，参照本规则执行。 使用外国政府及国际金融组织贷款的基本建设财务行为执行本规则。国家另有规定的，从其规定。"},{"i":61,"n":"第六十一条","txt":"项目建设内容仅为设备购置的，不执行本规则；项目建设内容以设备购置、房屋及其他建筑物购置为主并附有部分建筑安装工程的，可以简化执行本规则。 经营性项目的项目资本中，财政资金所占比例未超过50%的，项目建设单位可以简化执行本规则，但应当按照要求向财政部门、项目主管部门报送相关财务资料。国家另有规定的，从其规定。"},{"i":62,"n":"第六十二条","txt":"中央项目主管部门和各省、自治区、直辖市、计划单列市财政厅(局)可以根据本规则，结合本行业、本地区的项目情况，制定具体实施办法并报财政部备案。"},{"i":63,"n":"第六十三条","txt":"本规则自2016年9月1日起施行。2002年9月27日财政部发布的《基本建设财务管理规定》（财建〔2002〕394号）及其解释同时废止。 本规则施行前财政部制定的有关规定与本规则不一致的，按照本规则执行。《企业财务通则》（财政部令第41号）、《金融企业财务规则》（财政部令第42号）、《事业单位财务规则》（财政部令第68号）和《行政单位财务规则》（财政部令第71号）另有规定的，从其规定。"}],"zhengfukuaijizhunzejibenzhunze":[{"i":1,"n":"第一条","txt":"为了规范政府的会计核算，保证会计信息质量，根据《中华人民共和国会计法》、《中华人民共和国预算法》和其他有关法律、行政法规，制定本准则。"},{"i":2,"n":"第二条","txt":"本准则适用于各级政府、各部门、各单位（以下统称政府会计主体）。 前款所称各部门、各单位是指与本级政府财政部门直接或者间接发生预算拨款关系的国家机关、军队、政党组织、社会团体、事业单位和其他单位。 军队、已纳入企业财务管理体系的单位和执行《民间非营利组织会计制度》的社会团体，不适用本准则。"},{"i":3,"n":"第三条","txt":"政府会计由预算会计和财务会计构成。 预算会计实行收付实现制，国务院另有规定的，依照其规定。 财务会计实行权责发生制。"},{"i":4,"n":"第四条","txt":"政府会计具体准则及其应用指南、政府会计制度等，应当由财政部遵循本准则制定。"},{"i":5,"n":"第五条","txt":"政府会计主体应当编制决算报告和财务报告。 决算报告的目标是向决算报告使用者提供与政府预算执行情况有关的信息，综合反映政府会计主体预算收支的年度执行结果，有助于决算报告使用者进行监督和管理，并为编制后续年度预算提供参考和依据。政府决算报告使用者包括各级人民代表大会及其常务委员会、各级政府及其有关部门、政府会计主体自身、社会公众和其他利益相关者。 财务报告的目标是向财务报告使用者提供与政府的财务状况、运行情况（含运行成本，下同）和现金流量等有关信息，反映政府会计主体公共受托责任履行情况，有助于财务报告使用者作出决策或者进行监督和管理。政府财务报告使用者包括各级人民代表大会常务委员会、债权人、各级政府及其有关部门、政府会计主体自身和其他利益相关者。"},{"i":6,"n":"第六条","txt":"政府会计主体应当对其自身发生的经济业务或者事项进行会计核算。"},{"i":7,"n":"第七条","txt":"政府会计核算应当以政府会计主体持续运行为前提。"},{"i":8,"n":"第八条","txt":"政府会计核算应当划分会计期间，分期结算账目，按规定编制决算报告和财务报告。 会计期间至少分为年度和月度。会计年度、月度等会计期间的起讫日期采用公历日期。"},{"i":9,"n":"第九条","txt":"政府会计核算应当以人民币作为记账本位币。发生外币业务时，应当将有关外币金额折算为人民币金额计量，同时登记外币金额。"},{"i":10,"n":"第十条","txt":"政府会计核算应当采用借贷记账法记账。"},{"i":11,"n":"第十一条","txt":"政府会计主体应当以实际发生的经济业务或者事项为依据进行会计核算，如实反映各项会计要素的情况和结果，保证会计信息真实可靠。"},{"i":12,"n":"第十二条","txt":"政府会计主体应当将发生的各项经济业务或者事项统一纳入会计核算，确保会计信息能够全面反映政府会计主体预算执行情况和财务状况、运行情况、现金流量等。"},{"i":13,"n":"第十三条","txt":"政府会计主体提供的会计信息，应当与反映政府会计主体公共受托责任履行情况以及报告使用者决策或者监督、管理的需要相关，有助于报告使用者对政府会计主体过去、现在或者未来的情况作出评价或者预测。"},{"i":14,"n":"第十四条","txt":"政府会计主体对已经发生的经济业务或者事项，应当及时进行会计核算，不得提前或者延后。"},{"i":15,"n":"第十五条","txt":"政府会计主体提供的会计信息应当具有可比性。 同一政府会计主体不同时期发生的相同或者相似的经济业务或者事项，应当采用一致的会计政策，不得随意变更。确需变更的，应当将变更的内容、理由及其影响在附注中予以说明。 不同政府会计主体发生的相同或者相似的经济业务或者事项，应当采用一致的会计政策，确保政府会计信息口径一致，相互可比。"},{"i":16,"n":"第十六条","txt":"政府会计主体提供的会计信息应当清晰明了，便于报告使用者理解和使用。"},{"i":17,"n":"第十七条","txt":"政府会计主体应当按照经济业务或者事项的经济实质进行会计核算，不限于以经济业务或者事项的法律形式为依据。"},{"i":18,"n":"第十八条","txt":"政府预算会计要素包括预算收入、预算支出与预算结余。"},{"i":19,"n":"第十九条","txt":"预算收入是指政府会计主体在预算年度内依法取得的并纳入预算管理的现金流入。"},{"i":20,"n":"第二十条","txt":"预算收入一般在实际收到时予以确认，以实际收到的金额计量。"},{"i":21,"n":"第二十一条","txt":"预算支出是指政府会计主体在预算年度内依法发生并纳入预算管理的现金流出。"},{"i":22,"n":"第二十二条","txt":"预算支出一般在实际支付时予以确认，以实际支付的金额计量。"},{"i":23,"n":"第二十三条","txt":"预算结余是指政府会计主体预算年度内预算收入扣除预算支出后的资金余额，以及历年滚存的资金余额。"},{"i":24,"n":"第二十四条","txt":"预算结余包括结余资金和结转资金。 结余资金是指年度预算执行终了，预算收入实际完成数扣除预算支出和结转资金后剩余的资金。 结转资金是指预算安排项目的支出年终尚未执行完毕或者因故未执行，且下年需要按原用途继续使用的资金。"},{"i":25,"n":"第二十五条","txt":"符合预算收入、预算支出和预算结余定义及其确认条件的项目应当列入政府决算报表。"},{"i":26,"n":"第二十六条","txt":"政府财务会计要素包括资产、负债、净资产、收入和费用。"},{"i":27,"n":"第二十七条","txt":"资产是指政府会计主体过去的经济业务或者事项形成的，由政府会计主体控制的，预期能够产生服务潜力或者带来经济利益流入的经济资源。 服务潜力是指政府会计主体利用资产提供公共产品和服务以履行政府职能的潜在能力。 经济利益流入表现为现金及现金等价物的流入，或者现金及现金等价物流出的减少。"},{"i":28,"n":"第二十八条","txt":"政府会计主体的资产按照流动性，分为流动资产和非流动资产。 流动资产是指预计在1年内（含1年）耗用或者可以变现的资产，包括货币资金、短期投资、应收及预付款项、存货等。 非流动资产是指流动资产以外的资产，包括固定资产、在建工程、无形资产、长期投资、公共基础设施、政府储备资产、文物文化资产、保障性住房和自然资源资产等。"},{"i":29,"n":"第二十九条","txt":"符合本准则第二十七条规定的资产定义的经济资源，在同时满足以下条件时，确认为资产： （一）与该经济资源相关的服务潜力很可能实现或者经济利益很可能流入政府会计主体； （二）该经济资源的成本或者价值能够可靠地计量。"},{"i":30,"n":"第三十条","txt":"资产的计量属性主要包括历史成本、重置成本、现值、公允价值和名义金额。 在历史成本计量下，资产按照取得时支付的现金金额或者支付对价的公允价值计量。 在重置成本计量下，资产按照现在购买相同或者相似资产所需支付的现金金额计量。 在现值计量下，资产按照预计从其持续使用和最终处置中所产生的未来净现金流入量的折现金额计量。 在公允价值计量下，资产按照市场参与者在计量日发生的有序交易中，出售资产所能收到的价格计量。 无法采用上述计量属性的，采用名义金额（即人民币1元）计量。"},{"i":31,"n":"第三十一条","txt":"政府会计主体在对资产进行计量时，一般应当采用历史成本。 采用重置成本、现值、公允价值计量的，应当保证所确定的资产金额能够持续、可靠计量。"},{"i":32,"n":"第三十二条","txt":"符合资产定义和资产确认条件的项目，应当列入资产负债表。"},{"i":33,"n":"第三十三条","txt":"负债是指政府会计主体过去的经济业务或者事项形成的，预期会导致经济资源流出政府会计主体的现时义务。 现时义务是指政府会计主体在现行条件下已承担的义务。未来发生的经济业务或者事项形成的义务不属于现时义务，不应当确认为负债。"},{"i":34,"n":"第三十四条","txt":"政府会计主体的负债按照流动性，分为流动负债和非流动负债。 流动负债是指预计在1年内（含1年）偿还的负债，包括应付及预收款项、应付职工薪酬、应缴款项等。 非流动负债是指流动负债以外的负债，包括长期应付款、应付政府债券和政府依法担保形成的债务等。"},{"i":35,"n":"第三十五条","txt":"符合本准则第三十三条规定的负债定义的义务，在同时满足以下条件时，确认为负债： （一）履行该义务很可能导致含有服务潜力或者经济利益的经济资源流出政府会计主体； （二）该义务的金额能够可靠地计量。"},{"i":36,"n":"第三十六条","txt":"负债的计量属性主要包括历史成本、现值和公允价值。 在历史成本计量下，负债按照因承担现时义务而实际收到的款项或者资产的金额，或者承担现时义务的合同金额，或者按照为偿还负债预期需要支付的现金计量。 在现值计量下，负债按照预计期限内需要偿还的未来净现金流出量的折现金额计量。 在公允价值计量下，负债按照市场参与者在计量日发生的有序交易中，转移负债所需支付的价格计量。"},{"i":37,"n":"第三十七条","txt":"政府会计主体在对负债进行计量时，一般应当采用历史成本。 采用现值、公允价值计量的，应当保证所确定的负债金额能够持续、可靠计量。"},{"i":38,"n":"第三十八条","txt":"符合负债定义和负债确认条件的项目，应当列入资产负债表。"},{"i":39,"n":"第三十九条","txt":"净资产是指政府会计主体资产扣除负债后的净额。"},{"i":40,"n":"第四十条","txt":"净资产金额取决于资产和负债的计量。第四十一条 净资产项目应当列入资产负债表。"},{"i":41,"n":"第四十二条","txt":"收入是指报告期内导致政府会计主体净资产增加的、含有服务潜力或者经济利益的经济资源的流入。"},{"i":42,"n":"第四十三条","txt":"收入的确认应当同时满足以下条件： （一）与收入相关的含有服务潜力或者经济利益的经济资源很可能流入政府会计主体； （二）含有服务潜力或者经济利益的经济资源流入会导致政府会计主体资产增加或者负债减少； （三）流入金额能够可靠地计量。"},{"i":43,"n":"第四十四条","txt":"符合收入定义和收入确认条件的项目，应当列入收入费用表。"},{"i":44,"n":"第四十五条","txt":"费用是指报告期内导致政府会计主体净资产减少的、含有服务潜力或者经济利益的经济资源的流出。"},{"i":45,"n":"第四十六条","txt":"费用的确认应当同时满足以下条件： （一）与费用相关的含有服务潜力或者经济利益的经济资源很可能流出政府会计主体； （二）含有服务潜力或者经济利益的经济资源流出会导致政府会计主体资产减少或者负债增加； （三）流出金额能够可靠地计量。"},{"i":46,"n":"第四十七条","txt":"符合费用定义和费用确认条件的项目，应当列入收入费用表。"},{"i":47,"n":"第四十八条","txt":"政府决算报告是综合反映政府会计主体年度预算收支执行结果的文件。 政府决算报告应当包括决算报表和其他应当在决算报告中反映的相关信息和资料。 政府决算报告的具体内容及编制要求等，由财政部另行规定。"},{"i":48,"n":"第四十九条","txt":"政府财务报告是反映政府会计主体某一特定日期的财务状况和某一会计期间的运行情况和现金流量等信息的文件。 政府财务报告应当包括财务报表和其他应当在财务报告中披露的相关信息和资料。"},{"i":49,"n":"第五十条","txt":"政府财务报告包括政府综合财务报告和政府部门财务报告。 政府综合财务报告是指由政府财政部门编制的，反映各级政府整体财务状况、运行情况和财政中长期可持续性的报告。 政府部门财务报告是指政府各部门、各单位按规定编制的财务报告。"},{"i":50,"n":"第五十一条","txt":"财务报表是对政府会计主体财务状况、运行情况和现金流量等信息的结构性表述。 财务报表包括会计报表和附注。 会计报表至少应当包括资产负债表、收入费用表和现金流量表。 政府会计主体应当根据相关规定编制合并财务报表。"},{"i":51,"n":"第五十二条","txt":"资产负债表是反映政府会计主体在某一特定日期的财务状况的报表。"},{"i":52,"n":"第五十三条","txt":"收入费用表是反映政府会计主体在一定会计期间运行情况的报表。"},{"i":53,"n":"第五十四条","txt":"现金流量表是反映政府会计主体在一定会计期间现金及现金等价物流入和流出情况的报表。"},{"i":54,"n":"第五十五条","txt":"附注是对在资产负债表、收入费用表、现金流量表等报表中列示项目所作的进一步说明，以及对未能在这些报表中列示项目的说明。"},{"i":55,"n":"第五十六条","txt":"政府决算报告的编制主要以收付实现制为基础，以预算会计核算生成的数据为准。 政府财务报告的编制主要以权责发生制为基础，以财务会计核算生成的数据为准。"},{"i":56,"n":"第五十七条","txt":"本准则所称会计核算，包括会计确认、计量、记录和报告各个环节，涵盖填制会计凭证、登记会计账簿、编制报告全过程。"},{"i":57,"n":"第五十八条","txt":"本准则所称预算会计，是指以收付实现制为基础对政府会计主体预算执行过程中发生的全部收入和全部支出进行会计核算，主要反映和监督预算收支执行情况的会计。"},{"i":58,"n":"第五十九条","txt":"本准则所称财务会计，是指以权责发生制为基础对政府会计主体发生的各项经济业务或者事项进行会计核算，主要反映和监督政府会计主体财务状况、运行情况和现金流量等的会计。"},{"i":59,"n":"第六十条","txt":"本准则所称收付实现制，是指以现金的实际收付为标志来确定本期收入和支出的会计核算基础。凡在当期实际收到的现金收入和支出，均应作为当期的收入和支出；凡是不属于当期的现金收入和支出，均不应当作为当期的收入和支出。"},{"i":60,"n":"第六十一条","txt":"本准则所称权责发生制，是指以取得收取款项的权利或支付款项的义务为标志来确定本期收入和费用的会计核算基础。凡是当期已经实现的收入和已经发生的或应当负担的费用，不论款项是否收付，都应当作为当期的收入和费用；凡是不属于当期的收入和费用，即使款项已在当期收付，也不应当作为当期的收入和费用。"},{"i":61,"n":"第六十二条","txt":"本准则自2017年1月1日起施行。"}],"zhengfugoumaifuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范政府购买服务行为，促进转变政府职能，改善公共服务供给，根据《中华人民共和国预算法》《中华人民共和国政府采购法》《中华人民共和国合同法》等法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称政府购买服务，是指各级国家机关将属于自身职责范围且适合通过市场化方式提供的服务事项，按照政府采购方式和程序，交由符合条件的服务供应商承担，并根据服务数量和质量等因素向其支付费用的行为。"},{"i":3,"n":"第三条","txt":"政府购买服务应当遵循预算约束、以事定费、公开择优、诚实信用、讲求绩效原则。"},{"i":4,"n":"第四条","txt":"财政部负责制定全国性政府购买服务制度，指导和监督各地区、各部门政府购买服务工作。 县级以上地方人民政府财政部门负责本行政区域政府购买服务管理。"},{"i":5,"n":"第五条","txt":"各级国家机关是政府购买服务的购买主体。"},{"i":6,"n":"第六条","txt":"依法成立的企业、社会组织（不含由财政拨款保障的群团组织），公益二类和从事生产经营活动的事业单位，农村集体经济组织，基层群众性自治组织，以及具备条件的个人可以作为政府购买服务的承接主体。"},{"i":7,"n":"第七条","txt":"政府购买服务的承接主体应当符合政府采购法律、行政法规规定的条件。 购买主体可以结合购买服务项目的特点规定承接主体的具体条件，但不得违反政府采购法律、行政法规，以不合理的条件对承接主体实行差别待遇或者歧视待遇。"},{"i":8,"n":"第八条","txt":"公益一类事业单位、使用事业编制且由财政拨款保障的群团组织，不作为政府购买服务的购买主体和承接主体。"},{"i":9,"n":"第九条","txt":"政府购买服务的内容包括政府向社会公众提供的公共服务，以及政府履职所需辅助性服务。"},{"i":10,"n":"第十条","txt":"以下各项不得纳入政府购买服务范围： （一）不属于政府职责范围的服务事项； （二）应当由政府直接履职的事项； （三）政府采购法律、行政法规规定的货物和工程，以及将工程和服务打包的项目； （四）融资行为； （五）购买主体的人员招、聘用，以劳务派遣方式用工，以及设置公益性岗位等事项； （六）法律、行政法规以及国务院规定的其他不得作为政府购买服务内容的事项。"},{"i":11,"n":"第十一条","txt":"政府购买服务的具体范围和内容实行指导性目录管理，指导性目录依法予以公开。"},{"i":12,"n":"第十二条","txt":"政府购买服务指导性目录在中央和省两级实行分级管理，财政部和省级财政部门分别制定本级政府购买服务指导性目录，各部门在本级指导性目录范围内编制本部门政府购买服务指导性目录。 省级财政部门根据本地区情况确定省以下政府购买服务指导性目录的编制方式和程序。"},{"i":13,"n":"第十三条","txt":"有关部门应当根据经济社会发展实际、政府职能转变和基本公共服务均等化、标准化的要求，编制、调整指导性目录。 编制、调整指导性目录应当充分征求相关部门意见，根据实际需要进行专家论证。"},{"i":14,"n":"第十四条","txt":"纳入政府购买服务指导性目录的服务事项，已安排预算的，可以实施政府购买服务。"},{"i":15,"n":"第十五条","txt":"政府购买服务应当突出公共性和公益性，重点考虑、优先安排与改善民生密切相关，有利于转变政府职能、提高财政资金绩效的项目。 政府购买的基本公共服务项目的服务内容、水平、流程等标准要素，应当符合国家基本公共服务标准相关要求。"},{"i":16,"n":"第十六条","txt":"政府购买服务项目所需资金应当在相关部门预算中统筹安排，并与中期财政规划相衔接，未列入预算的项目不得实施。 购买主体在编报年度部门预算时，应当反映政府购买服务支出情况。政府购买服务支出应当符合预算管理有关规定。"},{"i":17,"n":"第十七条","txt":"购买主体应当根据购买内容及市场状况、相关供应商服务能力和信用状况等因素，通过公平竞争择优确定承接主体。"},{"i":18,"n":"第十八条","txt":"购买主体向个人购买服务，应当限于确实适宜实施政府购买服务并且由个人承接的情形，不得以政府购买服务名义变相用工。"},{"i":19,"n":"第十九条","txt":"政府购买服务项目采购环节的执行和监督管理，包括集中采购目录及标准、采购政策、采购方式和程序、信息公开、质疑投诉、失信惩戒等，按照政府采购法律、行政法规和相关制度执行。"},{"i":20,"n":"第二十条","txt":"购买主体实施政府购买服务项目绩效管理，应当开展事前绩效评估，定期对所购服务实施情况开展绩效评价，具备条件的项目可以运用第三方评价评估。 财政部门可以根据需要，对部门政府购买服务整体工作开展绩效评价，或者对部门实施的资金金额和社会影响大的政府购买服务项目开展重点绩效评价。"},{"i":21,"n":"第二十一条","txt":"购买主体及财政部门应当将绩效评价结果作为承接主体选择、预算安排和政策调整的重要依据。"},{"i":22,"n":"第二十二条","txt":"政府购买服务合同的签订、履行、变更，应当遵循《中华人民共和国合同法》的相关规定。"},{"i":23,"n":"第二十三条","txt":"购买主体应当与确定的承接主体签订书面合同，合同约定的服务内容应当符合本办法第九条、第十条的规定。 政府购买服务合同应当明确服务的内容、期限、数量、质量、价格，资金结算方式，各方权利义务事项和违约责任等内容。 政府购买服务合同应当依法予以公告。"},{"i":24,"n":"第二十四条","txt":"政府购买服务合同履行期限一般不超过1年；在预算保障的前提下，对于购买内容相对固定、连续性强、经费来源稳定、价格变化幅度小的政府购买服务项目，可以签订履行期限不超过3年的政府购买服务合同。"},{"i":25,"n":"第二十五条","txt":"购买主体应当加强政府购买服务项目履约管理，开展绩效执行监控，及时掌握项目实施进度和绩效目标实现情况，督促承接主体严格履行合同，按照合同约定向承接主体支付款项。"},{"i":26,"n":"第二十六条","txt":"承接主体应当按照合同约定提供服务，不得将服务项目转包给其他主体。"},{"i":27,"n":"第二十七条","txt":"承接主体应当建立政府购买服务项目台账，依照有关规定或合同约定记录保存并向购买主体提供项目实施相关重要资料信息。"},{"i":28,"n":"第二十八条","txt":"承接主体应当严格遵守相关财务规定，规范管理和使用政府购买服务项目资金。 承接主体应当配合相关部门对资金使用情况进行监督检查与绩效评价。"},{"i":29,"n":"第二十九条","txt":"承接主体可以依法依规使用政府购买服务合同向金融机构融资。 购买主体不得以任何形式为承接主体的融资行为提供担保。"},{"i":30,"n":"第三十条","txt":"有关部门应当建立健全政府购买服务监督管理机制。购买主体和承接主体应当自觉接受财政监督、审计监督、社会监督以及服务对象的监督。"},{"i":31,"n":"第三十一条","txt":"购买主体、承接主体及其他政府购买服务参与方在政府购买服务活动中，存在违反政府采购法律法规行为的，依照政府采购法律法规予以处理处罚；存在截留、挪用和滞留资金等财政违法行为的，依照《中华人民共和国预算法》《财政违法行为处罚处分条例》等法律法规追究法律责任；涉嫌犯罪的，移送司法机关处理。"},{"i":32,"n":"第三十二条","txt":"财政部门、购买主体及其工作人员，存在违反本办法规定的行为，以及滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，按照《中华人民共和国预算法》《中华人民共和国公务员法》《中华人民共和国监察法》《财政违法行为处罚处分条例》等国家有关规定追究相应责任；涉嫌犯罪的，移送司法机关处理。"},{"i":33,"n":"第三十三条","txt":"党的机关、政协机关、民主党派机关、承担行政职能的事业单位和使用行政编制的群团组织机关使用财政性资金购买服务的，参照本办法执行。"},{"i":34,"n":"第三十四条","txt":"涉密政府购买服务项目的实施，按照国家有关规定执行。"},{"i":35,"n":"第三十五条","txt":"本办法自2020年3月1日起施行。财政部、民政部、工商总局2014年12月15日颁布的《政府购买服务管理办法（暂行）》（财综﹝2014﹞96号）同时废止。"}],"zhengfucaigouxinxigonggaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范政府采购信息公告行为，提高政府采购活动透明度，促进公平竞争，根据《中华人民共和国政府采购法》（以下简称政府采购法），制定本办法。"},{"i":2,"n":"第二条","txt":"政府采购信息，是指规范政府采购活动的法律、法规、规章和其他规范性文件，以及反映政府采购活动状况的数据和资料的总称。 政府采购信息公告，是指将本办法规定应当公开的政府采购信息在财政部门指定的政府采购信息发布媒体上向社会公开发布。"},{"i":3,"n":"第三条","txt":"采购人、采购代理机构应当按照有关政府采购的法律、行政法规和本办法规定，公告政府采购信息。 前款所称采购代理机构，是指集中采购机构和依法经认定资格的其他采购代理机构。"},{"i":4,"n":"第四条","txt":"政府采购信息公告应当遵循信息发布及时、内容规范统一、渠道相对集中，便于获得查找的原则。"},{"i":5,"n":"第五条","txt":"县级以上各级财政部门负责对政府采购信息公告活动进行监督、检查和管理。但是，下列职责由省级以上财政部门履行： （一）确定应当公告的政府采购信息的范围和内容； （二）指定并监督检查公告政府采购信息的媒体。"},{"i":6,"n":"第六条","txt":"财政部负责确定政府采购信息公告的基本范围和内容，指定全国政府采购信息发布媒体。 省级（含计划单列市，下同）财政部门负责确定本地区政府采购信息公告的范围和内容，可以指定本地区政府采购信息发布媒体。 除财政部和省级财政部门以外，其他任何单位和个人不得指定政府采购信息的发布媒体。"},{"i":7,"n":"第七条","txt":"政府采购信息应当首先在财政部指定的政府采购信息发布媒体上公告。 地方的政府采购信息可以同时在其省级财政部门指定的政府采购信息发布媒体上公告。"},{"i":8,"n":"第八条","txt":"除涉及国家秘密、供应商的商业秘密，以及法律、行政法规规定应予保密的政府采购信息以外，下列政府采购信息必须公告： （一）有关政府采购的法律、法规、规章和其他规范性文件； （二）省级以上人民政府公布的集中采购目录、政府采购限额标准和公开招标数额标准； （三）政府采购招标业务代理机构名录； （四）招标投标信息，包括公开招标公告、邀请招标资格预审公告、中标公告、成交结果及其更正事项等； （五）财政部门受理政府采购投诉的联系方式及投诉处理决定； （六）财政部门对集中采购机构的考核结果； （七）采购代理机构、供应商不良行为记录名单； （八）法律、法规和规章规定应当公告的其他政府采购信息。"},{"i":9,"n":"第九条","txt":"除本办法第八条规定内容外，省级以上财政部门可以根据管理需要，增加需要公告的政府采购信息内容。"},{"i":10,"n":"第十条","txt":"公开招标公告应当包括下列内容： （一）采购人、采购代理机构的名称、地址和联系方式； （二）招标项目的名称、用途、数量、简要技术要求或者招标项目的性质； （三）供应商资格要求； （四）获取招标文件的时间、地点、方式及招标文件售价； （五）投标截止时间、开标时间及地点； （六）采购项目联系人姓名和电话。"},{"i":11,"n":"第十一条","txt":"邀请招标资格预审公告应当包括下列内容： （一）采购人、采购代理机构的名称、地址和联系方式； （二）招标项目的名称、用途、数量、简要技术要求或招标项目的性质； （三）供应商资格要求； （四）提交资格申请及证明材料的截止时间及资格审查日期； （五）采购项目联系人姓名和电话。"},{"i":12,"n":"第十二条","txt":"中标公告应当包括下列内容： （一）采购人、采购代理机构的名称、地址和联系方式； （二）采购项目名称、用途、数量、简要技术要求及合同履行日期； （三）定标日期（注明招标文件编号）； （四）本项目招标公告日期； （五）中标供应商名称、地址和中标金额； （六）评标委员会成员名单； （七）采购项目联系人姓名和电话。"},{"i":13,"n":"第十三条","txt":"采购信息更正公告应当包括下列内容： （一）采购人、采购代理机构名称、地址和联系方式； （二）原公告的采购项目名称及首次公告日期； （三）更正事项、内容及日期； （四）采购项目联系人和电话。"},{"i":14,"n":"第十四条","txt":"采购代理机构、供应商不良行为记录名单公告，应当包括当事人名称、事由、处理机关和处理结果等内容。"},{"i":15,"n":"第十五条","txt":"投诉处理决定公告应当包括下列内容： （一）采购人、采购代理机构名称； （二）采购项目名称及采购日期； （三）投诉人名称及投诉事项； （四）投诉处理机关名称； （五）处理决定的主要内容。"},{"i":16,"n":"第十六条","txt":"公告政府采购信息必须做到内容真实、准确可靠，不得有虚假和误导性陈述，不得遗漏依法必须公告的事项。"},{"i":17,"n":"第十七条","txt":"在各政府采购信息指定发布媒体上分别公告同一政府采购信息的，内容必须保持一致。内容不一致的，以在财政部指定的政府采购信息发布媒体上公告的信息为准，但法律、行政法规另有规定的除外。"},{"i":18,"n":"第十八条","txt":"在各政府采购信息指定发布媒体上公告同一政府采购信息的时间不一致的，以在财政部指定的政府采购信息发布媒体上最早公告信息的时间为公告时间和政府采购当事人对有关事项应当知道的时间。"},{"i":19,"n":"第十九条","txt":"政府采购法律、法规、规章和其他规范性文件，集中采购目录、政府采购限额标准，公开招标限额标准等信息，由省级以上人民政府财政部门负责在政府采购信息指定发布媒体上公告。"},{"i":20,"n":"第二十条","txt":"招标投标信息由采购人或者其委托的采购代理机构负责在政府采购信息指定发布媒体上公告。"},{"i":21,"n":"第二十一条","txt":"对集中采购机构的考核结果以及采购代理机构、供应商不良行为记录名单等信息，由同级人民政府财政部门按照有关规定在政府采购信息指定媒体上公告。"},{"i":22,"n":"第二十二条","txt":"本办法第十九条、第二十条和第二十一条规定以外的其他信息，属于政府采购监督管理方面的，由同级人民政府财政部门进行公告；属于采购业务方面的，由采购人或者其委托的采购代理机构进行公告。"},{"i":23,"n":"第二十三条","txt":"采购人、采购代理机构需要公告政府采购信息的，应当以传真、电子邮件等快捷方式将信息提供给政府采购信息指定发布媒体，也可经同级人民政府财政部门提供给政府采购信息指定发布媒体。"},{"i":24,"n":"第二十四条","txt":"政府采购信息指定发布媒体负责承办本办法规定的政府采购信息发布的具体事宜。 政府采购信息指定发布媒体发布政府采购信息，应当体现公益性原则。"},{"i":25,"n":"第二十五条","txt":"政府采购信息指定发布媒体应当按照信息提供者提供的信息内容发布信息。但是，对信息篇幅过大的，政府采购信息指定发布媒体可以按照统一的技术要求进行适当的压缩和调整；进行压缩和调整的，不得改变提供信息的实质性内容。"},{"i":26,"n":"第二十六条","txt":"政府采购信息指定发布媒体发现信息提供者提供的信息违反法律、法规、规章和本办法规定的，应当及时建议信息提供者修改；信息提供者拒不修改的，应当向信息提供者同级的人民政府财政部门报告。"},{"i":27,"n":"第二十七条","txt":"财政部门指定的政府采购信息发布媒体中的网络媒体，应当在收到公告信息之日起1个工作日内上网发布；指定的报纸，应当在收到公告信息之日起3个工作日内发布；指定的杂志，应当及时刊登有关公告信息。"},{"i":28,"n":"第二十八条","txt":"政府采购信息指定发布媒体应当对其发布的政府采购信息进行分类统计，并将统计结果按期报送同级人民政府财政部门。"},{"i":29,"n":"第二十九条","txt":"政府采购信息指定发布媒体应当向社会公告本媒体的名称和联系方式。名称和联系方式发生变更的，应当及时向社会公告，并向负责指定其发布政府采购信息的财政部门备案。"},{"i":30,"n":"第三十条","txt":"采购人或者采购代理机构有下列情形之一的，由县级人民政府财政部门责令限期改正，给予警告；对直接负责的主管人员和其他直接责任人员，由其行政主管部门或者有关机关给予处分，并予通报： （一）应当公告政府采购信息而未公告的； （二）不首先在财政部指定的政府采购信息发布媒体上公告信息，或者不在财政部门指定的政府采购信息发布媒体上公告信息的； （三）政府采购信息内容明显违反本办法规定的； （四）在两个以上政府采购信息指定发布媒体上公告同一信息的实质内容明显不一致的； （五）未按规定期限公告信息的。"},{"i":31,"n":"第三十一条","txt":"采购人或者采购代理机构有下列情形之一的，采购无效，并由县级人民政府财政部门给予警告或者通报批评；属于政府采购代理机构责任且情节严重的，依法取消其进行相关业务资格： （一）招标投标信息中以不合理条件限制或者排斥潜在投标人的； （二）公告的信息不真实，有虚假或者欺诈内容的。"},{"i":32,"n":"第三十二条","txt":"政府采购信息指定发布媒体有下列情形之一的，由省级以上人民政府财政部门给予警告；情节严重的，依法取消其政府采购信息指定发布媒体资格；造成经济损失的，依法承担相应的赔偿责任： （一）违反事先约定收取或者变相收取信息发布费用的； （二）无正当理由拒绝发布信息提供者提供信息的； （三）无正当理由延误政府采购信息发布时间的； （四）发布政府采购信息改变信息提供者提供信息实质性内容的； （五）其他违反政府采购信息管理的行为。"},{"i":33,"n":"第三十三条","txt":"任何单位和个人非法干预政府采购信息公告活动的，由省级以上人民政府财政部门责令限期改正，给予以警告；拒不改正的，转送有关机关依法处理。"},{"i":34,"n":"第三十四条","txt":"任何单位或者个人发现政府采购信息发布活动不符合本办法规定的，有权向同级人民政府财政部门控告和检举，有关财政部门应当依法予以处理。"},{"i":35,"n":"第三十五条","txt":"省级财政部门可以根据本办法，制定具体实施办法。"},{"i":36,"n":"第三十六条","txt":"本办法自2004年9月11日起施行。财政部2000年9月11日颁布实施的《政府采购信息公告管理办法》（财库[2000]7号）同时废止。"}],"zhengfucaigouxinxifabuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范政府采购信息发布行为，提高政府采购透明度，根据《中华人民共和国政府采购法》《中华人民共和国政府采购法实施条例》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"政府采购信息发布，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称政府采购信息，是指依照政府采购有关法律制度规定应予公开的公开招标公告、资格预审公告、单一来源采购公示、中标（成交）结果公告、政府采购合同公告等政府采购项目信息，以及投诉处理结果、监督检查处理结果、集中采购机构考核结果等政府采购监管信息。"},{"i":4,"n":"第四条","txt":"政府采购信息发布应当遵循格式规范统一、渠道相对集中、便于查找获得的原则。"},{"i":5,"n":"第五条","txt":"财政部指导和协调全国政府采购信息发布工作，并依照政府采购法律、行政法规有关规定，对中央预算单位的政府采购信息发布活动进行监督管理。 地方各级人民政府财政部门（以下简称财政部门）对本级预算单位的政府采购信息发布活动进行监督管理。"},{"i":6,"n":"第六条","txt":"财政部对中国政府采购网进行监督管理。省级（自治区、直辖市、计划单列市）财政部门对中国政府采购网省级分网进行监督管理。"},{"i":7,"n":"第七条","txt":"政府采购信息应当按照财政部规定的格式编制。"},{"i":8,"n":"第八条","txt":"中央预算单位政府采购信息应当在中国政府采购网发布，地方预算单位政府采购信息应当在所在行政区域的中国政府采购网省级分网发布。 除中国政府采购网及其省级分网以外，政府采购信息可以在省级以上财政部门指定的其他媒体同步发布。"},{"i":9,"n":"第九条","txt":"财政部门、采购人和其委托的采购代理机构（以下统称发布主体）应当对其提供的政府采购信息的真实性、准确性、合法性负责。 中国政府采购网及其省级分网和省级以上财政部门指定的其他媒体（以下统称指定媒体）应当对其收到的政府采购信息发布的及时性、完整性负责。"},{"i":10,"n":"第十条","txt":"发布主体发布政府采购信息不得有虚假和误导性陈述，不得遗漏依法必须公开的事项。"},{"i":11,"n":"第十一条","txt":"发布主体应当确保其在不同媒体发布的同一政府采购信息内容一致。 在不同媒体发布的同一政府采购信息内容、时间不一致的，以在中国政府采购网或者其省级分网发布的信息为准。同时在中国政府采购网和省级分网发布的，以在中国政府采购网上发布的信息为准。"},{"i":12,"n":"第十二条","txt":"指定媒体应当采取必要措施，对政府采购信息发布主体的身份进行核验。"},{"i":13,"n":"第十三条","txt":"指定媒体应当及时发布收到的政府采购信息。 中国政府采购网或者其省级分网应当自收到政府采购信息起1个工作日内发布。"},{"i":14,"n":"第十四条","txt":"指定媒体应当加强安全防护，确保发布的政府采购信息不被篡改、不遗漏，不得擅自删除或者修改信息内容。"},{"i":15,"n":"第十五条","txt":"指定媒体应当向发布主体免费提供信息发布服务，不得向市场主体和社会公众收取信息查阅费用。"},{"i":16,"n":"第十六条","txt":"采购人或者其委托的采购代理机构未依法在指定媒体上发布政府采购项目信息的，依照政府采购法实施条例第六十八条追究法律责任。 采购人或者其委托的采购代理机构存在其他违反本办法规定行为的，由县级以上财政部门依法责令限期改正，给予警告，对直接负责的主管人员和其他直接责任人员，建议其行政主管部门或者有关机关依法依规处理，并予通报。"},{"i":17,"n":"第十七条","txt":"指定媒体违反本办法规定的，由实施指定行为的省级以上财政部门依法责令限期改正，对直接负责的主管人员和其他直接责任人员，建议其行政主管部门或者有关机关依法依规处理，并予通报。"},{"i":18,"n":"第十八条","txt":"财政部门及其工作人员在政府采购信息发布活动中存在懒政怠政、滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，依照《中华人民共和国政府采购法》《中华人民共和国公务员法》《中华人民共和国监察法》《中华人民共和国政府采购法实施条例》等国家有关规定追究相应责任；涉嫌犯罪的，依法移送有关国家机关处理。"},{"i":19,"n":"第十九条","txt":"涉密政府采购项目信息发布，依照国家有关规定执行。"},{"i":20,"n":"第二十条","txt":"省级财政部门可以根据本办法制定具体实施办法。"},{"i":21,"n":"第二十一条","txt":"本办法自2020年3月1日起施行。财政部2004年9月11日颁布实施的《政府采购信息公告管理办法》（财政部令第19号）同时废止。"}],"zhengfucaigoukuangjiaxieyicaigoufangshiguanlizanxia9b8e1":[{"i":1,"n":"第一条","txt":"为了规范多频次、小额度采购活动，提高政府采购项目绩效，根据《中华人民共和国政府采购法》、《中华人民共和国政府采购法实施条例》等法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称框架协议采购，是指集中采购机构或者主管预算单位对技术、服务等标准明确、统一，需要多次重复采购的货物和服务，通过公开征集程序，确定第一阶段入围供应商并订立框架协议，采购人或者服务对象按照框架协议约定规则，在入围供应商范围内确定第二阶段成交供应商并订立采购合同的采购方式。 前款所称主管预算单位是指负有编制部门预算职责，向本级财政部门申报预算的国家机关、事业单位和团体组织。"},{"i":3,"n":"第三条","txt":"符合下列情形之一的，可以采用框架协议采购方式采购： （一）集中采购目录以内品目，以及与之配套的必要耗材、配件等，属于小额零星采购的； （二）集中采购目录以外，采购限额标准以上，本部门、本系统行政管理所需的法律、评估、会计、审计等鉴证咨询服务，属于小额零星采购的； （三）集中采购目录以外，采购限额标准以上，为本部门、本系统以外的服务对象提供服务的政府购买服务项目，需要确定2家以上供应商由服务对象自主选择的； （四）国务院财政部门规定的其他情形。 前款所称采购限额标准以上，是指同一品目或者同一类别的货物、服务年度采购预算达到采购限额标准以上。 属于本条第一款第二项情形，主管预算单位能够归集需求形成单一项目进行采购，通过签订时间、地点、数量不确定的采购合同满足需求的，不得采用框架协议采购方式。"},{"i":4,"n":"第四条","txt":"框架协议采购包括封闭式框架协议采购和开放式框架协议采购。 封闭式框架协议采购是框架协议采购的主要形式。除法律、行政法规或者本办法另有规定外，框架协议采购应当采用封闭式框架协议采购。"},{"i":5,"n":"第五条","txt":"集中采购目录以内品目以及与之配套的必要耗材、配件等，采用框架协议采购的，由集中采购机构负责征集程序和订立框架协议。 集中采购目录以外品目采用框架协议采购的，由主管预算单位负责征集程序和订立框架协议。其他预算单位确有需要的，经其主管预算单位批准，可以采用框架协议采购方式采购。其他预算单位采用框架协议采购方式采购的，应当遵守本办法关于主管预算单位的规定。 主管预算单位可以委托采购代理机构代理框架协议采购，采购代理机构应当在委托的范围内依法开展采购活动。 集中采购机构、主管预算单位及其委托的采购代理机构，本办法统称征集人。"},{"i":6,"n":"第六条","txt":"框架协议采购遵循竞争择优、讲求绩效的原则，应当有明确的采购标的和定价机制，不得采用供应商符合资格条件即入围的方法。"},{"i":7,"n":"第七条","txt":"框架协议采购应当实行电子化采购。"},{"i":8,"n":"第八条","txt":"集中采购机构采用框架协议采购的，应当拟定采购方案，报本级财政部门审核后实施。主管预算单位采用框架协议采购的，应当在采购活动开始前将采购方案报本级财政部门备案。"},{"i":9,"n":"第九条","txt":"封闭式框架协议采购是指符合本办法第三条规定情形，通过公开竞争订立框架协议后，除经过框架协议约定的补充征集程序外，不得增加协议供应商的框架协议采购。 封闭式框架协议的公开征集程序，按照政府采购公开招标的规定执行，本办法另有规定的，从其规定。"},{"i":10,"n":"第十条","txt":"开放式框架协议采购是指符合本条第二款规定情形，明确采购需求和付费标准等框架协议条件，愿意接受协议条件的供应商可以随时申请加入的框架协议采购。开放式框架协议的公开征集程序，按照本办法规定执行。 符合下列情形之一的，可以采用开放式框架协议采购： （一）本办法第三条第一款第一项规定的情形，因执行政府采购政策不宜淘汰供应商的，或者受基础设施、行政许可、知识产权等限制，供应商数量在3家以下且不宜淘汰供应商的； （二）本办法第三条第一款第三项规定的情形，能够确定统一付费标准，因地域等服务便利性要求，需要接纳所有愿意接受协议条件的供应商加入框架协议，以供服务对象自主选择的。"},{"i":11,"n":"第十一条","txt":"集中采购机构或者主管预算单位应当确定框架协议采购需求。框架协议采购需求在框架协议有效期内不得变动。 确定框架协议采购需求应当开展需求调查，听取采购人、供应商和专家等意见。面向采购人和供应商开展需求调查时，应当选择具有代表性的调查对象，调查对象一般各不少于3个。"},{"i":12,"n":"第十二条","txt":"框架协议采购需求应当符合以下规定： （一）满足采购人和服务对象实际需要，符合市场供应状况和市场公允标准，在确保功能、性能和必要采购要求的情况下促进竞争； （二）符合预算标准、资产配置标准等有关规定，厉行节约，不得超标准采购； （三）按照《政府采购品目分类目录》，将采购标的细化到底级品目，并细分不同等次、规格或者标准的采购需求，合理设置采购包； （四）货物项目应当明确货物的技术和商务要求，包括功能、性能、材料、结构、外观、安全、包装、交货期限、交货的地域范围、售后服务等； （五）服务项目应当明确服务内容、服务标准、技术保障、服务人员组成、服务交付或者实施的地域范围，以及所涉及的货物的质量标准、服务工作量的计量方式等。"},{"i":13,"n":"第十三条","txt":"集中采购机构或者主管预算单位应当在征集公告和征集文件中确定框架协议采购的最高限制单价。征集文件中可以明确量价关系折扣，即达到一定采购数量，价格应当按照征集文件中明确的折扣降低。在开放式框架协议中，付费标准即为最高限制单价。 最高限制单价是供应商第一阶段响应报价的最高限价。入围供应商第一阶段响应报价（有量价关系折扣的，包括量价关系折扣，以下统称协议价格）是采购人或者服务对象确定第二阶段成交供应商的最高限价。 确定最高限制单价时，有政府定价的，执行政府定价；没有政府定价的，应当通过需求调查，并根据需求标准科学确定，属于本办法第十条第二款第一项规定情形的采购项目，需要订立开放式框架协议的，与供应商协商确定。 货物项目单价按照台（套）等计量单位确定，其中包含售后服务等相关服务费用。服务项目单价按照单位采购标的价格或者人工单价等确定。服务项目所涉及的货物的费用，能够折算入服务项目单价的应当折入，"},{"i":14,"n":"第十四条","txt":"框架协议应当包括以下内容： （一）集中采购机构或者主管预算单位以及入围供应商的名称、地址和联系方式； （二）采购项目名称、编号； （三）采购需求以及最高限制单价； （四）封闭式框架协议第一阶段的入围产品详细技术规格或者服务内容、服务标准，协议价格； （五）入围产品升级换代规则； （六）确定第二阶段成交供应商的方式； （七）适用框架协议的采购人或者服务对象范围，以及履行合同的地域范围； （八）资金支付方式、时间和条件； （九）采购合同文本，包括根据需要约定适用的简式合同或者具有合同性质的凭单、订单； （十）框架协议期限； （十一）入围供应商清退和补充规则； （十二）协议方的权利和义务; （十三）需要约定的其他事项。"},{"i":15,"n":"第十五条","txt":"集中采购机构或者主管预算单位应当根据工作需要和采购标的市场供应及价格变化情况，科学合理确定框架协议期限。货物项目框架协议有效期一般不超过1年，服务项目框架协议有效期一般不超过2年。"},{"i":16,"n":"第十六条","txt":"集中采购机构或者主管预算单位应当根据框架协议约定，组织落实框架协议的履行，并履行下列职责： （一）为第二阶段合同授予提供工作便利； （二）对第二阶段最高限价和需求标准执行情况进行管理； （三）对第二阶段确定成交供应商情况进行管理； （四）根据框架协议约定，在质量不降低、价格不提高的前提下，对入围供应商因产品升级换代、用新产品替代原入围产品的情形进行审核； （五）建立用户反馈和评价机制，接受采购人和服务对象对入围供应商履行框架协议和采购合同情况的反馈与评价，并将用户反馈和评价情况向采购人和服务对象公开，作为第二阶段直接选定成交供应商的参考； （六）公开封闭式框架协议的第二阶段成交结果； （七）办理入围供应商清退和补充相关事宜。"},{"i":17,"n":"第十七条","txt":"采购人或者服务对象采购框架协议约定的货物、服务，应当将第二阶段的采购合同授予入围供应商，但是本办法第三十七条另有规定的除外。 同一框架协议采购应当使用统一的采购合同文本，采购人、服务对象和供应商不得擅自改变框架协议约定的合同实质性条款。"},{"i":18,"n":"第十八条","txt":"货物项目框架协议的入围供应商应当为入围产品生产厂家或者生产厂家唯一授权供应商。入围供应商可以委托一家或者多家代理商，按照框架协议约定接受采购人合同授予，并履行采购合同。入围供应商应当在框架协议中提供委托协议和委托的代理商名单。"},{"i":19,"n":"第十九条","txt":"入围供应商有下列情形之一，尚未签订框架协议的，取消其入围资格；已经签订框架协议的，解除与其签订的框架协议： （一）恶意串通谋取入围或者合同成交的； （二）提供虚假材料谋取入围或者合同成交的； （三）无正当理由拒不接受合同授予的； （四）不履行合同义务或者履行合同义务不符合约定，经采购人请求履行后仍不履行或者仍未按约定履行的； （五）框架协议有效期内，因违法行为被禁止或限制参加政府采购活动的； （六）框架协议约定的其他情形。 被取消入围资格或者被解除框架协议的供应商不得参加同一封闭式框架协议补充征集，或者重新申请加入同一开放式框架协议。"},{"i":20,"n":"第二十条","txt":"封闭式框架协议入围供应商无正当理由，不得主动放弃入围资格或者退出框架协议。 开放式框架协议入围供应商可以随时申请退出框架协议。集中采购机构或者主管预算单位应当在收到退出申请2个工作日内，发布入围供应商退出公告。"},{"i":21,"n":"第二十一条","txt":"征集人应当建立真实完整的框架协议采购档案，妥善保存每项采购活动的采购文件资料。除征集人和采购人另有约定外，合同授予的采购文件资料由采购人负责保存。 采购档案可以采用电子形式保存，电子档案和纸质档案具有同等效力。"},{"i":22,"n":"第二十二条","txt":"征集人应当发布征集公告。征集公告应当包括以下主要内容： （一）征集人的名称、地址、联系人和联系方式； （二）采购项目名称、编号，采购需求以及最高限制单价，适用框架协议的采购人或者服务对象范围，能预估采购数量的，还应当明确预估采购数量； （三）供应商的资格条件； （四）框架协议的期限； （五）获取征集文件的时间、地点和方式； （六）响应文件的提交方式、提交截止时间和地点，开启方式、时间和地点； （七）公告期限； （八）省级以上财政部门规定的其他事项。"},{"i":23,"n":"第二十三条","txt":"征集人应当编制征集文件。征集文件应当包括以下主要内容： （一）参加征集活动的邀请； （二）供应商应当提交的资格材料； （三）资格审查方法和标准； （四）采购需求以及最高限制单价； （五）政府采购政策要求以及政策执行措施； （六）框架协议的期限； （七）报价要求； （八）确定第一阶段入围供应商的评审方法、评审标准、确定入围供应商的淘汰率或者入围供应商数量上限和响应文件无效情形； （九）响应文件的编制要求，提交方式、提交截止时间和地点，开启方式、时间和地点，以及响应文件有效期； （十）拟签订的框架协议文本和采购合同文本； （十一）确定第二阶段成交供应商的方式； （十二）采购资金的支付方式、时间和条件； （十三）入围产品升级换代规则； （十四）用户反馈和评价机制； （十五）入围供应商的清退和补充规则； （十六）供应商信用信息查询渠道及截止时点、信用信息查询记录和证据留存的具体方式、信用信息的"},{"i":24,"n":"第二十四条","txt":"供应商应当按照征集文件要求编制响应文件，对响应文件的真实性和合法性承担法律责任。 供应商响应的货物和服务的技术、商务等条件不得低于采购需求，货物原则上应当是市场上已有销售的规格型号，不得是专供政府采购的产品。对货物项目每个采购包只能用一个产品进行响应，征集文件有要求的，应当同时对产品的选配件、耗材进行报价。服务项目包含货物的，响应文件中应当列明货物清单及质量标准。"},{"i":25,"n":"第二十五条","txt":"确定第一阶段入围供应商的评审方法包括价格优先法和质量优先法。 价格优先法是指对满足采购需求且响应报价不超过最高限制单价的货物、服务，按照响应报价从低到高排序，根据征集文件规定的淘汰率或者入围供应商数量上限，确定入围供应商的评审方法。 质量优先法是指对满足采购需求且响应报价不超过最高限制单价的货物、服务进行质量综合评分，按照质量评分从高到低排序，根据征集文件规定的淘汰率或者入围供应商数量上限，确定入围供应商的评审方法。货物项目质量因素包括采购标的的技术水平、产品配置、售后服务等，服务项目质量因素包括服务内容、服务水平、供应商的履约能力、服务经验等。质量因素中的可量化指标应当划分等次，作为评分项；质量因素中的其他指标可以作为实质性要求，不得作为评分项。 有政府定价、政府指导价的项目，以及对质量有特别要求的检测、实验等仪器设备，可以采用质量优先法，其他项目应当采用价格优先法。"},{"i":26,"n":"第二十六条","txt":"对耗材使用量大的复印、打印、实验、医疗等仪器设备进行框架协议采购的，应当要求供应商同时对3年以上约定期限内的专用耗材进行报价。评审时应当考虑约定期限的专用耗材使用成本，修正仪器设备的响应报价或者质量评分。 征集人应当在征集文件、框架协议和采购合同中规定，入围供应商在约定期限内，应当以不高于其报价的价格向适用框架协议的采购人供应专用耗材。"},{"i":27,"n":"第二十七条","txt":"确定第一阶段入围供应商时，提交响应文件和符合资格条件、实质性要求的供应商应当均不少于2家，淘汰比例一般不得低于20%，且至少淘汰一家供应商。 采用质量优先法的检测、实验等仪器设备采购，淘汰比例不得低于40%，且至少淘汰一家供应商。"},{"i":28,"n":"第二十八条","txt":"入围结果公告应当包括以下主要内容： （一）采购项目名称、编号； （二）征集人的名称、地址、联系人和联系方式； （三）入围供应商名称、地址及排序； （四）最高入围价格或者最低入围分值； （五）入围产品名称、规格型号或者主要服务内容及服务标准，入围单价； （六）评审小组成员名单； （七）采购代理服务收费标准及金额； （八）公告期限； （九）省级以上财政部门规定的其他事项。"},{"i":29,"n":"第二十九条","txt":"集中采购机构或者主管预算单位应当在入围通知书发出之日起30日内和入围供应商签订框架协议，并在框架协议签订后7个工作日内，将框架协议副本报本级财政部门备案。 框架协议不得对征集文件确定的事项以及入围供应商的响应文件作实质性修改。"},{"i":30,"n":"第三十条","txt":"征集人应当在框架协议签订后3个工作日内通过电子化采购系统将入围信息告知适用框架协议的所有采购人或者服务对象。 入围信息应当包括所有入围供应商的名称、地址、联系方式、入围产品信息和协议价格等内容。入围产品信息应当详细列明技术规格或者服务内容、服务标准等能反映产品质量特点的内容。 征集人应当确保征集文件和入围信息在整个框架协议有效期内随时可供公众查阅。"},{"i":31,"n":"第三十一条","txt":"除剩余入围供应商不足入围供应商总数70%且影响框架协议执行的情形外，框架协议有效期内，征集人不得补充征集供应商。 征集人补充征集供应商的，补充征集规则应当在框架协议中约定，补充征集的条件、程序、评审方法和淘汰比例应当与初次征集相同。补充征集应当遵守原框架协议的有效期。补充征集期间，原框架协议继续履行。"},{"i":32,"n":"第三十二条","txt":"确定第二阶段成交供应商的方式包括直接选定、二次竞价和顺序轮候。 直接选定方式是确定第二阶段成交供应商的主要方式。除征集人根据采购项目特点和提高绩效等要求，在征集文件中载明采用二次竞价或者顺序轮候方式外，确定第二阶段成交供应商应当由采购人或者服务对象依据入围产品价格、质量以及服务便利性、用户评价等因素，从第一阶段入围供应商中直接选定。"},{"i":33,"n":"第三十三条","txt":"二次竞价方式是指以框架协议约定的入围产品、采购合同文本等为依据，以协议价格为最高限价，采购人明确第二阶段竞价需求，从入围供应商中选择所有符合竞价需求的供应商参与二次竞价，确定报价最低的为成交供应商的方式。 进行二次竞价应当给予供应商必要的响应时间。 二次竞价一般适用于采用价格优先法的采购项目。"},{"i":34,"n":"第三十四条","txt":"顺序轮候方式是指根据征集文件中确定的轮候顺序规则，对所有入围供应商依次授予采购合同的方式。 每个入围供应商在一个顺序轮候期内，只有一次获得合同授予的机会。合同授予顺序确定后，应当书面告知所有入围供应商。除清退入围供应商和补充征集外，框架协议有效期内不得调整合同授予顺序。 顺序轮候一般适用于服务项目。"},{"i":35,"n":"第三十五条","txt":"以二次竞价或者顺序轮候方式确定成交供应商的，征集人应当在确定成交供应商后2个工作日内逐笔发布成交结果公告。 成交结果单笔公告可以在省级以上财政部门指定的媒体上发布，也可以在开展框架协议采购的电子化采购系统发布，发布成交结果公告的渠道应当在征集文件或者框架协议中告知供应商。单笔公告应当包括以下主要内容： （一）采购人的名称、地址和联系方式； （二）框架协议采购项目名称、编号； （三）成交供应商名称、地址和成交金额； （四）成交标的名称、规格型号或者主要服务内容及服务标准、数量、单价； （五）公告期限。 征集人应当在框架协议有效期满后10个工作日内发布成交结果汇总公告。汇总公告应当包括前款第一项、第二项内容和所有成交供应商的名称、地址及其成交合同总数和总金额。"},{"i":36,"n":"第三十六条","txt":"框架协议采购应当订立固定价格合同。 根据实际采购数量和协议价格确定合同总价的，合同中应当列明实际采购数量或者计量方式，包括服务项目用于计算合同价的工日数、服务工作量等详细工作量清单。采购人应当要求供应商提供能证明其按照合同约定数量或者工作量清单履约的相关记录或者凭证，作为验收资料一并存档。"},{"i":37,"n":"第三十七条","txt":"采购人证明能够以更低价格向非入围供应商采购相同货物，且入围供应商不同意将价格降至非入围供应商以下的，可以将合同授予非入围供应商。 采购项目适用前款规定的，征集人应当在征集文件中载明并在框架协议中约定。 采购人将合同授予非入围供应商的，应当在确定成交供应商后1个工作日内，将成交结果抄送征集人，由征集人按照单笔公告要求发布成交结果公告。采购人应当将相关证明材料和采购合同一并存档备查。"},{"i":38,"n":"第三十八条","txt":"订立开放式框架协议的，征集人应当发布征集公告，邀请供应商加入框架协议。征集公告应当包括以下主要内容： （一）本办法第二十二条第一项至四项和第二十三条第二项至三项、第十三项至十六项内容； （二）订立开放式框架协议的邀请； （三）供应商提交加入框架协议申请的方式、地点，以及对申请文件的要求； （四）履行合同的地域范围、协议方的权利和义务、入围供应商的清退机制等框架协议内容； （五）采购合同文本； （六）付费标准，费用结算及支付方式； （七）省级以上财政部门规定的其他事项。"},{"i":39,"n":"第三十九条","txt":"征集公告发布后至框架协议期满前，供应商可以按照征集公告要求，随时提交加入框架协议的申请。征集人应当在收到供应商申请后7个工作日内完成审核，并将审核结果书面通知申请供应商。"},{"i":40,"n":"第四十条","txt":"征集人应当在审核通过后2个工作日内，发布入围结果公告，公告入围供应商名称、地址、联系方式及付费标准，并动态更新入围供应商信息。 征集人应当确保征集公告和入围结果公告在整个框架协议有效期内随时可供公众查阅。"},{"i":41,"n":"第四十一条","txt":"征集人可以根据采购项目特点，在征集公告中申明是否与供应商另行签订书面框架协议。申明不再签订书面框架协议的，发布入围结果公告，视为签订框架协议。"},{"i":42,"n":"第四十二条","txt":"第二阶段成交供应商由采购人或者服务对象从第一阶段入围供应商中直接选定。 供应商履行合同后，依据框架协议约定的凭单、订单以及结算方式，与采购人进行费用结算。"},{"i":43,"n":"第四十三条","txt":"主管预算单位、采购人、采购代理机构违反本办法规定的，由财政部门责令限期改正；情节严重的，给予警告，对直接负责的主管人员和其他责任人员，由其行政主管部门或者有关机关依法给予处分，并予以通报。"},{"i":44,"n":"第四十四条","txt":"违反本办法规定，经责令改正后仍然影响或者可能影响入围结果或者成交结果的，依照政府采购法等有关法律、行政法规处理。"},{"i":45,"n":"第四十五条","txt":"供应商有本办法第十九条第一款第一项至三项情形之一，以及无正当理由放弃封闭式框架协议入围资格或者退出封闭式框架协议的，依照政府采购法等有关法律、行政法规追究法律责任。"},{"i":46,"n":"第四十六条","txt":"政府采购当事人违反本办法规定，给他人造成损失的，依法承担民事责任。"},{"i":47,"n":"第四十七条","txt":"财政部门及其工作人员在履行监督管理职责中存在滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，依法追究相应责任。"},{"i":48,"n":"第四十八条","txt":"除本办法第三十五条规定外，本办法规定的公告信息，应当在省级以上财政部门指定的媒体上发布。"},{"i":49,"n":"第四十九条","txt":"本办法规定按日计算期间的，开始当天不计入，从次日开始计算。期限的最后一日是国家法定节假日的，顺延到节假日后的次日为期限的最后一日。"},{"i":50,"n":"第五十条","txt":"本办法所称的“以上”、“以下”、“内”、“以内”、“不少于”、“不超过”，包括本数；所称的“不足”、“低于”，不包括本数。"},{"i":51,"n":"第五十一条","txt":"各省、自治区、直辖市财政部门可以根据本办法制定具体实施办法。"},{"i":52,"n":"第五十二条","txt":"本办法自2022年3月1日起施行。"}],"zhengfucaigouhuowuhefuwuzhaobiaotoubiaoguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了规范政府采购当事人的采购行为，加强对政府购货物和服务招标投标活动的监督管理， 维护社会公共利益和府采购招标投标活动当事人的合法权益，依据《中华人民共和政府采购法》(以下简称政府采购法)和其他有关法律规定，定本办法．"},{"i":2,"n":"第二条","txt":"采购人及采购代理机构(以下统称“招标采购单位”)进行政府采购货物或者服务(以下简 称“货物服务”)招标标活动，适用本办法。 前款所称采购代理机构，是指集中采购机构和依法经认定资的其 他采购代理机构。"},{"i":3,"n":"第三条","txt":"货物服务招标分为公开招标和邀请招标。 公开招标，是指招标采购单位依法以招标公告的方式邀请不定的 供应商参加投标。 邀请招标，是指招标采购单位依法从符合相应资格条件的供商中 随机邀请三家以上供应商，并以投标邀请书的方式，邀请参加投标。"},{"i":4,"n":"第四条","txt":"货物服务采购项目达到公开招标数额标准的，必须采用公开招标方式。因特殊情况需要采用 公开招标以外方式的，应当在采购活动开始前获得设区的市、自治州以上人民政府财政部门的批准。"},{"i":5,"n":"第五条","txt":"招标采购单位不得将应当以公开招标方式采购的货物服务化整为零或者以其他方式规避公开 招标采购。"},{"i":6,"n":"第六条","txt":"任何单位和个人不得阻挠和限制供应商自由参加货物服务招标投标活动，不得指定货物的品牌、服务的供应商和采购代理机构，以及采用其他方式非法干涉货物服务招 标投标活动。"},{"i":7,"n":"第七条","txt":"在货物服务招标投标活动中，招标采购单位工作人员、评标委员会成员及其他相关人员与供应商有利害关系的，必须回避。供应商认为上述人员与其他供应商有利害关 系的，可以申请其回避。"},{"i":8,"n":"第八条","txt":"参加政府采购货物服务投标活动的供应商(以下简称“投标人”)，应当是提供本国货物服务的本国供应 商，但法律、行政法规规定外国供应商可以参加货物服务招标投标活动的除外。 外国供应商依法参加货物服务招标投标活动的，应当按照本办法的规定执行。"},{"i":9,"n":"第九条","txt":"货物服务招标投标活动，应当有助于实现国家经济和社会发展政策目标，包括保护环境，扶持不发达地区 和少数民族地区，促进中小企业发展等。"},{"i":10,"n":"第十条","txt":"县级以上各级人民政府财政部门应当依法履行对货物服务招标投标活动的监督管理职责。"},{"i":11,"n":"第十一条","txt":"招标采购单位应当按照本办法规定组织开展货物服务招标投标活动。 采购人可以依法委托采购代理机构办理货物服务招标事宜，也可以自行组织开展货物服务招标活动，但必须符合 本办法第十二条规定的条件。 集中采购机构应当依法独立开展货物服务招标活动。其他采购代理机构应当根据采购人的委托办理货物服务招标 事宜。"},{"i":12,"n":"第十二条","txt":"采购人符合下 列条件的，可以自行组织招标： (一)具有独立承担民事责任的能力； (二)具有编制招标文件和组织招标能力，有与采购招标项目规模和复杂程度相适应的技术、经济等方面的采购 和管理人员； (三)采购人员经过省级以上人民政府财政部门组织的政府采购培训。 采购人不符合前款规定条件的，必须委托采购代理机构代理招标。"},{"i":13,"n":"第十三条","txt":"采购人委托采购代理机构招标的，应当与采购代 理机构签订委托协议，确定委托代理的事项，约定双方的权利和义务。"},{"i":14,"n":"第十四条","txt":"采用公开招标方式采购的，招标采购单位必须在财政部 门指定的政府采购信息发布媒体上发布招标公告。"},{"i":15,"n":"第十五条","txt":"采用邀请招标方式采购的，招标采购单位应当在省级以 上人民政府财政部门指定的政府采购信息媒体发布资格预审公告，公布投标人资格条件，资格预审公告的期限不得少于七个工作日。 投标人应当在资格预审公告期结束之日起三个工作日前，按公告要求提交资格证明文件。招标采购单位从评审合 格投标人中通过随机方式选择三家以上的投标入，并向其发出投标邀请书。"},{"i":16,"n":"第十六条","txt":"采用招标方式采购的，自招标文件开始发出之日起至投 标人提交投标文件截止之日止，不得少于二十日。"},{"i":17,"n":"第十七条","txt":"公开招标公告应当包括以下主要内容： (一)招标采购单位的名称、地址和联系方法； (二)招标项目的名称、数量或者招标项目的性质； (三)投标人的资格要求； (四)获取招标文件的时间、地点、方式及招标文件售价； (五)投标截止时间、开标时间及地点。"},{"i":18,"n":"第十八条","txt":"招标采购单位应当根据招标项目的特点和需求编制招标文件。招标文件包括以下内容： (一)投标邀请； (二)投标人须知(包括密封、签署、盖章要求等)； (三)投标人应当提交的资格、资信证明文件； (四)投标报价要求、投标文件编制要求和投标保证金交纳方式； (五)招标项目的技术规格、要求和数量，包括附件、图纸等； (六)合同主要条款及合同签订方式； (七)交货和提供服务的时间； (八)评标方法、评标标准和废标条款； (九)投标截止时问、开标时间及地点； (十)省级以上财政部门规定的其他事项。 招标人应当在招标文件中规定并标明实质性要求和条件。"},{"i":19,"n":"第十九条","txt":"招标采购单位应当制作纸质招标文件，也可以在财政部 门指定的网络媒体上发布电子招标文件，并应当保持两者的一致。电子招标文件与纸质招标文件具有同等法律效力。"},{"i":20,"n":"第二十条","txt":"招标采购单位可以要求投标人提交符合招标文件规定要求的备选投标方案，但应当在招标文 件中说明，并明确相应的评审标准和处理办法。"},{"i":21,"n":"第二十一条","txt":"招标文件规定的各项技术标准应当符合国家强制性标准。 招标文件不得要求或者标明特定的投标人或者产品，以及含有倾向性或者排斥潜在投标人的其他内容。"},{"i":22,"n":"第二十二条","txt":"招标采购单位可以根据需要，就招标文件征询有关专 家或者供应商的意见。"},{"i":23,"n":"第二十三条","txt":"招标文件售价应当按照弥补招标文件印制成本费用的 原则确定，不得以营利为目的，不得以招标采购金额作为确定招标文件售价依据。"},{"i":24,"n":"第二十四条","txt":"招标采购单位在发布招标公告、发出投标邀请书或者 发出招标文件后，不得擅自终止招标。"},{"i":25,"n":"第二十五条","txt":"招标采购单位根据招标采购项目的具体情况，可以组织潜在投标人现场考察或者召开开标前 答疑会，但不得单独或者分别组织只有一个投标人参加的现场考察．"},{"i":26,"n":"第二十六条","txt":"开标前，招标采购单位和有关工作人员不得向他人透露已获取招标文件的潜在投标人的名 称、数量以及可能影响公平竞争的有关招标投标的其他情况。"},{"i":27,"n":"第二十七条","txt":"招标采购单位对已发出的招标文件进行必要澄清或者 修改的，应当在招标文件要求提交投标文件截止时问十五日前，在财政部门指定的政府采购信息发布媒体上发布更正公告，并以书面形式通知所有招标文件收受人。该澄清或者修改的 内容为招标文件的组成部分。"},{"i":28,"n":"第二十八条","txt":"招标采购单位可以视采购具体情况，延长投标截止时间和开标时间，但至少应当在招标文件要求提交 投标文件的截止时间三日前，将变更时间书面通知所有招标文件收受人，并在财政部门指定的政府采购信息发布媒体上发布变更公告。"},{"i":29,"n":"第二十九条","txt":"投标人是响应招标并且符合招标文件规定资格条件和参加投标竞争的法人、其他组织或者自然人。 第三十条条 投标人应当按照招标文件的要求编制投标文件。投标文件应对招标文件提出的要求和条件作出实质性响应。 投标文件由商务部分、技术部分、价格部分和其他部分组成。"},{"i":30,"n":"第三十一条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件密封送达投标地点。招标采购单 位收到投标文件后，应当签收保存，任何单位和个人不得在开标前开启投标文件。 在招标文件要求提交投标文件的截止时间之后送达的投标文件，为无效投标文件，招标采购单位应当拒收。"},{"i":31,"n":"第三十二条","txt":"投标人在投标截止时间前，可以对所递交的投标文件进行补充、修改或者撤回，并书面通知招标采购 单位。补充、修改的内容应当按招标文件要求签署、盖章，并作为投标文件的组成部分。"},{"i":32,"n":"第三十三条","txt":"投标人根 据招标文件载明的标的采购项目实际情况，拟在中标后将中标项目的非主体、非关键性工作交由他人完成的，应当在投标文件中载明。"},{"i":33,"n":"第三十四条","txt":"两个以上供应商可以组成一个投标联合体，以一个投标人的身份投标。 以联合体形式参加投标的，联合体各方均应当符合政府采购法第二十二条第一款规定的条件。采购人根据采购项 目的特殊要求规定投标人特定条件的，联合体各方中至少应当有一方符合采购人规定的特定条件。 联合体各方之问应当签订共同投标协议，明确约定联合体各方承担的工作和相应的责任，并将共同投标协议连同 投标文件一并提交招标采购单位。联合体各方签订共同投标协议后，不得再以自己名义单独在同一项目中投标，也不得组成新的联合体参加同一项目投标。 招标采购单位不得强制投标人组成联合体共同投标，不得限制投标人之间的竞争。"},{"i":34,"n":"第三十五条","txt":"投标人之间不得相互串通投标报价，不得妨碍其他投标人的公平竞争，不得损害招标采购单位或者其 他投标人的合法权益。 投标人不得以向招标采购单位、评标委员会成员行贿或者采取其他不正当手段谋取中标。"},{"i":35,"n":"第三十六条","txt":"招标采购单位应当在招标文件中明确投标保证金的数额及交纳办法。招标采购单位规定的投标保证金 数额，不得超过采购项目概算的百分之一。 投标人投标时，应当按招标文件要求交纳投标保证金。投标保证金可以采用现金支票、银行汇票、银行保函等形 式交纳。投标人未按招标文件要求交纳投标保证金的，招标采购单位应当拒绝接收投标人的投标文件。 联合体投标的，可以由联合体中的一方或者共同提交投标保证金，以一方名义提交投标保证金的，对联合体各方 均具有约束力。"},{"i":36,"n":"第三十七条","txt":"招标采购单位应当在中标通知书发出后五个工作日内退还未中标供应商的投标保证金，在采购合同签订后五个工作日内退还中标供应商的投标保证金。招标采购单位逾 期退还投标保证金的，除应当退还投标保证金本金外，还应当按商业银行同期贷款利率上浮20％后的利率支付资金占用费。"},{"i":37,"n":"第三十八条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开送行；开标地点应当为招 标文件中预先确定的地点。 招标采购单位在开标前，应当通知同级人民政府财政部门及有关部门。财政部门及有关部门可以视情况到现场监 督开标活动。"},{"i":38,"n":"第三十九条","txt":"开标由招标采购单位主持，采购人、投标人和有关方 面代表参加。"},{"i":39,"n":"第四十条","txt":"开标时，应当由投标人或者其推选的代表检查投标文件的密封情况，也可以由招标人委托的 公证机构检查并公证；经确认无误后，由招标工作人员当众拆封，宣读投标人名称、投标价格、价格折扣、招标文件允许提供的备选投标方案和投标文件的其他主要内容。 未宣读的投标价格、价格折扣和招标文件允许提供的备选投标方案等实质内容，评标时不予承认．"},{"i":40,"n":"第四十一条","txt":"开标时，投标文件中开标一览表(报价表)内容与投标文件中明细表内容不一致的，以开标一览表(报价表)为准。 投标文件的大写金额和小写金额不一致的，以大写金额为准；总价金额与按单价汇总金额不一致的，以单 价金额计算结果为准；单价金额小数点有明显错位的，应以总价为准，并修改单价；对不同文字文本投标文件的解释发生异议的，以中文文本为准。"},{"i":41,"n":"第四十二条","txt":"开标过程应当由招标采购单位指定专人负责记录，并存档备查。"},{"i":42,"n":"第四十三条","txt":"投标截止时问结束后参加投标的供应商不足三家的，除采购任务取消情形外，招标采购单位 应当报告设区的市、自治州以上人民政府财政部门，由财政部门按照以下原则处理： (一)招标文件没有不合理条款、招标公告时间及程序符合规定的，同意采取竞争性谈判、询价或者单一来源方 式采购； (二)招标文件存在不合理条款的，招标公告时间及程序不符合规定的，应予废标，并责成招标采购单位依法重 新招标。 在评标期间，出现符合 专业条件的供应商或者对招标文件作出实质响应的供应商不足三家情形的，可以比照前款规定执行。"},{"i":43,"n":"第四十四条","txt":"评标工作由招标采购单位负责组织，具体评标事务由 招标采购单位依法组建的评标委员会负责，并独立履行下列职责： (一)审查投标文件是否符合招标文件要求，并作出评价： (二)要求投标供应商对投标文件有关事项作出解释或者澄清： (三)推荐中标候选供应商名单，或者受采购人委托按照事先确定的办法直接确定中标供应商： (四)向招标采购单位或者有关部门报告非法干预评标工作的行为。"},{"i":44,"n":"第四十五条","txt":"评标委员会由采购人代表和有关技术、经济等方面的专家组 成，成员人数应当为五人以上单数。其中，技术、经济等方面的专家不得少于成员总数的三分之二。采购数额在300万元以上、技术复杂的项目，评标委员会中技术、经济方面的专 家人数应当为五人以上单数。 招标采购单位就招标文件征询过意见的专家，不得再作为评标专家参加评标。采购人不得以专家身份参与本部门 或者本单位采购项目的评标。采购代理机构工作人员不得参加由本机构代理的政府采购项目的评标。 评标委员会成员名单原则上应在开标前确定，并在招标结果确定前保密。"},{"i":45,"n":"第四十六条","txt":"评标专家应当 熟悉政府采购、招标投标的相关政策法规，熟悉市场行情，有良好的职业道德，遵守招标纪律，从事相关领域工作满八年并具有高级职称或者具有同等专业水平。"},{"i":46,"n":"第四十七条","txt":"各级人民政府财政部门应当对专家实行动态管理。"},{"i":47,"n":"第四十八条","txt":"招标采购单位应当从同级或上一级财政部门设立的政府采购评审专家库中，通过随机方式抽 取评标专家． 招标采购机构对技术复杂、专业尾极强的项目，通过随机方式难以确定合适评标专家的，经竣箧黄帝．自治州以 上人民政府财政部门同意，可以采取选择性方式确定评标专家。"},{"i":48,"n":"第四十九条","txt":"评标委员会成员应当蠡行下列义务： (一)遵纪守法，客观、公正、廉洁地履行职责； (二)按照招标文件规定的评标方法和评标标准进行评标，对评审意见承担个人责任； (三)对评标过程和结果，以及供应商的商业秘密保密； (四)参与评标报告的起草； (五)配合财政部门的投诉处理工作： (六)配合招标采购单位答复投标供应商提出的质疑。"},{"i":49,"n":"第五十条","txt":"货物服务招标采购的评标方法分为最低评标价法、综合评分法和性价比法。"},{"i":50,"n":"第五十一条","txt":"最低评标价 法，是指以价格为主要因素确定中标候选供应商的评标方法，即在全部满足招标文件实质性要求前提下，依据统一的价格要素评定最低报价，以提出最低报价的投标人作为中标候选供 应商或者中标供应商的评标方法。 最低评标价法适用于标准定制商品及通用服务项目。"},{"i":51,"n":"第五十二条","txt":"综合评分法，是指在最大限度地满足招标文件实质性要求前提下，按照招标文件中规定的各 项因素进行综合评审后，以评标总得分最高的投标人作为中标候选供应商或者中标供应商的评标方法。 综合评分的主要因素是：价格、技术、财务状况、信誉、业绩、服务、对招标文件的响应程度，以及相应的眨重 或者权值等。上述因素应当在招标文件中事先规定。 评标时，评标委员会各成员应当独立对每个有效投标人的标书进行评价、打分，然后汇总每个投标人每项评分因 素的得分。 采用综合评分法的，货物项目的价格分值占总分值的比重(即权值)为百分之三十至百分之六十；服务项目的价 格分值占总分值的比重(印权值)为百分之十至百分之三十。执行统一价格标准的服务项目，其价格不列为评分因素。有特殊情况需要调整的，应当经同级人民政府财政部门批准。 评标总得分=F1×A1+F2×A2+……+Fn×An F1、F2……Fn分别为各项评分因素的汇总得分："},{"i":52,"n":"第五十三条","txt":"性价比法，是指按照要求对投标文件进行评审后，计算出每个有效投标人除价格因素以外的 其他各项评分因素(包括技术、财务状况、信誉、业绩、服务、对招标文件的响应程度等)的汇总得分，并除以该投标人的投标报价，以商数(评标总得分)最高的投标人为中标候选 供应商或者中标供应商的评标方法。 评标总得分=B／N B为投标人的综合得分，B=F1xA1+F2×A2+……+Fn×An，其中：F1、F2……Fn分别为 除价格因素以外的其他各项评分因素的汇总得分；A1、A2．……An分别为除价格因素以外的其他各项评分因素所占的权重(A1+A2+……+An=1)。 N为投标人的投标报价。"},{"i":53,"n":"第五十四条","txt":"评标应当遵循下列工作程序： (一)投标文件初审。初审分为资格性检查和符合性检查。 1、资格性检查。依据法律法规和招标文件的规定，对投标文件中的资格证明、投标保证金等进行审查，以确定 投标供应商是否具备投标资格。 2、符合性检查。依据招标文件的规定，从投标文件的有效性、完整性和对招标文件的响应程度进行审查，以确 定是否对招标文件的实质性要求作出响应。 (二)澄清有关问题。对投标文件中含义不明确、同类问题表述不一致或者有明显文字和计算错误的内容，评标 委员会可以书面形式(应当由评标委员会专家签字)要求投标人作出必要的澄清、说明或者纠正。投标人的澄清、说明或者补正应当采用书面形式，由其授权的代表签字，并不得超出 投标文件的范围或者改变投标文件的实质性内容。 (三)比较与评价。按 招标文件中规定的评标方法和标准，对资格性检查和符合性检查合格的投标文件进行商务和技术评估，综合比较与评价。 (四)"},{"i":54,"n":"第五十五条","txt":"在评标中，不 得改变招标文件中规定的评标标准、方法和中标条件。"},{"i":55,"n":"第五十六条","txt":"投标文件属下 列情况之一的，应当在资格性、符合性检查时按照无效投标处理： (一)应交未交投标保证金的； (二)未按照招标文件规定要求密封、签署、盖章的； (三)不具备招标文件中规定资格要求的； (四)不符合法律、法规和招标文件中规定的其他实质性要求的。"},{"i":56,"n":"第五十七条","txt":"在招标采购 中，有政府采购法第三十六条第一款第(二)至第(四)项规定情形之一的，招标采购单位应当予以废标，并将废标理由通知所有投标供应商。 废标后，除采购任务取消情形外，招标采购单位应当重新组织招标。需要采取其他采购方式的，应当在采购活动 开始前获得设区的市、自治州以上人民政府财政部门的批准。"},{"i":57,"n":"第五十八条","txt":"招标采购单位应当采取必要措施，保证评标在严格保密的情况下进行。 任何单位和个人不得非法干预、影响评标办法的确定，以及评标过程和结果。"},{"i":58,"n":"第五十九条","txt":"采购代理机构 应当在评标结束后五个工作日内将评标报告送采购人． 采购人应当在收到评标报告后五个工作日内，按照评标报告中推荐的中标候选供应商顺序确定中标供应商；也可 以事先授权评标委员会直接确定中标供应商。 采购人自行组织招标的，应当在评标结束后五个工作日内确定中标供应商。"},{"i":59,"n":"第六十条","txt":"中标供应商因不可抗力或者自身原因不能履行政府采购合同的，采购人可以与排位在中标供 应商之后第一位的中标候选供应商签订政府采购合同，以此类推。"},{"i":60,"n":"第六十一条","txt":"在确定中标供 应商前，招标采购单位不得与投标供应商就投标价格、投标方案等实质性内容进行谈判。"},{"i":61,"n":"第六十二条","txt":"中标供应商确 定后，中标结果应当在财政部门指定的政府采购信息发布媒体上公告。公告内容应当包括招标项目名称、中标供应商名单、评标委员会成员名单、招标采购单位的名称和电话。 在发布公告的同时，招标采购单位应当向中标供应商发出中标通知书，中标通知书对采购人和中标供应商具有同 等法律效力。 中标通知书发出后，采购人改变中标结果，或者中标供应商放弃中标，应当承担相应的法律责任。"},{"i":62,"n":"第六十三条","txt":"投标供应商对 中标公告有异议的，应当在中标公告发布之日起七个工作日内，以书面形式向招标采购单位提出质疑。招标采购单位应当在收到投标供应商书面质疑后七个工作日内，对质疑内容作出 答复。 质疑供应商对招标采购单位的答复不满意或者招标采购单位未在规定时间内答复的，可以在答复期满后十五个工 作日内按有关规定，向同级人民政府财政部门投诉．财政部门应当在收到投诉后三十个工作日内，对投诉事项作出处理决定。 处理投诉事项期间，财政部门可以视具体情况书面通知招标采购单位暂停签订合同等活动，但暂停时间最长不得 超过三十曰。"},{"i":63,"n":"第六十四条","txt":"采购人或者采购代理机构应当自中标通知书发出之日起三十日内，按照招标文件和中标供应 商投标文件的约定，与中标供应商签订书面合同。所签订的合同不得对招标文件和中标供应商投标文件作实质性修改。 招标采购单位不得向中标供应商提出任何不合理的要求，作为签订合同的条件，不得与中标供应商私下订立背离 合同实质性内容的协议。"},{"i":64,"n":"第六十五条","txt":"采购人或者采购代理机构应当自采购合同签订之日起七个工作日内，按照有关规定将采购合 同副本报同级人民政府财政部门备案。"},{"i":65,"n":"第六十六条","txt":"法律、行政法 规规定应当办理批准、登记等手续后生效的合同，依照其规定。"},{"i":66,"n":"第六十七条","txt":"招标采购单位应当建立真实完整的招标采购档案，妥善保管每项采购活动的采购文件，并不得伪造、变造、隐匿或者销毁。采购文件的保存期限为从采购结束之日起至 少保存十五年。"},{"i":67,"n":"第六十八条","txt":"招标采购单位有下列情形之一的，责令限期改正，给予警告，可以按照有关法律规定并处罚款，对直 接负责的主管人员和其他直接责任人员，由其行政主管部门或者有关机关依法给予处分，并予通报： (一)应当采用公开招标方式而擅自采用其他方式采购的； (二)应当在财政部门指定的政府采购信息发布媒体上公告信息而未公告的； (三)将必须进行招标的项目化整为零或者以其他任何方式规避招标的； (四)以不合理的要求限制或者排斥潜在投标供应商，对潜在投标供应商实行差别待遇或者歧视待遇，或者招标 文件指定特定的供应商、含有倾向性或者排斥潜在投标供应商的其他内容的： (五)评标委员会组成不符合本办法规定的； (六)无正当理由不按照依法推荐的中标候选供应商顺序确定中标供应商，或者在评标委员会依法推荐的中标候 选供应商以外确定中标供应商的； (七)在招标过程中与投标人进行协商谈判，或者不按照招标文件和中标供应商的投标文件确"},{"i":68,"n":"第六十九条","txt":"招标采购单位及其工作人员有下列情形之一，构成犯罪的，依法追究刑事责任：尚不构成犯罪的，按 照有关法律规定处以罚款，有违法所得的，并处没收违法所得，由其行政主管部门或者有关机关依法给予处分，并予通报： (一)与投标人恶意串通的； (二)在采购过程中接受贿赂或者获取其他不正当利益的； (三)在有关部门依法实施的监督检查中提供虚假情况的； (四)开标前泄露已获取招标文件的潜在投标人的名称、数量、标底或者其他可能影响公平竞争的有关招标投标 情况的。"},{"i":69,"n":"第七十条","txt":"采购代理机构有本办法第六十八条、第六十九条 违法行为之一，情节严重的，可以取消其政府采购代理资格，并予以公告．"},{"i":70,"n":"第七十一条","txt":"有本办法第六十八条、第六十九条违法行为之一，并且影响或者可能影响中标结果的，应当按照下列情况分别处理： (一)未确定中标候选供应商的，终止招标活动，依法重新招标； (二)中标候选供应商已经确定但采购合同尚未履行的，撤销合同，从中标候选供应商中按顺序另行确定中标供 应商； (三)采购合同已经履行的，给采购人、投标人造成损失的，由责任人承担赔偿责任。"},{"i":71,"n":"第七十二条","txt":"采购人对应当实行集中采购的政府采购项目不委托集中采购机构进行招标的，或者委托不具备政府采 购代理资格的中介机构办理政府采购招标事务的，责令改正；拒不改正的，停止按预算向其支付资金，由其上级行政主管部门或者有关机关依法给予其直接负责的主管人员和其他直接 责任人员处分。"},{"i":72,"n":"第七十三条","txt":"招标采购单位违反有关规定隐匿、销毁应当保存的招标、投标过程中的有关文件或者伪造、变造招 标、投标过程中的有关文件的，处以二万元以上十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员，由其行政主管部门或者有关机关依法给予处分，并予通报：构成犯 罪的，依法追究刑事责任。"},{"i":73,"n":"第七十四条","txt":"投标人有下列情形之一的，处以政府采购项目中标金额千分之五以上千分之十以下的罚款，列入不良 行为记录名单，在一至三年内禁止参加政府采购活动，并予以公告，有违法所得的，并处没收违法所得，情节严重的，由工商行政管理机关吊销营业执照；构成犯罪的，依法追究刑事 责任： (一)提供虚假材料谋取中标的； (二)采取不正当手段诋毁、排挤其他投标人的； (三)与招标采购单位、其他投标人恶意串通的； (四)向招标采购单位行贿或者提供其他不正当利益的； (五)在招标过程中与招标采购单位进行协商谈判、不按照招标文件和中标供应商的投标文件订立合同，或者与 采购人另行订立背离合同实质性内容的协议的； (六)拒绝有关部门监督检查或者提供虚假情况的。 投标人有前款第(一)至(五)项情形之一的，中标无效。"},{"i":74,"n":"第七十五条","txt":"中标供应商有下列情形之一的，招标采购单位不予退还其交纳的投标保证金；情节严重的，由财政部门将其列入不良行为记录名单，在一至三年内禁止参加政府采购活 动，并予以通报： (一)中标后无正当理由不与采购人或者采购代理机构签订合同的； (二)将中标项目转让给他人，或者在投标文件中未说明，且未经采购招标机构同意，将中标项目分包给他人 的； (三)拒绝履行合同义务的。"},{"i":75,"n":"第七十六条","txt":"政府采购当事人有本办法第六十八条、第六十九条、第七十四条、第七十五条违法行为之一，给他人 造成损失的，应当依照有关民事法律规定承担民事责任。"},{"i":76,"n":"第七十七条","txt":"评标委员会成员有下列行为之一的，责令改正，给予警告，可以并处一千元以下的罚款： (一)明知应当回避而 未主动回避的； (二)在知道自己为评标委员会成员身份后至评标结束前的时段内私下接触投标供应商的； (三)在评标过程中擅离职守，影响评标程序正常进行的； (四)在评标过程中有明显不合理或者不正当倾向性的； (五)未按招标文件规定的评标方法和标准进行评标的。 上述行为影响中标结果的，中标结果无效。"},{"i":77,"n":"第七十八条","txt":"评标委员会成员或者与评标活动有关的工作人员有下列行为之一的，给予警告，没收违法所得，可以并处三千元以上五万元以下的罚款；对评标委员会成员取消评标委 员会成员资格，不得再参加任何政府采购招标项目的评标，并在财政部门指定的政府采购信息发布媒体上予以公告；构成犯罪的，依法追究刑事责任： (一)收受投标人、其他利害关系人的财物或者其他不正当利益的； (二)泄露有关投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况的。"},{"i":78,"n":"第七十九条","txt":"任何单位或者个人非法干预、影响评标的过程或者结果的，责令改正；由该单位、个人的上级行政主管部门或者有关机关给予单位责任人或者个人处分。"},{"i":79,"n":"第八十条","txt":"财政部门工作人员在实施政府采购监督检查中违反规定滥用职权、玩忽职守、徇私舞弊的，依法给予行 政处分；构成犯罪的，依法追究刑事责任。"},{"i":80,"n":"第八十一条","txt":"财政部门对投标人的投诉无故逾期未作处理的，依法给予直接负责的主管人员和其他直接责任人员行政处分。"},{"i":81,"n":"第八十二条","txt":"有本办法规定的中标无效情形的，由同级或其上级财政部门认定中标无效。中标无效的，应当依照本 办法规定从其他中标人或者中标候选人中重新确定，或者依照本办法重新进行招标。"},{"i":82,"n":"第八十三条","txt":"本办法所规定的行政处罚，由县级以上人民政府财政部门负责实施。"},{"i":83,"n":"第八十四条","txt":"政府采购当事人对行政处罚不服的，可以依法申请行政复议，或者直接向人民法院提起行政诉讼。逾 期未申请复议，也未向人民法院起诉，又不履行行政处罚决定的，由作出行政处罚决定的机关申请人民法院强制执行。"},{"i":84,"n":"第八十五条","txt":"政府采购货物服务可以实行协议供货采购和定点采购，但协议供货采购和定点供应商必须通过公开招标方式确定；因特殊情况需要采用公开招标以外方式确定的，应当 获得省级以上人民政府财政部门批准。 协议供货采购和定点采购的管理办法，由财政部另行规定。"},{"i":85,"n":"第八十六条","txt":"政府采购货物中的进口机电产品进行招标投标的，按照国家有关办法执行。"},{"i":86,"n":"第八十七条","txt":"使用国际组织和外国政府贷款进行的政府采购货物和服务招标，贷款方或者资金提供方与中方达成的 协议对采购的具体条件另有规定的，可以适用其规定，但不得损害国家利益和社会公共利益。"},{"i":87,"n":"第八十八条","txt":"对因严重自然灾害和其他不可抗力事件所实施的紧急采购和涉及国家安金和秘密的采购，不适用本办法。"},{"i":88,"n":"第八十九条","txt":"本办法由财政部负责解释。 各省、自治区、直辖市人民政府财政部门可以根据本办法制定具体实施办法。"},{"i":89,"n":"第九十条","txt":"本办法自2004年9月11日起施行。财政部1999年6月24日颁布实施的《政府采购招标投标 管理暂行办法》(财预字[1999]363号)同时废止。"}],"zhengfucaigouhuowuhefuwuzhaobiaotoubiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范政府采购当事人的采购行为，加强对政府采购货物和服务招标投标活动的监督管理，维护国家利益、社会公共利益和政府采购招标投标活动当事人的合法权益，依据《中华人民共和国政府采购法》（以下简称政府采购法）、《中华人民共和国政府采购法实施条例》（以下简称政府采购法实施条例）和其他有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内开展政府采购货物和服务（以下简称货物服务）招标投标活动。"},{"i":3,"n":"第三条","txt":"货物服务招标分为公开招标和邀请招标。 公开招标，是指采购人依法以招标公告的方式邀请非特定的供应商参加投标的采购方式。 邀请招标，是指采购人依法从符合相应资格条件的供应商中随机抽取3家以上供应商，并以投标邀请书的方式邀请其参加投标的采购方式。"},{"i":4,"n":"第四条","txt":"属于地方预算的政府采购项目,省、自治区、直辖市人民政府根据实际情况，可以确定分别适用于本行政区域省级、设区的市级、县级公开招标数额标准。"},{"i":5,"n":"第五条","txt":"采购人应当在货物服务招标投标活动中落实节约能源、保护环境、扶持不发达地区和少数民族地区、促进中小企业发展等政府采购政策。"},{"i":6,"n":"第六条","txt":"采购人应当按照行政事业单位内部控制规范要求，建立健全本单位政府采购内部控制制度，在编制政府采购预算和实施计划、确定采购需求、组织采购活动、履约验收、答复询问质疑、配合投诉处理及监督检查等重点环节加强内部控制管理。 采购人不得向供应商索要或者接受其给予的赠品、回扣或者与采购无关的其他商品、服务。"},{"i":7,"n":"第七条","txt":"采购人应当按照财政部制定的《政府采购品目分类目录》确定采购项目属性。按照《政府采购品目分类目录》无法确定的，按照有利于采购项目实施的原则确定。"},{"i":8,"n":"第八条","txt":"采购人委托采购代理机构代理招标的，采购代理机构应当在采购人委托的范围内依法开展采购活动。 采购代理机构及其分支机构不得在所代理的采购项目中投标或者代理投标，不得为所代理的采购项目的投标人参加本项目提供投标咨询。"},{"i":9,"n":"第九条","txt":"未纳入集中采购目录的政府采购项目，采购人可以自行招标，也可以委托采购代理机构在委托的范围内代理招标。 采购人自行组织开展招标活动的，应当符合下列条件： （一）有编制招标文件、组织招标的能力和条件； （二）有与采购项目专业性相适应的专业人员。"},{"i":10,"n":"第十条","txt":"采购人应当对采购标的的市场技术或者服务水平、供应、价格等情况进行市场调查，根据调查情况、资产配置标准等科学、合理地确定采购需求，进行价格测算。"},{"i":11,"n":"第十一条","txt":"采购需求应当完整、明确，包括以下内容： （一）采购标的需实现的功能或者目标，以及为落实政府采购政策需满足的要求； （二）采购标的需执行的国家相关标准、行业标准、地方标准或者其他标准、规范； （三）采购标的需满足的质量、安全、技术规格、物理特性等要求； （四）采购标的的数量、采购项目交付或者实施的时间和地点； （五）采购标的需满足的服务标准、期限、效率等要求； （六）采购标的的验收标准； （七）采购标的的其他技术、服务等要求。"},{"i":12,"n":"第十二条","txt":"采购人根据价格测算情况，可以在采购预算额度内合理设定最高限价，但不得设定最低限价。"},{"i":13,"n":"第十三条","txt":"公开招标公告应当包括以下主要内容： （一）采购人及其委托的采购代理机构的名称、地址和联系方法； （二）采购项目的名称、预算金额，设定最高限价的，还应当公开最高限价； （三）采购人的采购需求； （四）投标人的资格要求； （五）获取招标文件的时间期限、地点、方式及招标文件售价； （六）公告期限； （七）投标截止时间、开标时间及地点； （八）采购项目联系人姓名和电话。"},{"i":14,"n":"第十四条","txt":"采用邀请招标方式的，采购人或者采购代理机构应当通过以下方式产生符合资格条件的供应商名单，并从中随机抽取3家以上供应商向其发出投标邀请书： （一）发布资格预审公告征集； （二）从省级以上人民政府财政部门（以下简称财政部门）建立的供应商库中选取； （三）采购人书面推荐。 采用前款第一项方式产生符合资格条件供应商名单的，采购人或者采购代理机构应当按照资格预审文件载明的标准和方法，对潜在投标人进行资格预审。 采用第一款第二项或者第三项方式产生符合资格条件供应商名单的，备选的符合资格条件供应商总数不得少于拟随机抽取供应商总数的两倍。 随机抽取是指通过抽签等能够保证所有符合资格条件供应商机会均等的方式选定供应商。随机抽取供应商时，应当有不少于两名采购人工作人员在场监督，并形成书面记录，随采购文件一并存档。 投标邀请书应当同时向所有受邀请的供应商发出。"},{"i":15,"n":"第十五条","txt":"资格预审公告应当包括以下主要内容： （一）本办法第十三条第一至四项、第六项和第八项内容； （二）获取资格预审文件的时间期限、地点、方式； （三）提交资格预审申请文件的截止时间、地点及资格预审日期。"},{"i":16,"n":"第十六条","txt":"招标公告、资格预审公告的公告期限为5个工作日。公告内容应当以省级以上财政部门指定媒体发布的公告为准。公告期限自省级以上财政部门指定媒体最先发布公告之日起算。"},{"i":17,"n":"第十七条","txt":"采购人、采购代理机构不得将投标人的注册资本、资产总额、营业收入、从业人员、利润、纳税额等规模条件作为资格要求或者评审因素，也不得通过将除进口货物以外的生产厂家授权、承诺、证明、背书等作为资格要求，对投标人实行差别待遇或者歧视待遇。"},{"i":18,"n":"第十八条","txt":"采购人或者采购代理机构应当按照招标公告、资格预审公告或者投标邀请书规定的时间、地点提供招标文件或者资格预审文件，提供期限自招标公告、资格预审公告发布之日起计算不得少于5个工作日。提供期限届满后，获取招标文件或者资格预审文件的潜在投标人不足3家的，可以顺延提供期限，并予公告。 公开招标进行资格预审的，招标公告和资格预审公告可以合并发布，招标文件应当向所有通过资格预审的供应商提供。"},{"i":19,"n":"第十九条","txt":"采购人或者采购代理机构应当根据采购项目的实施要求，在招标公告、资格预审公告或者投标邀请书中载明是否接受联合体投标。如未载明，不得拒绝联合体投标。"},{"i":20,"n":"第二十条","txt":"采购人或者采购代理机构应当根据采购项目的特点和采购需求编制招标文件。招标文件应当包括以下主要内容： （一）投标邀请； （二）投标人须知（包括投标文件的密封、签署、盖章要求等）； （三）投标人应当提交的资格、资信证明文件； （四）为落实政府采购政策，采购标的需满足的要求，以及投标人须提供的证明材料； （五）投标文件编制要求、投标报价要求和投标保证金交纳、退还方式以及不予退还投标保证金的情形； （六）采购项目预算金额，设定最高限价的，还应当公开最高限价； （七）采购项目的技术规格、数量、服务标准、验收等要求，包括附件、图纸等； （八）拟签订的合同文本； （九）货物、服务提供的时间、地点、方式； （十）采购资金的支付方式、时间、条件； （十一）评标方法、评标标准和投标无效情形； （十二）投标有效期； （十三）投标截止时间、开标时间及地点； （十四）采购代理机构代理费用的收取标准和方式； （十"},{"i":21,"n":"第二十一条","txt":"采购人或者采购代理机构应当根据采购项目的特点和采购需求编制资格预审文件。资格预审文件应当包括以下主要内容： （一）资格预审邀请； （二）申请人须知； （三）申请人的资格要求； （四）资格审核标准和方法； （五）申请人应当提供的资格预审申请文件的内容和格式； （六）提交资格预审申请文件的方式、截止时间、地点及资格审核日期； （七）申请人信用信息查询渠道及截止时点、信用信息查询记录和证据留存的具体方式、信用信息的使用规则等内容； （八）省级以上财政部门规定的其他事项。 资格预审文件应当免费提供。"},{"i":22,"n":"第二十二条","txt":"采购人、采购代理机构一般不得要求投标人提供样品，仅凭书面方式不能准确描述采购需求或者需要对样品进行主观判断以确认是否满足采购需求等特殊情况除外。 要求投标人提供样品的，应当在招标文件中明确规定样品制作的标准和要求、是否需要随样品提交相关检测报告、样品的评审方法以及评审标准。需要随样品提交检测报告的，还应当规定检测机构的要求、检测内容等。 采购活动结束后，对于未中标人提供的样品，应当及时退还或者经未中标人同意后自行处理；对于中标人提供的样品，应当按照招标文件的规定进行保管、封存，并作为履约验收的参考。"},{"i":23,"n":"第二十三条","txt":"投标有效期从提交投标文件的截止之日起算。投标文件中承诺的投标有效期应当不少于招标文件中载明的投标有效期。投标有效期内投标人撤销投标文件的，采购人或者采购代理机构可以不退还投标保证金。"},{"i":24,"n":"第二十四条","txt":"招标文件售价应当按照弥补制作、邮寄成本的原则确定，不得以营利为目的，不得以招标采购金额作为确定招标文件售价的依据。"},{"i":25,"n":"第二十五条","txt":"招标文件、资格预审文件的内容不得违反法律、行政法规、强制性标准、政府采购政策，或者违反公开透明、公平竞争、公正和诚实信用原则。 有前款规定情形，影响潜在投标人投标或者资格预审结果的，采购人或者采购代理机构应当修改招标文件或者资格预审文件后重新招标。"},{"i":26,"n":"第二十六条","txt":"采购人或者采购代理机构可以在招标文件提供期限截止后，组织已获取招标文件的潜在投标人现场考察或者召开开标前答疑会。 组织现场考察或者召开答疑会的，应当在招标文件中载明，或者在招标文件提供期限截止后以书面形式通知所有获取招标文件的潜在投标人。"},{"i":27,"n":"第二十七条","txt":"采购人或者采购代理机构可以对已发出的招标文件、资格预审文件、投标邀请书进行必要的澄清或者修改，但不得改变采购标的和资格条件。澄清或者修改应当在原公告发布媒体上发布澄清公告。澄清或者修改的内容为招标文件、资格预审文件、投标邀请书的组成部分。 澄清或者修改的内容可能影响投标文件编制的，采购人或者采购代理机构应当在投标截止时间至少15日前，以书面形式通知所有获取招标文件的潜在投标人；不足15日的，采购人或者采购代理机构应当顺延提交投标文件的截止时间。 澄清或者修改的内容可能影响资格预审申请文件编制的，采购人或者采购代理机构应当在提交资格预审申请文件截止时间至少3日前，以书面形式通知所有获取资格预审文件的潜在投标人；不足3日的，采购人或者采购代理机构应当顺延提交资格预审申请文件的截止时间。"},{"i":28,"n":"第二十八条","txt":"投标截止时间前，采购人、采购代理机构和有关人员不得向他人透露已获取招标文件的潜在投标人的名称、数量以及可能影响公平竞争的有关招标投标的其他情况。"},{"i":29,"n":"第二十九条","txt":"采购人、采购代理机构在发布招标公告、资格预审公告或者发出投标邀请书后，除因重大变故采购任务取消情况外，不得擅自终止招标活动。 终止招标的，采购人或者采购代理机构应当及时在原公告发布媒体上发布终止公告，以书面形式通知已经获取招标文件、资格预审文件或者被邀请的潜在投标人，并将项目实施情况和采购任务取消原因报告本级财政部门。已经收取招标文件费用或者投标保证金的，采购人或者采购代理机构应当在终止采购活动后5个工作日内，退还所收取的招标文件费用和所收取的投标保证金及其在银行产生的孳息。"},{"i":30,"n":"第三十条","txt":"投标人，是指响应招标、参加投标竞争的法人、其他组织或者自然人。"},{"i":31,"n":"第三十一条","txt":"采用最低评标价法的采购项目，提供相同品牌产品的不同投标人参加同一合同项下投标的，以其中通过资格审查、符合性审查且报价最低的参加评标；报价相同的，由采购人或者采购人委托评标委员会按照招标文件规定的方式确定一个参加评标的投标人，招标文件未规定的采取随机抽取方式确定，其他投标无效。 使用综合评分法的采购项目，提供相同品牌产品且通过资格审查、符合性审查的不同投标人参加同一合同项下投标的，按一家投标人计算，评审后得分最高的同品牌投标人获得中标人推荐资格；评审得分相同的，由采购人或者采购人委托评标委员会按照招标文件规定的方式确定一个投标人获得中标人推荐资格，招标文件未规定的采取随机抽取方式确定，其他同品牌投标人不作为中标候选人。 非单一产品采购项目，采购人应当根据采购项目技术构成、产品价格比重等合理确定核心产品，并在招标文件中载明。多家投标人提供的核心产品品牌相同的，按前两款规定处理。"},{"i":32,"n":"第三十二条","txt":"投标人应当按照招标文件的要求编制投标文件。投标文件应当对招标文件提出的要求和条件作出明确响应。"},{"i":33,"n":"第三十三条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件密封送达投标地点。采购人或者采购代理机构收到投标文件后，应当如实记载投标文件的送达时间和密封情况，签收保存，并向投标人出具签收回执。任何单位和个人不得在开标前开启投标文件。 逾期送达或者未按照招标文件要求密封的投标文件，采购人、采购代理机构应当拒收。"},{"i":34,"n":"第三十四条","txt":"投标人在投标截止时间前，可以对所递交的投标文件进行补充、修改或者撤回，并书面通知采购人或者采购代理机构。补充、修改的内容应当按照招标文件要求签署、盖章、密封后，作为投标文件的组成部分。"},{"i":35,"n":"第三十五条","txt":"投标人根据招标文件的规定和采购项目的实际情况，拟在中标后将中标项目的非主体、非关键性工作分包的，应当在投标文件中载明分包承担主体，分包承担主体应当具备相应资质条件且不得再次分包。"},{"i":36,"n":"第三十六条","txt":"投标人应当遵循公平竞争的原则，不得恶意串通，不得妨碍其他投标人的竞争行为，不得损害采购人或者其他投标人的合法权益。 在评标过程中发现投标人有上述情形的，评标委员会应当认定其投标无效，并书面报告本级财政部门。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，视为投标人串通投标，其投标无效： （一）不同投标人的投标文件由同一单位或者个人编制； （二）不同投标人委托同一单位或者个人办理投标事宜； （三）不同投标人的投标文件载明的项目管理成员或者联系人员为同一人； （四）不同投标人的投标文件异常一致或者投标报价呈规律性差异； （五）不同投标人的投标文件相互混装； （六）不同投标人的投标保证金从同一单位或者个人的账户转出。"},{"i":38,"n":"第三十八条","txt":"投标人在投标截止时间前撤回已提交的投标文件的，采购人或者采购代理机构应当自收到投标人书面撤回通知之日起５个工作日内，退还已收取的投标保证金，但因投标人自身原因导致无法及时退还的除外。 采购人或者采购代理机构应当自中标通知书发出之日起5个工作日内退还未中标人的投标保证金，自采购合同签订之日起5个工作日内退还中标人的投标保证金或者转为中标人的履约保证金。 采购人或者采购代理机构逾期退还投标保证金的，除应当退还投标保证金本金外，还应当按中国人民银行同期贷款基准利率上浮20％后的利率支付超期资金占用费，但因投标人自身原因导致无法及时退还的除外。"},{"i":39,"n":"第三十九条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间进行。开标地点应当为招标文件中预先确定的地点。 采购人或者采购代理机构应当对开标、评标现场活动进行全程录音录像。录音录像应当清晰可辨，音像资料作为采购文件一并存档。"},{"i":40,"n":"第四十条","txt":"开标由采购人或者采购代理机构主持，邀请投标人参加。评标委员会成员不得参加开标活动。"},{"i":41,"n":"第四十一条","txt":"开标时，应当由投标人或者其推选的代表检查投标文件的密封情况；经确认无误后，由采购人或者采购代理机构工作人员当众拆封，宣布投标人名称、投标价格和招标文件规定的需要宣布的其他内容。 投标人不足3家的，不得开标。"},{"i":42,"n":"第四十二条","txt":"开标过程应当由采购人或者采购代理机构负责记录，由参加开标的各投标人代表和相关工作人员签字确认后随采购文件一并存档。 投标人代表对开标过程和开标记录有疑义，以及认为采购人、采购代理机构相关工作人员有需要回避的情形的，应当场提出询问或者回避申请。采购人、采购代理机构对投标人代表提出的询问或者回避申请应当及时处理。 投标人未参加开标的，视同认可开标结果。"},{"i":43,"n":"第四十三条","txt":"公开招标数额标准以上的采购项目，投标截止后投标人不足3家或者通过资格审查或符合性审查的投标人不足3家的，除采购任务取消情形外，按照以下方式处理： （一）招标文件存在不合理条款或者招标程序不符合规定的，采购人、采购代理机构改正后依法重新招标； （二）招标文件没有不合理条款、招标程序符合规定，需要采用其他采购方式采购的，采购人应当依法报财政部门批准。"},{"i":44,"n":"第四十四条","txt":"公开招标采购项目开标结束后，采购人或者采购代理机构应当依法对投标人的资格进行审查。 合格投标人不足3家的，不得评标。"},{"i":45,"n":"第四十五条","txt":"采购人或者采购代理机构负责组织评标工作，并履行下列职责： （一）核对评审专家身份和采购人代表授权函，对评审专家在政府采购活动中的职责履行情况予以记录，并及时将有关违法违规行为向财政部门报告； （二）宣布评标纪律； （三）公布投标人名单，告知评审专家应当回避的情形； （四）组织评标委员会推选评标组长，采购人代表不得担任组长； （五）在评标期间采取必要的通讯管理措施，保证评标活动不受外界干扰； （六）根据评标委员会的要求介绍政府采购相关政策法规、招标文件； （七）维护评标秩序，监督评标委员会依照招标文件规定的评标程序、方法和标准进行独立评审，及时制止和纠正采购人代表、评审专家的倾向性言论或者违法违规行为； （八）核对评标结果，有本办法第六十四条规定情形的，要求评标委员会复核或者书面说明理由，评标委员会拒绝的，应予记录并向本级财政部门报告； （九）评审工作完成后，按照规定向评审专家支付劳务报"},{"i":46,"n":"第四十六条","txt":"评标委员会负责具体评标事务，并独立履行下列职责： （一）审查、评价投标文件是否符合招标文件的商务、技术等实质性要求； （二）要求投标人对投标文件有关事项作出澄清或者说明； （三）对投标文件进行比较和评价； （四）确定中标候选人名单，以及根据采购人委托直接确定中标人； （五）向采购人、采购代理机构或者有关部门报告评标中发现的违法行为。"},{"i":47,"n":"第四十七条","txt":"评标委员会由采购人代表和评审专家组成，成员人数应当为5人以上单数，其中评审专家不得少于成员总数的三分之二。 采购项目符合下列情形之一的，评标委员会成员人数应当为7人以上单数： （一）采购预算金额在1000万元以上； （二）技术复杂； （三）社会影响较大。 评审专家对本单位的采购项目只能作为采购人代表参与评标，本办法第四十八条第二款规定情形除外。采购代理机构工作人员不得参加由本机构代理的政府采购项目的评标。 评标委员会成员名单在评标结果公告前应当保密。"},{"i":48,"n":"第四十八条","txt":"采购人或者采购代理机构应当从省级以上财政部门设立的政府采购评审专家库中，通过随机方式抽取评审专家。 对技术复杂、专业性强的采购项目，通过随机方式难以确定合适评审专家的，经主管预算单位同意，采购人可以自行选定相应专业领域的评审专家。"},{"i":49,"n":"第四十九条","txt":"评标中因评标委员会成员缺席、回避或者健康等特殊原因导致评标委员会组成不符合本办法规定的，采购人或者采购代理机构应当依法补足后继续评标。被更换的评标委员会成员所作出的评标意见无效。 无法及时补足评标委员会成员的，采购人或者采购代理机构应当停止评标活动，封存所有投标文件和开标、评标资料，依法重新组建评标委员会进行评标。原评标委员会所作出的评标意见无效。 采购人或者采购代理机构应当将变更、重新组建评标委员会的情况予以记录，并随采购文件一并存档。"},{"i":50,"n":"第五十条","txt":"评标委员会应当对符合资格的投标人的投标文件进行符合性审查，以确定其是否满足招标文件的实质性要求。"},{"i":51,"n":"第五十一条","txt":"对于投标文件中含义不明确、同类问题表述不一致或者有明显文字和计算错误的内容，评标委员会应当以书面形式要求投标人作出必要的澄清、说明或者补正。 投标人的澄清、说明或者补正应当采用书面形式，并加盖公章，或者由法定代表人或其授权的代表签字。投标人的澄清、说明或者补正不得超出投标文件的范围或者改变投标文件的实质性内容。"},{"i":52,"n":"第五十二条","txt":"评标委员会应当按照招标文件中规定的评标方法和标准，对符合性审查合格的投标文件进行商务和技术评估，综合比较与评价。"},{"i":53,"n":"第五十三条","txt":"评标方法分为最低评标价法和综合评分法。"},{"i":54,"n":"第五十四条","txt":"最低评标价法，是指投标文件满足招标文件全部实质性要求，且投标报价最低的投标人为中标候选人的评标方法。 技术、服务等标准统一的货物服务项目，应当采用最低评标价法。 采用最低评标价法评标时，除了算术修正和落实政府采购政策需进行的价格扣除外，不能对投标人的投标价格进行任何调整。"},{"i":55,"n":"第五十五条","txt":"综合评分法，是指投标文件满足招标文件全部实质性要求，且按照评审因素的量化指标评审得分最高的投标人为中标候选人的评标方法。 评审因素的设定应当与投标人所提供货物服务的质量相关，包括投标报价、技术或者服务水平、履约能力、售后服务等。资格条件不得作为评审因素。评审因素应当在招标文件中规定。 评审因素应当细化和量化，且与相应的商务条件和采购需求对应。商务条件和采购需求指标有区间规定的，评审因素应当量化到相应区间，并设置各区间对应的不同分值。 评标时，评标委员会各成员应当独立对每个投标人的投标文件进行评价，并汇总每个投标人的得分。 货物项目的价格分值占总分值的比重不得低于30%；服务项目的价格分值占总分值的比重不得低于10%。执行国家统一定价标准和采用固定价格采购的项目，其价格不列为评审因素。 价格分应当采用低价优先法计算，即满足招标文件要求且投标价格最低的投标报价为评标基准价，其价格分为满分。"},{"i":56,"n":"第五十六条","txt":"采用最低评标价法的，评标结果按投标报价由低到高顺序排列。投标报价相同的并列。投标文件满足招标文件全部实质性要求且投标报价最低的投标人为排名第一的中标候选人"},{"i":57,"n":"第五十七条","txt":"采用综合评分法的，评标结果按评审后得分由高到低顺序排列。得分相同的，按投标报价由低到高顺序排列。得分且投标报价相同的并列。投标文件满足招标文件全部实质性要求，且按照评审因素的量化指标评审得分最高的投标人为排名第一的中标候选人。"},{"i":58,"n":"第五十八条","txt":"评标委员会根据全体评标成员签字的原始评标记录和评标结果编写评标报告。评标报告应当包括以下内容： （一）招标公告刊登的媒体名称、开标日期和地点； （二）投标人名单和评标委员会成员名单； （三）评标方法和标准； （四）开标记录和评标情况及说明，包括无效投标人名单及原因； （五）评标结果，确定的中标候选人名单或者经采购人委托直接确定的中标人； （六）其他需要说明的情况，包括评标过程中投标人根据评标委员会要求进行的澄清、说明或者补正，评标委员会成员的更换等。"},{"i":59,"n":"第五十九条","txt":"投标文件报价出现前后不一致的，除招标文件另有规定外，按照下列规定修正： （一）投标文件中开标一览表（报价表）内容与投标文件中相应内容不一致的，以开标一览表（报价表）为准； （二）大写金额和小写金额不一致的，以大写金额为准； （三）单价金额小数点或者百分比有明显错位的，以开标一览表的总价为准，并修改单价； （四）总价金额与按单价汇总金额不一致的，以单价金额计算结果为准。 同时出现两种以上不一致的，按照前款规定的顺序修正。修正后的报价按照本办法第五十一条第二款的规定经投标人确认后产生约束力，投标人不确认的，其投标无效。"},{"i":60,"n":"第六十条","txt":"评标委员会认为投标人的报价明显低于其他通过符合性审查投标人的报价，有可能影响产品质量或者不能诚信履约的，应当要求其在评标现场合理的时间内提供书面说明，必要时提交相关证明材料；投标人不能证明其报价合理性的，评标委员会应当将其作为无效投标处理。"},{"i":61,"n":"第六十一条","txt":"评标委员会成员对需要共同认定的事项存在争议的，应当按照少数服从多数的原则作出结论。持不同意见的评标委员会成员应当在评标报告上签署不同意见及理由，否则视为同意评标报告。"},{"i":62,"n":"第六十二条","txt":"评标委员会及其成员不得有下列行为： （一）确定参与评标至评标结束前私自接触投标人； （二）接受投标人提出的与投标文件不一致的澄清或者说明，本办法第五十一条规定的情形除外； （三）违反评标纪律发表倾向性意见或者征询采购人的倾向性意见； （四）对需要专业判断的主观评审因素协商评分； （五）在评标过程中擅离职守，影响评标程序正常进行的； （六）记录、复制或者带走任何评标资料； （七）其他不遵守评标纪律的行为。 评标委员会成员有前款第一至五项行为之一的，其评审意见无效，并不得获取评审劳务报酬和报销异地评审差旅费。"},{"i":63,"n":"第六十三条","txt":"投标人存在下列情况之一的，投标无效: （一）未按照招标文件的规定提交投标保证金的； （二）投标文件未按招标文件要求签署、盖章的； （三）不具备招标文件中规定的资格要求的； （四）报价超过招标文件中规定的预算金额或者最高限价的； （五）投标文件含有采购人不能接受的附加条件的; （六）法律、法规和招标文件规定的其他无效情形。"},{"i":64,"n":"第六十四条","txt":"评标结果汇总完成后，除下列情形外，任何人不得修改评标结果： （一）分值汇总计算错误的； （二）分项评分超出评分标准范围的； （三）评标委员会成员对客观评审因素评分不一致的； （四）经评标委员会认定评分畸高、畸低的。 评标报告签署前，经复核发现存在以上情形之一的，评标委员会应当当场修改评标结果，并在评标报告中记载；评标报告签署后，采购人或者采购代理机构发现存在以上情形之一的，应当组织原评标委员会进行重新评审，重新评审改变评标结果的，书面报告本级财政部门。 投标人对本条第一款情形提出质疑的，采购人或者采购代理机构可以组织原评标委员会进行重新评审，重新评审改变评标结果的，应当书面报告本级财政部门。"},{"i":65,"n":"第六十五条","txt":"评标委员会发现招标文件存在歧义、重大缺陷导致评标工作无法进行，或者招标文件内容违反国家有关强制性规定的，应当停止评标工作，与采购人或者采购代理机构沟通并作书面记录。采购人或者采购代理机构确认后，应当修改招标文件，重新组织采购活动。"},{"i":66,"n":"第六十六条","txt":"采购人、采购代理机构应当采取必要措施，保证评标在严格保密的情况下进行。除采购人代表、评标现场组织人员外，采购人的其他工作人员以及与评标工作无关的人员不得进入评标现场。 有关人员对评标情况以及在评标过程中获悉的国家秘密、商业秘密负有保密责任。"},{"i":67,"n":"第六十七条","txt":"评标委员会或者其成员存在下列情形导致评标结果无效的，采购人、采购代理机构可以重新组建评标委员会进行评标，并书面报告本级财政部门，但采购合同已经履行的除外： （一）评标委员会组成不符合本办法规定的； （二）有本办法第六十二条第一至五项情形的； （三）评标委员会及其成员独立评标受到非法干预的； （四）有政府采购法实施条例第七十五条规定的违法行为的。 有违法违规行为的原评标委员会成员不得参加重新组建的评标委员会。"},{"i":68,"n":"第六十八条","txt":"采购代理机构应当在评标结束后2个工作日内将评标报告送采购人。 采购人应当自收到评标报告之日起５个工作日内，在评标报告确定的中标候选人名单中按顺序确定中标人。中标候选人并列的，由采购人或者采购人委托评标委员会按照招标文件规定的方式确定中标人；招标文件未规定的，采取随机抽取的方式确定。 采购人自行组织招标的，应当在评标结束后5个工作日内确定中标人。 采购人在收到评标报告5个工作日内未按评标报告推荐的中标候选人顺序确定中标人，又不能说明合法理由的，视同按评标报告推荐的顺序确定排名第一的中标候选人为中标人。"},{"i":69,"n":"第六十九条","txt":"采购人或者采购代理机构应当自中标人确定之日起2个工作日内，在省级以上财政部门指定的媒体上公告中标结果，招标文件应当随中标结果同时公告。 中标结果公告内容应当包括采购人及其委托的采购代理机构的名称、地址、联系方式，项目名称和项目编号，中标人名称、地址和中标金额，主要中标标的的名称、规格型号、数量、单价、服务要求，中标公告期限以及评审专家名单。 中标公告期限为1个工作日。 邀请招标采购人采用书面推荐方式产生符合资格条件的潜在投标人的，还应当将所有被推荐供应商名单和推荐理由随中标结果同时公告。 在公告中标结果的同时，采购人或者采购代理机构应当向中标人发出中标通知书；对未通过资格审查的投标人，应当告知其未通过的原因；采用综合评分法评审的，还应当告知未中标人本人的评审得分与排序。"},{"i":70,"n":"第七十条","txt":"中标通知书发出后，采购人不得违法改变中标结果，中标人无正当理由不得放弃中标。"},{"i":71,"n":"第七十一条","txt":"采购人应当自中标通知书发出之日起30日内，按照招标文件和中标人投标文件的规定，与中标人签订书面合同。所签订的合同不得对招标文件确定的事项和中标人投标文件作实质性修改。 采购人不得向中标人提出任何不合理的要求作为签订合同的条件。"},{"i":72,"n":"第七十二条","txt":"政府采购合同应当包括采购人与中标人的名称和住所、标的、数量、质量、价款或者报酬、履行期限及地点和方式、验收要求、违约责任、解决争议的方法等内容。"},{"i":73,"n":"第七十三条","txt":"采购人与中标人应当根据合同的约定依法履行合同义务。 政府采购合同的履行、违约责任和解决争议的方法等适用《中华人民共和国合同法》。"},{"i":74,"n":"第七十四条","txt":"采购人应当及时对采购项目进行验收。采购人可以邀请参加本项目的其他投标人或者第三方机构参与验收。参与验收的投标人或者第三方机构的意见作为验收书的参考资料一并存档。"},{"i":75,"n":"第七十五条","txt":"采购人应当加强对中标人的履约管理，并按照采购合同约定，及时向中标人支付采购资金。对于中标人违反采购合同约定的行为，采购人应当及时处理，依法追究其违约责任。"},{"i":76,"n":"第七十六条","txt":"采购人、采购代理机构应当建立真实完整的招标采购档案，妥善保存每项采购活动的采购文件。"},{"i":77,"n":"第七十七条","txt":"采购人有下列情形之一的，由财政部门责令限期改正；情节严重的，给予警告，对直接负责的主管人员和其他直接责任人员由其行政主管部门或者有关机关依法给予处分，并予以通报；涉嫌犯罪的，移送司法机关处理： （一）未按照本办法的规定编制采购需求的； （二）违反本办法第六条第二款规定的； （三）未在规定时间内确定中标人的； （四）向中标人提出不合理要求作为签订合同条件的。"},{"i":78,"n":"第七十八条","txt":"采购人、采购代理机构有下列情形之一的，由财政部门责令限期改正，情节严重的，给予警告，对直接负责的主管人员和其他直接责任人员，由其行政主管部门或者有关机关给予处分，并予通报；采购代理机构有违法所得的，没收违法所得，并可以处以不超过违法所得3倍、最高不超过3万元的罚款，没有违法所得的，可以处以1万元以下的罚款： （一）违反本办法第八条第二款规定的； （二）设定最低限价的； （三）未按照规定进行资格预审或者资格审查的； （四）违反本办法规定确定招标文件售价的； （五）未按规定对开标、评标活动进行全程录音录像的； （六）擅自终止招标活动的； （七）未按照规定进行开标和组织评标的； （八）未按照规定退还投标保证金的； （九）违反本办法规定进行重新评审或者重新组建评标委员会进行评标的； （十）开标前泄露已获取招标文件的潜在投标人的名称、数量或者其他可能影响公平竞争的有关招标投标情况的； （十一）未"},{"i":79,"n":"第七十九条","txt":"有本办法第七十七条、第七十八条规定的违法行为之一，经改正后仍然影响或者可能影响中标结果的，依照政府采购法实施条例第七十一条规定处理。"},{"i":80,"n":"第八十条","txt":"政府采购当事人违反本办法规定，给他人造成损失的，依法承担民事责任。"},{"i":81,"n":"第八十一条","txt":"评标委员会成员有本办法第六十二条所列行为之一的，由财政部门责令限期改正；情节严重的，给予警告，并对其不良行为予以记录。"},{"i":82,"n":"第八十二条","txt":"财政部门应当依法履行政府采购监督管理职责。财政部门及其工作人员在履行监督管理职责中存在懒政怠政、滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，依照政府采购法、《中华人民共和国公务员法》、《中华人民共和国行政监察法》、政府采购法实施条例等国家有关规定追究相应责任；涉嫌犯罪的，移送司法机关处理。"},{"i":83,"n":"第八十三条","txt":"政府采购货物服务电子招标投标、政府采购货物中的进口机电产品招标投标有关特殊事宜，由财政部另行规定。"},{"i":84,"n":"第八十四条","txt":"本办法所称主管预算单位是指负有编制部门预算职责，向本级财政部门申报预算的国家机关、事业单位和团体组织。"},{"i":85,"n":"第八十五条","txt":"本办法规定按日计算期间的，开始当天不计入，从次日开始计算。期限的最后一日是国家法定节假日的，顺延到节假日后的次日为期限的最后一日。"},{"i":86,"n":"第八十六条","txt":"本办法所称的“以上”、“以下”、“内”、“以内”，包括本数；所称的“不足”，不包括本数。"},{"i":87,"n":"第八十七条","txt":"各省、自治区、直辖市财政部门可以根据本办法制定具体实施办法。"},{"i":88,"n":"第八十八条","txt":"本办法自2017年10月1日起施行。财政部2004年8月11日发布的《政府采购货物和服务招标投标管理办法》（财政部令第18号）同时废止。"}],"zhengfucaigouzhiyihetousubanfa":[{"i":1,"n":"第一条","txt":"为了规范政府采购质疑和投诉行为，保护参加政府采购活动当事人的合法权益，根据《中华人民共和国政府采购法》《中华人民共和国政府采购法实施条例》和其他有关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于政府采购质疑的提出和答复、投诉的提起和处理。"},{"i":3,"n":"第三条","txt":"政府采购供应商（以下简称供应商）提出质疑和投诉应当坚持依法依规、诚实信用原则。"},{"i":4,"n":"第四条","txt":"政府采购质疑答复和投诉处理应当坚持依法依规、权责对等、公平公正、简便高效原则。"},{"i":5,"n":"第五条","txt":"采购人负责供应商质疑答复。采购人委托采购代理机构采购的，采购代理机构在委托授权范围内作出答复。 县级以上各级人民政府财政部门（以下简称财政部门）负责依法处理供应商投诉。"},{"i":6,"n":"第六条","txt":"供应商投诉按照采购人所属预算级次，由本级财政部门处理。 跨区域联合采购项目的投诉，采购人所属预算级次相同的，由采购文件事先约定的财政部门负责处理，事先未约定的，由最先收到投诉的财政部门负责处理；采购人所属预算级次不同的，由预算级次最高的财政部门负责处理。"},{"i":7,"n":"第七条","txt":"采购人、采购代理机构应当在采购文件中载明接收质疑函的方式、联系部门、联系电话和通讯地址等信息。 县级以上财政部门应当在省级以上财政部门指定的政府采购信息发布媒体公布受理投诉的方式、联系部门、联系电话和通讯地址等信息。"},{"i":8,"n":"第八条","txt":"供应商可以委托代理人进行质疑和投诉。其授权委托书应当载明代理人的姓名或者名称、代理事项、具体权限、期限和相关事项。供应商为自然人的，应当由本人签字；供应商为法人或者其他组织的，应当由法定代表人、主要负责人签字或者盖章，并加盖公章。 代理人提出质疑和投诉，应当提交供应商签署的授权委托书。"},{"i":9,"n":"第九条","txt":"以联合体形式参加政府采购活动的，其投诉应当由组成联合体的所有供应商共同提出。"},{"i":10,"n":"第十条","txt":"供应商认为采购文件、采购过程、中标或者成交结果使自己的权益受到损害的，可以在知道或者应知其权益受到损害之日起7个工作日内，以书面形式向采购人、采购代理机构提出质疑。 采购文件可以要求供应商在法定质疑期内一次性提出针对同一采购程序环节的质疑。"},{"i":11,"n":"第十一条","txt":"提出质疑的供应商（以下简称质疑供应商）应当是参与所质疑项目采购活动的供应商。 潜在供应商已依法获取其可质疑的采购文件的，可以对该文件提出质疑。对采购文件提出质疑的，应当在获取采购文件或者采购文件公告期限届满之日起7个工作日内提出。"},{"i":12,"n":"第十二条","txt":"供应商提出质疑应当提交质疑函和必要的证明材料。质疑函应当包括下列内容： （一）供应商的姓名或者名称、地址、邮编、联系人及联系电话； （二）质疑项目的名称、编号； （三）具体、明确的质疑事项和与质疑事项相关的请求； （四）事实依据； （五）必要的法律依据； （六）提出质疑的日期。 供应商为自然人的，应当由本人签字；供应商为法人或者其他组织的，应当由法定代表人、主要负责人，或者其授权代表签字或者盖章，并加盖公章。"},{"i":13,"n":"第十三条","txt":"采购人、采购代理机构不得拒收质疑供应商在法定质疑期内发出的质疑函，应当在收到质疑函后7个工作日内作出答复，并以书面形式通知质疑供应商和其他有关供应商。"},{"i":14,"n":"第十四条","txt":"供应商对评审过程、中标或者成交结果提出质疑的，采购人、采购代理机构可以组织原评标委员会、竞争性谈判小组、询价小组或者竞争性磋商小组协助答复质疑。"},{"i":15,"n":"第十五条","txt":"质疑答复应当包括下列内容： （一）质疑供应商的姓名或者名称； （二）收到质疑函的日期、质疑项目名称及编号； （三）质疑事项、质疑答复的具体内容、事实依据和法律依据； （四）告知质疑供应商依法投诉的权利； （五）质疑答复人名称； （六）答复质疑的日期。 质疑答复的内容不得涉及商业秘密。"},{"i":16,"n":"第十六条","txt":"采购人、采购代理机构认为供应商质疑不成立，或者成立但未对中标、成交结果构成影响的，继续开展采购活动；认为供应商质疑成立且影响或者可能影响中标、成交结果的，按照下列情况处理： （一）对采购文件提出的质疑，依法通过澄清或者修改可以继续开展采购活动的，澄清或者修改采购文件后继续开展采购活动；否则应当修改采购文件后重新开展采购活动。 （二）对采购过程、中标或者成交结果提出的质疑，合格供应商符合法定数量时，可以从合格的中标或者成交候选人中另行确定中标、成交供应商的，应当依法另行确定中标、成交供应商；否则应当重新开展采购活动。 质疑答复导致中标、成交结果改变的，采购人或者采购代理机构应当将有关情况书面报告本级财政部门。"},{"i":17,"n":"第十七条","txt":"质疑供应商对采购人、采购代理机构的答复不满意，或者采购人、采购代理机构未在规定时间内作出答复的，可以在答复期满后15个工作日内向本办法第六条规定的财政部门提起投诉。"},{"i":18,"n":"第十八条","txt":"投诉人投诉时,应当提交投诉书和必要的证明材料，并按照被投诉采购人、采购代理机构（以下简称被投诉人）和与投诉事项有关的供应商数量提供投诉书的副本。投诉书应当包括下列内容： （一）投诉人和被投诉人的姓名或者名称、通讯地址、邮编、联系人及联系电话； （二）质疑和质疑答复情况说明及相关证明材料； （三）具体、明确的投诉事项和与投诉事项相关的投诉请求； （四）事实依据； （五）法律依据； （六）提起投诉的日期。 投诉人为自然人的，应当由本人签字；投诉人为法人或者其他组织的，应当由法定代表人、主要负责人，或者其授权代表签字或者盖章，并加盖公章。"},{"i":19,"n":"第十九条","txt":"投诉人应当根据本办法第七条第二款规定的信息内容，并按照其规定的方式提起投诉。 投诉人提起投诉应当符合下列条件： （一）提起投诉前已依法进行质疑； （二）投诉书内容符合本办法的规定； （三）在投诉有效期限内提起投诉； （四）同一投诉事项未经财政部门投诉处理； （五）财政部规定的其他条件。"},{"i":20,"n":"第二十条","txt":"供应商投诉的事项不得超出已质疑事项的范围，但基于质疑答复内容提出的投诉事项除外。"},{"i":21,"n":"第二十一条","txt":"财政部门收到投诉书后，应当在5个工作日内进行审查，审查后按照下列情况处理： （一）投诉书内容不符合本办法第十八条规定的，应当在收到投诉书5个工作日内一次性书面通知投诉人补正。补正通知应当载明需要补正的事项和合理的补正期限。未按照补正期限进行补正或者补正后仍不符合规定的，不予受理。 （二）投诉不符合本办法第十九条规定条件的，应当在3个工作日内书面告知投诉人不予受理，并说明理由。 （三）投诉不属于本部门管辖的，应当在3个工作日内书面告知投诉人向有管辖权的部门提起投诉。 （四）投诉符合本办法第十八条、第十九条规定的，自收到投诉书之日起即为受理，并在收到投诉后8个工作日内向被投诉人和其他与投诉事项有关的当事人发出投诉答复通知书及投诉书副本。"},{"i":22,"n":"第二十二条","txt":"被投诉人和其他与投诉事项有关的当事人应当在收到投诉答复通知书及投诉书副本之日起5个工作日内，以书面形式向财政部门作出说明，并提交相关证据、依据和其他有关材料。"},{"i":23,"n":"第二十三条","txt":"财政部门处理投诉事项原则上采用书面审查的方式。财政部门认为有必要时，可以进行调查取证或者组织质证。 财政部门可以根据法律、法规规定或者职责权限，委托相关单位或者第三方开展调查取证、检验、检测、鉴定。 质证应当通知相关当事人到场，并制作质证笔录。质证笔录应当由当事人签字确认。"},{"i":24,"n":"第二十四条","txt":"财政部门依法进行调查取证时，投诉人、被投诉人以及与投诉事项有关的单位及人员应当如实反映情况，并提供财政部门所需要的相关材料。"},{"i":25,"n":"第二十五条","txt":"应当由投诉人承担举证责任的投诉事项，投诉人未提供相关证据、依据和其他有关材料的，视为该投诉事项不成立；被投诉人未按照投诉答复通知书要求提交相关证据、依据和其他有关材料的，视同其放弃说明权利，依法承担不利后果。"},{"i":26,"n":"第二十六条","txt":"财政部门应当自收到投诉之日起30个工作日内，对投诉事项作出处理决定。"},{"i":27,"n":"第二十七条","txt":"财政部门处理投诉事项，需要检验、检测、鉴定、专家评审以及需要投诉人补正材料的，所需时间不计算在投诉处理期限内。 前款所称所需时间，是指财政部门向相关单位、第三方、投诉人发出相关文书、补正通知之日至收到相关反馈文书或材料之日。 财政部门向相关单位、第三方开展检验、检测、鉴定、专家评审的，应当将所需时间告知投诉人。"},{"i":28,"n":"第二十八条","txt":"财政部门在处理投诉事项期间，可以视具体情况书面通知采购人和采购代理机构暂停采购活动，暂停采购活动时间最长不得超过30日。 采购人和采购代理机构收到暂停采购活动通知后应当立即中止采购活动，在法定的暂停期限结束前或者财政部门发出恢复采购活动通知前，不得进行该项采购活动。"},{"i":29,"n":"第二十九条","txt":"投诉处理过程中，有下列情形之一的，财政部门应当驳回投诉： （一）受理后发现投诉不符合法定受理条件； （二）投诉事项缺乏事实依据，投诉事项不成立； （三）投诉人捏造事实或者提供虚假材料； （四）投诉人以非法手段取得证明材料。证据来源的合法性存在明显疑问，投诉人无法证明其取得方式合法的，视为以非法手段取得证明材料。"},{"i":30,"n":"第三十条","txt":"财政部门受理投诉后,投诉人书面申请撤回投诉的，财政部门应当终止投诉处理程序，并书面告知相关当事人。"},{"i":31,"n":"第三十一条","txt":"投诉人对采购文件提起的投诉事项，财政部门经查证属实的，应当认定投诉事项成立。经认定成立的投诉事项不影响采购结果的，继续开展采购活动；影响或者可能影响采购结果的，财政部门按照下列情况处理： （一）未确定中标或者成交供应商的，责令重新开展采购活动。 （二）已确定中标或者成交供应商但尚未签订政府采购合同的，认定中标或者成交结果无效，责令重新开展采购活动。 （三）政府采购合同已经签订但尚未履行的，撤销合同，责令重新开展采购活动。 （四）政府采购合同已经履行，给他人造成损失的，相关当事人可依法提起诉讼，由责任人承担赔偿责任。"},{"i":32,"n":"第三十二条","txt":"投诉人对采购过程或者采购结果提起的投诉事项，财政部门经查证属实的，应当认定投诉事项成立。经认定成立的投诉事项不影响采购结果的，继续开展采购活动；影响或者可能影响采购结果的，财政部门按照下列情况处理： （一）未确定中标或者成交供应商的，责令重新开展采购活动。 （二）已确定中标或者成交供应商但尚未签订政府采购合同的，认定中标或者成交结果无效。合格供应商符合法定数量时，可以从合格的中标或者成交候选人中另行确定中标或者成交供应商的，应当要求采购人依法另行确定中标、成交供应商；否则责令重新开展采购活动。 （三）政府采购合同已经签订但尚未履行的，撤销合同。合格供应商符合法定数量时，可以从合格的中标或者成交候选人中另行确定中标或者成交供应商的，应当要求采购人依法另行确定中标、成交供应商；否则责令重新开展采购活动。 （四）政府采购合同已经履行，给他人造成损失的，相关当事人可依法提起诉讼,由责任人承担赔"},{"i":33,"n":"第三十三条","txt":"财政部门作出处理决定，应当制作投诉处理决定书，并加盖公章。投诉处理决定书应当包括下列内容： （一）投诉人和被投诉人的姓名或者名称、通讯地址等； （二）处理决定查明的事实和相关依据，具体处理决定和法律依据； （三）告知相关当事人申请行政复议的权利、行政复议机关和行政复议申请期限，以及提起行政诉讼的权利和起诉期限； （四）作出处理决定的日期。"},{"i":34,"n":"第三十四条","txt":"财政部门应当将投诉处理决定书送达投诉人和与投诉事项有关的当事人，并及时将投诉处理结果在省级以上财政部门指定的政府采购信息发布媒体上公告。 投诉处理决定书的送达，参照《中华人民共和国民事诉讼法》关于送达的规定执行。"},{"i":35,"n":"第三十五条","txt":"财政部门应当建立投诉处理档案管理制度，并配合有关部门依法进行的监督检查。"},{"i":36,"n":"第三十六条","txt":"采购人、采购代理机构有下列情形之一的，由财政部门责令限期改正；情节严重的，给予警告，对直接负责的主管人员和其他直接责任人员，由其行政主管部门或者有关机关给予处分，并予通报： （一）拒收质疑供应商在法定质疑期内发出的质疑函； （二）对质疑不予答复或者答复与事实明显不符，并不能作出合理说明； （三）拒绝配合财政部门处理投诉事宜。"},{"i":37,"n":"第三十七条","txt":"投诉人在全国范围12个月内三次以上投诉查无实据的，由财政部门列入不良行为记录名单。 投诉人有下列行为之一的，属于虚假、恶意投诉，由财政部门列入不良行为记录名单，禁止其1至3年内参加政府采购活动： （一）捏造事实; （二）提供虚假材料; （三）以非法手段取得证明材料。证据来源的合法性存在明显疑问，投诉人无法证明其取得方式合法的，视为以非法手段取得证明材料。"},{"i":38,"n":"第三十八条","txt":"财政部门及其工作人员在履行投诉处理职责中违反本办法规定及存在其他滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，依照《中华人民共和国政府采购法》《中华人民共和国公务员法》《中华人民共和国行政监察法》《中华人民共和国政府采购法实施条例》等国家有关规定追究相应责任；涉嫌犯罪的，依法移送司法机关处理。"},{"i":39,"n":"第三十九条","txt":"质疑函和投诉书应当使用中文。质疑函和投诉书的范本，由财政部制定。"},{"i":40,"n":"第四十条","txt":"相关当事人提供外文书证或者外国语视听资料的，应当附有中文译本，由翻译机构盖章或者翻译人员签名。 相关当事人向财政部门提供的在中华人民共和国领域外形成的证据，应当说明来源，经所在国公证机关证明，并经中华人民共和国驻该国使领馆认证，或者履行中华人民共和国与证据所在国订立的有关条约中规定的证明手续。 相关当事人提供的在香港特别行政区、澳门特别行政区和台湾地区内形成的证据，应当履行相关的证明手续。"},{"i":41,"n":"第四十一条","txt":"财政部门处理投诉不得向投诉人和被投诉人收取任何费用。但因处理投诉发生的第三方检验、检测、鉴定等费用，由提出申请的供应商先行垫付。投诉处理决定明确双方责任后，按照“谁过错谁负担”的原则由承担责任的一方负担；双方都有责任的，由双方合理分担。"},{"i":42,"n":"第四十二条","txt":"本办法规定的期间开始之日，不计算在期间内。期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。期间不包括在途时间，质疑和投诉文书在期满前交邮的，不算过期。 本办法规定的“以上”“以下”均含本数。"},{"i":43,"n":"第四十三条","txt":"对在质疑答复和投诉处理过程中知悉的国家秘密、商业秘密、个人隐私和依法不予公开的信息，财政部门、采购人、采购代理机构等相关知情人应当保密。"},{"i":44,"n":"第四十四条","txt":"省级财政部门可以根据本办法制定具体实施办法。"},{"i":45,"n":"第四十五条","txt":"本办法自2018年3月1日起施行。财政部2004年8月11日发布的《政府采购供应商投诉处理办法》（财政部令第20号）同时废止。"}],"zhengfucaigoufeizhaobiaocaigoufangshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范政府采购行为，加强对采用非招标采购方式采购活动的监督管理，维护国家利益、社会公共利益和政府采购当事人的合法权益，依据《中华人民共和国政府采购法》(以下简称政府采购法)和其他法律、行政法规的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"采购人、采购代理机构采用非招标采购方式采购货物、工程和服务的，适用本办法。 本办法所称非招标采购方式，是指竞争性谈判、单一来源采购和询价采购方式。 竞争性谈判是指谈判小组与符合资格条件的供应商就采购货物、工程和服务事宜进行谈判，供应商按照谈判文件的要求提交响应文件和最后报价，采购人从谈判小组提出的成交候选人中确定成交供应商的采购方式。 单一来源采购是指采购人从某一特定供应商处采购货物、工程和服务的采购方式。 询价是指询价小组向符合资格条件的供应商发出采购货物询价通知书，要求供应商一次报出不得更改的价格，采购人从询价小组提出的成交候选人中确定成交供应商的采购方式。"},{"i":3,"n":"第三条","txt":"采购人、采购代理机构采购以下货物、工程和服务之一的，可以采用竞争性谈判、单一来源采购方式采购；采购货物的，还可以采用询价采购方式： （一）依法制定的集中采购目录以内，且未达到公开招标数额标准的货物、服务； （二）依法制定的集中采购目录以外、采购限额标准以上，且未达到公开招标数额标准的货物、服务； （三）达到公开招标数额标准、经批准采用非公开招标方式的货物、服务； （四）按照招标投标法及其实施条例必须进行招标的工程建设项目以外的政府采购工程。"},{"i":4,"n":"第四条","txt":"达到公开招标数额标准的货物、服务采购项目，拟采用非招标采购方式的，采购人应当在采购活动开始前，报经主管预算单位同意后，向设区的市、自治州以上人民政府财政部门申请批准。"},{"i":5,"n":"第五条","txt":"根据本办法第四条申请采用非招标采购方式采购的，采购人应当向财政部门提交以下材料并对材料的真实性负责： （一）采购人名称、采购项目名称、项目概况等项目基本情况说明； （二）项目预算金额、预算批复文件或者资金来源证明； （三）拟申请采用的采购方式和理由。"},{"i":6,"n":"第六条","txt":"采购人、采购代理机构应当按照政府采购法和本办法的规定组织开展非招标采购活动，并采取必要措施，保证评审在严格保密的情况下进行。 任何单位和个人不得非法干预、影响评审过程和结果。"},{"i":7,"n":"第七条","txt":"竞争性谈判小组或者询价小组由采购人代表和评审专家共3人以上单数组成，其中评审专家人数不得少于竞争性谈判小组或者询价小组成员总数的2/3。采购人不得以评审专家身份参加本部门或本单位采购项目的评审。采购代理机构人员不得参加本机构代理的采购项目的评审。 达到公开招标数额标准的货物或者服务采购项目，或者达到招标规模标准的政府采购工程，竞争性谈判小组或者询价小组应当由5人以上单数组成。 采用竞争性谈判、询价方式采购的政府采购项目，评审专家应当从政府采购评审专家库内相关专业的专家名单中随机抽取。技术复杂、专业性强的竞争性谈判采购项目，通过随机方式难以确定合适的评审专家的，经主管预算单位同意，可以自行选定评审专家。技术复杂、专业性强的竞争性谈判采购项目，评审专家中应当包含1名法律专家。"},{"i":8,"n":"第八条","txt":"竞争性谈判小组或者询价小组在采购活动过程中应当履行下列职责： （一）确认或者制定谈判文件、询价通知书； （二）从符合相应资格条件的供应商名单中确定不少于3家的供应商参加谈判或者询价； （三）审查供应商的响应文件并作出评价； （四）要求供应商解释或者澄清其响应文件； （五）编写评审报告； （六）告知采购人、采购代理机构在评审过程中发现的供应商的违法违规行为。"},{"i":9,"n":"第九条","txt":"竞争性谈判小组或者询价小组成员应当履行下列义务： （一）遵纪守法，客观、公正、廉洁地履行职责； （二）根据采购文件的规定独立进行评审，对个人的评审意见承担法律责任； （三）参与评审报告的起草； （四）配合采购人、采购代理机构答复供应商提出的质疑； （五）配合财政部门的投诉处理和监督检查工作。"},{"i":10,"n":"第十条","txt":"谈判文件、询价通知书应当根据采购项目的特点和采购人的实际需求制定，并经采购人书面同意。采购人应当以满足实际需求为原则，不得擅自提高经费预算和资产配置等采购标准。 谈判文件、询价通知书不得要求或者标明供应商名称或者特定货物的品牌，不得含有指向特定供应商的技术、服务等条件。"},{"i":11,"n":"第十一条","txt":"谈判文件、询价通知书应当包括供应商资格条件、采购邀请、采购方式、采购预算、采购需求、采购程序、价格构成或者报价要求、响应文件编制要求、提交响应文件截止时间及地点、保证金交纳数额和形式、评定成交的标准等。 谈判文件除本条第一款规定的内容外，还应当明确谈判小组根据与供应商谈判情况可能实质性变动的内容，包括采购需求中的技术、服务要求以及合同草案条款。"},{"i":12,"n":"第十二条","txt":"采购人、采购代理机构应当通过发布公告、从省级以上财政部门建立的供应商库中随机抽取或者采购人和评审专家分别书面推荐的方式邀请不少于 3家符合相应资格条件的供应商参与竞争性谈判或者询价采购活动。 符合政府采购法第二十二条第一款规定条件的供应商可以在采购活动开始前加入供应商库。财政部门不得对供应商申请入库收取任何费用，不得利用供应商库进行地区和行业封锁。 采取采购人和评审专家书面推荐方式选择供应商的，采购人和评审专家应当各自出具书面推荐意见。采购人推荐供应商的比例不得高于推荐供应商总数的 50%。"},{"i":13,"n":"第十三条","txt":"供应商应当按照谈判文件、询价通知书的要求编制响应文件，并对其提交的响应文件的真实性、合法性承担法律责任。"},{"i":14,"n":"第十四条","txt":"采购人、采购代理机构可以要求供应商在提交响应文件截止时间之前交纳保证金。保证金应当采用支票、汇票、本票、网上银行支付或者金融机构、担保机构出具的保函等非现金形式交纳。保证金数额应当不超过采购项目预算的2%。 供应商为联合体的，可以由联合体中的一方或者多方共同交纳保证金，其交纳的保证金对联合体各方均具有约束力。"},{"i":15,"n":"第十五条","txt":"供应商应当在谈判文件、询价通知书要求的截止时间前，将响应文件密封送达指定地点。在截止时间后送达的响应文件为无效文件，采购人、采购代理机构或者谈判小组、询价小组应当拒收。 供应商在提交询价响应文件截止时间前，可以对所提交的响应文件进行补充、修改或者撤回，并书面通知采购人、采购代理机构。补充、修改的内容作为响应文件的组成部分。补充、修改的内容与响应文件不一致的，以补充、修改的内容为准。"},{"i":16,"n":"第十六条","txt":"谈判小组、询价小组在对响应文件的有效性、完整性和响应程度进行审查时，可以要求供应商对响应文件中含义不明确、同类问题表述不一致或者有明显文字和计算错误的内容等作出必要的澄清、说明或者更正。供应商的澄清、说明或者更正不得超出响应文件的范围或者改变响应文件的实质性内容。 谈判小组、询价小组要求供应商澄清、说明或者更正响应文件应当以书面形式作出。供应商的澄清、说明或者更正应当由法定代表人或其授权代表签字或者加盖公章。由授权代表签字的，应当附法定代表人授权书。供应商为自然人的，应当由本人签字并附身份证明。"},{"i":17,"n":"第十七条","txt":"谈判小组、询价小组应当根据评审记录和评审结果编写评审报告，其主要内容包括： （一）邀请供应商参加采购活动的具体方式和相关情况，以及参加采购活动的供应商名单； （二）评审日期和地点，谈判小组、询价小组成员名单； （三）评审情况记录和说明，包括对供应商的资格审查情况、供应商响应文件评审情况、谈判情况、报价情况等； （四）提出的成交候选人的名单及理由。 评审报告应当由谈判小组、询价小组全体人员签字认可。谈判小组、询价小组成员对评审报告有异议的，谈判小组、询价小组按照少数服从多数的原则推荐成交候选人，采购程序继续进行。对评审报告有异议的谈判小组、询价小组成员，应当在报告上签署不同意见并说明理由，由谈判小组、询价小组书面记录相关情况。谈判小组、询价小组成员拒绝在报告上签字又不书面说明其不同意见和理由的，视为同意评审报告。"},{"i":18,"n":"第十八条","txt":"采购人或者采购代理机构应当在成交供应商确定后2个工作日内，在省级以上财政部门指定的媒体上公告成交结果，同时向成交供应商发出成交通知书，并将竞争性谈判文件、询价通知书随成交结果同时公告。成交结果公告应当包括以下内容： （一）采购人和采购代理机构的名称、地址和联系方式； （二）项目名称和项目编号； （三）成交供应商名称、地址和成交金额； （四）主要成交标的的名称、规格型号、数量、单价、服务要求； （五）谈判小组、询价小组成员名单及单一来源采购人员名单。 采用书面推荐供应商参加采购活动的，还应当公告采购人和评审专家的推荐意见。"},{"i":19,"n":"第十九条","txt":"采购人与成交供应商应当在成交通知书发出之日起30日内，按照采购文件确定的合同文本以及采购标的、规格型号、采购金额、采购数量、技术和服务要求等事项签订政府采购合同。 采购人不得向成交供应商提出超出采购文件以外的任何要求作为签订合同的条件，不得与成交供应商订立背离采购文件确定的合同文本以及采购标的、规格型号、采购金额、采购数量、技术和服务要求等实质性内容的协议。"},{"i":20,"n":"第二十条","txt":"采购人或者采购代理机构应当在采购活动结束后及时退还供应商的保证金，但因供应商自身原因导致无法及时退还的除外。未成交供应商的保证金应当在成交通知书发出后5个工作日内退还，成交供应商的保证金应当在采购合同签订后5个工作日内退还。 有下列情形之一的，保证金不予退还： （一）供应商在提交响应文件截止时间后撤回响应文件的； （二）供应商在响应文件中提供虚假材料的； （三）除因不可抗力或谈判文件、询价通知书认可的情形以外，成交供应商不与采购人签订合同的； （四）供应商与采购人、其他供应商或者采购代理机构恶意串通的； （五）采购文件规定的其他情形。"},{"i":21,"n":"第二十一条","txt":"除资格性审查认定错误和价格计算错误外，采购人或者采购代理机构不得以任何理由组织重新评审。采购人、采购代理机构发现谈判小组、询价小组未按照采购文件规定的评定成交的标准进行评审的，应当重新开展采购活动，并同时书面报告本级财政部门。"},{"i":22,"n":"第二十二条","txt":"除不可抗力等因素外，成交通知书发出后，采购人改变成交结果，或者成交供应商拒绝签订政府采购合同的，应当承担相应的法律责任。 成交供应商拒绝签订政府采购合同的，采购人可以按照本办法第三十六条第二款、第四十九条第二款规定的原则确定其他供应商作为成交供应商并签订政府采购合同，也可以重新开展采购活动。拒绝签订政府采购合同的成交供应商不得参加对该项目重新开展的采购活动。"},{"i":23,"n":"第二十三条","txt":"在采购活动中因重大变故，采购任务取消的，采购人或者采购代理机构应当终止采购活动，通知所有参加采购活动的供应商，并将项目实施情况和采购任务取消原因报送本级财政部门。"},{"i":24,"n":"第二十四条","txt":"采购人或者采购代理机构应当按照采购合同规定的技术、服务等要求组织对供应商履约的验收，并出具验收书。验收书应当包括每一项技术、服务等要求的履约情况。大型或者复杂的项目，应当邀请国家认可的质量检测机构参加验收。验收方成员应当在验收书上签字，并承担相应的法律责任。"},{"i":25,"n":"第二十五条","txt":"谈判小组、询价小组成员以及与评审工作有关的人员不得泄露评审情况以及评审过程中获悉的国家秘密、商业秘密。"},{"i":26,"n":"第二十六条","txt":"采购人、采购代理机构应当妥善保管每项采购活动的采购文件。采购文件包括采购活动记录、采购预算、谈判文件、询价通知书、响应文件、推荐供应商的意见、评审报告、成交供应商确定文件、单一来源采购协商情况记录、合同文本、验收证明、质疑答复、投诉处理决定以及其他有关文件、资料。采购文件可以电子档案方式保存。 采购活动记录至少应当包括下列内容： （一）采购项目类别、名称； （二）采购项目预算、资金构成和合同价格； （三）采购方式，采用该方式的原因及相关说明材料； （四）选择参加采购活动的供应商的方式及原因； （五）评定成交的标准及确定成交供应商的原因； （六）终止采购活动的，终止的原因。"},{"i":27,"n":"第二十七条","txt":"符合下列情形之一的采购项目，可以采用竞争性谈判方式采购： （一）招标后没有供应商投标或者没有合格标的，或者重新招标未能成立的； （二）技术复杂或者性质特殊，不能确定详细规格或者具体要求的； （三）非采购人所能预见的原因或者非采购人拖延造成采用招标所需时间不能满足用户紧急需要的； （四）因艺术品采购、专利、专有技术或者服务的时间、数量事先不能确定等原因不能事先计算出价格总额的。 公开招标的货物、服务采购项目，招标过程中提交投标文件或者经评审实质性响应招标文件要求的供应商只有两家时，采购人、采购代理机构按照本办法第四条经本级财政部门批准后可以与该两家供应商进行竞争性谈判采购，采购人、采购代理机构应当根据招标文件中的采购需求编制谈判文件，成立谈判小组，由谈判小组对谈判文件进行确认。符合本款情形的，本办法第三十三条、第三十五条中规定的供应商最低数量可以为两家。"},{"i":28,"n":"第二十八条","txt":"符合本办法第二十七条第一款第一项情形和第二款情形，申请采用竞争性谈判采购方式时，除提交本办法第五条第一至三项规定的材料外，还应当提交下列申请材料： （一）在省级以上财政部门指定的媒体上发布招标公告的证明材料； （二）采购人、采购代理机构出具的对招标文件和招标过程是否有供应商质疑及质疑处理情况的说明； （三）评标委员会或者3名以上评审专家出具的招标文件没有不合理条款的论证意见。"},{"i":29,"n":"第二十九条","txt":"从谈判文件发出之日起至供应商提交首次响应文件截止之日止不得少于3个工作日。 提交首次响应文件截止之日前，采购人、采购代理机构或者谈判小组可以对已发出的谈判文件进行必要的澄清或者修改，澄清或者修改的内容作为谈判文件的组成部分。澄清或者修改的内容可能影响响应文件编制的，采购人、采购代理机构或者谈判小组应当在提交首次响应文件截止之日3个工作日前，以书面形式通知所有接收谈判文件的供应商，不足3个工作日的，应当顺延提交首次响应文件截止之日。"},{"i":30,"n":"第三十条","txt":"谈判小组应当对响应文件进行评审，并根据谈判文件规定的程序、评定成交的标准等事项与实质性响应谈判文件要求的供应商进行谈判。未实质性响应谈判文件的响应文件按无效处理，谈判小组应当告知有关供应商。"},{"i":31,"n":"第三十一条","txt":"谈判小组所有成员应当集中与单一供应商分别进行谈判，并给予所有参加谈判的供应商平等的谈判机会。"},{"i":32,"n":"第三十二条","txt":"在谈判过程中，谈判小组可以根据谈判文件和谈判情况实质性变动采购需求中的技术、服务要求以及合同草案条款，但不得变动谈判文件中的其他内容。实质性变动的内容，须经采购人代表确认。 对谈判文件作出的实质性变动是谈判文件的有效组成部分，谈判小组应当及时以书面形式同时通知所有参加谈判的供应商。 供应商应当按照谈判文件的变动情况和谈判小组的要求重新提交响应文件，并由其法定代表人或授权代表签字或者加盖公章。由授权代表签字的，应当附法定代表人授权书。供应商为自然人的，应当由本人签字并附身份证明。"},{"i":33,"n":"第三十三条","txt":"谈判文件能够详细列明采购标的的技术、服务要求的，谈判结束后，谈判小组应当要求所有继续参加谈判的供应商在规定时间内提交最后报价，提交最后报价的供应商不得少于3家。 谈判文件不能详细列明采购标的的技术、服务要求，需经谈判由供应商提供最终设计方案或解决方案的，谈判结束后，谈判小组应当按照少数服从多数的原则投票推荐3家以上供应商的设计方案或者解决方案，并要求其在规定时间内提交最后报价。 最后报价是供应商响应文件的有效组成部分。"},{"i":34,"n":"第三十四条","txt":"已提交响应文件的供应商，在提交最后报价之前，可以根据谈判情况退出谈判。采购人、采购代理机构应当退还退出谈判的供应商的保证金。"},{"i":35,"n":"第三十五条","txt":"谈判小组应当从质量和服务均能满足采购文件实质性响应要求的供应商中，按照最后报价由低到高的顺序提出3名以上成交候选人，并编写评审报告。"},{"i":36,"n":"第三十六条","txt":"采购代理机构应当在评审结束后2个工作日内将评审报告送采购人确认。 采购人应当在收到评审报告后5个工作日内，从评审报告提出的成交候选人中，根据质量和服务均能满足采购文件实质性响应要求且最后报价最低的原则确定成交供应商，也可以书面授权谈判小组直接确定成交供应商。采购人逾期未确定成交供应商且不提出异议的，视为确定评审报告提出的最后报价最低的供应商为成交供应商。"},{"i":37,"n":"第三十七条","txt":"出现下列情形之一的，采购人或者采购代理机构应当终止竞争性谈判采购活动，发布项目终止公告并说明原因，重新开展采购活动： （一）因情况变化，不再符合规定的竞争性谈判采购方式适用情形的； （二）出现影响采购公正的违法、违规行为的； （三）在采购过程中符合竞争要求的供应商或者报价未超过采购预算的供应商不足3家的，但本办法第二十七条第二款规定的情形除外。"},{"i":38,"n":"第三十八条","txt":"属于政府采购法第三十一条第一项情形，且达到公开招标数额的货物、服务项目，拟采用单一来源采购方式的，采购人、采购代理机构在按照本办法第四条报财政部门批准之前，应当在省级以上财政部门指定媒体上公示，并将公示情况一并报财政部门。公示期不得少于5个工作日，公示内容应当包括： （一）采购人、采购项目名称和内容； （二）拟采购的货物或者服务的说明； （三）采用单一来源采购方式的原因及相关说明； （四）拟定的唯一供应商名称、地址； （五）专业人员对相关供应商因专利、专有技术等原因具有唯一性的具体论证意见，以及专业人员的姓名、工作单位和职称； （六）公示的期限； （七）采购人、采购代理机构、财政部门的联系地址、联系人和联系电话。"},{"i":39,"n":"第三十九条","txt":"任何供应商、单位或者个人对采用单一来源采购方式公示有异议的，可以在公示期内将书面意见反馈给采购人、采购代理机构，并同时抄送相关财政部门。"},{"i":40,"n":"第四十条","txt":"采购人、采购代理机构收到对采用单一来源采购方式公示的异议后，应当在公示期满后5个工作日内，组织补充论证，论证后认为异议成立的，应当依法采取其他采购方式；论证后认为异议不成立的，应当将异议意见、论证意见与公示情况一并报相关财政部门。 采购人、采购代理机构应当将补充论证的结论告知提出异议的供应商、单位或者个人。"},{"i":41,"n":"第四十一条","txt":"采用单一来源采购方式采购的，采购人、采购代理机构应当组织具有相关经验的专业人员与供应商商定合理的成交价格并保证采购项目质量。"},{"i":42,"n":"第四十二条","txt":"单一来源采购人员应当编写协商情况记录，主要内容包括： （一）依据本办法第三十八条进行公示的，公示情况说明； （二）协商日期和地点，采购人员名单； （三）供应商提供的采购标的成本、同类项目合同价格以及相关专利、专有技术等情况说明； （四）合同主要条款及价格商定情况。 协商情况记录应当由采购全体人员签字认可。对记录有异议的采购人员，应当签署不同意见并说明理由。采购人员拒绝在记录上签字又不书面说明其不同意见和理由的，视为同意。"},{"i":43,"n":"第四十三条","txt":"出现下列情形之一的，采购人或者采购代理机构应当终止采购活动，发布项目终止公告并说明原因，重新开展采购活动： （一）因情况变化，不再符合规定的单一来源采购方式适用情形的； （二）出现影响采购公正的违法、违规行为的； （三）报价超过采购预算的。"},{"i":44,"n":"第四十四条","txt":"询价采购需求中的技术、服务等要求应当完整、明确，符合相关法律、行政法规和政府采购政策的规定。"},{"i":45,"n":"第四十五条","txt":"从询价通知书发出之日起至供应商提交响应文件截止之日止不得少于3个工作日。 提交响应文件截止之日前，采购人、采购代理机构或者询价小组可以对已发出的询价通知书进行必要的澄清或者修改，澄清或者修改的内容作为询价通知书的组成部分。澄清或者修改的内容可能影响响应文件编制的，采购人、采购代理机构或者询价小组应当在提交响应文件截止之日3个工作日前，以书面形式通知所有接收询价通知书的供应商，不足3个工作日的，应当顺延提交响应文件截止之日。"},{"i":46,"n":"第四十六条","txt":"询价小组在询价过程中，不得改变询价通知书所确定的技术和服务等要求、评审程序、评定成交的标准和合同文本等事项。"},{"i":47,"n":"第四十七条","txt":"参加询价采购活动的供应商，应当按照询价通知书的规定一次报出不得更改的价格。"},{"i":48,"n":"第四十八条","txt":"询价小组应当从质量和服务均能满足采购文件实质性响应要求的供应商中，按照报价由低到高的顺序提出3名以上成交候选人，并编写评审报告。"},{"i":49,"n":"第四十九条","txt":"采购代理机构应当在评审结束后2个工作日内将评审报告送采购人确认。 采购人应当在收到评审报告后5个工作日内，从评审报告提出的成交候选人中，根据质量和服务均能满足采购文件实质性响应要求且报价最低的原则确定成交供应商，也可以书面授权询价小组直接确定成交供应商。采购人逾期未确定成交供应商且不提出异议的，视为确定评审报告提出的最后报价最低的供应商为成交供应商。"},{"i":50,"n":"第五十条","txt":"出现下列情形之一的，采购人或者采购代理机构应当终止询价采购活动，发布项目终止公告并说明原因，重新开展采购活动： （一）因情况变化，不再符合规定的询价采购方式适用情形的； （二）出现影响采购公正的违法、违规行为的； （三）在采购过程中符合竞争要求的供应商或者报价未超过采购预算的供应商不足3家的。"},{"i":51,"n":"第五十一条","txt":"采购人、采购代理机构有下列情形之一的，责令限期改正，给予警告；有关法律、行政法规规定处以罚款的，并处罚款；涉嫌犯罪的，依法移送司法机关处理： （一）未按照本办法规定在指定媒体上发布政府采购信息的； （二）未按照本办法规定组成谈判小组、询价小组的； （三）在询价采购过程中与供应商进行协商谈判的； （四）未按照政府采购法和本办法规定的程序和要求确定成交候选人的； （五）泄露评审情况以及评审过程中获悉的国家秘密、商业秘密的。 采购代理机构有前款情形之一，情节严重的，暂停其政府采购代理机构资格3至6个月；情节特别严重或者逾期不改正的，取消其政府采购代理机构资格。"},{"i":52,"n":"第五十二条","txt":"采购人有下列情形之一的，责令限期改正，给予警告；有关法律、行政法规规定处以罚款的，并处罚款： （一）未按照政府采购法和本办法的规定采用非招标采购方式的； （二）未按照政府采购法和本办法的规定确定成交供应商的； （三）未按照采购文件确定的事项签订政府采购合同，或者与成交供应商另行订立背离合同实质性内容的协议的； （四）未按规定将政府采购合同副本报本级财政部门备案的。"},{"i":53,"n":"第五十三条","txt":"采购人、采购代理机构有本办法第五十一条、第五十二条规定情形之一，且情节严重或者拒不改正的，其直接负责的主管人员和其他直接责任人员属于国家机关工作人员的，由任免机关或者监察机关依法给予处分，并予通报。"},{"i":54,"n":"第五十四条","txt":"成交供应商有下列情形之一的，责令限期改正，情节严重的，列入不良行为记录名单，在1至 3年内禁止参加政府采购活动，并予以通报： （一）未按照采购文件确定的事项签订政府采购合同，或者与采购人另行订立背离合同实质性内容的协议的； （二）成交后无正当理由不与采购人签订合同的； （三）拒绝履行合同义务的。"},{"i":55,"n":"第五十五条","txt":"谈判小组、询价小组成员有下列行为之一的，责令改正，给予警告；有关法律、行政法规规定处以罚款的，并处罚款；涉嫌犯罪的，依法移送司法机关处理： （一）收受采购人、采购代理机构、供应商、其他利害关系人的财物或者其他不正当利益的； （二）泄露评审情况以及评审过程中获悉的国家秘密、商业秘密的； （三）明知与供应商有利害关系而不依法回避的； （四）在评审过程中擅离职守，影响评审程序正常进行的； （五）在评审过程中有明显不合理或者不正当倾向性的； （六）未按照采购文件规定的评定成交的标准进行评审的。 评审专家有前款情形之一，情节严重的，取消其政府采购评审专家资格，不得再参加任何政府采购项目的评审，并在财政部门指定的政府采购信息发布媒体上予以公告。"},{"i":56,"n":"第五十六条","txt":"有本办法第五十一条、第五十二条、第五十五条违法行为之一，并且影响或者可能影响成交结果的，应当按照下列情形分别处理： （一）未确定成交供应商的，终止本次采购活动，依法重新开展采购活动； （二）已确定成交供应商但采购合同尚未履行的，撤销合同，从合格的成交候选人中另行确定成交供应商，没有合格的成交候选人的，重新开展采购活动； （三）采购合同已经履行的，给采购人、供应商造成损失的，由责任人依法承担赔偿责任。"},{"i":57,"n":"第五十七条","txt":"政府采购当事人违反政府采购法和本办法规定，给他人造成损失的，应当依照有关民事法律规定承担民事责任。"},{"i":58,"n":"第五十八条","txt":"任何单位或者个人非法干预、影响评审过程或者结果的，责令改正；该单位责任人或者个人属于国家机关工作人员的，由任免机关或者监察机关依法给予处分。"},{"i":59,"n":"第五十九条","txt":"财政部门工作人员在实施监督管理过程中违法干预采购活动或者滥用职权、玩忽职守、徇私舞弊的，依法给予处分；涉嫌犯罪的，依法移送司法机关处理。"},{"i":60,"n":"第六十条","txt":"本办法所称主管预算单位是指负有编制部门预算职责，向同级财政部门申报预算的国家机关、事业单位和团体组织。"},{"i":61,"n":"第六十一条","txt":"各省、自治区、直辖市人民政府财政部门可以根据本办法制定具体实施办法。"},{"i":62,"n":"第六十二条","txt":"本办法自2014年2月1日起施行。"}],"zhucekuaijishiquanguotongyikaoshibanfa":[{"i":1,"n":"第一条","txt":"为规范注册会计师全国统一考试工作，根据《中华人民共和国注册会计师法》，制定本办法。"},{"i":2,"n":"第二条","txt":"财政部成立注册会计师考试委员会（以下简称财政部考委会），组织领导注册会计师全国统一考试工作。财政部考委会设立注册会计师考试委员会办公室（以下简称财政部考办），组织实施注册会计师全国统一考试工作。财政部考办设在中国注册会计师协会。 各省、自治区、直辖市财政厅（局）成立地方注册会计师考试委员会（以下简称地方考委会），组织领导本地区注册会计师全国统一考试工作。地方考委会设立地方注册会计师考试委员会办公室（以下简称地方考办），组织实施本地区注册会计师全国统一考试工作。地方考办设在各省、自治区、直辖市注册会计师协会。"},{"i":3,"n":"第三条","txt":"财政部考委会确定考试组织工作原则，制定考试工作方针、政策，审定考试大纲，确定考试命题原则，处理考试组织工作的重大问题，指导地方考委会工作。 地方考委会贯彻、实施财政部考委会的决定，处理本地区考试组织工作的重大问题。"},{"i":4,"n":"第四条","txt":"符合下列条件的中国公民，可以报名参加注册会计师全国统一考试： （一）具有完全民事行为能力； （二）具有高等专科以上学校毕业学历、或者具有会计或者相关专业中级以上技术职称。"},{"i":5,"n":"第五条","txt":"有下列情形之一的人员，不得报名参加注册会计师全国统一考试： （一）因被吊销注册会计师证书，自处罚决定之日起至申请报名之日止不满5年者； （二）以前年度参加注册会计师全国统一考试因违规而受到停考处理期限未满者。"},{"i":6,"n":"第六条","txt":"考试划分为专业阶段考试和综合阶段考试。考生在通过专业阶段考试的全部科目后，才能参加综合阶段考试。 专业阶段考试设会计、审计、财务成本管理、公司战略与风险管理、经济法、税法6个科目；综合阶段考试设职业能力综合测试1个科目。 每科目考试的具体时间，在各年度财政部考委会发布的《注册会计师全国统一考试报名简章》中明确。 考试范围在各年度财政部考委会发布的《注册会计师全国统一考试大纲》中确定。"},{"i":7,"n":"第七条","txt":"考试方式为闭卷、笔试。"},{"i":8,"n":"第八条","txt":"报名参加考试的人员报名时需要交纳考试报名费。报名费标准按各省、自治区、直辖市价格主管部门、财政部门制定的相关规定执行。"},{"i":9,"n":"第九条","txt":"报名的具体时间在各年度财政部考委会发布的《注册会计师全国统一考试报名简章》中规定，地方考委会应当据此确定本地区具体报名日期，并向社会公告。"},{"i":10,"n":"第十条","txt":"报名人员可以在一次考试中同时报考专业阶段考试 6个科目，也可以选择报考部分科目。"},{"i":11,"n":"第十一条","txt":"具有会计或者相关专业高级技术职称的人员，可以申请免予专业阶段考试1个专长科目的考试。"},{"i":12,"n":"第十二条","txt":"应考人员答卷由财政部考办集中组织评阅，考试成绩由财政部考委会负责认定，由地方考办通知应考人员。 每科考试均实行百分制，60分为成绩合格分数线。"},{"i":13,"n":"第十三条","txt":"专业阶段考试的单科考试合格成绩5年内有效。对在连续5个年度考试中取得专业阶段考试全部科目考试合格成绩的考生，财政部考委会颁发注册会计师全国统一考试专业阶段考试合格证书。 综合阶段考试科目应在取得注册会计师全国统一考试专业阶段考试合格证书后5个年度考试中完成。对取得综合阶段考试科目考试合格成绩的考生，财政部考委会颁发注册会计师全国统一考试全科考试合格证书。 注册会计师全国统一考试专业阶段考试合格证书由考生向参加专业阶段考试最后一科考试所在地的地方考办领取。注册会计师全国统一考试全科考试合格证书由考生向参加职业能力综合测试科目考试所在地的地方考办领取。"},{"i":14,"n":"第十四条","txt":"参加注册会计师全国统一考试的人员及组织考试相关人员，必须遵守注册会计师全国统一考试的相关规则、守则等，违者按照《注册会计师全国统一考试违规行为处理办法》予以处理。"},{"i":15,"n":"第十五条","txt":"注册会计师全国统一考试的试题、参考答案和评分标准按照国家秘密管理。 每科目考试的试题、参考答案和评分标准的保密期限，从该科目当年命题开始至该科目考试结束前允许考生离开考场的时间止。"},{"i":16,"n":"第十六条","txt":"香港特别行政区、澳门特别行政区、台湾地区居民及外国人参加注册会计师全国统一考试办法，由财政部另行规定。"},{"i":17,"n":"第十七条","txt":"本办法自公布之日起施行。 2001年 8月1日财政部发布的《注册会计师全国统一考试办法》（财会[2001]1053号）同时废止。 本办法公布前，已经参加注册会计师全国统一考试并取得2005年度至2008年度任一考试科目合格成绩的考生，以及已经获准免试或者豁免注册会计师全国统一考试部分考试科目的考生，参加2009年注册会计师全国统一考试的办法，由财政部另行规定。 2009.3.23"}],"zhucekuaijishiquanguotongyikaoshiweiguixingweichulc32882":[{"i":1,"n":"第一条","txt":"为加强注册会计师全国统一考试（以下简称注册会计师考试）管理，严肃考试纪律，规范注册会计师考试违规行为的处理，保证注册会计师考试的公平、公正，根据《中华人民共和国注册会计师法》，制定本办法。"},{"i":2,"n":"第二条","txt":"对注册会计师考试应考人员、考试工作人员及其他相关人员违规行为的处理适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称违规行为，是指应考人员、考试工作人员及其他相关人员违反考试纪律和考试工作有关规定的行为。"},{"i":4,"n":"第四条","txt":"本办法所称应考人员，是指参加注册会计师考试的人员。 本办法所称考试工作人员，是指参加组织注册会计师考试报名、命（审）题、印送试卷、监考、试卷评阅、成绩核查、发放成绩或者考试合格证书等工作的人员。 本办法所称其他相关人员，是指应考人员、考试工作人员以外的，与注册会计师考试相关的人员。"},{"i":5,"n":"第五条","txt":"处理违规行为，应当做到事实清楚、证据确凿、程序规范、适用规定准确。"},{"i":6,"n":"第六条","txt":"中国注册会计师协会（以下简称中注协）和省、自治区、直辖市注册会计师协会（以下简称省级注协），依据本办法对应考人员、考试工作人员及其他相关人员的违规行为进行处理。 监考人员依据本办法对应考人员的违规行为进行当场处理，应当及时向中注协和省级注协报告。"},{"i":7,"n":"第七条","txt":"应考人员有伪造或者涂改证件或者证明，或者以其他不正当手段获取考试资格行为的，由中注协给予取消其当年所参加的全部考试科目考试成绩的处理。"},{"i":8,"n":"第八条","txt":"考试实施期间，应考人员有下列行为之一的，由监考人员给予口头警告，并责令改正。经警告仍不改正的，监考人员按照本办法第二十二条规定的程序，终止其本场考试，并责令退出考场；由省级注协给予取消本场考试成绩的处理： （一）携带规定以外的物品进入考场未按照规定放在指定位置的； （二）考试开始30分钟后仍未按照规定填写（填涂）姓名、身份证件号、准考证号，或者粘贴条形码的； （三）使用规定以外的笔和纸答题的； （四）未在规定考场座位参加考试，或者在考试期间擅自离开座位的； （五）在考场内喧哗等影响考场秩序的； （六）考试开始信号发出前答题，或者考试结束信号发出后继续答题的； （七）在答题卡、答题卷上作提示标记或者在非署名处署名的； （八）在规定时间未办理交卷手续离开考场的。"},{"i":9,"n":"第九条","txt":"考试实施期间，应考人员有下列行为之一的，监考人员按照本办法第二十二条规定的程序终止其本场考试，并责令退出考场；由省级注协给予其取消本场考试成绩和不得参加以后连续5个年度注册会计师考试的处理： （一）抄袭或者协助他人抄袭答案或者其他与考试内容有关资料的； （二）以口头或者打手势等方式传递考试信息的； （三）考试开始后被查出携带电子作弊设备、通讯工具以及使用规定以外物品的； （四）交换答题卡、答题卷或者试题卷的； （五）故意损毁答题卡、答题卷或者试题卷，或者将答题卡、答题卷或者试题卷以及草稿纸带出考场的； （六）在允许考生离开考场的时间前强行退出考场的； （七）故意妨碍监考人员履行职责的。"},{"i":10,"n":"第十条","txt":"考试实施期间，应考人员有下列行为之一的，监考人员按照本办法第二十二条规定的程序终止其本场考试，并责令退出考场；由省级注协给予其取消本场考试成绩和终身不得参加注册会计师考试的处理： （一）由他人在考场外协助答题的； （二）利用电子设备、通讯工具等接收或者发送与考试内容相关信息的； （三）由他人冒名代替或者代替他人参加考试的； （四）参与有组织舞弊的； （五）有其他严重扰乱考试秩序行为的。"},{"i":11,"n":"第十一条","txt":"试卷评阅期间，经评卷专家组认定，应考人员试卷有下列情形之一的，由中注协给予其取消本场考试成绩和不得参加以后连续5个年度注册会计师考试的处理： （一）同一试卷答题笔迹前后不一致的； （二）同一科目两份以上（含两份）答卷答案文字表述、主要错点一致的。"},{"i":12,"n":"第十二条","txt":"伪造或者涂改证件或者证明，或者以其他不正当手段获取免予考试资格的，由中注协给予其取消考试成绩或者免予考试的资格和不得参加以后连续5个年度注册会计师考试的处理。"},{"i":13,"n":"第十三条","txt":"伪造注册会计师全国统一考试专业阶段合格证书和注册会计师全国统一考试全科合格证书的，由中注协给予其终身不得参加注册会计师考试的处理。"},{"i":14,"n":"第十四条","txt":"在组织报名、编排考场或者发放准考证期间，考试工作人员有下列行为之一的，由省级注协给予其停止参加当年及以后年度注册会计师考试工作的处理，并视情节轻重给予或者建议所在单位给予相应处分： （一）为不具备参加考试资格的人员提供虚假证明或者证件，使其取得考试资格的； （二）因编排考场或者发放准考证等工作失误，致使应考人员未能如期参加考试，或者使考试工作受到重大影响的。"},{"i":15,"n":"第十五条","txt":"在注册会计师考试试题命制期间以及试题、参考答案和评分标准的保密期限内，考试工作人员有下列行为之一的，由中注协给予其停止参加当年及以后年度注册会计师考试工作的处理，并视情节轻重给予或者建议所在单位给予相应处分： （一）应当回避考试工作而隐瞒不报的； （二）丢失、泄露、盗窃或者损毁试题、参考答案和评分标准的； （三）截留、窃取、擅自开拆、外传未开考试题、参考答案和评分标准的。"},{"i":16,"n":"第十六条","txt":"在考试实施期间，考试工作人员有下列行为之一的，由省级注协给予其停止参加当年及以后年度注册会计师考试工作的处理，并视情节轻重给予或者建议所在单位给予相应处分： （一）擅自为应考人员调换考场或者座位的； （二）未按照规定时间拆启试题的； （三）发现应考人员有违规行为不予制止的； （四）因未认真履行职责，造成所负责的考场秩序混乱的； （五）擅自将答题卡、答题卷、试题卷、考试用纸或者与考试有关内容带出考场或者传递给他人的； （六）强迫或者唆使他人违规，或者参与考场内外串通违规的； （七）应当回避考试工作而隐瞒不报的； （八）考试后擅自拆启已密封的答题卡、答题卷或者试题卷的； （九）擅自变更考试时间、地点或者其他考试安排的。"},{"i":17,"n":"第十七条","txt":"在试卷评阅期间，考试工作人员有下列行为之一的，由中注协给予其停止参加当年及以后年度注册会计师考试工作的处理，并视情节轻重给予或者建议所在单位给予相应处分： （一）有应当回避考试工作情形而未回避的； （二）在评卷中擅自更改评分标准，或者不按评分标准进行评卷的； （三）偷换或者涂改应考人员答卷、考试成绩或者考场原始记录材料的； （四）盗窃或者损毁应考人员答题卡、答题卷的； （五）泄漏有关考试信息的。"},{"i":18,"n":"第十八条","txt":"在考试的日常管理工作中，考试工作人员有下列行为之一的，由中注协或者省级注协给予其停止参加当年及以后年度注册会计师考试工作的处理，并视情节轻重给予或者建议所在单位给予相应处分： （一）擅自更改或者编造考试数据或者信息的； （二）未经批准向社会提供有关考试评卷信息的； （三）以不正当手段协助他人获得免试资格，或者取得单科合格成绩凭证或者全科合格证书的； （四）利用考试工作之便，索贿、受贿或者谋取其他不正当利益的； （五）利用考试工作之便，以权谋私或者打击报复应考人员的； （六）销毁、藏匿或者伪造证据的； （七）阻止他人揭发检举或者提供证据资料的； （八）对揭发检举人打击报复的； （九）干扰或者妨碍中注协或者省级注协调查核实有关情况的。"},{"i":19,"n":"第十九条","txt":"考试工作人员有其他对考试工作造成不良影响行为的，由中注协视情节轻重给予相应处理。"},{"i":20,"n":"第二十条","txt":"考点管理混乱，影响考试工作的，由中注协取消该考点承办注册会计师考试的资格，并视情节轻重，对考点负责人给予或者建议所在单位给予相应处分。"},{"i":21,"n":"第二十一条","txt":"其他相关人员有下列行为之一的，由中注协给予其终身不得参加注册会计师考试的处理，并建议所在单位或相关部门给予相应处分；已经取得注册会计师全国统一考试专业阶段合格证书或者全科合格证书的，由财政部注册会计师考试委员会予以撤销： （一）组织或者参与有组织的集体舞弊行为的； （二）利用电子设备、通讯工具等传送、接收考试信息的； （三）故意破坏、干扰考场监控设施的； （四）妨碍考试工作人员履行职责，或者诬陷、威胁、殴打考试工作人员或应考人员的； （五）组织替考或代替他人参加考试的； （六）蓄意散布有关考试的虚假信息，造成严重后果的； （七）其他严重扰乱考试秩序的行为。"},{"i":22,"n":"第二十二条","txt":"监考人员对应考人员当场作出终止本场考试，并责令退出考场处理的，应当由2名监考人员对其违规行为进行认定，在应考人员违规情况报告单中记录其违规情况，并在其答题卡和答题卷页首空白处签注“违规”字样。记录的内容应当当场告知应考人员。"},{"i":23,"n":"第二十三条","txt":"监考人员对应考人员的违规证据，应按有关规定采取必要的保全措施。其中对应考人员违规使用的物品进行暂扣的，应当填写清单，并在7日内退还应考人员。"},{"i":24,"n":"第二十四条","txt":"考试结束后，监考人员应当将应考人员违规情况报告单，连同应考人员的答题卡、答题卷及有关证据按照有关规定一并报送考试所在地省级注协。"},{"i":25,"n":"第二十五条","txt":"省级注协应当依据本办法和应考人员违规情况报告单记录的情况及相关证据，对违规行为给予处理。 省级注协在对应考人员给予不得参加以后连续5个年度注册会计师考试或者终身不得参加注册会计师考试的处理之前，应当报经中注协核准。 省级注协作出的全部处理决定应当报中注协备案。"},{"i":26,"n":"第二十六条","txt":"考试工作人员在试卷评阅期间发现有异常试卷的，应当填写异常试卷报告单，并按照工作程序核实后，提交中注协。 中注协应当按照规定的程序提交评卷专家组进行认定。"},{"i":27,"n":"第二十七条","txt":"中注协和省级注协在对应考人员、考试工作人员和其他相关人员违规行为作出处理决定前，应当告知当事人作出处理决定的事实、理由及依据，并告知当事人有权进行陈述和申辨。 作出不得参加以后连续5个年度注册会计师考试或者终身不得参加注册会计师考试决定之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，应当组织听证。"},{"i":28,"n":"第二十八条","txt":"中注协和省级注协对违规行为作出处理决定的，应当制作违规行为处理决定书，并将处理决定书及时送达被处理人。 直接送达有困难的，可以采取委托送达、邮寄送达或公告送达等方式送达。"},{"i":29,"n":"第二十九条","txt":"违规行为处理决定书应当载明下列事项： （一）被处理人姓名、身份证件号及准考证号； （二）违规的事实和证据； （三）处理的依据和结果； （四）不服处理决定，申请行政复议或者提起行政诉讼的途径和期限； （五）作出处理决定的单位名称和日期。 处理决定书应当盖有作出处理决定单位的印章。"},{"i":30,"n":"第三十条","txt":"中注协和省级注协应当受理对违规行为的举报，并进行核实、处理。"},{"i":31,"n":"第三十一条","txt":"中注协对应考人员、考试工作人员和其他相关人员违规行为进行处理的，应当向社会公布相关信息并向受到处理的人员所在单位通报有关情况。"},{"i":32,"n":"第三十二条","txt":"财政部注册会计师考试委员会作出撤销注册会计师全国统一考试专业阶段合格证书或者全科合格证书决定的程序，按照行政处罚法的规定执行。"},{"i":33,"n":"第三十三条","txt":"应考人员、考试工作人员及其他相关人员有本办法规定的违规行为，涉嫌违反治安管理规定的，移送公安机关处理；涉嫌犯罪的，移送司法机关处理。"},{"i":34,"n":"第三十四条","txt":"本办法自2010年3月1日起施行。2006年8月9日财政部发布的《注册会计师全国统一考试违规行为处理办法》（财政部令第40号）同时废止。"}],"zhucekuaijishizhucebanfa":[{"i":1,"n":"第一条","txt":"为了规范注册会计师注册工作，根据《中华人民 共和国注册会计师法》及相关法律，制定本办法。"},{"i":2,"n":"第二条","txt":"申请注册成为注册会计师适用本办法。"},{"i":3,"n":"第三条","txt":"省、自治区、直辖市注册会计师协会 （以下简称“省级注册会计师协会”）负责本地区注册会计师的注册及相关管理工作。中国注册会计师协会对省级注册会计师协会的注册管理工作进行指导。 注册会计师依法执行业 务，应当取得财政部统一制定的中华人民共和国注册会计师证书（以下简称“注册会计师证书”）。"},{"i":4,"n":"第四条","txt":"具备下列条件之一，并在中国境内从事审计业务 工作2年以上者，可以向省级注册会计师协会申请注册： （一）参加注册会计师全 国统一考试成绩合格； （二）经依法认定或者考 核具有注册会计师资格。"},{"i":5,"n":"第五条","txt":"注册申请人有下列情形之一的，不予注册： （一）不具有完全民事行 为能力的； （二）因受刑事处罚，自 刑罚执行完毕之日起至申请注册之日止不满5年的； （三）因在财务、会计、 审计、企业管理或者其他经济管理工作中犯有严重错误受行政处罚、撤职以上处分，自处罚、处分决定生效之日起至申请注册之日止不满2年的； （四）受吊销注册会计师 证书的处罚，自处罚决定生效之日起至申请注册之日止不满5年的； （五）因以欺骗、贿赂等 不正当手段取得注册会计师证书而被撤销注册，自撤销注册决定生效之日起至申请注册之日止不满3年的； （六）不在会计师事务所 专职执业的； （七）年龄超过 70周岁的。"},{"i":6,"n":"第六条","txt":"注册申请人申请注册，应当通过所在的会计师事 务所向会计师事务所所在地的省级注册会计师协会提交下列材料： （一）注册会计师注册申 请表（附表1）； （二）注册会计师全国统 一考试全科合格证书复印件； （三） 2名注册会计师出具的注册申请人从事审计业务2年以上证明表（附表2）； （四）与所在会计师事务 所签定的聘用合同复印件； （五）有效身份证件或者 身份证明复印件（外国人应当提交护照和签证复印件，香港、澳门特别行政区及台湾地区居民应当提交在香港、澳门特别行政区及台湾地区的身份证件复印件和 中国出入境行政管理部门发放的通行证复印件替代此项材料）； （六）有效人事档案证明 或者退休证明复印件（外国人和香港、澳门特别行政区及台湾地区居民应当提交由中国劳动行政管理部门发放的就业证复印件替代此项材料）。 经依法认定或者考核具有 注册会计师资格的，应当提交相关文件和符合认定或者考核条件的相关证明，替"},{"i":7,"n":"第七条","txt":"注册申请人和所在的会计师事务所应当对申请材 料内容的真实性负责，证明人应当对证明材料内容的真实性负责。"},{"i":8,"n":"第八条","txt":"省级注册会计师协会应当在受理注册申请的办公 场所将申请注册应当提交的材料目录及要求、准予注册的程序及期限，以及不予注册的情形予以公示。"},{"i":9,"n":"第九条","txt":"省级注册会计师协会收到注册申请人提交的申请 材料后，应当对注册申请人提交的申请材料进行形式审查，并核对有关复印件与原件是否相符。对申请材料不齐全或者不符合法定形式的注册申请人，应当当场或者在 5个工作日内一次告知其需要补正的全部材料及内容。 对申请材料齐全、符合法 定形式，或者按照要求提交全部补正申请材料的注册申请人，应当受理其注册申请。"},{"i":10,"n":"第十条","txt":"省级注册会计师协会受理或者不予受理注册申 请，应当向注册申请人出具加盖本单位专用印章和注明日期的书面凭证。"},{"i":11,"n":"第十一条","txt":"省级注册会计师协会应当对申请材料的内容进行审查，并自受理 注册申请之日起20个工作日内作出准予或者不予注册的决定。20个工作日内不能作出决定的，经省级注册会计师协会负责人批准，可以延长10个工作日，并应当将延长期限的理由 告知注册申请人。"},{"i":12,"n":"第十二条","txt":"省级注册会计师协会作出准予注册决定的，应当自作出决 定之日起10个 工作日内向注册申请人颁发注册会计师证书。 省级注册会计师协会应当 自作出准予注册决定之日起20个工作日内，将准予注册的决定和注册会计师注册备案表（附表3）报送财政部、中国注册会计师协会备案，抄报所在地的省、自治区、直辖市人民政府财政部门（以下简称“省级财政部门”）并将准予注册人员的名单在全国 性报刊或者相关网站上予以公告。"},{"i":13,"n":"第十三条","txt":"省级注册会计师协会作出不予注册决定的，应当 自作出决定之日起15个工作日内书面通知注册申请人。书面通知中应当说明不予注册的理由，并告知注册申请人享有依法申请行政 复议或者提起行政诉讼的权利。"},{"i":14,"n":"第十四条","txt":"财政部依法对省级注册会计师协会的注册工作进 行检查，发现注册不符合本办法规定的，应当通知省级注册会计师协会撤销注册。"},{"i":15,"n":"第十五条","txt":"中国注册会计师协会和省级注册会计师协会应当 对注册会计师的任职资格和执业情况进行监督检查，必要时可以进行实地检查。"},{"i":16,"n":"第十六条","txt":"注册会计师有下列情形之一的，由所在地的省级注册会计师协会 撤销注册，收回注册会计师证书： （一）完全丧失民事行为 能力的； （二）受刑事处罚的； （三）自行停止执行注册 会计师业务满1年的； （四）以欺骗、贿赂等不 正当手段取得注册会计师证书的。"},{"i":17,"n":"第十七条","txt":"省级注册会计师协会工作人员滥用职权、玩忽职守准予注册的， 或者对不具备申请资格或不符合法定条件的申请人准予注册的，由省级注册会计师协会撤销注册，收回注册会计师证书。"},{"i":18,"n":"第十八条","txt":"被撤销注册的人员可以重新申请注册，但必须符 合本办法第四条规定条件，并且没有本办法第五条规定所列情形。"},{"i":19,"n":"第十九条","txt":"注册会计师有下列情形之一的，由所在地的省级注册会计师协会 注销注册： （一）依法被撤销注册， 或者吊销注册会计师证书的； （二）不在会计师事务所 专职执业的。"},{"i":20,"n":"第二十条","txt":"省级注册会计师协会应当将注销注册的决定抄报 财政部和所在地的省级财政部门、中国注册会计师协会，并自作出决定之日起10个工作日内将注销注册人员的名单在全国性报刊或者相 关网站上予以公告。"},{"i":21,"n":"第二十一条","txt":"注册会计师违反《中华人民共和国注册会计师 法》第二十条、第二十一条规定，由财政部或者所在地的省级财政部门给予警告；情节严重的，可以由财政部或者所在地的省级财政部门暂停其执行业务或者吊销注册会计师证书。 财政部和省级财政部门应 当按照《中华人民共和国行政处罚法》及有关规定实施行政处罚，并将行政处罚决定抄送中国注册会计师协会和注册会计师所在地的省级注册会计师协会。"},{"i":22,"n":"第二十二条","txt":"受到行政处罚，或者被撤销注册或注销注册的当 事人有异议的，可以依法申请行政复议或者提起行政诉讼。"},{"i":23,"n":"第二十三条","txt":"香港、澳门特别行政区和台湾地区居民以及按照互惠原则确认的外国人申请注册，依照本办法办理。"},{"i":24,"n":"第二十四条","txt":"本办法自2005年3月1日起施行。 自本办法施行之日起， 《注册会计师注册审批暂行办法》（93）财会协字第122号、《外籍中国注册会计师注册审批暂行办法》（财协字[1998]9号）、《〈外籍中国注册会计师注册审批暂行办法〉的补充规定》（财会[2003]34号）同时废止。 附件省略"}],"xingzhengdanweiguoyouzichanguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范和加强行政单位国有资产管理，维护国有资产的安全和完整，合理配置国有资产，提高国有资产使用效益，保障行政单位履行职能，根据国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于各级党的机关、人大机关、行政机关、政协机关、审判机关、检察机关和各民主党派机关（以下统称行政单位）的国有资产管理行为。"},{"i":3,"n":"第三条","txt":"本办法所称的行政单位国有资产，是指由各级行政单位占有、使用的，依法确认为国家所有，能以货币计量的各种经济资源的总称，即行政单位的国有（公共）财产。 行政单位国有资产包括行政单位用国家财政性资金形成的资产、国家调拨给行政单位的资产、行政单位按照国家规定组织收入形成的资产，以及接受捐赠和其他经法律确认为国家所有的资产，其表现形式为固定资产、流动资产和无形资产等。"},{"i":4,"n":"第四条","txt":"行政单位国有资产管理的主要任务是: （一）建立和健全各项规章制度; （二）推动国有资产的合理配置和有效使用; （三）保障国有资产的安全和完整; （四）监管尚未脱钩的经济实体的国有资产，实现国有资产的保值增值。"},{"i":5,"n":"第五条","txt":"行政单位国有资产管理的内容包括:资产配置、资产使用、资产处置、资产评估、产权界定、产权纠纷调处、产权登记、资产清查、资产统计报告和监督检查等。"},{"i":6,"n":"第六条","txt":"行政单位国有资产管理活动，应当遵循以下原则: （一）资产管理与预算管理相结合; （二）资产管理与财务管理相结合; （三）实物管理与价值管理相结合。"},{"i":7,"n":"第七条","txt":"行政单位国有资产管理，实行国家统一所有，政府分级监管，单位占有、使用的管理体制。"},{"i":8,"n":"第八条","txt":"各级财政部门是政府负责行政单位国有资产管理的职能部门，对行政单位国有资产实行综合管理。其主要职责是: （一）贯彻执行国家有关国有资产管理的法律、法规和政策; （二）根据国家国有资产管理的有关规定，制定行政单位国有资产管理的规章制度，并对执行情况进行监督检查; （三）负责会同有关部门研究制定本级行政单位国有资产配置标准，负责资产配置事项的审批，按规定进行资产处置和产权变动事项的审批，负责组织产权界定、产权纠纷调处、资产统计报告、资产评估、资产清查等工作; （四）负责本级行政单位出租、出借国有资产的审批，负责与行政单位尚未脱钩的经济实体的国有资产的监督管理; （五）负责本级行政单位国有资产收益的监督、管理; （六）对本级行政单位和下级财政部门的国有资产管理工作进行监督、检查; （七）向本级政府和上级财政部门报告有关国有资产管理工作。"},{"i":9,"n":"第九条","txt":"行政单位对本单位占有、使用的国有资产实施具体管理。其主要职责是: （一）根据行政单位国有资产管理的规定，负责制定本单位国有资产管理具体办法并组织实施; （二）负责本单位国有资产的账卡管理、清查登记、统计报告及日常监督检查等工作; （三）负责本单位国有资产的采购、验收、维修和保养等日常管理工作，保障国有资产的安全完整; （四）负责办理本单位国有资产的配置、处置、出租、出借等事项的报批手续; （五）负责与行政单位尚未脱钩的经济实体的国有资产的具体监督管理工作并承担保值增值的责任; （六）接受财政部门的指导和监督，报告本单位国有资产管理情况。"},{"i":10,"n":"第十条","txt":"财政部门根据工作需要，可以将国有资产管理的部分工作交由有关单位完成。有关单位应当完成所交给的国有资产管理工作，向财政部门负责，并报告工作的完成情况。"},{"i":11,"n":"第十一条","txt":"各级财政部门和行政单位应当明确国有资产管理的机构和人员，加强行政单位国有资产管理工作。"},{"i":12,"n":"第十二条","txt":"行政单位国有资产配置应当遵循以下原则: （一）严格执行法律、法规和有关规章制度; （二）与行政单位履行职能需要相适应; （三）科学合理，优化资产结构; （四）勤俭节约，从严控制。"},{"i":13,"n":"第十三条","txt":"对有规定配备标准的资产，应当按照标准进行配备;对没有规定配备标准的资产，应当从实际需要出发，从严控制，合理配备。财政部门对要求配置的资产，能通过调剂解决的，原则上不重新购置。"},{"i":14,"n":"第十四条","txt":"购置有规定配备标准的资产，除国家另有规定外，应当按下列程序报批: （一）行政单位的资产管理部门会同财务部门审核资产存量，提出拟购置资产的品目、数量，测算经费额度，经单位负责人审核同意后报同级财政部门审批，并按照同级财政部门要求提交相关材料; （二）同级财政部门根据单位资产状况对行政单位提出的资产购置项目进行审批; （三）经同级财政部门审批同意，各单位可以将资产购置项目列入单位年度部门预算，并在编制年度部门预算时将批复文件和相关材料一并报同级财政部门，作为审批部门预算的依据。未经批准，不得列入部门预算，也不得列入单位经费支出。"},{"i":15,"n":"第十五条","txt":"经批准召开重大会议、举办大型活动等需要购置资产的，由会议或者活动主办单位按照本办法规定程序报批。"},{"i":16,"n":"第十六条","txt":"行政单位购置纳入政府采购范围的资产，依法实施政府采购。"},{"i":17,"n":"第十七条","txt":"行政单位资产管理部门应当对购置的资产进行验收、登记，并及时进行账务处理。"},{"i":18,"n":"第十八条","txt":"行政单位应当建立健全国有资产使用管理制度，规范国有资产使用行为。"},{"i":19,"n":"第十九条","txt":"行政单位应当认真做好国有资产的使用管理工作，做到物尽其用，充分发挥国有资产的使用效益;保障国有资产的安全完整，防止国有资产使用中的不当损失和浪费。"},{"i":20,"n":"第二十条","txt":"行政单位对所占有、使用的国有资产应当定期清查盘点，做到家底清楚，账、卡、实相符，防止国有资产流失。"},{"i":21,"n":"第二十一条","txt":"行政单位应当建立严格的国有资产管理责任制，将国有资产管理责任落实到人。"},{"i":22,"n":"第二十二条","txt":"行政单位不得用国有资产对外担保，法律另有规定的除外。"},{"i":23,"n":"第二十三条","txt":"行政单位不得以任何形式用占有、使用的国有资产举办经济实体。在本办法颁布前已经用占有、使用的国有资产举办经济实体的，应当按照国家关于党政机关与所办经济实体脱钩的规定进行脱钩。脱钩之前，行政单位应当按照国家有关规定对其经济实体的经济效益、收益分配及使用情况等进行严格监管。 财政部门应当对其经济效益、收益分配及使用情况进行监督检查。"},{"i":24,"n":"第二十四条","txt":"行政单位拟将占有、使用的国有资产对外出租、出借的，必须事先上报同级财政部门审核批准。未经批准，不得对外出租、出借。 同级财政部门应当根据实际情况对行政单位国有资产对外出租、出借事项严格控制，从严审批。"},{"i":25,"n":"第二十五条","txt":"行政单位出租、出借的国有资产，其所有权性质不变，仍归国家所有;所形成的收入，按照政府非税收入管理的规定，实行“收支两条 线” 管理。"},{"i":26,"n":"第二十六条","txt":"对行政单位中超标配置、低效运转或者长期闲置的国有资产，同级财政部门有权调剂使用或者处置。"},{"i":27,"n":"第二十七条","txt":"行政单位国有资产处置，是指行政单位国有资产产权的转移及核销，包括各类国有资产的无偿转让、出售、置换、报损、报废等。"},{"i":28,"n":"第二十八条","txt":"行政单位需处置的国有资产范围包括: （一）闲置资产; （二）因技术原因并经过科学论证，确需报废、淘汰的资产; （三）因单位分立、撤销、合并、改制、隶属关系改变等原因发生的产权或者使用权转移的资产; （四）盘亏、呆账及非正常损失的资产; （五）已超过使用年限无法使用的资产; （六）依照国家有关规定需要进行资产处置的其他情形。"},{"i":29,"n":"第二十九条","txt":"行政单位处置国有资产应当严格履行审批手续，未经批准不得处置。"},{"i":30,"n":"第三十条","txt":"资产处置应当由行政单位资产管理部门会同财务部门、技术部门审核鉴定，提出意见，按审批权限报送审批。"},{"i":31,"n":"第三十一条","txt":"行政单位国有资产处置的审批权限和处置办法，除国家另有规定外，由财政部门根据本办法规定。"},{"i":32,"n":"第三十二条","txt":"行政单位国有资产处置应当按照公开、公正、公平的原则进行。资产的出售与置换应当采取拍卖、招投标、协议转让及国家法律、行政法规规定的其他方式进行。"},{"i":33,"n":"第三十三条","txt":"行政单位国有资产处置的变价收入和残值收入，按照政府非税收入管理的规定，实行“收支两条 线”管理。"},{"i":34,"n":"第三十四条","txt":"行政单位分立、撤销、合并、改制及隶属关系发生改变时，应当对其占有、使用的国有资产进行清查登记，编制清册，报送财政部门审核、处置，并及时办理资产转移手续。"},{"i":35,"n":"第三十五条","txt":"行政单位联合召开重大会议、举办大型活动等而临时购置的国有资产，由主办单位在会议、活动结束时按照本办法规定报批后处置。"},{"i":36,"n":"第三十六条","txt":"行政单位有下列情形之一的，应当对相关资产进行评估: （一）行政单位取得的没有原始价格凭证的资产; （二）拍卖、有偿转让、置换国有资产; （三）依照国家有关规定需要进行资产评估的其他情形。"},{"i":37,"n":"第三十七条","txt":"行政单位国有资产评估项目实行核准制和备案制。实行核准制和备案制的项目范围、权限由财政部门另行规定。"},{"i":38,"n":"第三十八条","txt":"行政单位国有资产评估工作应当委托具有资产评估资质的资产评估机构进行。"},{"i":39,"n":"第三十九条","txt":"进行资产评估的行政单位，应当如实提供有关情况和资料，并对所提供的情况和资料的客观性、真实性和合法性负责，不得以任何形式干预评估机构独立执业。"},{"i":40,"n":"第四十条","txt":"产权纠纷是指由于财产所有权、经营权、使用权等产权归属不清而发生的争议。"},{"i":41,"n":"第四十一条","txt":"行政单位之间的产权纠纷，由当事人协商解决。协商不能解决的，由财政部门或者同级政府调解、裁定。"},{"i":42,"n":"第四十二条","txt":"行政单位与非行政单位、组织或者个人之间发生产权纠纷，由行政单位提出处理意见，并报经财政部门同意后，与对方当事人协商解决。协商不能解决的，依照司法程序处理。"},{"i":43,"n":"第四十三条","txt":"行政单位应当建立资产登记档案，并严格按照财政部门的要求做出报告。 财政部门、行政单位应当建立和完善资产管理信息系统，对国有资产实行动态管理。"},{"i":44,"n":"第四十四条","txt":"行政单位报送资产统计报告，应当做到真实、准确、及时、完整，并对国有资产占有、使用、变动、处置等情况做出文字分析说明。财政部门与行政单位应当对国有资产实行绩效管理，监督资产使用的有效性。"},{"i":45,"n":"第四十五条","txt":"财政部门应当对行政单位资产统计报告进行审核批复，必要时可以委托有关单位进行审计。经财政部门审核批复的统计报告，应当作为预算管理和资产管理的依据和基础。"},{"i":46,"n":"第四十六条","txt":"财政部门可以根据工作需要，组织开展资产清查工作。进行资产清查的实施办法，由县级以上人民政府财政部门另行制定。"},{"i":47,"n":"第四十七条","txt":"财政部门可以根据国有资产统计工作的需要，开展行政单位国有资产产权登记工作。产权登记办法，由开展产权登记的财政部门制定并负责组织实施。"},{"i":48,"n":"第四十八条","txt":"财政部门、行政单位及其工作人员，应当认真履行国有资产管理职责，依法维护国有资产的安全、完整。"},{"i":49,"n":"第四十九条","txt":"财政部门、行政单位应当加强国有资产管理和监督，坚持单位内部监督与财政监督、审计监督、社会监督相结合，事前监督、事中监督、事后监督相结合，日常监督与专项检查相结合。"},{"i":50,"n":"第五十条","txt":"财政部门、行政单位及其工作人员违反本办法的规定，擅自占有、使用、处置国有资产的，按照《财政违法行为处罚处分条 例》处理。违反国家国有资产管理规定的其他行为，按国家有关法律法规处理。"},{"i":51,"n":"第五十一条","txt":"参照公务员制度管理的事业单位和社会团体的国有资产管理依照本办法执行。"},{"i":52,"n":"第五十二条","txt":"行政单位所属独立核算的非公务员管理的事业单位执行事业单位国有资产管理的有关规定，独立核算的企业执行企业国有资产管理的有关规定，不执行本办法。"},{"i":53,"n":"第五十三条","txt":"地方财政部门可以根据本办法及上级财政部门有关国有资产管理的规定，制定本地区和本级行政单位国有资产管理的规章制度，并报上一级财政部门备案。"},{"i":54,"n":"第五十四条","txt":"行政单位境外国有资产管理办法由财政部另行制定。中央级行政单位的国有资产管理实施办法，由财政部会同有关部门根据本办法制定。"},{"i":55,"n":"第五十五条","txt":"中国人民解放军等特定单位占有、使用的国有资产的管理办法，由解放军总后勤部等有关部门会同财政部另行制定。"},{"i":56,"n":"第五十六条","txt":"本办法自2006年7月1日起施行。此前颁布的有关行政单位国有资产管理的规章制度，凡与本办法相抵触的，以本办法为准。"}],"xingzhengdanweicaiwuguize-2":[{"i":1,"n":"第一条","txt":"为了规范行政单位的财务行为，加强行政单位财务管理和监督，提高资金使用效益，保障行政单位工作任务的完成，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于各级各类国家机关、政党组织（以下统称行政单位）的财务活动。"},{"i":3,"n":"第三条","txt":"行政单位财务管理的基本原则是：量入为出，保障重点，兼顾一般，厉行节约，制止奢侈浪费，降低行政成本，注重资金使用效益。"},{"i":4,"n":"第四条","txt":"行政单位财务管理的主要任务是： （一）科学、合理编制预算，严格预算执行，完整、准确、及时编制决算，真实反映单位财务状况； （二）建立健全财务管理制度，实施预算绩效管理，加强对行政单位财务活动的控制和监督； （三）加强资产管理，合理配置、有效利用、规范处置资产，防止国有资产流失； （四）定期编制财务报告，进行财务活动分析； （五）对行政单位所属并归口行政财务管理的单位的财务活动实施指导、监督； （六）加强对非独立核算的机关后勤服务部门的财务管理，实行内部核算办法。"},{"i":5,"n":"第五条","txt":"行政单位的财务活动在单位负责人领导下，由单位财务部门统一管理。 行政单位应当单独设置财务机构，配备专职财务会计人员，实行独立核算。人员编制少、财务工作量小等不具备独立核算条件的单位，可以实行单据报账制度。"},{"i":6,"n":"第六条","txt":"行政单位预算由收入预算和支出预算组成。"},{"i":7,"n":"第七条","txt":"按照预算管理权限，行政单位预算管理分为下列级次： （一）向同级财政部门申报预算的行政单位，为一级预算单位； （二）向上一级预算单位申报预算并有下级预算单位的行政单位，为二级预算单位； （三）向上一级预算单位申报预算，且没有下级预算单位的行政单位，为基层预算单位。 一级预算单位有下级预算单位的，为主管预算单位。"},{"i":8,"n":"第八条","txt":"各级预算单位应当按照预算管理级次申报预算，并按照批准的预算组织实施，定期将预算执行情况向上一级预算单位或者同级财政部门报告。"},{"i":9,"n":"第九条","txt":"财政部门对行政单位实行收支统一管理，定额、定项拨款，超支不补，结转和结余按规定使用的预算管理办法。"},{"i":10,"n":"第十条","txt":"行政单位编制预算，应当综合考虑以下因素： （一）年度工作计划和相应支出需求； （二）以前年度预算执行情况； （三）以前年度结转和结余情况； （四）资产占有和使用情况； （五）其他因素。"},{"i":11,"n":"第十一条","txt":"行政单位预算依照下列程序编报和审批： （一）行政单位测算、提出预算建议数，逐级汇总后报送同级财政部门； （二）财政部门审核行政单位提出的预算建议数，下达预算控制数； （三）行政单位根据预算控制数正式编制年度预算，逐级汇总后报送同级财政部门； （四）经法定程序批准后，财政部门批复行政单位预算。"},{"i":12,"n":"第十二条","txt":"行政单位应当严格执行预算，按照收支平衡的原则，合理安排各项资金，不得超预算安排支出。 预算在执行中原则上不予调整。因特殊情况确需调整预算的，行政单位应当按照规定程序报送审批。"},{"i":13,"n":"第十三条","txt":"行政单位应当按照规定编制决算，逐级审核汇总后报同级财政部门审批。"},{"i":14,"n":"第十四条","txt":"行政单位应当加强决算审核和分析，规范决算管理工作，保证决算数据的完整、真实、准确。"},{"i":15,"n":"第十五条","txt":"收入是指行政单位依法取得的非偿还性资金，包括财政拨款收入和其他收入。 财政拨款收入，是指行政单位从同级财政部门取得的财政预算资金。 其他收入，是指行政单位依法取得的除财政拨款收入以外的各项收入。 行政单位依法取得的应当上缴财政的罚没收入、行政事业性收费、政府性基金、国有资产处置和出租出借收入等，不属于行政单位的收入。"},{"i":16,"n":"第十六条","txt":"行政单位取得各项收入，应当符合国家规定，按照财务管理的要求，分项如实核算。"},{"i":17,"n":"第十七条","txt":"行政单位的各项收入应当全部纳入单位预算，统一核算，统一管理。"},{"i":18,"n":"第十八条","txt":"支出是指行政单位为保障机构正常运转和完成工作任务所发生的资金耗费和损失，包括基本支出和项目支出。 基本支出，是指行政单位为保障机构正常运转和完成日常工作任务发生的支出，包括人员支出和公用支出。 项目支出，是指行政单位为完成特定的工作任务，在基本支出之外发生的支出。"},{"i":19,"n":"第十九条","txt":"行政单位应当将各项支出全部纳入单位预算。 各项支出由单位财务部门按照批准的预算和有关规定审核办理。"},{"i":20,"n":"第二十条","txt":"行政单位的支出应当严格执行国家规定的开支范围及标准，建立健全支出管理制度，对节约潜力大、管理薄弱的支出进行重点管理和控制。"},{"i":21,"n":"第二十一条","txt":"行政单位从财政部门或者上级预算单位取得的项目资金，应当按照批准的项目和用途使用，专款专用、单独核算，并按照规定向同级财政部门或者上级预算单位报告资金使用情况，接受财政部门和上级预算单位的检查监督。 项目完成后，行政单位应当向同级财政部门或者上级预算单位报送项目支出决算和使用效果的书面报告。"},{"i":22,"n":"第二十二条","txt":"行政单位应当严格执行国库集中支付制度和政府采购制度等规定。"},{"i":23,"n":"第二十三条","txt":"行政单位应当加强支出的绩效管理，提高资金的使用效益。"},{"i":24,"n":"第二十四条","txt":"行政单位应当依法加强各类票据管理，确保票据来源合法、内容真实、使用正确，不得使用虚假票据。"},{"i":25,"n":"第二十五条","txt":"结转资金，是指当年预算已执行但未完成，或者因故未执行，下一年度需要按照原用途继续使用的资金。"},{"i":26,"n":"第二十六条","txt":"结余资金，是指当年预算工作目标已完成，或者因故终止，当年剩余的资金。 结转资金在规定使用年限未使用或者未使用完的，视为结余资金。"},{"i":27,"n":"第二十七条","txt":"财政拨款结转和结余的管理，应当按照同级财政部门的规定执行。"},{"i":28,"n":"第二十八条","txt":"资产是指行政单位占有或者使用的，能以货币计量的经济资源，包括流动资产、固定资产、在建工程、无形资产等。"},{"i":29,"n":"第二十九条","txt":"流动资产是指可以在一年内变现或者耗用的资产，包括现金、银行存款、零余额账户用款额度、应收及暂付款项、存货等。 前款所称存货是指行政单位在工作中为耗用而储存的资产，包括材料、燃料、包装物和低值易耗品等。"},{"i":30,"n":"第三十条","txt":"固定资产是指使用期限超过一年，单位价值在1000元以上（其中：专用设备单位价值在1500元以上），并且在使用过程中基本保持原有物质形态的资产。单位价值虽未达到规定标准，但是耐用时间在一年以上的大批同类物资，作为固定资产管理。 固定资产一般分为六类：房屋及构筑物；通用设备；专用设备；文物和陈列品；图书、档案；家具、用具、装具及动植物。"},{"i":31,"n":"第三十一条","txt":"在建工程是指已经发生必要支出，但尚未达到交付使用状态的建设工程。 在建工程达到交付使用状态时，应当按照规定办理工程竣工财务决算和资产交付使用。"},{"i":32,"n":"第三十二条","txt":"无形资产是指不具有实物形态而能为使用者提供某种权利的资产，包括著作权、土地使用权等。"},{"i":33,"n":"第三十三条","txt":"行政单位应当建立健全单位资产管理制度，加强和规范资产配置、使用和处置管理，维护资产安全完整。"},{"i":34,"n":"第三十四条","txt":"行政单位应当按照科学规范、从严控制、保障工作需要的原则合理配置资产。 行政单位资产有原始凭证的，按照原始凭证记账；无原始凭证的，应当依法进行评估，按照评估价值记账。"},{"i":35,"n":"第三十五条","txt":"行政单位应当加强资产日常管理工作，做好资产建账、核算和登记工作，定期或者不定期进行清查盘点，保证账账相符，账实相符。年度终了，应当进行全面清查盘点。对资产盘盈、盘亏应当及时处理。"},{"i":36,"n":"第三十六条","txt":"行政单位开设银行存款账户，应当报同级财政部门审批，并由财务部门统一管理。"},{"i":37,"n":"第三十七条","txt":"行政单位应当加强应收及暂付款项的管理，严格控制规模，并及时进行清理，不得长期挂账。"},{"i":38,"n":"第三十八条","txt":"行政单位的资产增加时，应当及时登记入账；减少时，应当按照资产处置规定办理报批手续，进行账务处理。 行政单位的固定资产不计提折旧，但财政部另有规定的除外。"},{"i":39,"n":"第三十九条","txt":"行政单位不得以任何形式用占有、使用的国有资产对外投资或者举办经济实体。对于未与行政单位脱钩的经济实体，行政单位应当按照有关规定进行监管。 除法律、行政法规另有规定外，行政单位不得举借债务，不得对外提供担保。"},{"i":40,"n":"第四十条","txt":"未经同级财政部门批准，行政单位不得将占有、使用的国有资产对外出租、出借。"},{"i":41,"n":"第四十一条","txt":"行政单位应当按照国家有关规定实行资源共享、装备共建，提高资产使用效率。"},{"i":42,"n":"第四十二条","txt":"行政单位资产处置应当遵循公开、公平、公正的原则，依法进行评估，严格履行相关审批程序。"},{"i":43,"n":"第四十三条","txt":"负债是指行政单位所承担的能以货币计量，需要以资产或者劳务偿还的债务，包括应缴款项、暂存款项、应付款项等。"},{"i":44,"n":"第四十四条","txt":"应缴款项是指行政单位依法取得的应当上缴财政的资金，包括罚没收入、行政事业性收费、政府性基金、国有资产处置和出租出借收入等。"},{"i":45,"n":"第四十五条","txt":"行政单位取得罚没收入、行政事业性收费、政府性基金、国有资产处置和出租出借收入等，应当按照国库集中收缴的有关规定及时足额上缴，不得隐瞒、滞留、截留、挪用和坐支。"},{"i":46,"n":"第四十六条","txt":"暂存款项是行政单位在业务活动中与其他单位或者个人发生的预收、代管等待结算的款项。"},{"i":47,"n":"第四十七条","txt":"行政单位应当加强对暂存款项的管理，不得将应当纳入单位收入管理的款项列入暂存款项；对各种暂存款项应当及时清理、结算，不得长期挂账。"},{"i":48,"n":"第四十八条","txt":"行政单位划转撤并的财务处理，应当在财政部门、主管预算单位等部门的监督指导下进行。 划转撤并的行政单位应当对单位的财产、债权、债务等进行全面清理，编制财产目录和债权、债务清单，提出财产作价依据和债权、债务处理办法，做好资产的移交、接收、划转和管理工作，并妥善处理各项遗留问题。"},{"i":49,"n":"第四十九条","txt":"划转撤并的行政单位的资产经主管预算单位审核并上报财政部门和有关部门批准后，分别按照下列规定处理： （一）转为事业单位和改变隶属关系的行政单位，其资产无偿移交，并相应调整、划转经费指标。 （二）转为企业的行政单位，其资产按照有关规定进行评估作价后，转作企业的国有资本。 （三）撤销的行政单位，其全部资产由财政部门或者财政部门授权的单位处理。 （四）合并的行政单位，其全部资产移交接收单位或者新组建单位；合并后多余的资产，由财政部门或者财政部门授权的单位处理。 （五）分立的行政单位，其资产按照有关规定移交分立后的行政单位，并相应划转经费指标。"},{"i":50,"n":"第五十条","txt":"财务报告是反映行政单位一定时期财务状况和预算执行结果的总结性书面文件。"},{"i":51,"n":"第五十一条","txt":"行政单位的财务报告，包括财务报表和财务情况说明书。 财务报表包括资产负债表、收入支出表、支出明细表、财政拨款收入支出表、固定资产投资决算报表等主表及有关附表。 财务情况说明书，主要说明行政单位本期收入、支出、结转、结余、专项资金使用及资产负债变动等情况，以及影响财务状况变化的重要事项，总结财务管理经验，对存在的问题提出改进意见。"},{"i":52,"n":"第五十二条","txt":"财务分析是依据会计核算资料和其他有关信息资料，对单位财务活动过程及其结果进行的研究、分析和评价。"},{"i":53,"n":"第五十三条","txt":"财务分析的内容包括预算编制与执行情况、收入支出状况、人员增减情况、资产使用情况等。 财务分析的指标主要有：支出增长率、当年预算支出完成率、人均开支、项目支出占总支出的比率、人员支出占总支出的比率、公用支出占总支出的比率、人均办公使用面积、人车比例等。 行政单位可以根据其业务特点，增加财务分析指标。"},{"i":54,"n":"第五十四条","txt":"行政单位应当真实、准确、完整、及时地编制财务报告，认真进行财务分析，并按照规定报送财政部门、主管预算单位和其他有关部门。"},{"i":55,"n":"第五十五条","txt":"行政单位财务监督主要包括对预算管理、收入管理、支出管理、结转和结余管理、资产管理、负债管理等的监督。"},{"i":56,"n":"第五十六条","txt":"行政单位财务监督应当实行事前监督、事中监督、事后监督相结合，日常监督与专项监督相结合，并对违反财务规章制度的问题进行检查处理。"},{"i":57,"n":"第五十七条","txt":"行政单位应当建立健全内部控制制度、经济责任制度、财务信息披露制度等监督制度，依法公开财务信息。"},{"i":58,"n":"第五十八条","txt":"行政单位应当依法接受主管预算单位和财政、审计部门的监督。"},{"i":59,"n":"第五十九条","txt":"财政部门、行政单位及其工作人员违反本规则，按照《财政违法行为处罚处分条例》（国务院令第 427号）处理。"},{"i":60,"n":"第六十条","txt":"行政单位基本建设投资的财务管理，应当执行本规则，但国家基本建设投资财务管理制度另有规定的，从其规定。"},{"i":61,"n":"第六十一条","txt":"参照公务员法管理的事业单位财务制度的适用，由财政部另行规定。 行政单位所属独立核算的企业、事业单位分别执行相应的财务制度，不执行本规则。"},{"i":62,"n":"第六十二条","txt":"省、自治区、直辖市人民政府财政部门可以依据本规则结合本地区实际情况制定实施办法。"},{"i":63,"n":"第六十三条","txt":"本规则自2013年1月1日起施行。 附：行政单位财务分析指标 1.支出增长率，衡量行政单位支出的增长水平。计算公式为： 支出增长率＝(本期支出总额÷上期支出总额-1)×100% 2.当年预算支出完成率，衡量行政单位当年支出总预算及分项预算完成的程度。计算公式为： 当年预算支出完成率＝年终执行数÷（年初预算数±年中预算调整数）×100% 年终执行数不含上年结转和结余支出数。 3.人均开支，衡量行政单位人均年消耗经费水平。计算公式为： 人均开支＝本期支出数÷本期平均在职人员数×100% 4.项目支出占总支出的比率，衡量行政单位的支出结构。计算公式为： 项目支出比率=本期项目支出数÷本期支出总数 ×100% 5.人员支出、公用支出占总支出的比率，衡量行政单位的支出结构。计算公式为： 人员支出比率=本期人员支出数÷本期支出总数 ×100% 公用支出比率=本期公用支出数÷本期支出总数 ×100%"}],"xingzhengdanweicaiwuguize":[{"i":1,"n":"第一条","txt":"为了规范行政单位的财务行为，加强行政单位财务管理和监督，提高资金使用效益，保障行政单位工作任务的完成，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于各级各类国家机关、政党组织（以下统称行政单位）的财务活动。"},{"i":3,"n":"第三条","txt":"行政单位财务管理的基本原则是：艰苦奋斗，厉行节约；量入为出，保障重点；从严从简，勤俭办一切事业；制止奢侈浪费，降低行政成本，注重资金使用效益。"},{"i":4,"n":"第四条","txt":"行政单位财务管理的主要任务是： （一）科学、合理编制预算，严格预算执行，完整、准确、及时编制决算； （二）建立健全财务制度，实施内部控制管理，加强对行政单位财务活动的控制和监督； （三）全面实施绩效管理，提高资金使用效益； （四）加强资产管理，合理配置、有效利用、规范处置资产，防止国有资产流失； （五）按照规定编制决算报告和财务报告，真实反映单位预算执行情况、财务状况和运行情况； （六）对行政单位所属并归口行政财务管理的单位的财务活动实施指导、监督； （七）加强对非独立核算的机关后勤服务部门的财务管理，实行内部核算办法。"},{"i":5,"n":"第五条","txt":"行政单位的财务活动在单位负责人领导下，由单位财务部门统一管理。 行政单位应当实行独立核算，明确承担相关职责的机构，配备与履职相适应的财务、会计人员力量。不具备配备条件的，可以委托经批准从事代理记账业务的中介机构代理记账。 行政单位的各项经济业务事项应当按照国家统一的会计制度进行会计核算。"},{"i":6,"n":"第六条","txt":"行政单位预算由收入预算和支出预算组成。"},{"i":7,"n":"第七条","txt":"按照预算管理权限，行政单位预算管理分为下列级次： （一）向本级财政部门申报预算的行政单位，为一级预算单位； （二）向一级预算单位申报预算并有下级预算单位的行政单位，为二级预算单位，依次类推； （三）向上一级预算单位申报预算，且没有下级预算单位的行政单位，为基层预算单位。 一级预算单位有下级预算单位的，为主管预算单位。"},{"i":8,"n":"第八条","txt":"各级预算单位应当按照预算管理级次申报预算，并按照批准的预算组织实施，定期将预算执行情况向上一级预算单位或者本级财政部门报告。"},{"i":9,"n":"第九条","txt":"国家对行政单位实行收支统一管理、结转和结余按照规定使用的预算管理办法。"},{"i":10,"n":"第十条","txt":"行政单位编制预算，应当综合考虑以下因素： （一）年度工作计划和收支预测； （二）以前年度预算执行情况； （三）以前年度结转和结余情况； （四）资产配置标准和存量资产情况； （五）有关绩效结果； （六）其他因素。"},{"i":11,"n":"第十一条","txt":"行政单位预算依照下列程序编报和审批： （一）行政单位测算、提出预算建议数，逐级汇总后报送本级财政部门； （二）财政部门审核行政单位提出的预算建议数，下达预算控制数； （三）行政单位根据预算控制数正式编制年度预算草案，逐级汇总后报送本级财政部门； （四）经法定程序批准后，财政部门批复行政单位预算。"},{"i":12,"n":"第十二条","txt":"行政单位应当严格执行预算，按照收支平衡的原则，合理安排各项资金，不得超预算安排支出。 预算在执行中应当严格控制调剂。确需调剂的，行政单位应当按照规定程序办理。"},{"i":13,"n":"第十三条","txt":"行政单位应当按照规定编制决算草案，逐级审核汇总后报本级财政部门审批。"},{"i":14,"n":"第十四条","txt":"行政单位应当加强决算审核和分析，规范决算管理工作，保证决算数据的完整、真实、准确。"},{"i":15,"n":"第十五条","txt":"行政单位应当全面实施预算绩效管理，加强绩效结果应用，提高资金使用效益。"},{"i":16,"n":"第十六条","txt":"收入是指行政单位依法取得的非偿还性资金，包括财政拨款收入和其他收入。 财政拨款收入，是指行政单位从本级财政部门取得的预算资金。 其他收入，是指行政单位依法取得的除财政拨款收入以外的各项收入。 行政单位依法取得的应当上缴财政的罚没收入、行政事业性收费收入、政府性基金收入、国有资源（资产）有偿使用收入等，不属于行政单位的收入。"},{"i":17,"n":"第十七条","txt":"行政单位取得各项收入，应当符合国家规定，按照财务管理的要求，分项如实核算。"},{"i":18,"n":"第十八条","txt":"行政单位应当将各项收入全部纳入单位预算，统一核算，统一管理，未纳入预算的收入不得安排支出。"},{"i":19,"n":"第十九条","txt":"支出是指行政单位为保障机构正常运转和完成工作任务所发生的资金耗费和损失，包括基本支出和项目支出。 基本支出，是指行政单位为保障其机构正常运转和完成日常工作任务所发生的支出，包括人员经费和公用经费。 项目支出，是指行政单位为完成其特定的工作任务所发生的支出。"},{"i":20,"n":"第二十条","txt":"行政单位应当将各项支出全部以项目形式纳入预算项目库，实施项目全生命周期管理，未纳入预算项目库的项目一律不得安排预算。 各项支出由单位财务部门按照批准的预算和有关规定审核办理。"},{"i":21,"n":"第二十一条","txt":"行政单位应当严格执行国家规定的开支范围及标准，不得擅自扩大开支范围、提高开支标准，建立健全支出管理制度，合理安排支出进度，严控一般性支出。"},{"i":22,"n":"第二十二条","txt":"行政单位从财政部门或者上级预算单位取得的项目资金，应当按照批准的项目和用途使用，专款专用，在单位统一会计账簿中按项目明细单独核算，并按照有关规定报告资金使用情况，接受财政部门和上级预算单位的监督。"},{"i":23,"n":"第二十三条","txt":"行政单位应当严格执行国库集中支付制度和政府采购法律制度等规定。"},{"i":24,"n":"第二十四条","txt":"行政单位可以根据机构运转和完成工作任务的实际需要，实行成本核算。成本核算的具体办法按照国务院财政部门有关规定执行。"},{"i":25,"n":"第二十五条","txt":"行政单位应当依法依规加强各类票据管理，确保票据来源合法、内容真实、使用正确，不得使用虚假票据。"},{"i":26,"n":"第二十六条","txt":"结转资金，是指当年预算已执行但未完成，或者因故未执行，下一年度需要按照原用途继续使用的资金。"},{"i":27,"n":"第二十七条","txt":"结余资金，是指当年预算工作目标已完成，或者因故终止，当年剩余的资金。 结转资金在规定使用年限未使用或者未使用完的，视为结余资金。"},{"i":28,"n":"第二十八条","txt":"财政拨款结转和结余的管理，应当按照国家有关规定执行。"},{"i":29,"n":"第二十九条","txt":"资产是指行政单位依法直接支配的、能以货币计量的各类经济资源，包括流动资产、固定资产、在建工程、无形资产、公共基础设施、政府储备物资、文物文化资产、保障性住房等。"},{"i":30,"n":"第三十条","txt":"流动资产是指预计在一年以内耗用或者可以变现的资产，包括货币资金、应收及预付款项、存货等。 前款所称存货是指行政单位在工作中为耗用而储存的资产，包括材料、产品、包装物和低值易耗品以及未达到固定资产标准的用具、装具、动植物等。"},{"i":31,"n":"第三十一条","txt":"固定资产是指使用期限超过一年，单位价值在1000元以上，并且在使用过程中基本保持原有物质形态的资产。单位价值虽未达到规定标准，但是耐用时间在一年以上的大批同类物资，作为固定资产管理。"},{"i":32,"n":"第三十二条","txt":"在建工程是指已经发生必要支出，但尚未达到交付使用状态的建设项目工程。 在建工程达到交付使用状态时，应当按照规定办理工程竣工财务决算和资产交付使用，期限最长不得超过1年。"},{"i":33,"n":"第三十三条","txt":"无形资产是指不具有实物形态而能为使用者提供某种权利的资产，包括专利权、商标权、著作权、土地使用权、非专利技术等。"},{"i":34,"n":"第三十四条","txt":"行政单位应当建立健全单位资产管理制度，明确资产使用人和管理人的岗位责任，按照国家规定设置国有资产台账，加强和规范资产配置、使用和处置管理，维护资产安全完整。涉及资产评估的，按照国家有关规定执行。 行政单位应当汇总编制本单位行政事业性国有资产管理情况报告。"},{"i":35,"n":"第三十五条","txt":"行政单位应当根据依法履行职能和完成工作任务的需要，结合资产存量和价值、资产配置标准、绩效目标和财政承受能力，优先通过调剂方式配置资产。不能调剂的，可以采用购置、建设、租用等方式。"},{"i":36,"n":"第三十六条","txt":"行政单位应当加强资产日常管理工作，做好资产建账、核算和登记工作，定期或者不定期进行清查盘点、对账，保证账账相符，账实相符。出现资产盘盈盘亏的，应当按照财务、会计和资产管理制度有关规定处理。 行政单位对需要办理权属登记的资产应当依法及时办理。"},{"i":37,"n":"第三十七条","txt":"行政单位开设银行存款账户，应当报本级财政部门审批或者备案，并由财务部门统一管理。"},{"i":38,"n":"第三十八条","txt":"行政单位应当加强应收及预付款项的管理，严格控制规模，并及时进行清理，不得长期挂账。"},{"i":39,"n":"第三十九条","txt":"行政单位的资产增加时，应当及时登记入账；减少时，应当按照资产处置规定办理报批手续，进行账务处理。 行政单位货币性资产损失核销，按照本级财政部门预算及财务管理有关规定执行。"},{"i":40,"n":"第四十条","txt":"除法律另有规定外，行政单位不得以任何形式用其依法直接支配的国有资产对外投资或者设立营利性组织。对于未与行政单位脱钩的营利性组织，行政单位应当按照有关规定进行监管。 除法律、行政法规另有规定外，行政单位不得以任何方式举借债务，不得以任何方式对外提供担保。"},{"i":41,"n":"第四十一条","txt":"行政单位对外出租、出借国有资产，应当按照有关规定履行相关审批程序。未经批准，不得对外出租、出借。"},{"i":42,"n":"第四十二条","txt":"行政单位应当在确保安全使用的前提下，推进本单位大型设备等国有资产共享共用工作，可以对提供方给予合理补偿。"},{"i":43,"n":"第四十三条","txt":"行政单位资产处置应当遵循公开、公平、公正和竞争、择优的原则，依法进行资产评估，严格履行相关审批程序。"},{"i":44,"n":"第四十四条","txt":"公共基础设施、政府储备物资、文物文化资产、保障性住房等国有资产管理的具体办法，由国务院财政部门会同有关部门制定。"},{"i":45,"n":"第四十五条","txt":"负债是指行政单位过去的经济业务事项形成的、预期会导致经济资源流出的现时义务，包括应缴款项、暂存款项、应付款项等。"},{"i":46,"n":"第四十六条","txt":"应缴款项是指行政单位依法取得的应当上缴财政的资金，包括罚没收入、行政事业性收费收入、政府性基金收入、国有资源（资产）有偿使用收入等。"},{"i":47,"n":"第四十七条","txt":"行政单位取得罚没收入、行政事业性收费收入、政府性基金收入、国有资源（资产）有偿使用收入等，应当按照国库集中收缴的有关规定及时足额上缴，不得隐瞒、滞留、截留、占用、挪用、拖欠或者坐支。"},{"i":48,"n":"第四十八条","txt":"暂存款项是行政单位在业务活动中与其他单位或者个人发生的预收、代管等待结算的款项。"},{"i":49,"n":"第四十九条","txt":"行政单位应当加强对暂存款项的管理，不得将应当纳入单位收入管理的款项列入暂存款项；对各种暂存款项应当及时清理、结算，不得长期挂账。"},{"i":50,"n":"第五十条","txt":"行政单位划转撤并的财务处理，应当在财政部门、主管预算单位等部门的监督指导下进行。 划转撤并的行政单位应当对单位的财产、债权、债务等进行全面清理，编制财产目录和债权、债务清单，提出财产作价依据和债权、债务处理办法，做好资产和负债的移交、接收、划转和管理工作，并妥善处理各项遗留问题。"},{"i":51,"n":"第五十一条","txt":"划转撤并的行政单位的资产和负债经主管预算单位审核并上报财政部门和有关部门批准后，分别按照下列规定处理： （一）转为事业单位和改变隶属关系的行政单位，其资产和负债无偿移交，并相应调整、划转经费指标。 （二）转为企业的行政单位，其资产按照有关规定进行评估作价并扣除负债后，转作企业的国有资本。 （三）撤销的行政单位，其全部资产和负债由财政部门或者财政部门授权的单位处理。 （四）合并的行政单位，其全部资产和负债移交接收单位或者新组建单位，并相应划转经费指标；合并后多余的资产，由财政部门或者财政部门授权的单位处理。 （五）分立的行政单位，其资产和负债按照有关规定移交分立后的行政单位，并相应划转经费指标。"},{"i":52,"n":"第五十二条","txt":"行政单位应当按照国家有关规定向主管预算单位和财政部门以及其他有关的报告使用者提供财务报告、决算报告。 行政单位财务会计和预算会计要素的确认、计量、记录、报告应当遵循政府会计准则制度的规定。"},{"i":53,"n":"第五十三条","txt":"财务报告主要以权责发生制为基础编制，以财务会计核算生成的数据为准，综合反映行政单位特定日期财务状况和一定时期运行情况等信息。"},{"i":54,"n":"第五十四条","txt":"财务报告由财务报表和财务分析两部分组成。财务报表主要包括资产负债表、收入费用表等会计报表和报表附注。财务分析的内容主要包括财务状况分析、运行情况分析和财务管理情况等。"},{"i":55,"n":"第五十五条","txt":"决算报告主要以收付实现制为基础编制，以预算会计核算生成的数据为准，综合反映行政单位年度预算收支执行结果等信息。"},{"i":56,"n":"第五十六条","txt":"决算报告由决算报表和决算分析两部分组成。决算报表主要包括收入支出表、财政拨款收入支出表等。决算分析的内容主要包括收支预算执行分析、资金使用效益分析和机构人员情况等。"},{"i":57,"n":"第五十七条","txt":"行政单位财务监督主要包括对预算管理、收入管理、支出管理、结转和结余管理、资产管理、负债管理等的监督。"},{"i":58,"n":"第五十八条","txt":"行政单位财务监督应当实行事前监督、事中监督、事后监督相结合，日常监督与专项监督相结合，并对违反财务规章制度的问题进行检查处理。"},{"i":59,"n":"第五十九条","txt":"行政单位应当建立健全内部控制制度、经济责任制度、财务信息披露制度等监督制度，按照规定编制内部控制报告，依法依规公开财务信息，做好预决算公开工作。"},{"i":60,"n":"第六十条","txt":"行政单位应当遵守财经纪律和财务制度，依法接受主管预算单位和财政、审计部门的监督。"},{"i":61,"n":"第六十一条","txt":"财政部门、行政单位及其工作人员存在违反本规则规定的行为，以及其他滥用职权、玩忽职守、徇私舞弊等违法违规行为的，依法追究相应责任。"},{"i":62,"n":"第六十二条","txt":"行政单位基本建设投资的财务管理，应当执行本规则，但国家基本建设投资财务管理制度另有规定的，从其规定。"},{"i":63,"n":"第六十三条","txt":"行政单位应当严格按照《中华人民共和国保守国家秘密法》等法律法规和有关规定，做好涉密事项的财务管理工作。"},{"i":64,"n":"第六十四条","txt":"行政单位所属独立核算的企业、事业单位分别执行相应的财务制度，不执行本规则。"},{"i":65,"n":"第六十五条","txt":"省、自治区、直辖市人民政府财政部门可以依据本规则结合本地区实际情况制定实施办法。"},{"i":66,"n":"第六十六条","txt":"本规则自2023年3月1日起施行。《行政单位财务规则》（财政部令第71号）同时废止。"}],"caizhengjiguanshishixingzhengxuketingzhengbanfa":[{"i":1,"n":"第一条","txt":"为了规范财政机关行政许可听证程序，保护公民、法人和其他组织的合法权益，保障财政机 关依法实施行政许可，根据《中华人民共和国行政许可法》和有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府财政机关(以下统称财政机关)实施行政许可听证，适用本办法。"},{"i":3,"n":"第三条","txt":"财政机关实施行政许可听证，应当遵循公开、公平、公正和便民的原则。"},{"i":4,"n":"第四条","txt":"行政许可听证，由财政机关法制工作机构，或者财政机关指定的审查行政许可申请机构以外 的其他机构办理。"},{"i":5,"n":"第五条","txt":"财政机关对依法应当进行听证的行政许可事项不组织听证，或者不按照规定组织听证的，不 得作出行政许可决定。"},{"i":6,"n":"第六条","txt":"法律、法规、规章规定实施行政许可应当听证的事项，或者财政机关认为需要听证的其他涉 及公共利益的重大行政许可事项，财政机关应当组织听证。"},{"i":7,"n":"第七条","txt":"直接涉及申请人与他人之间重大利益关系的行政许可事项，申请人、利害关系人提出听证申 请的，财政机关应当组织听证。"},{"i":8,"n":"第八条","txt":"听证人员包括：听证主持人、听证员和记录员。 听证主持人由财政机关负责人指定 本机关法制工作机构的工作人员，或者审查该行政许可申请工作人员以外的其他人员担任。 听证员由听证主持人所在机构负责 人指定，协助听证主持人工作。 记录员由听证主持人指定，负责听 证笔录的制作和其他相关事务。"},{"i":9,"n":"第九条","txt":"听证参加人包括：审查该行政许可申请的工作人员，该行政许可的申请人、利害关系人。"},{"i":10,"n":"第十条","txt":"财政机关在作出属于本办法第六条规定情形的行政许可决定前，应当向社会公告，并按期举 行听证。 公告内容包括：听证事项、听证时 间和地点、听证人员、听证参加人等。"},{"i":11,"n":"第十一条","txt":"财政机关在作出属于本办法第七条规定情形的行政许可决定前，应当告知申请人、利害关系 人享有要求听证的权利。 财政机关告知申请人、利害关系人 享有听证权利，应当送达《财政行政许可听证告知书》。《财政行政许可听证告知书》应当载明拟作出的行政许可事项，申请人、利害关系人享有的权利等内容。"},{"i":12,"n":"第十二条","txt":"申请人、利害关系人要求听证的，应当在收到《行政许可听证告知书》之日起五日内向财政 机关提出书面申请。逾期不提出申请的，视为放弃听证权利。财政机关即可依法作出行政许可决定。"},{"i":13,"n":"第十三条","txt":"财政机关应当在收到申请人、利害关系人听证申请之日起二十日内组织听证。"},{"i":14,"n":"第十四条","txt":"财政机关应当于举行听证的七日前向申请人、利害关系人、审查该行政许可的机构或人员送 达《财政行政许可听证通知书》。《财政行政许可听证通知书))应当载明听证时间、听 证地点以及 听证人员等事项。"},{"i":15,"n":"第十五条","txt":"申请人、利害关系人可以委托一至二名代理人参加听证。代理人参加听证的，应当在举行听 证的三日前向组织听证的财政机关提交授权委托书。"},{"i":16,"n":"第十六条","txt":"申请人、利害关系人认为听证人员与该行政许可事项有直接利害关系的，有权申请其回避。 回避申请应当在举行听证的三日前向财政机关提出，并说明理由。 听证人员认为与该行政许可事项有 直接利害关系的，应当自行提出回避。 听证主持人的回避，由财政机关负 责人决定。 听证员、记录员的回避，由听证主 持人决定。"},{"i":17,"n":"第十七条","txt":"财政行政许可听证应当公开进行，但涉及国家秘密、商业秘密或者个人隐私的除外。 因涉及商业秘密或者个人隐私不宜 公开听证的，由申请人、利害关系人提出申请，财政机关审核决定。 公开听证的行政许可事项，应当先 期公告听证事项、听证时间和地点、听证人员及听证参加入，并允许群众旁听。"},{"i":18,"n":"第十八条","txt":"听证会应当按照下列程序进行： (一)记录员查明听证参加人身份 和到场情况； (二)听证主持人宣布听证事 由、听证会组成人员、听证纪律，告知听证参加人的权利义务，宣布听证开始； (三)审查行政许可申请的工作人 员陈述审查意见和理由，提供审查证据； (四)申请人、利害关系人或其代 理人提出证据，进行陈述、申辩和质证； (五)听证参加人就行政许可事项 的真实性、合法性等进行辩论； (六)辩论终结，听证主持人就行 政许可事项的事实、证据及其他有关问题，再次征求听证参加人意见。听证参加人作最后陈述。 (七)听证主持人宣布听证结 束。"},{"i":19,"n":"第十九条","txt":"听证活动中，听证主持人应当维护听证秩序。对违反听证纪律的人员，听证主持人有权予以 警告或者批评；情节严重的，有权责令其退场。"},{"i":20,"n":"第二十条","txt":"行政许可听证应当制作听证笔录。听证笔录应当载明下列内容： (一)听证事项； (二)听证人员姓名、职务； (三)听证参加人基本情况； (四)听证时间、地点； (五)听证公开情况； (六)听证参加入的意见、理由及 提供的证据； (七)听证主持人对听证活动中有 关事项的处理情况； (八)其他应当记入笔录的事 项。 听证笔录应当交听证参加人确认无 误后签字或者盖章。听证参加人认为笔录有错误的，有权要求补充或者改正。听证参加人拒绝签字或盖章的，听证主持人应当记明情况附卷。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，可以延期举行听证： (一)因不可抗力导致听证无法按期举行的； (二)申请人：利害关系入或其代 理人申请延期，有正当理由的； (三)可以延期的其他情形。"},{"i":22,"n":"第二十二条","txt":"听证过程中，有下列情形之一的，中止听证： (一)听证参加人提出新的事 实、理由和依据，听证主持人认为需要重新调查核实的； (二)申请听证的公民死亡、法人 或者其他组织终止，尚未确定权利义务承受人的； (三)其他应当中止听证的情 形。"},{"i":23,"n":"第二十三条","txt":"听证过程中，有下列情形之一的，终止听证： (一)申请人、利害关系人撤回听 证申请的； (二)申请人、利害关系人无正当 理由不参加听证的； (三)其他应当终止听证的情 形。"},{"i":24,"n":"第二十四条","txt":"延期、中止听证由负责听证事项的机构负责人决定。 延期、中止听证的，应当通知听证 参加入。 延期、中止听证情形消失后，应当 于七日内恢复听证，并书面通知听证参加入。 终止听证由财政机关负责人决定。"},{"i":25,"n":"第二十五条","txt":"财政机关应当根据听证笔录，作出行政许可决定。未经听证程序质证的证据，不能作为作出 行政许可决定的依据。"},{"i":26,"n":"第二十六条","txt":"财政机关组 织听证，不得向申请人、利害关系人收取费用。 组织听证所需的场所、设备以及必 需的费用，财政机关应当予以保障。"},{"i":27,"n":"第二十七条","txt":"本办法自2004年10月1日起施行。"}],"caizhengjiguanxingzhengchufatingzhengshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范财政机关行政处罚听证程序，维护公民、法人和其他组织的合法权益，保障和监督财政机关依法实施行政处罚，根据《中华人民共和国行政处罚法》，制定本实施办法。"},{"i":2,"n":"第二条","txt":"财政机关行政处罚的听证，应当遵循合法、公正、公开、及时和便民的原则，保障当事人陈述、申辩和质证的权利。"},{"i":3,"n":"第三条","txt":"听证由拟作出财政行政处罚的财政机关组织，具体工作由其法制工作机构或者承担法制工作职责的机构负责实施。"},{"i":4,"n":"第四条","txt":"听证人员包括：听证主持人、听证员和记录员。 听证主持人由财政机关负责人指定本机关法制工作机构或者承担法制工作职责的机构中非本案调查人员担任。 听证员由听证主持人所在机构负责人指定，协助听证主持人工作。　记录员由听证主持人指定，负责听证笔录的制作和其他相关事务。 财政部驻各地财政监察专员办事机构(以下简称专员办)作出的财政行政处罚，其听证主持人由该专员办负责人指定非本案调查人员担任。"},{"i":5,"n":"第五条","txt":"听证参加人包括：当事人、案件调查人员、与案件处理结果可能有利害关系的第三人、证人、鉴定人、翻译人员等。"},{"i":6,"n":"第六条","txt":"财政机关在行政处罚案件调查终结后，对公民、法人或者其他组织依法作出下列行政处罚决定之前，应当告知当事人有要求举行听证的权利： (一)暂停会计师事务所经营业务； (二)暂停注册会计师执行业务； (三)吊销注册会计师证书； (四)吊销会计从业资格证书； (五)撤销会计师事务所； (六)取消政府采购业务代理资格； (七)较大数额罚款； (八)法律、法规和规章规定的其他应当告知听证权利的事项。 财政部以及专员办作出罚款行政处罚的，其“较大数额罚款”的标准为对公民作出5000元以上罚款，对法人或者其他组织作出5万元以上罚款。地方财政机关作出罚款行政处罚的，其“较大数额罚款”的标准按照各省、自治区、直辖市人大常委会或者人民政府的规定执行。"},{"i":7,"n":"第七条","txt":"财政机关告知当事人有要求举行听证的权利，应当送达《财政行政处罚事项告知书》。《财政行政处罚事项告知书》应当载明行政处罚的事实、理由、依据和拟作出行政处罚决定的内容、当事人的权利等。"},{"i":8,"n":"第八条","txt":"当事人要求听证的，可以在《财政行政处罚事项告知书》的送达回证上签署意见，也可以自收到《财政行政处罚事项告知书》之日起3日内向财政机关书面提出听证要求。逾期不提出的，财政机关视为放弃听证权利，并记录在案。"},{"i":9,"n":"第九条","txt":"财政机关应当在收到当事人听证要求之日起20日内组织听证，并在听证的7日前将《财政行政处罚听证通知书》送达听证参加人。通知听证参加人举行听证的时间、地点，以及听证主持人、听证员、记录员的姓名和职务及其他有关事项，由听证参加人在《财政行政处罚听证通知书》的送达回证上签字。"},{"i":10,"n":"第十条","txt":"当事人可以亲自参加听证，也可以委托1至2名代理人参加听证。当事人委托代理人参加听证的，应当在举行听证的3日前向组织听证的财政机关提交授权委托书，授权委托书应当注明代理权限等有关事项。"},{"i":11,"n":"第十一条","txt":"当事人认为听证主持人、听证员、记录员、鉴定人、翻译人员与本案有直接利害关系的，有权申请回避。回避申请，应当在举行听证的3日前向财政机关提出，并说明理由。 听证主持人、听证员、记录员、鉴定人、翻译人员是本案当事人的近亲属的，或者认为自己与本案有直接利害关系或其他关系可能影响公证听证的，应当提出回避。"},{"i":12,"n":"第十二条","txt":"听证主持人的回避，由组织听证的财政机关负责人决定。 听证员的回避，由听证主持人所在机构负责人决定。 记录员、鉴定人、翻译人员的回避，由听证主持人决定。"},{"i":13,"n":"第十三条","txt":"财政行政处罚听证应当公开进行，但是涉及国家秘密、商业秘密或者个人隐私的除外。涉及商业秘密或者个人隐私不宜公开进行听证的，应由当事人于举行听证的3日前提出，由财政机关审核后确定。 公开举行听证的案件，应当先期公告当事人的姓名或名称、案由和听证的时间、地点，并应当允许公众旁听。"},{"i":14,"n":"第十四条","txt":"听证应当按照下列程序进行： (一)记录员查明听证参加人身份和到场情况。 (二)听证主持人宣布听证事由、听证会组成人员、听证纪律，告知听证参加人的权利和义务，宣布听证开始。 (三)案件调查人员提出已掌握的事实、证据，拟作出行政处罚的理由、依据以及处罚意见。 (四)当事人或其代理人就案件的事实、理由和证据进行陈述、申辩和质证。 (五)听证参加人就案件的事实、各自出示的证据的合法性、真实性及有关的问题进行辩论。辩论先由案件调查人员陈述，再由当事人或其代理人申辩，然后双方相互辩论。 (六)辩论终结，听证主持人可以就案件的事实、证据及有关问题，再次征求听证参加人的意见。听证参加人可作最后陈述。 (七)听证主持人宣布听证结束。"},{"i":15,"n":"第十五条","txt":"听证的全部活动，应当由记录员制作听证笔录。 听证笔录应当交听证参加人确认无误后签字或者盖章。听证参加人认为有错误的，有权要求补充或者改正。听证参加人拒绝签字或者盖章的，应当记明情况附卷。 听证笔录由听证主持人、听证员和记录员审阅、签名。"},{"i":16,"n":"第十六条","txt":"听证过程中，听证参加人违反听证纪律或者扰乱听证秩序的，听证主持人应当予以制止；制止无效的，可以责令其退出听证会场。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，可以延期举行听证： (一)因不可抗力导致听证无法按期举行的； (二)当事人或其代理人申请延期，有正当理由的； (三)可以延期的其他情形。"},{"i":18,"n":"第十八条","txt":"听证过程中，有下列情形之一的，中止听证： (一)听证主持人认为证据有疑问无法听证辩明，可能影响财政机关行政处罚决定的准确和公正的，或者当事人或其代理人提出新的事实、理由和证据，听证主持人认为需要重新调查核实的； (二)申请听证的公民死亡、法人或者其他组织终止，尚未确定权利义务承受人的； (三)听证参加人违反听证纪律或扰乱听证秩序，听证主持人制止无效的； (四)其他应当中止听证的情形。 听证主持人和记录员应当将听证中止情形载入听证笔录。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，终止听证： (一)有权提起听证的公民死亡，没有继承人或者继承人放弃听证权利的； (二)有权提起听证的法人或者其他组织终止，承受其权利的法人或者组织放弃听证权利的； (三)当事人撤回听证申请，放弃听证权利的； (四)当事人无正当理由不参加听证的； (五)其他应当终止听证的情形。"},{"i":20,"n":"第二十条","txt":"延期、中止听证由负责听证事项的机构负责人决定。 延期、中止听证的，应当通知听证参加人。 延期、中止听证情形消失后，应当于7日内恢复听证，并书面通知听证参加人。 终止听证由财政机关负责人决定。"},{"i":21,"n":"第二十一条","txt":"听证结束后，听证主持人应当根据听证情况，写出听证报告，连同听证笔录报财政机关负责人。 听证报告应当载明下列内容：听证的时间、地点；听证人员、听证参加人基本情况；听证事由；当事人与案件调查人员对事实、证据的认定和对处罚建议的主要分歧；听证主持人的意见和建议。"},{"i":22,"n":"第二十二条","txt":"听证主持人、听证员、记录员应当严格按照法律及有关规定行使权利。违反法律及有关规定的，取消其听证主持人、听证员、记录员的资格，并承担相应责任。"},{"i":23,"n":"第二十三条","txt":"财政机关对依法应当听证的行政处罚事项不组织听证，或者不按照规定组织听证的，不得作出行政处罚决定。已作出的行政处罚决定无效。"},{"i":24,"n":"第二十四条","txt":"因组织听证所发生的费用由组织听证的财政机关承担。 当事人参加听证所发生的费用，组织听证的财政机关不予承担。"},{"i":25,"n":"第二十五条","txt":"本办法自2005年3月1日起施行。1998年5月15日财政部发布的《财政部门行政处罚听证程序实施办法》(财法字〔1998〕18号)同时废止。"}],"caizhengjianchagongzuobanfa":[{"i":1,"n":"第一条","txt":"为了规范财政检查工作，保障和监督财政部门有效实施财政检查，保护公民、法人和其他组织的合法权益，根据《中华人民共和国预算法》、《财政违法行为处罚处分条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府财政部门及省级以上人民政府财政部门的派出机构（以下统称财政部门）依法实施财政检查，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称财政检查，是指财政部门为履行财政监督职责，纠正财政违法行为，维护国家财政经济秩序，对单位和个人执行财税法规情况以及财政、财务、会计等管理事项进行检查的活动。"},{"i":4,"n":"第四条","txt":"财政部门实施财政检查，应当遵循合法、客观、公正、公开的原则。"},{"i":5,"n":"第五条","txt":"财政部门应当按照法律、法规、规章和本办法的规定，在规定的职权范围内，实施财政检查，依法做出检查结论或处理、处罚决定。对财政检查工作管辖发生争议的，报请共同的上一级财政部门指定管辖。"},{"i":6,"n":"第六条","txt":"财政部门应当制定年度财政检查计划，按计划组织开展财政检查，或者根据日常财政管理需要，组织开展财政检查。"},{"i":7,"n":"第七条","txt":"财政部门组织开展财政检查应当组成检查组，并指定检查组组长。检查组实行组长负责制。"},{"i":8,"n":"第八条","txt":"检查组检查人员由财政部门工作人员组成。检查人员应当具备下列条件: （一）熟悉有关法律、法规、规章和政策; （二）掌握相关的专业知识; （三）具有一定的调查研究、综合分析和文字表达能力。第九条 根据需要，财政部门可以聘请专门机构或者具有专门知识的人员协助检查人员开展检查工作。"},{"i":9,"n":"第十条","txt":"检查人员与被检查单位或个人（以下统称被检查人）有直接利害关系的，应当回避。被检查人认为检查人员与自己有利害关系的，可以要求检查人员回避。检查人员的回避，由财政部门负责人决定。"},{"i":10,"n":"第十一条","txt":"检查人员应当遵守国家有关保密规定，不得泄露检查中知悉的国家秘密和商业秘密，不得将检查中取得的材料用于与检查工作无关的事项。"},{"i":11,"n":"第十二条","txt":"检查组在实施财政检查前，应当熟悉与检查事项有关的法律、法规、规章和政策，了解被检查人的基本情况，编制财政检查工作方案。"},{"i":12,"n":"第十三条","txt":"财政部门实施财政检查，一般应于3个工作日前向被检查人送达财政检查通知书。 财政部门认为实施财政检查的3个工作日前向被检查人送达检查通知书对检查工作有不利影响时，经财政部门负责人批准，检查通知书可在实施财政检查前适当时间下达。财政检查通知书的内容包括: （一）被检查人的名称; （二）检查的依据、范围、内容、方式和时间; （三）对被检查人配合检查工作的具体要求; （四）检查组组长及检查人员名单、联系方式; （五）财政部门公章及签发日期。"},{"i":13,"n":"第十四条","txt":"实施财政检查时，检查人员不得少于两人，并应当向被检查人出示证件。检查人员可以向被检查人询问有关情况，被检查人应当予以配合，如实回答询问、反映情况。询问应当制作笔录，并由被检查人签字或盖章。"},{"i":14,"n":"第十五条","txt":"实施财政检查时，检查人员可以要求被检查人提供有关资料，并可以对有关资料进行复制。提供的资料是外国文字或少数民族文字记录的，被检查人应当将资料译成中文。"},{"i":15,"n":"第十六条","txt":"实施财政检查时，检查人员可以运用查账、盘点、查询及函证、计算、分析性复核等方法。"},{"i":16,"n":"第十七条","txt":"实施财政检查时，经财政部门负责人批准，检查人员可以向与被检查人有经济业务往来的单位查询有关情况，可以依法向金融机构查询被检查单位的存款。检查人员查询存款时，应当持有财政部门签发的查询存款通知书，并负有保密义务。"},{"i":17,"n":"第十八条","txt":"实施财政检查时，在有关证据可能灭失或者以后难以取得的情况下，经财政部门负责人批准，可以先行登记保存，并应当在7个工作日内及时做出处理决定。在此期间，被检查人或者有关人员不得销毁或者转移证据。"},{"i":18,"n":"第十九条","txt":"检查人员在检查中取得的证明材料，应当有提供者的签名或者盖章。未取得提供者签名或盖章的材料，检查人员应当注明原因。"},{"i":19,"n":"第二十条","txt":"实施财政检查时，检查人员应当将检查内容与事项予以记录和摘录，编制财政检查工作底稿，并由被检查人签字或者盖章。"},{"i":20,"n":"第二十一条","txt":"检查组组长应当对本组其他检查人员的工作质量进行监督，并对有关事项进行必要的审查和复核。"},{"i":21,"n":"第二十二条","txt":"检查组在实施检查中，遇到重大问题应当及时向财政部门请示汇报。"},{"i":22,"n":"第二十三条","txt":"检查工作结束前，检查组应当就检查工作的基本情况、被检查人存在的问题等事项书面征求被检查人的意见。被检查人自收到书面征求意见函之日起 5个工作日内，提出书面意见或说明;在规定期限内没有提出书面意见或说明的，视为无异议。"},{"i":23,"n":"第二十四条","txt":"检查组应于检查结束10个工作日内，向财政部门提交书面财政检查报告;特殊情况下，经批准提交财政检查报告的时间可以延长，但最长不得超过 30日。检查组在提交财政检查报告时，还应当一并提交行政处理、处罚建议或者移送处理建议以及财政检查工作底稿等材料。"},{"i":24,"n":"第二十五条","txt":"财政检查报告应当包括下列内容: （一）被检查人的基本情况; （二）检查范围、内容、方式和时间; （三）被检查人执行财税法规情况以及财政、财务、会计等管理事项的基本情况; （四）被检查人存在财政违法行为的基本事实以及认定依据、证据; （五）被检查人的意见或说明; （六）应当向财政部门报告的其他事项; （七）检查组组长签名及财政检查报告日期。"},{"i":25,"n":"第二十六条","txt":"财政部门应当建立健全财政检查的复核制度，指定内部有关职能机构或者专门人员，对检查组提交的财政检查报告以及其他有关材料予以复核。复核人员与被检查人或者检查人员有直接利害关系的，应当回避。"},{"i":26,"n":"第二十七条","txt":"负责复核的有关职能机构或者专门人员，应当从以下几个方面对财政检查报告以及其他有关材料进行复核: （一）检查事项认定的事实是否清楚; （二）取得的证据是否真实、充分; （三）检查程序是否合法; （四）认定财政违法行为的法律依据是否适当; （五）提出的行政处理、处罚建议或者移送处理建议是否适当; （六）其他需要复核的事项。 有关职能机构或者专门人员对财政检查报告复核后，应当提出复核意见。"},{"i":27,"n":"第二十八条","txt":"财政部门对财政检查报告和复核意见进行审定后，应当根据不同情况做出如下处理: （一）对未发现有财政违法行为的被检查人做出检查结论; （二）对有财政违法行为的被检查人依法做出行政处理、处罚决定 ; （三）对不属于本部门职权范围的事项依法移送。财政检查报告与复核意见存在重大分歧的，财政部门应当责成检查组进一步核实、补正有关情况或者材料 ;必要时，应当另行派出检查组，重新实施财政检查。"},{"i":28,"n":"第二十九条","txt":"财政部门做出行政处理、处罚决定的，应当制作行政处理、处罚决定书。行政处理、处罚决定书应当载明以下事项: （一）当事人的姓名或者名称、地址; （二）违反法律、法规或者规章的事实和证据; （三）行政处理、处罚的种类和依据; （四）行政处理、处罚履行的方式和期限; （五）不服行政处理、处罚决定，申请行政复议或者提起行政诉讼的途径和期限; （六）做出行政处理、处罚决定的财政部门名称和日期;行政处理、处罚决定书必须盖有做出行政处理、处罚决定的财政部门印章。"},{"i":29,"n":"第三十条","txt":"财政部门在做出行政处罚决定之前，应当告知当事人做出行政处罚的事实、理由及依据，并告知当事人依法享有的权利。当事人有权进行陈述和申辩。财政部门必须充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行核查;当事人提出的事实、理由或者证据成立的，财政部门应当采纳。"},{"i":30,"n":"第三十一条","txt":"财政部门做出应当告知听证权利的行政处罚决定之前，应当告知当事人有要求举行听证的权利;当事人要求听证的，财政部门应当组织听证。财政部门举行听证的，依照《财政机关行政处罚听证实施办法》（财政部令第23号）的规定办理。"},{"i":31,"n":"第三十二条","txt":"财政部门依法做出行政处理、处罚决定后，应当将行政处理、处罚决定书送达当事人。行政处理、处罚决定书自送达之日起生效。"},{"i":32,"n":"第三十三条","txt":"当事人对行政处理、处罚不服的，依照《中华人民共和国行政复议法》、《中华人民共和国行政诉讼法》的规定申请行政复议或者提起行政诉讼。行政复议和行政诉讼期间，行政处理、处罚决定不停止执行，法律另有规定的除外。"},{"i":33,"n":"第三十四条","txt":"财政部门应当依法对财政行政处理、处罚决定执行情况进行监督检查。"},{"i":34,"n":"第三十五条","txt":"被检查人有财政违法行为的，财政部门可以公告其财政违法行为及行政处理、处罚、处分决定。"},{"i":35,"n":"第三十六条","txt":"财政检查工作结束后，财政部门应当做好财政检查工作相关材料的立卷归档工作。"},{"i":36,"n":"第三十七条","txt":"财政部门的工作人员在财政检查工作中，滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十八条","txt":"财政部门对财政检查工作中发现的影响财税政策、预算执行等方面的重要问题，应当及时向本级人民政府和上一级财政部门报告。"},{"i":38,"n":"第三十九条","txt":"财政部门实施会计监督检查，适用本办法以及2001年2月20日财政部发布的《财政部门实施会计监督办法》（财政部令第 10号）。"},{"i":39,"n":"第四十条","txt":"本办法自2006年3月1日起施行。1998年10月8日财政部发布的《财政检查工作规则》（财监字［1998］223号）同时废止。"}],"caizhengjiandujianchaanjianyisongbanfa":[{"i":1,"n":"第一条","txt":"为了加强对财政监督检查案件移送工作的管理，规范财政监督检查案件移送，保障财政监督检查职责的履行，根据《财政违法行为处罚处分条例》、《行政执法机关移送涉嫌犯罪案件的规定》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称财政监督检查案件移送，是指县级以上人民政府财政部门和省级以上人民政府财政部门的派出机构（以下统称财政部门）在履行监督检查职责时，对不属于财政部门职权范围的案件和其他事项，依法依纪移送其他机关处理的行为。"},{"i":3,"n":"第三条","txt":"财政部门依法依纪实施财政监督检查案件移送，适用本办法。"},{"i":4,"n":"第四条","txt":"财政部门移送财政监督检查案件（以下简称案件移送），应当符合法律、法规、规章的规定，做到事实清楚、材料齐全、程序合法、手续完备。 属于财政部门职权范围的案件和其他事项，财政部门应当依法处理，不得移送其他机关。"},{"i":5,"n":"第五条","txt":"财政部门履行监督检查职责时，对需要由税务、银行、证券、保险、海关、国有资产管理以及其他有关主管或者监管机关处理的案件，应当依法办理案件移送。"},{"i":6,"n":"第六条","txt":"财政部门履行监督检查职责时，对依法依纪应当追究责任的公务员，财政部门无权处理的，应当将案件材料移送有关监察机关或者具有人事管理权限的任免机关处理。 对法律、法规授权的具有管理公共事务职能的组织以及国家行政机关依法委托的组织中除工勤人员以外的工作人员，企业、事业单位、社会团体中由国家行政机关以委任、派遣等形式任命的人员以及其他人员依法依纪应当追究责任的，参照前款规定执行。"},{"i":7,"n":"第七条","txt":"财政部门履行监督检查职责时，认为有关单位或者个人涉嫌犯罪的，应当按照《行政执法机关移送涉嫌犯罪案件的规定》办理案件移送。 同一案件既涉嫌职务犯罪又涉嫌其他犯罪，检察机关与公安机关分别具有管辖权的，向案件所涉嫌主罪的管辖机关移送。"},{"i":8,"n":"第八条","txt":"财政部驻各省、自治区、直辖市、计划单列市财政监察专员办事处认为应当移送的案件，凡涉嫌犯罪金额在1000万元以上的，或者责任人员涉及副厅（局）级以上领导干部的，以及其他性质、情节恶劣或者具有较大社会影响的案件，应当报送财政部决定移送机关。 省级财政部门派出机构的移送案件，性质、情节恶劣或者具有较大社会影响的，其具体情形及移送机关由省级财政部门确定。"},{"i":9,"n":"第九条","txt":"财政部门向其他机关移送案件前已经作出的行政处理、行政处罚，不停止执行。移送案件时，应当将行政处理、行政处罚决定等案件材料一并移送其他机关。 不得以行政处理、行政处罚等方式代替案件移送。"},{"i":10,"n":"第十条","txt":"财政部门履行监督检查职责时，承办机构或者承办人员认为需要案件移送的，应当向财政部门提出移送建议。"},{"i":11,"n":"第十一条","txt":"财政部门应当指定 2名以上工作人员或者内部有关机构对案件是否移送进行复核。 复核人员或者机构应当按照有关规定，对建议移送案件的事实是否清楚、材料是否齐全、程序是否合法、手续是否完备等情形进行复核，并提出移送处理意见，报本级财政部门负责人审批。"},{"i":12,"n":"第十二条","txt":"财政部门应当自接到移送处理意见之日起7日内，作出案件移送或者不予移送的决定。 决定移送的，财政部门应当明确具体的受移送机关，办理移送手续，并将案件的有关材料及时、完整地移送受移送机关。 决定不予移送的，财政部门应当将决定的理由和依据记录在案，并依法进行处理。"},{"i":13,"n":"第十三条","txt":"财政部门办理案件移送时，应当向受移送机关提交《财政监督检查案件移送通知书》，并附下列材料： （一）案件基本情况； （二）案件的检查报告或者调查报告； （三）已作出处理处罚的情况以及处理处罚建议； （四）有关证据； （五）涉案款物清单； （六）其他需要移送的材料。"},{"i":14,"n":"第十四条","txt":"财政部门向受移送机关提交《财政监督检查案件移送通知书》时，应当附送案件移送通知书送达回证，并要求被移送机关在送达回证上签名或者盖章。"},{"i":15,"n":"第十五条","txt":"财政部门应当及时了解、掌握移送案件的进展情况。案件移送后超过30日尚未收到送达回证的，或者受理后超过90日尚未收到书面处理结果的，财政部门应当制发《财政监督检查移送案件询问函》，向受移送机关询问移送案件进展情况。"},{"i":16,"n":"第十六条","txt":"对受移送机关不接收或者不予受理的案件，财政部门仍有异议的，应当与受移送机关进行协商或者向有关部门反映，并将结果记录在案。"},{"i":17,"n":"第十七条","txt":"对其他机关移送财政部门处理的案件，财政部门应当在7日内进行审核，并作出是否受理的决定。对不予受理的，财政部门应当在30日内书面向移送机关说明不予受理的理由，并退还移送的案件材料；对予以受理的，财政部门应当及时处理，并在90日内将处理结果书面通知移送机关。"},{"i":18,"n":"第十八条","txt":"财政部门应当建立案件移送登记制度，完善档案管理，及时对案件移送情况、处理结果等进行统计分析，并将有关汇总分析报告报送上一级财政部门。"},{"i":19,"n":"第十九条","txt":"上级财政部门应当加强对下级财政部门案件移送工作的指导和监督。"},{"i":20,"n":"第二十条","txt":"财政部门应当加强与受移送机关的沟通和协调。受移送机关在查处移送案件过程中，需要财政部门配合的，财政部门应当予以协助。"},{"i":21,"n":"第二十一条","txt":"财政部门及其工作人员在案件移送工作中，应当移送而不移送或者违反规定移送，造成严重后果的，应当依法依纪追究责任。"},{"i":22,"n":"第二十二条","txt":"本办法自 2009年2月1日 起施行。"}],"caizhengpiaojuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范财政票据行为，加强政府非税收入征收管理和单位财务监督，维护国家财经秩序，保护公民、法人和其他组织的合法权益，根据国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"财政票据的印制、领购、发放、使用、保管、核销、销毁及监督检查等活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称财政票据，是指由财政部门监（印）制、发放、管理，国家机关、事业单位、具有公共管理或者公共服务职能的社会团体及其他组织（以下简称“行政事业单位”）依法收取政府非税收入或者从事非营利性活动收取财物时，向公民、法人和其他组织开具的凭证。 财政票据是财务收支和会计核算的原始凭证，是财政、审计等部门进行监督检查的重要依据。"},{"i":4,"n":"第四条","txt":"财政部门是财政票据的主管部门。 财政部负责全国财政票据管理工作，承担中央单位财政票据的印制、发放、核销、销毁和监督检查等工作，指导地方财政票据管理工作。 省、自治区、直辖市人民政府财政部门（以下简称省级财政部门）负责本行政区域财政票据的印制、发放、核销、销毁和监督检查等工作，指导下级财政部门财政票据管理工作。 省级以下财政部门负责本行政区域财政票据的申领、发放、核销、销毁和监督检查等工作。"},{"i":5,"n":"第五条","txt":"财政部门应当积极推进财政票据电子化改革，依托计算机和网络技术手段，实行电子开票、自动核销、全程跟踪、源头控制，提高财政票据管理水平。"},{"i":6,"n":"第六条","txt":"财政票据的种类和适用范围如下： （一）非税收入类票据 1.非税收入通用票据，是指行政事业单位依法收取政府非税收入时开具的通用凭证。 2.非税收入专用票据，是指特定的行政事业单位依法收取特定的政府非税收入时开具的专用凭证。主要包括行政事业性收费票据、政府性基金票据、国有资源（资产）收入票据、罚没票据等。 3.非税收入一般缴款书，是指实施政府非税收入收缴管理制度改革的行政事业单位收缴政府非税收入时开具的通用凭证。 （二）结算类票据 资金往来结算票据，是指行政事业单位在发生暂收、代收和单位内部资金往来结算时开具的凭证。 （三）其他财政票据 1.公益事业捐赠票据，是指国家机关、公益性事业单位、公益性社会团体和其他公益性组织依法接受公益性捐赠时开具的凭证。 2.医疗收费票据，是指非营利医疗卫生机构从事医疗服务取得医疗收入时开具的凭证。 3.社会团体会费票据，是指依法成立的社会团体向会员收取会费时"},{"i":7,"n":"第七条","txt":"财政票据包括非定额和定额两种形式。 非定额财政票据应当包括票据名称、票据编码、票据监制章、项目、标准、数量、金额、交款人、开票日期、联次及其用途、开票单位、开票人、复核人等内容。 定额财政票据应当包括票据名称、票据编码、票据监制章、金额、开票日期、联次及其用途等内容。"},{"i":8,"n":"第八条","txt":"非定额财政票据一般设置三联，包括存根联、收据联、记账联，各联次采用不同颜色予以区分。定额财政票据一般设置两联，包括存根联、收据联。存根联由开票方留存，收据联由支付方收执，记账联由开票方留做记账凭证。 非税收入一般缴款书属于非定额财政票据，一般设置五联，包括回单联、借方凭证、贷方凭证、收据联、存根联。回单联退执收单位，借方凭证和贷方凭证分别由缴款人、收款人开户银行留存，收据联由缴款人收执，存根联由执收单位留存。 第三章财政票据的印制"},{"i":9,"n":"第九条","txt":"财政票据由省级以上财政部门按照管理权限分别监（印）制。"},{"i":10,"n":"第十条","txt":"省级以上财政部门应当按照国家政府采购有关规定确定承印财政票据的企业，并与其签订印制合同。 财政票据印制企业应当按照印制合同和财政部门规定的式样印制票据。 禁止私自印制、伪造、变造财政票据。"},{"i":11,"n":"第十一条","txt":"印制财政票据应当使用省级以上财政部门确定的防伪专用品。禁止私自生产、使用或者伪造财政票据防伪专用品。"},{"i":12,"n":"第十二条","txt":"财政票据应当套印全国统一式样的财政票据监制章。财政票据监制章的形状、规格和印色由财政部统一规定。 禁止伪造、变造财政票据监制章，禁止在非财政票据上套印财政票据监制章。"},{"i":13,"n":"第十三条","txt":"财政票据应当使用中文印制。民族自治地方的财政票据，可以加印一种当地通用的民族文字。有实际需要的，可以同时使用中外两种文字印制。"},{"i":14,"n":"第十四条","txt":"财政票据印制企业应当建立票据印制管理制度和保管措施，对财政票据式样模板、财政票据监制章印模、防伪专用品等的使用和管理实行专人负责，不得将承印的财政票据委托其他企业印制，不得向委托印制票据的财政部门以外的其他单位或者个人提供财政票据。"},{"i":15,"n":"第十五条","txt":"印制合同终止后，财政票据印制企业应当将印制票据所需用品、资料交还委托印制票据的财政部门，不得自行保留或者提供给其他单位或者个人。"},{"i":16,"n":"第十六条","txt":"禁止在境外印制财政票据。"},{"i":17,"n":"第十七条","txt":"财政票据实行不定期换版制度。全国统一式样的财政票据换版时间、内容和要求，由财政部确定；非全国统一式样的财政票据换版时间、内容和要求，由财政部和省级财政部门按照职责权限分别确定。 财政票据换版时应当进行公告。"},{"i":18,"n":"第十八条","txt":"省级以下财政部门应当根据本地区用票需求，按照财政管理体制向上一级财政部门报送用票计划，申领财政票据。上级财政部门经审核后发放财政票据。"},{"i":19,"n":"第十九条","txt":"财政票据实行凭证领购、分次限量、核旧领新制度。 领购财政票据，一般按照财务隶属关系向同级财政部门申请。"},{"i":20,"n":"第二十条","txt":"首次领购财政票据，应当按照规定程序办理《财政票据领购证》。 办理《财政票据领购证》，应当提交申请函、单位法人证书、组织机构代码证书副本原件及复印件，填写《财政票据领购证申请表》，并按照领购财政票据的类别提交相关依据。 领购非税收入类票据的，应当根据收取非税收入的性质分别提交下列依据： （一）收取行政事业性收费的，提交国务院或者省级人民政府及其财政、价格主管部门批准收取行政事业性收费的文件复印件； （二）收取政府性基金的，提交国务院或者财政部批准收取政府性基金的文件复印件； （三）收取国有资源（资产）收入的，提交国务院或者省级人民政府及其财政部门批准收取国有资源收入的文件复印件，或者有关部门批准出租、出借、处置国有资产的文件复印件； （四）收取罚没收入的，提交证明本单位具有罚没处罚权限的法律依据。 领购其他财政票据的，分别提交下列依据： （一）领购公益事业捐赠票据的，提交本单位符合接受捐"},{"i":21,"n":"第二十一条","txt":"受理申请的财政部门应当对申请单位提交的材料进行审核，对符合条件的单位，核发《财政票据领购证》，并发放财政票据。 《财政票据领购证》应当包括单位基本信息、使用的财政票据名称、非税收入项目（含标准）、文件依据、购领票据记录、审核票据记录、作废票据记录、票据检查及违纪处理记录、销毁票据记录等项目。"},{"i":22,"n":"第二十二条","txt":"再次领购财政票据，应当出示《财政票据领购证》，提供前次票据使用情况，包括票据的种类、册（份）数、起止号码、使用份数、作废份数、收取金额及票据存根等内容。受理申请的财政部门审核后，核销财政票据存根，并发放财政票据。"},{"i":23,"n":"第二十三条","txt":"领购未列入《财政票据领购证》内的财政票据，应当向原核发领购证的财政部门提出申请，并依照本办法规定提交相应材料。受理申请的财政部门审核后，应当在《财政票据领购证》上补充新增财政票据的相关信息，并发放财政票据。"},{"i":24,"n":"第二十四条","txt":"财政票据一次领购的数量一般不超过本单位六个月的使用量。"},{"i":25,"n":"第二十五条","txt":"财政部门发放财政票据时，对按照规定可以收取工本费的，收取后应当缴入同级国库，纳入预算管理。"},{"i":26,"n":"第二十六条","txt":"财政票据使用单位应当指定专人负责管理财政票据，建立票据使用登记制度，设置票据管理台账，按照规定向财政部门报送票据使用情况。"},{"i":27,"n":"第二十七条","txt":"财政票据应当按照规定填写，做到字迹清楚、内容完整真实、印章齐全、各联次内容和金额一致。填写错误的，应当另行填写。 因填写错误等原因而作废的财政票据，应当加盖作废戳记或者注明“作废”字样，并完整保存各联次，不得擅自销毁。"},{"i":28,"n":"第二十八条","txt":"填写财政票据应当统一使用中文。财政票据以两种文字印制的，可以同时使用另一种文字填写。"},{"i":29,"n":"第二十九条","txt":"财政票据使用单位不得转让、出借、代开、买卖、擅自销毁、涂改财政票据；不得串用财政票据，不得将财政票据与其他票据互相替代。"},{"i":30,"n":"第三十条","txt":"省级财政部门印制的财政票据应当在本行政区域内发放使用，但派驻外地的单位在派驻地使用的情形除外。"},{"i":31,"n":"第三十一条","txt":"财政票据应当按照规定使用。不按规定使用的，付款单位和个人有权拒付款项，财务部门不得报销。"},{"i":32,"n":"第三十二条","txt":"财政票据使用完毕，使用单位应当按照要求填写相关资料，按顺序清理财政票据存根、装订成册、妥善保管。 财政票据存根的保存期限一般为5年。保存期满需要销毁的，报经原核发票据的财政部门查验后销毁。保存期未满、但有特殊情况需要提前销毁的，应当报原核发票据的财政部门批准。"},{"i":33,"n":"第三十三条","txt":"尚未使用但应予作废销毁的财政票据，使用单位应当登记造册，报原核发票据的财政部门核准、销毁。"},{"i":34,"n":"第三十四条","txt":"财政票据使用单位发生合并、分立、撤销、职权变更，或者收费项目被依法取消或者名称变更的，应当自变动之日起15日内，向原核发票据的财政部门办理《财政票据领购证》的变更或者注销手续；对已使用财政票据的存根和尚未使用的财政票据应当分别登记造册，报财政部门核准、销毁。"},{"i":35,"n":"第三十五条","txt":"财政票据或者《财政票据领购证》灭失的，财政票据使用单位应当查明原因，及时以书面形式报告原核发票据的财政部门，并自发现之日起3日内登报声明作废。"},{"i":36,"n":"第三十六条","txt":"财政部门、财政票据印制企业、财政票据使用单位应当设置财政票据专用仓库或者专柜，指定专人负责保管，确保财政票据安全。"},{"i":37,"n":"第三十七条","txt":"财政部门应当建立健全财政票据监督检查制度，对财政票据印制、使用、管理等情况进行检查。"},{"i":38,"n":"第三十八条","txt":"财政部门实施监督检查，应当按照规定程序和要求进行，不得滥用职权、徇私舞弊，不得向被检查单位收取费用。"},{"i":39,"n":"第三十九条","txt":"财政票据使用单位和财政票据印制企业应当自觉接受财政部门的监督检查，如实反映情况，提供有关资料，不得隐瞒、弄虚作假或者拒绝、阻挠。"},{"i":40,"n":"第四十条","txt":"单位和个人违反本办法规定，有下列行为之一的，由县级以上财政部门责令改正并给予警告；对非经营活动中的违法行为，处以1000元以下罚款；对经营活动中的违法行为，有违法所得的，处以违法所得金额3倍以下不超过30000元的罚款，没有违法所得的，处以10000元以下罚款。涉嫌犯罪的，依法移送司法机关： （一）违反规定印制财政票据； （二）转让、出借、串用、代开财政票据； （三）伪造、变造、买卖、擅自销毁财政票据； （四）伪造、使用伪造的财政票据监制章； （五）未按规定使用财政票据监制章； （六）违反规定生产、使用、伪造财政票据防伪专用品； （七）在境外印制财政票据； （八）其他违反财政票据管理规定的行为。 单位和个人违反本办法规定，对涉及财政收入的财政票据有本条第一款所列行为之一的，依照《财政违法行为处罚处分条例》第十六条的规定予以处理、处罚。"},{"i":41,"n":"第四十一条","txt":"财政部门、行政事业单位工作人员违反本办法规定，在工作中徇私舞弊、玩忽职守、滥用职权的，依法给予处分；涉嫌犯罪的，依法移送司法机关。"},{"i":42,"n":"第四十二条","txt":"单位和个人对处理、处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。 国家工作人员对处分不服的，可以依照有关规定申请复核或者提出申诉。"},{"i":43,"n":"第四十三条","txt":"中国人民解放军和中国人民武装警察部队适用《军队票据管理规定》。"},{"i":44,"n":"第四十四条","txt":"省级财政部门可以依据本办法，结合本地区实际情况制定具体实施办法，报财政部备案。"},{"i":45,"n":"第四十五条","txt":"本办法自2013年1月 1日起施行。1998年9月21日财政部发布的《行政事业性收费和政府性基金票据管理规定》（财综字〔1998〕 104号）同时废止。"}],"caizhengxingzhengchufatingzhengshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范财政部门行政处罚听证程序,维护公民、法人和其他组织的合法权益，保障和监督财政部门依法实施行政处罚，根据《中华人民共和国行政处罚法》，制定本办法。"},{"i":2,"n":"第二条","txt":"财政部门行政处罚听证，应当遵循合法、公正、公开、及时和便民的原则，保障当事人陈述、申辩和质证的权利。"},{"i":3,"n":"第三条","txt":"听证由拟作出财政行政处罚的财政部门组织，具体工作由其法制工作机构或者财政部门负责人指定的机构负责实施。"},{"i":4,"n":"第四条","txt":"听证人员包括：听证主持人、听证员和记录员。 听证主持人由财政部门负责人指定本部门非本案调查人员担任。 听证员由听证主持人所在机构负责人指定非本案调查人员担任，协助听证主持人工作。 记录员由听证主持人指定非本案调查人员担任，负责听证笔录等具体工作。 财政部各地监管局（以下简称监管局）作出的财政行政处罚，其听证主持人由该监管局负责人指定非本案调查人员担任。"},{"i":5,"n":"第五条","txt":"听证参加人包括：当事人及其代理人、案件调查人员、第三人及其代理人、证人、鉴定人、翻译人员等有关人员。"},{"i":6,"n":"第六条","txt":"财政部门拟作出下列行政处罚决定的，应当告知当事人有要求听证的权利，当事人要求听证的，财政部门应当组织听证： （一）吊销行政许可证件; （二）暂停会计师事务所执业; （三）责令资产评估机构停业; （四）禁止供应商参加政府采购活动、禁止采购代理机构代理政府采购业务； （五）责令会计人员不得从事会计工作； （六）暂停注册会计师执行业务； （七）责令资产评估专业人员停止从业； （八）较大数额罚款； （九）没收较大数额违法所得、没收较大价值非法财物； （十）法律、法规和规章规定的其他事项。 财政部作出罚款、没收违法所得、没收非法财物等行政处罚的，“较大数额”、“较大价值”标准为对公民作出1万元以上的处罚，对法人或者其他组织作出10万元以上的处罚。 地方财政部门作出罚款、没收违法所得、没收非法财物等行政处罚的，其听证相关数额标准按照各省、自治区、直辖市人大常委会或者人民政府的规定执行。"},{"i":7,"n":"第七条","txt":"财政部门告知当事人有要求举行听证的权利，应当送达《财政行政处罚事项告知书》。《财政行政处罚事项告知书》应当载明行政处罚的内容及事实、理由、依据，当事人依法享有的权利等。"},{"i":8,"n":"第八条","txt":"当事人要求听证的，可以在《财政行政处罚事项告知书》的送达回证上签署意见，也可以向财政部门书面提出。听证申请应当在收到《财政行政处罚事项告知书》之日起5日内提出，未在规定期限内提出的，财政部门视为放弃听证权利，并记录在案。"},{"i":9,"n":"第九条","txt":"财政部门应当在收到当事人听证申请之日起30日内组织听证，并在举行听证的7日前将《财政行政处罚听证通知书》送达听证参加人。《财政行政处罚听证通知书》应当载明听证的时间、地点，听证主持人、听证员、记录员的姓名，当事人的权利及其他有关事项。听证参加人应当在收到《财政行政处罚听证通知书》的3日内将送达回证发回财政部门。"},{"i":10,"n":"第十条","txt":"当事人可以亲自参加听证，也可以委托1至2名代理人参加听证。当事人委托代理人参加听证的，应当在举行听证日前向财政部门提交委托人签名或者盖章的授权委托书及委托代理人的身份证明文件。授权委托书应当载明委托事项及权限。委托代理人代为撤回听证申请或者明确放弃听证权利的，应当有委托人的明确授权。"},{"i":11,"n":"第十一条","txt":"当事人认为听证人员、鉴定人、翻译人员与本案有直接利害关系或其他关系可能影响公正听证的，有权申请回避。 听证人员、鉴定人、翻译人员认为自己与本案有直接利害关系或其他关系可能影响公正听证的，应当主动提出回避。"},{"i":12,"n":"第十二条","txt":"听证主持人的回避，由组织听证的财政部门负责人决定。 听证员的回避，由听证主持人所在机构负责人决定。 记录员、鉴定人、翻译人员的回避，由听证主持人决定。"},{"i":13,"n":"第十三条","txt":"除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，听证应当公开举行。 当事人认为不宜公开进行听证的，应当在收到《财政行政处罚听证通知书》之日起3日内书面提出。 公开举行听证的案件，应当先期公告当事人的姓名或名称、案由和听证的时间、地点，并应当允许公众旁听。"},{"i":14,"n":"第十四条","txt":"听证应当按照下列程序进行： （一）听证开始前由记录员查明听证参加人身份、到场情况，并宣读听证纪律； （二）听证主持人宣读听证事由、听证会组成人员，告知听证参加人的权利和义务，宣布听证开始； （三）案件调查人员提出已掌握的事实、证据，拟作出行政处罚的理由、依据以及处罚意见； （四）当事人或其代理人进行陈述、申辩，并可以提出与案件事实相关的证据； （五）第三人或其代理人进行陈述，并可以提出与案件事实相关的证据； （六）当事人或其代理人、第三人或其代理人和案件调查人员就案件的事实、各自出示证据的合法性、真实性、关联性等问题进行相互质证、辩论。经听证主持人允许，双方可以向证人、鉴定人员发问； （七）辩论终结，听证主持人可以就案件的事实、证据及有关问题，再次征求听证参加人的意见； （八）当事人或其代理人、第三人或其代理人、案件调查人员作最后陈述； （九）听证主持人宣布听证结束。"},{"i":15,"n":"第十五条","txt":"听证举行的全过程应当进行录像或者录音，并由记录员制作听证笔录。 听证笔录应当交听证参加人确认无误后签字或者盖章。听证参加人认为有错误的，有权要求补充或者改正。听证参加人拒绝签字或者盖章的，应当在笔录中注明。 听证主持人、听证员和记录员应当对听证笔录进行审阅、签名。"},{"i":16,"n":"第十六条","txt":"听证过程中，听证参加人违反听证纪律或者扰乱听证秩序的，听证主持人应当予以制止；制止无效的，可以责令其退出听证会场。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，由听证主持人决定延期举行听证： （一）当事人或其代理人在举行听证日前书面申请延期，且延期理由正当的； （二）听证参加人违反听证纪律或扰乱听证秩序，听证主持人制止无效的； （三）可以延期的其他情形。 延期举行听证的，财政部门应当及时向听证参加人送达《财政行政处罚听证延期通知书》，告知延期理由和重新听证的时间。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，由听证主持人决定中止听证： （一）听证主持人认为证据有疑问无法听证辩明，可能影响财政部门行政处罚决定的准确和公正的，或者当事人或其代理人提出新的事实、理由和证据，主持人认为需要重新调查核实的； （二）存在回避情形，且无法即时更换被申请回避人员致使听证无法按期举行的； （三）申请听证的公民死亡、法人或者其他组织终止，尚未确定权利义务承受人的； （四）因不可抗力，致使听证无法继续举行的； （五）可以中止听证的其他情形。 中止举行听证的，财政部门应当及时向听证参加人送达《财政行政处罚听证中止通知书》，告知中止理由。 中止情形消失后，财政部门应当在举行听证的时间确定后重新向听证参加人送达《财政行政处罚听证通知书》。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，由具体负责实施听证工作的机构负责人决定终止听证： （一）有权提起听证的公民死亡、丧失行为能力，没有继承人或者继承人放弃听证权利的,以及没有监护人或者监护人放弃听证权利的； （二）有权提起听证的法人或者其他组织终止，无权利义务承受人或者承受其权利的法人或者组织放弃听证权利的； （三）当事人书面撤回听证申请，放弃听证权利的； （四）当事人及其代理人无正当理由拒不出席听证或未经主持人许可中途退出的； （五）可以终止听证的其他情形。"},{"i":20,"n":"第二十条","txt":"听证结束后，财政部门应当根据听证笔录，依法作出行政处罚决定。"},{"i":21,"n":"第二十一条","txt":"听证主持人、听证员、记录员应当严格按照法律及有关规定履行职责。违反法律及有关规定的，取消其听证主持人、听证员、记录员的资格，并承担相应的责任。"},{"i":22,"n":"第二十二条","txt":"财政部门对依法应当听证的行政处罚事项不组织听证，或者不按照规定组织听证的，不得作出行政处罚决定。"},{"i":23,"n":"第二十三条","txt":"因组织听证所发生的费用由组织听证的财政部门承担。 当事人参加听证所发生的费用，组织听证的财政部门不予承担。"},{"i":24,"n":"第二十四条","txt":"当事人同意并签订确认书的，财政部门可以采用传真、电子邮件等电子方式送达《财政行政处罚事项告知书》、《财政行政处罚听证通知书》、《财政行政处罚听证延期通知书》、《财政行政处罚听证中止通知书》等文书。"},{"i":25,"n":"第二十五条","txt":"经过听证程序的案件，听证期间不计算在行政处罚决定的期限内。 听证期间为当事人提出听证申请之日至听证笔录由听证参加人完成签字或者盖章之日。"},{"i":26,"n":"第二十六条","txt":"本办法中“3日”、“5日”、“7日”的规定是指工作日，不含法定节假日。"},{"i":27,"n":"第二十七条","txt":"本办法自2022年3月1日起施行。《财政机关行政处罚听证实施办法》（财政部令第23号）同时废止。"}],"caizhengbuxinfanggongzuobanfa":[{"i":1,"n":"第一条","txt":"为了加强财政部信访工作，保持财政部门同人民群众的密切联系，保护信访人合法权益，维护信访秩序，根据《信访条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"财政部及所属单位应当按照本办法规定组织信访工作，处理来信，接待来访，对信访人提出的投诉、申诉、检举、意见和建议进行研究，及时、正确处理信访人反映的问题。"},{"i":3,"n":"第三条","txt":"财政部信访工作坚持统一领导，分工负责，谁主管、谁负责，依法、及时解决与疏导教育相结合的原则。各单位应当按照职责分工组织信访工作，使信访工作制度化、规范化，充分发挥其联系群众、反馈民意、民主监督、化解矛盾的作用。"},{"i":4,"n":"第四条","txt":"财政部信访工作实行主要领导负责制。各级领导应当加强对信访工作的领导，阅批来信，接待来访，听取信访工作汇报，指导、督促财政部及本单位信访工作。"},{"i":5,"n":"第五条","txt":"财政部信访工作机构及其工作人员应当切实履行职责，及时协调处理群众来信，接待群众来访，不得推诿、敷衍、拖延。 具体办理信访事项的单位及其工作人员应当贯彻党和国家各项方针政策，严格依法办事，妥善处理信访事项。"},{"i":6,"n":"第六条","txt":"财政部信访工作应当保护信访人合法权益。对投诉、检举及反映问题的信访人个人信息予以保密；需调查处理的信访事项，应当由被举报单位上一级机关或有关部门查证，不得将举报信或举报内容转交或泄露给被举报单位和个人。"},{"i":7,"n":"第七条","txt":"财政部设立信访工作领导小组（以下简称领导小组），全面负责财政部信访工作。主要职责如下： （一）贯彻执行党和国家有关信访工作方针、政策和法律、行政法规； （二）拟订财政部信访工作规章制度； （三）指导、督促国务院批转财政部办理的信访事项； （四）协调处理重大或异常信访事件。"},{"i":8,"n":"第八条","txt":"财政部信访工作领导小组办公室（以下简称信访办）是领导小组的办事机构，设在财政部办公厅，负责落实领导小组布置的各项任务，承办日常信访工作事项。主要职责如下： （一）受理信访事项，组织处理信访人来信，接待或安排接待信访人来访； （二）向部内有关单位交办信访事项，并协调、催办、检查，必要时配合了解信访事项情况； （三）在信访信息系统登记信访事项，公布信访事项处理进程及结果（举报类除外）； （四）协调办理国务院及有关单位交办的信访事项； （五）督促办理部领导批示的信访事项； （六）统一书面回复信访人信访事项是否受理及处理结果； （七）研究、分析财政部信访工作情况，编写有关工作简报，反映、报告信访工作情况； （八）对部内各单位信访工作进行业务指导； （九）依法提出对违反本办法有关规定的责任人的行政处分建议； （十）就重大、复杂信访事项组织召开信访听证会。"},{"i":9,"n":"第九条","txt":"部内各单位依据各自职责，具体承办有关信访事项。主要职责如下： （一）研究、处理信访人提出的信访事项； （二）向信访办书面回复信访人提出的信访事项处理意见； （三）组织研究、分析信访中反映的情况，提出完善和改进工作建议。"},{"i":10,"n":"第十条","txt":"财政部信访工作实行领导负责制，定期或不定期安排领导接待来访。领导接待来访的时间、地点向社会公布。"},{"i":11,"n":"第十一条","txt":"财政部信访办工作地址、邮政编码、电子信箱、工作电话向社会公布。接待来访工作时间和地点向社会公布。有关情况发生变更，应当于7日内重新公布。"},{"i":12,"n":"第十二条","txt":"信访事项处理程序： （一）信息接收。信访人采取来信方式的，当日来信，当日拆封，将信封、信件及其附件一并装订；采用电子邮件、传真、电话、走访等方式的，收到当日将信访人提供的信息转为书面形式并装订。 （二）登记。将信访人姓名、工作单位（或家庭地址）、提供信息时间和主要内容输入信访信息系统。 （三）受理。信访办自收到信访人提出的信访事项之日起，15日内决定该信访事项是否受理，并书面告知信访人。对不属于财政职责范围的事项，信访办应当报告领导小组同意后作出不予受理决定，并书面告知信访人不予受理的理由及应当受理部门或机构。信访人姓名、住址不清的除外。 （四）报告。对投诉、申诉、检举信件和意见、建议涉及重要工作的，信访办应当及时报告领导小组负责人。 （五）分转。对于受理的信访事项，信访办按照来信内容和部内各单位职责分工转送有关单位办理。需两个以上单位共同办理的，应当明确主办单位和协办单位。 （六）转"},{"i":13,"n":"第十三条","txt":"各单位对信访人要文明、热情、诚恳，耐心听取来访群众的陈述，了解问题要点和来访人基本要求，如实记录。 对来访人询问有关财税业务、举报违反财税法规等方面的问题，必要时按照部内职责分工由相关单位直接接谈。"},{"i":14,"n":"第十四条","txt":"信访事项经调查核实，分别作出以下决定： （一）事实清楚、证据充分，作出相应的决定，并书面答复信访人。 （二）信访人的请求有一定合理性，应当对信访人作出解释，同时向有关单位提出完善制度的建议。 （三）信访人的请求不符合法律、法规及其他有关规定，不予支持，并书面答复信访人。"},{"i":15,"n":"第十五条","txt":"信访人对地方财政部门作出的信访事项处理意见不服，申请财政部复查、复核的，办理程序按照本办法第十二条及其他有关规定办理。对于重大、复杂信访事项的复核，信访人可以申请举行听证。"},{"i":16,"n":"第十六条","txt":"信访办应当就以下事项向领导小组提交年度工作报告： （一）受理信访事项的数据统计、信访事项涉及领域及被投诉较多的单位； （二）转办、督办情况； （三）信访事项办理情况； （四）信访工作中提出的完善政策和改进工作的建议及被采纳情况。"},{"i":17,"n":"第十七条","txt":"档案管理。 （一）信访信息原稿由信访办存档，妥善装订保管。保存期3年，期满销毁。 （二）各单位负责信访工作的人员，应当及时清理本单位承办的信访材料，将收集、整理后的相关材料退回信访办归档。各单位可根据需要留存原信复印件。 （三）地方财政部门报来的调查处理报告，送领导小组及有关单位阅批后退回信访办存档。 （四）信访工作简报，由信访办存档。 （五）信访年度工作报告经领导小组阅批后退回信访办存档。"},{"i":18,"n":"第十八条","txt":"本办法自2005年10月1日起施行。1998年10月21日发布的《财政部信访工作办法》同时废止。"}],"caizhengbumenneibujiandujianchabanfa":[{"i":1,"n":"第一条","txt":"为了规范财政部门内部监督检查行为，保障财政部门内部监督检查有效实施，根据《中华人民共和国预算法》、《中华人民共和国会计法》等法律的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府财政部门（以下简称财政部门）进行的内部监督检查，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称财政部门内部监督检查，是指财政部门统一领导、财政监督机构具体组织实施的，对本部门内部各业务管理机构和派出机构履行财政管理职责，本部门及所属单位预 算、财务与资产管理，本部门内部控制等情况的监督检查。"},{"i":4,"n":"第四条","txt":"财政部门应当按照依法监督、注重预防和规范管理的原则开展内部监督检查工作，促进本部门及其工作人员遵守国家法律制度、强化内部控制、防范管理风险、提高管理效能、推 进廉政建设。 上级财政部门应当督促和指导下级财政部门开展内部监督检查工作。"},{"i":5,"n":"第五条","txt":"财政部门内部监督检查工作实行主要领导负责制。财政部门主要负责人对本部门内部监督检查工作负总责，分管负责人负直接领导责任。"},{"i":6,"n":"第六条","txt":"财政部门应当对下列事项实施内部监督检查： （一）预算编制、预算执行、预算调整和决算等管理情况； （二）国库集中收付、财政和预算单位账户管理、国库现金管理、政府采购监督管理、国债和地方政府债券发行与兑付管理等情况； （三）税收减免等税政管理情况； （四）政府非税收入管理、财政票据管理、彩票管理情况； （五）财政专项资金管理情况； （六）行政事业单位及企业国有资产和财务管理情况； （七）会计管理、注册会计师行业和资产评估行业监管情况； （八）外国政府、国际金融组织贷款和赠款管理情况； （九）本部门及所属单位的预算、资产和财务管理情况； （十）财政部门内部控制制度建立与执行情况； （十一）对审计机关、上级财政部门等监督检查和本部门内部监督检查查出问题的整改落实情况； （十二）其他需要监督检查的事项。"},{"i":7,"n":"第七条","txt":"财政部门应当建立内部监督检查负责人专题会议制度和内部监督检查联络员制度等内部监督检查协调机制。 内部监督检查负责人专题会议由财政部门主要负责人或分管负责人主持，财政部门内部有关机构或所属单位负责人参加，通报内部监督检查情况，研究内部监督检查工作重点和问题整改等 相关问题。 财政部门内部各业务管理机构和所属单位应当设立内部监督检查联络员，协助和配合财政监督机构开展内部监督检查工作。"},{"i":8,"n":"第八条","txt":"财政部门内部监督检查人员以财政监督机构人员为主。必要时，报经财政部门主要负责人或分管负责人批准，财政监督机构可以抽调财政部门内部各业务管理机构、派出机构和所 属单位人员参与内部监督检查工作。 在对财政部门所属单位实施内部监督检查时，根据需要，财政监督机构可以聘用专门机构或者具有专门知识的人员协助检查人员开展内部监督检查工作。 财政部门内部监督检查人员开展内部监督检查工作时，必须忠于职守、依法监督、廉洁自律、保守秘密，做到公正、客观、规范、高效。"},{"i":9,"n":"第九条","txt":"财政部门应当重点监督检查本部门内部各业务管理机构和派出机构履行财政管理工作职责的合法性、合规性和有效性，本部门及所属单位预算、财务管理与会计核算的合法性、真 实性以及资产的完整性、安全性，财政部门内部控制的健全性、合理性和有效性。"},{"i":10,"n":"第十条","txt":"财政部门对财政部门内部控制进行监督检查时，应当从控制环境、风险评估、控制措施、信息与沟通和监督检查等方面进行检查评价，及时发现内部控制缺陷，防范管理风险，促 进完善财政部门内部控制。 检查评价的重点内容包括：内部控制制度建设、工作人员岗位胜任能力、风险识别与应对、授权批准、岗位职责分离、查验与核对、工作督导以及信息准确性与沟通有效性等。"},{"i":11,"n":"第十一条","txt":"财政监督机构根据工作需要，要求财政部门内部各业务管理机构、派出机构和所属单位提供有关文件、账表、凭证等相关资料的，有关机构和单位应当全面、及时地提供，并对 所提供资料的完整性和真实性负责。"},{"i":12,"n":"第十二条","txt":"财政部门应当结合本部门实际情况，综合运用日常监督和重点检查方式开展内部监督检查工作，实现对本部门管理活动的全过程监督。 日常监督是指对日常财政管理活动实施的实时、动态监督，包括事前审核、实时监控、现场核查、跟踪问效等。 重点检查是指根据年度重点检查计划，按照规定程序组织实施的有针对性、有重点的监督检查。"},{"i":13,"n":"第十三条","txt":"财政部门应当制定并按照年度重点检查计划，开展内部监督检查的重点检查工作。 年度重点检查计划由财政监督机构提出，报经财政部门负责人批准后及时通知被检查的各相关业务管理机构、派出机构和所属单位。 财部门每年对本部门有预算管理职能的内部各业务管理机构的重点检查数不得低于该类机构数的30%。"},{"i":14,"n":"第十四条","txt":"开展重点检查工作应当组成检查组，检查组组长由财政监督机构确定。检查组实行组长负责制。 检查人员与被检查单位或者检查事项有直接利害关系的，应当回避。"},{"i":15,"n":"第十五条","txt":"财政监督机构实施重点检查，一般应于3个工作日前向被检查单位送达检查通知书。 检查通知书应当包括下列内容： （一）被检查单位名称； （二）检查的依据、范围、内容、方式和实施计划； （三）对被检查单位配合检查工作的具体要求； （四）检查组组长及其他成员名单、联系电话； （五）财政监督机构印章及签发日期。"},{"i":16,"n":"第十六条","txt":"实施重点检查时，经批准，检查人员可以向与被检查单位有经济业务往来的部门和单位核实有关情况。必要时，可以根据《财政检查工作办法》（财政部令第32号）对有关问题进行延伸检查。"},{"i":17,"n":"第十七条","txt":"检查组对被检查单位实施检查或调查、询问时，检查人员不得少于2人。 证明材料应当有提供者的签名或盖章。未取得提供者签名或盖章的，检查人员应当注明原因。 检查人员应当将检查内容与事项予以记录和摘录，编制财政检查工作底稿，并由被检查单位相关人员签字或者被检查单位盖章。"},{"i":18,"n":"第十八条","txt":"检查组组长应当对检查人员的工作质量进行监督，并对有关事项进行必要的审查和复核，实施检查中遇到重大问题，应当及时报告。"},{"i":19,"n":"第十九条","txt":"检查结束前，检查组应当就检查工作的基本情况、被检查单位存在的问题等事项征求被检查单位意见。被检查单位应当在5个工作日内予以回复。在规定期限内没有回复的，视为无异议。"},{"i":20,"n":"第二十条","txt":"检查组应当在被检查单位回复意见后10个工作日内向财政监督机构提交检查报告。 检查报告应当包括以下内容： （一）被检查单位财政财务管理、会计核算、内部控制运行等基本情况及对该单位工作的基本评价； （二）被检查单位违法行为的基本事实、认定依据和处理意见； （三）改进财政、财务管理的意见和建议； （四）其他应当报告的事项。"},{"i":21,"n":"第二十一条","txt":"财政监督机构应当在检查组提交检查报告后5个工作日内，从以下几个方面对检查报告进行复核： （一）对被检查单位的工作评价是否恰当； （二）与检查事项有关的事实是否清楚； （三）检查证据是否真实、充分； （四）对有关问题的定性和处理意见是否合法、适当，表述是否准确； （五）提出的改进建议是否适当； （六）其他需要复核的事项。"},{"i":22,"n":"第二十二条","txt":"财政监督机构应当将复核形成的检查报告送被检查单位征求意见。被检查单位应当自收到检查报告之日起5个工作日内，提出书面意见或说明；无正当理由逾期没有提出书面意见或说明的，视为无异议。 财政监督机构应当将检查情况、审定后的检查报告和被检查单位的书面意见，一并上报财政部门负责人。"},{"i":23,"n":"第二十三条","txt":"检查报告经财政部门负责人同意后，财政监督机构应当及时将财政部门负责人要求、监督检查结论和处理意见送达被检查单位。"},{"i":24,"n":"第二十四条","txt":"财政部门内部各业务管理机构、派出机构和所属单位，应当做好内部监督检查发现问题的整改工作。有关机构和单位应当在收到监督检查结论和处理意见后30日内，将整改情况书面报告财政部门负责人，并抄送财政监督机构。"},{"i":25,"n":"第二十五条","txt":"财政监督机构应当定期回访被检查单位整改落实内部监督检查处理意见和管理建议的情况，定期检查审计机关和上级财政部门查出问题的整改情况，并向财政部门负责人报 告。"},{"i":26,"n":"第二十六条","txt":"财政部门应当建立内部监督检查专题报告制度。财政监督机构应当定期对内部监督检查中发现的共性问题进行归纳总结，分析原因，提出建议，并向财政部门负责人专题报 告。"},{"i":27,"n":"第二十七条","txt":"财政部门应当将内部监督检查结果作为财政部门内部各业务管理机构、派出机构和所属单位评选先进和干部考核、任用的参考依据。 财政部门有预算管理职能的内部各业务管理机构，应当将内部监督检查结果作为加强预算管理的参考依据。"},{"i":28,"n":"第二十八条","txt":"全部检查工作结束后30日内，财政监督机构应当将检查资料进行鉴别整理，依照档案管理的有关规定归卷存档。"},{"i":29,"n":"第二十九条","txt":"财政部门应当推进内部监督检查信息化建设，实现财政监督机构与其他业务管理机构对于财政管理信息系统的信息共享，充分利用计算机信息化技术开展内部监督检查工作。"},{"i":30,"n":"第三十条","txt":"内部监督检查发现的被检查单位和个人的违法违纪行为，依照有关法律、法规的规定追究相应责任。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的被检查单位和个人，由财政部门根据有关规定给予内部通报批评或行政处分；涉嫌犯罪的，依法移送司法机关处理： （一）拒绝、拖延提供情况和资料或者提供虚假情况和资料的； （二）妨碍内部监督检查人员行使职权的； （三）拒不执行内部监督检查决定的； （四）报复陷害内部监督检查人员的。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的内部监督检查人员，由财政部门根据有关规定给予处理；涉嫌犯罪的，依法移送司法机关处理： （一）弄虚作假，隐瞒事实真相的； （二）滥用职权，以权谋私的； （三）玩忽职守，给国家和单位造成重大损失的； （四）泄露国家秘密或者被监督检查单位秘密的。"},{"i":33,"n":"第三十三条","txt":"各省、自治区、直辖市和计划单列市财政厅（局），新疆生产建设兵团财务局，可以根据本办法，结合实际情况制定具体实施办法。"},{"i":34,"n":"第三十四条","txt":"本办法自2010年3月1日起实施。2002年1月16日财政部发布的《财政部门内部监督检查暂行办法》（财监[2002]3号）和2003年12月30日财政部发布的《财政部内部监督检查工作规则（试行）》（财监[2003]129号）同时废止。"}],"caizhengbumenshishikuaijijiandubanfa":[{"i":1,"n":"第一条","txt":"为规范财政部门会计监督工作，保障财政部门有效实施会计监督，保护公民、法人和其他组织的合法权益，根据《中华人民共和国会计法》（以下简称《会计法》）、《中华人民共和国行政处罚法》（以下简称《行政处罚法》）、《企业财务会计报告条例》等有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国务院财政部门及其派出机构和县级以上地方各级人民政府财政部门（以下统称财政部门）对国家机关、社会团体、公司、企业、事业单位和其他组织（以下统称单位）执行《会计法》和国家统一的会计制度的行为实施监督检查以及对违法会计行为实施行政处罚，适用本办法。 当事人的违法会计行为依法应当给予行政处分的，执行有关法律、行政法规的规定。"},{"i":3,"n":"第三条","txt":"县级以上财政部门负责本行政区域的会计监督检查，并依法对违法会计行为实施行政处罚。 跨行政区域行政处罚案件的管辖确定，由相关的财政部门协商解决；协商不成的，报请共同的上一级财政部门指定管辖。 上级财政部门可以直接查处下级财政部门管辖的案件，下级财政部门对于重大、疑难案件可以报请上级财政部门管辖。"},{"i":4,"n":"第四条","txt":"财政部门对违法会计行为案件的处理，应当按照本办法规定的程序，经审查立案、组织检查、审理后，作出处理决定。"},{"i":5,"n":"第五条","txt":"财政部门应当在内部指定专门的机构或者在相关机构中指定专门的人员负责会计监督检查和违法会计行为案件的立案、审理、执行、移送和案卷管理等工作。财政部门内部相关机构或者职责的设立，应当体现案件调查与案件审理相分离、罚款决定与罚款收缴相分离的原则。"},{"i":6,"n":"第六条","txt":"财政部门应当建立健全会计监督制度，并将会计监督与财务监督和其他财政监督结合起来，不断改进和加强会计监督工作。"},{"i":7,"n":"第七条","txt":"任何单位和个人对违法会计行为有权检举。 财政部门对受理的检举应当及时按照有关规定处理，不得将检举人姓名和检举材料转给被检举单位和被检举人个人。"},{"i":8,"n":"第八条","txt":"财政部门及其工作人员对在会计监督检查工作中知悉的国家秘密和商业秘密负有保密义务。"},{"i":9,"n":"第九条","txt":"财政部门依法对各单位设置会计账簿的下列情况实施监督检查： （一）应当设置会计账簿的是否按规定设置会计账簿； （二）是否存在账外设账的行为； （三）是否存在伪造、变造会计账簿的行为； （四）设置会计账簿是否存在其他违反法律、行政法规和国家统一的会计制度的行为。"},{"i":10,"n":"第十条","txt":"财政部门依法对各单位会计凭证、会计账簿、财务会计报告和其他会计资料的真实性、完整性实施监督检查，内容包括： （一）《会计法》第十条规定的应当办理会计手续、进行会计核算的经济业务事项是否如实在会计凭证、会计账簿、财务会计报告和其他会计资料上反映； （二）填制的会计凭证、登记的会计账簿、编制的财务会计报告与实际发生的经济业务事项是否相符； （三）财务会计报告的内容是否符合有关法律、行政法规和国家统一的会计制度的规定； （四）其他会计资料是否真实、完整。"},{"i":11,"n":"第十一条","txt":"财政部门依法对各单位会计核算的下列情况实施监督检查： （一）采用会计年度、使用记账本位币和会计记录文字是否符合法律、行政法规和国家统一的会计制度的规定； （二）填制或者取得原始凭证、编制记账凭证、登记会计账簿是否符合法律、行政法规和国家统一的会计制度的规定； （三）财务会计报告的编制程序、报送对象和报送期限是否符合法律、行政法规和国家统一的会计制度的规定； （四）会计处理方法的采用和变更是否符合法律、行政法规和国家统一的会计制度的规定； （五）使用的会计软件及其生成的会计资料是否符合法律、行政法规和国家统一的会计制度的规定； （六）是否按照法律、行政法规和国家统一的会计制度的规定建立并实施内部会计监督制度； （七）会计核算是否有其他违法会计行为。"},{"i":12,"n":"第十二条","txt":"财政部门依法对各单位会计档案的建立、保管和销毁是否符合法律、行政法规和国家统一的会计制度的规定实施监督检查。"},{"i":13,"n":"第十三条","txt":"财政部门依法对公司、企业执行《会计法》第二十五条和第二十六条的情况实施监督检查。"},{"i":14,"n":"第十四条","txt":"财政部门依法对各单位任用会计人员的下列情况实施监督检查： （一）从事会计工作的人员是否持有会计从业资格证书； （二）会计机构负责人（会计主管人员）是否具备法律、行政法规和国家统一的会计制度规定的任职资格。"},{"i":15,"n":"第十五条","txt":"国务院财政部门及其派出机构和省、自治区、直辖市财政部门依法对会计师事务所出具的审计报告的程序和内容实施监督检查。"},{"i":16,"n":"第十六条","txt":"财政部门实施会计监督检查可以采用下列形式： （一）对单位遵守《会计法》、会计行政法规和国家统一的会计制度情况进行全面检查； （二）对单位会计基础工作、从事会计工作的人员持有会计从业资格证书、会计人员从业情况进行专项检查或者抽查； （三）对有检举线索或者在财政管理工作中发现有违法嫌疑的单位进行重点检查； （四）对经注册会计师审计的财务会计报告进行定期抽查； （五）对会计师事务所出具的审计报告进行抽查； （六）依法实施其他形式的会计监督检查。"},{"i":17,"n":"第十七条","txt":"财政部门实施会计监督检查，应当执行《财政检查工作规则》（财政部财监字[1998]223号）和本办法规定的工作程序、要求，保证会计监督检查的工作质量。"},{"i":18,"n":"第十八条","txt":"在会计监督检查中，检查人员应当如实填写会计监督检查工作记录。 会计监督检查工作记录应当包括下列内容： （一）检查工作记录的编号； （二）被检查单位违法会计行为发生的日期、记账凭证编号、会计账簿名称和编号、财务会计报告名称和会计期间、会计档案编号； （三）被检查单位违法会计行为主要内容摘录； （四）会计监督检查工作记录附件的主要内容和页数； （五）其他应当说明的事项； （六）检查人员签章及填制日期； （七）检查组长签章及日期。 前款第（四）项所称会计监督检查工作记录附件应当包括下列材料： （一）与被检查事项有关的会计凭证、会计账簿、财务会计报告等会计资料的复印件； （二）与被检查事项有关的文件、合同、协议、往来函件等资料的复印件； （三）注册会计师及其会计师事务所出具的审计报告、有关资料的复印件； （四）其他有关资料。"},{"i":19,"n":"第十九条","txt":"财政部门实施会计监督检查，可以在被检查单位的业务场所进行；必要时，经财政部门负责人批准，也可以将被 检查单位以前会计年度的会计凭证、会计账簿、财务会计报告和其他有关资料调回财政部门检查，但须由组织检查的财政部门向被检查单位开具调用会计资料清单，并在三个月内完整退还。"},{"i":20,"n":"第二十条","txt":"财政部门在被检查单位涉嫌违法的证据可能灭失或者以后难以取得的情况下，经财政部门负责人批准，可以对证据先行登记保存，并应当在七日内对先行登记保存的证据作出处理决定。"},{"i":21,"n":"第二十一条","txt":"国务院财政部门及其派出机构在对有关单位会计资料的真实性、完整性实施监督检查过程中，发现重大违法嫌疑时，可以向与被检查单位有经济业务往来的单位查询被检查单位开立账户的金融机构查询有关情况。向与被检查单位有经济业务往来的单位查询有关情况，应当经国务院财政部门或者其派出机构负责人批准，并持查询情况许可证明；向被检查单位开立账户的金融机构查询情况，应当遵守《关于财政部及其派出机构查询被监督单位有关情况若干具体问题的通知》（财政部、中国人民银行财监字[2000]39号）的规定。"},{"i":22,"n":"第二十二条","txt":"检查组应当在检查工作结束后十日内，将会计监督检查报告、会计监督检查工作记录及其附件、被检查当事人提出的书面意见提交组织检查的财政部门。 会计监督检查报告应当包括下列内容： （一）检查的范围、内容、形式和时间； （二）被检查单位的基本情况； （三）检查组检查工作的基本情况； （四）当事人的违法会计行为和确认违法事实的依据； （五）对当事人给予行政处罚的建议； （六）对当事人给予行政处分的建议； （七）对涉嫌犯罪的当事人提出移送司法机关的建议； （八）其他需要说 明的内容； （九）检查组组长签章及日期。"},{"i":23,"n":"第二十三条","txt":"财政部门对于检查组提交的会计监督检查报告及其他有关材料应当按照本办法第四章的有关规定进行审理，并作出处理决定。"},{"i":24,"n":"第二十四条","txt":"财政部门在会计监督检查中实施行政处罚的种类包括： （一）警告； （二）罚款； （三）吊销会计从业资格证书。"},{"i":25,"n":"第二十五条","txt":"财政部门对违法会计行为查实后，应当责令当事人改正或者限期改正，并依法给予行政处罚。"},{"i":26,"n":"第二十六条","txt":"当事人有下列情形之一的，财政部门应当依法从轻给予行政处罚： （一）违法会计行为是初犯，且主动改正违法会计行为、消除危害后果的； （二）违法会计行为是受他人胁迫进行的； （三）配合财政部门查处违法会计行为有立功表现的； （四）其它依法应当从轻给予行政处罚的。"},{"i":27,"n":"第二十七条","txt":"当事人有下列情形之一的，财政部门应当依法从重给予行政处罚： （一）无故未能按期改正违法会计行为的； （二）屡查屡犯的； （三）抗拒、阻挠依法实施的监督，不如实提供有关会计资料和情况的； （四）胁迫他人实施违法会计行为的； （五）违法会计行为对单位的财务状况和经营成果产生重大影响的； （六）以虚假的经济业务事项或者资料为依据进行会计核算，造成会计信息严重失实的； （七）随意改变会计要素确认标准、计量方法，造成会计信息严重失实的； （八）违法会计行为是以截留、挪用、侵占、浪费国家财政资金为目的的； （九）违法会计行为已构成犯罪但司法机关免予刑事处罚的。"},{"i":28,"n":"第二十八条","txt":"财政部门在对本办法第九条、第十条、第十一条、第十二条、第十三条、第十四条规定的内容实施会计监督检查中，发现当事人有《会计法》第四十二条第一款所列违法会计行为的，应当依照《会计法》第四十二条的规定处理。"},{"i":29,"n":"第二十九条","txt":"财政部门在对本办法第九条、第十条、第十一条、第十二条、第十三条规定的内容实施会计监督检查中，发现当事人有伪造、变造会计凭证、会计账簿或者编制虚假财务会计报告的，应当依照《会计法》第四十三条的规定处理。"},{"i":30,"n":"第三十条","txt":"财政部门在对本办法第九条、第十条、第十一条、第十二条、第十三条规定的内容实施会计监督检查中，发现有隐匿或者故意销毁依法应当保存的会计凭证、会计账簿、财务会计报告的违法会计行为的，应当依照《会计法》第四十四条的规定处理。"},{"i":31,"n":"第三十一条","txt":"财政部门在实施会计监督检查中，发现被检查单位的有关人员有授意、指使、强令会计机构、会计人员及其他人员伪造、变造或者隐匿、故意销毁依法应当保存的会计凭证、会计账簿，编制虚假财务会计报告行为的，应当依照《会计法》第四十五条的规定处理。"},{"i":32,"n":"第三十二条","txt":"财政部门在会计监督检查中发现单位负责人对依法履行职责的会计人员实行打击报复的，应当依照《会计法》第四十六条的规定处理。"},{"i":33,"n":"第三十三条","txt":"财政部门对本办法第十五条规定的内容实施监督检查时，发现注册会计师及会计师事务所出具审计报告的程序和内容违反《中华人民共和国注册会计师法》规定的，应当依照《中华人民共和国注册会计师法》的有关规定处理。"},{"i":34,"n":"第三十四条","txt":"财政部门认为违法会计行为构成犯罪的，应当依照有关规定移送司法机关处理。"},{"i":35,"n":"第三十五条","txt":"财政部门的工作人员在实施会计监督中，有下列行为之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）滥用职权的； （二）玩忽职守、徇私舞弊的； （三）索贿受贿的； （四）泄露国家秘密、商业秘密的。"},{"i":36,"n":"第三十六条","txt":"财政部门对违法会计行为实施行政处罚，应当按照本章规定的程序办理。"},{"i":37,"n":"第三十七条","txt":"财政部门对公民、法人和其他组织检举的违法会计行为案件，应当予以审查，并在七日内决定是否立案。"},{"i":38,"n":"第三十八条","txt":"财政部门对违法会计行为案件的下列内容予以审查： （一）违法事实是否清楚； （二）证据是否确凿； （三）其他需要审查的内容。"},{"i":39,"n":"第三十九条","txt":"财政部门对符合下列条件的违法会计行为案件应当予以立案： （一）有明确的违法会计行为、违法会计行为人； （二）有可靠的事实依据； （三）当事人的违法会计行为依法应当给予行政处罚； （四）属于本机关管辖。"},{"i":40,"n":"第四十条","txt":"财政部门对违法会计行为案件审查后，认为不符合立案条件的，应当告知检举人，并将审查意见存档；认为案件依法应当由其他部门管辖的，及时将案件材料移送有关部门。"},{"i":41,"n":"第四十一条","txt":"对下列违法会计行为案件，财政部门可以直接立案： （一）在会计监督检查中发现的； （二）在其它财政监督检查中发现的； （三）在日常财政管理工作中发现的； （四）上级财政部门指定办理、下级财政部门上报的； （五）有关部门移送的。"},{"i":42,"n":"第四十二条","txt":"财政部门对按照本办法第三十七条、第三十九条和第四十一条（三）、（四）、（五）项规定立案的违法会计行为案件，应当按照本办法第二章规定的程序实施会计监督检查。"},{"i":43,"n":"第四十三条","txt":"财政部门应当建立违法会计行为案件的审理制度。 财政部门应当指定专门的机构或者在相关机构中指定专门的人员，负责对已经立案并实施会计监督检查的案件按照本章规定的程序审核检查组提交的有关材料，以确定是否对当事人给予行政处罚以及对当事人的处罚种类和幅度。"},{"i":44,"n":"第四十四条","txt":"财政部门对违法会计行为案件的审理应当依照有关法律、行政法规和规章的规定进行，并遵循实事求是、证据确凿、程序合法、错罚相当的原则。"},{"i":45,"n":"第四十五条","txt":"案件审理人员应当对违法会计行为案件的下列内容进行审查： （一）实施的会计监督检查是否符合法定程序； （二）当事人的违法事实是否清楚； （三）收集的证明材料是否真实、充分； （四）认定违法会计行为所适用的依据是否正确； （五）建议给予的行政处罚种类和幅度是否合法和适当； （六）当事人陈述和申辩的理由是否成立； （七）需要审理的其他事项。"},{"i":46,"n":"第四十六条","txt":"案件审理人员对其审理的案件可以分别作出下列处理： （一）对会计监督检查未履行法定程序的，经向财政部门负责人报告并批准后，采取必要的弥补措施。 （二）对违法事实不清、证据不充分的。中止审理，并通知有关检查人员予以说明或者补充、核实有关的检查材料。必要时，经财政部门负责人批准，可另行组织调查、取证。 （三）对认定违法会计行 为所适用的依据、建议给予的行政处罚的种类和幅度不正确、不适当的，提出修改意见。 （四）对审理事项没有异议的，签署同意意见。"},{"i":47,"n":"第四十七条","txt":"财政部门根据对违法会计行为案件的审理结果，分别作出下列处理决定： （一）违法事实不能成立的，不得给予行政处罚。 （二）违法会计行为轻微，依法不予行政处罚的，不予行政处罚。 （三）违法事实成立，依法应当给予行政处罚的，作出行政处罚决定。 （四）违法会计行为 应当给予行政处分的，将有关材料移送其所在单位或者有关单位，并提出给予行政处分的具体建议。 （五）按照有关法律、行政法规和规章的规定，违法行为应当由其他部门实施行政处罚的，将有关材料移送有关部门处理。 （六）认为违法行为构成犯罪的，将违法案件有关材料移送司法机关处理。"},{"i":48,"n":"第四十八条","txt":"财政部门对当事人没有违法会计行为或者违法会计行为轻微依法不予行政处罚的，应当制作会计监督检查结论，送达当事人，并根据需要将副本抄送有关单位。 会计监督检查结论包括下列内容： （一）财政部门的名称； （二）检查的范围、内容、形式和时间； （三）对检查事项未发现违法会计行为或者违法会计行为轻微依法不予行政处罚的说明； （四）要求当事人限期改正违法会计行为的期限； （五）其他需要说明的内容。"},{"i":49,"n":"第四十九条","txt":"财政部门对违法会计行为依法作出行政处罚决定后，应当制作会计监督行政处罚决定书，送达当事人，并根据需要将副本抄送有关单位。 会计监督行政处罚决定书应当载明下列事项： （一）当事人名称或者姓名、地址； （二）违反法律、行政法规、国家统一的会计制度的事实和证据； （三） 要求当事人限期改正违法会计行为的期限； （四）行政处罚决定及其依据； （五）行政处罚的履行方式和期限； （六）当事人不服行政处罚决定，申请行政复议或者提起行政诉论的途径和期限； （七）作出行政处罚决定的财政部门的名称、印章； （八）作出行政处罚决定的日期、处罚决定文号； （九）如果有附件应当说明附件的名称和数量。"},{"i":50,"n":"第五十条","txt":"财政部门在作出行政处罚决定之前，应当告知当事人作出行政处罚决定的事实、理由及依据。当事人有权进行陈述和申辩。 财政部门应当充分听取当事人的意见，并应当对当事人提出的事实、理由和证据 进行复核；当事人提出的事实、理由或者证据成立的，财政部门应当采纳。 财政部门不得因当事人申辩而加重处罚。"},{"i":51,"n":"第五十一条","txt":"财政部门作出较大数额罚款、吊销会计从业资格证书的行政处罚决定之前，应当告知当事人有要求听证的权利；当事人要求听证的，应当按照《财政部门行政处罚听证程序实施办法》（财政部财法字[1998]第18号）的规定组织听证。"},{"i":52,"n":"第五十二条","txt":"听证程序终结后，财政部门应当根据本办法第四十七条的规定作出处理决定。"},{"i":53,"n":"第五十三条","txt":"财政部门应当在接到会计监督检查报告之日起三十日内作出处理决定，并送达当事人；遇有特殊情况可延长至六十日内送达当事人。"},{"i":54,"n":"第五十四条","txt":"财政部门依法作出行政处罚决定后，应当在规定的期限内履行行政处罚决定。 当事人对行政处罚决定不服申请行政复议或者提起行政诉讼的，行政处罚不停止执行，但法律、行政法规另有规定的除外。"},{"i":55,"n":"第五十五条","txt":"当事人逾期不申请行政复议或者不提起行政诉讼又不履行处罚决定的，由作出行政处罚决定的财政部门申请人民法院强制执行。"},{"i":56,"n":"第五十六条","txt":"当事人到期不缴纳罚款的，作出处罚决定的财政部门可以按照《行政处罚法》的有关规定对当事人加处罚款。 当事人对加处罚款有异议的，应当先缴纳罚款和因逾期缴纳罚款所加处的罚款，再依法申请行政复议或者提起行政诉讼。"},{"i":57,"n":"第五十七条","txt":"案件结案后，案件审理人员应当做好案件材料的立卷归档工作。"},{"i":58,"n":"第五十八条","txt":"财政部门应当建立违法会计行为案件备案制度。 县级以上地方财政部门对适用听证程序、提起行政诉讼和上级财政部门指定办理的案件，应当在结案后三十日内向上一级财政部门备案。"},{"i":59,"n":"第五十九条","txt":"本办法所称“违法会计行为”，是指公民、法人和其它组织违反《会计法》和其他有关法律、行政法规、国家统一的会计制度的行为。 本办法所称“违法会计行为案件”，是指财政部门发现的或者受理的公民、法人和其它组织涉嫌有违法会计行为的案件。"},{"i":60,"n":"第六十条","txt":"本办法所称“当事人”，是指财政部门实施会计监督检查的单位及其对会计行为直接负责的主管人员和其他直接责任人员。"},{"i":61,"n":"第六十一条","txt":"本办法第五十一条所称“较大数额罚款”，是指对个人处以二千元以上罚款、对法人或者其他组织处以五万元以上罚款。 各省、自治区、直辖市通过的地方法规对“较大数额罚款”的限额另有规定的，可以不受上述数额的限制。"},{"i":62,"n":"第六十二条","txt":"本办法所称“限期改正”的期限原则上为十五日。有特殊原因需要延长的，由组织检查的财政部门决定。"},{"i":63,"n":"第六十三条","txt":"本办法所称的“日”，均指有效工作日。"},{"i":64,"n":"第六十四条","txt":"各省、自治区、直辖市、计划单列市财政部门、新疆生产建设兵团可以依照本办法制定具体的实施办法，报国务院财政部门备案。"},{"i":65,"n":"第六十五条","txt":"本办法自发布之日起施行。"}],"caizhengbumenjiandubanfa":[{"i":1,"n":"第一条","txt":"为了规范财政部门监督行为，加强财政管理，保障财政资金安全规范有效使用，维护国家财经秩序，根据国家有关财政管理法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府财政部门（以下简称财政部门）依法对单位和个人（以下统称监督对象）涉及财政、财务、会计等事项实施监督适用本办法。 省级以上人民政府财政部门派出机构在规定职权范围内依法实施监督。"},{"i":3,"n":"第三条","txt":"财政部门应当按照财政管理体制、财务隶属关系对财政、财务等事项实施监督；按照行政区域对会计事项实施监督。 上级财政部门应当加强对下级财政部门监督工作的指导；下级财政部门应当及时将监督中发现的重大问题向本级人民政府和上级财政部门报告。"},{"i":4,"n":"第四条","txt":"财政部门实施监督应当坚持事前、事中和事后监督相结合，建立覆盖所有政府性资金和财政运行全过程的监督机制。"},{"i":5,"n":"第五条","txt":"财政部门实施监督应当与财政管理相结合，将监督结果作为预算安排的重要参考依据；根据监督结果完善相关政策、加强财政管理。"},{"i":6,"n":"第六条","txt":"财政部门应当加强绩效监督，提高财政资金使用效益。"},{"i":7,"n":"第七条","txt":"财政部门应当加强信息化建设，充分运用现代技术手段实施监督，提高监督效率。"},{"i":8,"n":"第八条","txt":"财政部门的监督职责由本部门专职监督机构和业务管理机构共同履行；由专职监督机构实行统一归口管理、统一组织实施、统一规范程序、统一行政处罚。"},{"i":9,"n":"第九条","txt":"专职监督机构应当履行下列监督职责： （一）制定本部门监督工作规划； （二）参与拟定涉及监督职责的财税政策及法律制度； （三）牵头拟定本部门年度监督计划； （四）组织实施涉及重大事项的专项监督； （五）向业务管理机构反馈监督结果及意见； （六）组织实施本部门内部监督检查。"},{"i":10,"n":"第十条","txt":"业务管理机构应当履行下列监督职责： （一）在履行财政、财务、会计等管理职责过程中加强日常监督； （二）配合专职监督机构进行专项监督； （三）根据监督结果完善相关财政政策； （四）向专职监督机构反馈意见采纳情况。"},{"i":11,"n":"第十一条","txt":"专职监督机构和业务管理机构实施监督，应当协调配合、信息共享。"},{"i":12,"n":"第十二条","txt":"实施监督的财政部门工作人员（以下简称监督人员）应当具备与财政监督工作相适应的专业知识和业务能力。 监督人员应当廉洁自律，秉公执法，保守秘密。"},{"i":13,"n":"第十三条","txt":"监督人员与监督对象有利害关系的应当回避。 监督对象有权申请有利害关系的监督人员回避。 监督人员的回避，由财政部门负责人决定。"},{"i":14,"n":"第十四条","txt":"监督人员依法履行监督职责受法律保护。 对财政部门依法实施的监督，监督对象应当予以配合、如实反映情况；不得拒绝、阻挠、拖延；不得对监督人员打击报复。"},{"i":15,"n":"第十五条","txt":"财政部门可以根据需要，聘请有关专业机构或者专业人员协助监督工作。 财政部门应当加强对所聘机构和人员的统一管理。"},{"i":16,"n":"第十六条","txt":"财政部门依法对下列事项实施监督： （一）财税法规、政策的执行情况； （二）预算编制、执行、调整和决算情况； （三）税收收入、政府非税收入等政府性资金的征收、管理情况； （四）国库集中收付、预算单位银行账户的管理使用情况； （五）政府采购法规、政策的执行情况； （六）行政、事业单位国有资产，金融类、文化企业等国有资产的管理情况； （七）财务会计制度的执行情况； （八）外国政府、国际金融组织贷款和赠款的管理情况； （九）法律法规规定的其他事项。 对会计师事务所和资产评估机构设立及执业情况的监督，由省级以上人民政府财政部门依法实施。"},{"i":17,"n":"第十七条","txt":"财政部门实施监督，可以依法采取下列措施： （一）要求监督对象按照要求提供与监督事项有关的资料； （二）调取、查阅、复制监督对象有关预算编制、执行、调整和决算资料，会计凭证和账簿、财务会计报告、审计报告、账户信息、电子信息管理系统情况，以及其他有关资料 ; （三）经县级以上人民政府财政部门负责人批准，向与被监督单位有经济业务往来的单位查询有关情况，向金融机构查询被监督单位的存款； （四）在证据可能灭失或者以后难以取得的情况下，经县级以上人民政府财政部门负责人批准，先行登记保存证据，并在7日内及时作出处理决定； （五）对正在进行的财政违法行为，责令停止；拒不执行的，暂停财政拨款或者停止拨付与财政违法行为直接有关的款项；已经拨付的，责令暂停使用； （六）法律法规规定的其他措施。"},{"i":18,"n":"第十八条","txt":"财政部门实施监督过程中，发现监督对象制定或者执行的规定与国家相关规定相抵触的，可以根据职权予以纠正或者建议有权机关予以纠正。"},{"i":19,"n":"第十九条","txt":"对监督对象财政违法行为作出的处理、处罚决定及其执行情况，除涉及国家秘密、商业秘密、个人隐私外，财政部门可以公开。"},{"i":20,"n":"第二十条","txt":"对有关财政违法行为的举报，财政部门应当按照规定处理，并为举报人保密。"},{"i":21,"n":"第二十一条","txt":"财政部门实施监督，可以采取监控、督促、调查、核查、审查、检查、评价等方法。"},{"i":22,"n":"第二十二条","txt":"财政部门实施监督，可以采取专项监督和日常监督相结合的方式。 专项监督应当结合年度监督计划，按照规定程序组织实施。 日常监督应当结合履行财政、财务、会计等管理职责，按照规定程序组织实施。"},{"i":23,"n":"第二十三条","txt":"财政部门实施监督，应当依法对财政违法行为作出处理处罚；对不属于本部门职权范围的事项，应当按照规定程序移送有权机关处理。"},{"i":24,"n":"第二十四条","txt":"财政部门实施监督，应当加强与监察、审计等有关机关的沟通和协作。有关机关已经作出的调查、检查、审计结论能够满足本部门履行职责需要的，应当加以利用。 财政部门履行监督职责，可以提请有关机关予以协助。"},{"i":25,"n":"第二十五条","txt":"监督对象有下列情形之一的，由县级以上人民政府财政部门责令限期改正，并给予警告；直接负责的主管人员和其他直接责任人员属于国家工作人员的，建议有关主管部门依法给予处分；涉嫌犯罪的，依法移送司法机关： （一）拒绝、阻挠、拖延财政部门依法实施的监督的； （二）不如实提供有关资料的； （三）对监督人员进行打击报复的。"},{"i":26,"n":"第二十六条","txt":"监督人员实施监督过程中玩忽职守、滥用职权、徇私舞弊或者泄露国家秘密、商业秘密的，依法给予行政处分；涉嫌犯罪的，依法移送司法机关。"},{"i":27,"n":"第二十七条","txt":"监督对象对处理、处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。 国家工作人员对处分不服的，可以依照有关规定申请复核或者提出申诉。"},{"i":28,"n":"第二十八条","txt":"乡镇财政机构在规定职权范围内，或者受上级政府财政部门委托，依法实施监督工作，参照本办法执行。"},{"i":29,"n":"第二十九条","txt":"本办法自2012 年5 月1日起施行。"}],"zichanpingguhangyecaizhengjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强资产评估行业财政监督管理，促进资产评估行业健康发展，根据《中华人民共和国资产评估法》（以下简称资产评估法）等法律、行政法规和国务院的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"资产评估机构及其资产评估专业人员根据委托对单项资产、资产组合、企业价值、金融权益、资产损失或者其他经济权益进行评定、估算，并出具资产评估报告的专业服务行为和财政部门对资产评估行业实施监督管理，适用本办法。 资产评估机构及其资产评估专业人员从事前款规定业务，涉及法律、行政法规和国务院规定由其他评估行政管理部门管理的，按照其他有关规定执行。"},{"i":3,"n":"第三条","txt":"涉及国有资产或者公共利益等事项，属于本办法第二条规定范围有法律、行政法规规定需要评估的法定资产评估业务（以下简称“法定资产评估业务”），委托人应当按照资产评估法和有关法律、行政法规的规定，委托资产评估机构进行评估。"},{"i":4,"n":"第四条","txt":"财政部门对资产评估行业的监督管理，实行行政监管、行业自律与机构自主管理相结合的原则。"},{"i":5,"n":"第五条","txt":"财政部负责统筹财政部门对全国资产评估行业的监督管理，制定有关监督管理办法和资产评估基本准则，指导和督促地方财政部门实施监督管理。 财政部门对资产评估机构从事证券期货相关资产评估业务实施的监督管理，由财政部负责。"},{"i":6,"n":"第六条","txt":"各省、自治区、直辖市、计划单列市财政厅（局）（以下简称省级财政部门）负责对本行政区域内资产评估行业实施监督管理。"},{"i":7,"n":"第七条","txt":"中国资产评估协会依照法律、行政法规、本办法和其协会章程的规定，负责全国资产评估行业的自律管理。 地方资产评估协会依照法律、法规、本办法和其协会章程的规定，负责本地区资产评估行业的自律管理。"},{"i":8,"n":"第八条","txt":"资产评估机构从事资产评估业务，除本办法第十六条规定外，依法不受行政区域、行业限制，任何组织或者个人不得非法干预。"},{"i":9,"n":"第九条","txt":"资产评估专业人员包括资产评估师（含珠宝评估专业，下同）和具有资产评估专业知识及实践经验的其他资产评估从业人员。 资产评估师是指通过中国资产评估协会组织实施的资产评估师资格全国统一考试的资产评估专业人员。 其他资产评估从业人员从事本办法第二条规定的资产评估业务，应当接受财政部门的监管。除从事法定资产评估业务外，其所需的资产评估专业知识及实践经验，由资产评估机构自主评价认定。 由其他评估行政管理部门管理的其他专业领域评估师从事本办法第二条规定的资产评估业务，按照本条第三款规定执行。"},{"i":10,"n":"第十条","txt":"资产评估专业人员从事资产评估业务，应当加入资产评估机构，并且只能在一个资产评估机构从事业务。 资产评估专业人员应当与资产评估机构签订劳动合同，建立社会保险缴纳关系，按照国家有关规定办理人事档案存放手续。"},{"i":11,"n":"第十一条","txt":"资产评估专业人员从事资产评估业务，应当遵守法律、行政法规和本办法的规定，执行资产评估准则及资产评估机构的各项规章制度，依法签署资产评估报告，不得签署本人未承办业务的资产评估报告或者有重大遗漏的资产评估报告。 未取得资产评估师资格的人员，不得签署法定资产评估业务资产评估报告，其签署的法定资产评估业务资产评估报告无效。"},{"i":12,"n":"第十二条","txt":"资产评估专业人员应当接受资产评估协会的自律管理和所在资产评估机构的自主管理，不得从事损害资产评估机构合法利益的活动。 加入资产评估协会的资产评估专业人员，平等享有章程规定的权利，履行章程规定的义务。"},{"i":13,"n":"第十三条","txt":"资产评估机构应当依法采用合伙或者公司形式，并符合资产评估法第十五条规定的条件。 不符合资产评估法第十五条规定条件的资产评估机构不得承接资产评估业务。"},{"i":14,"n":"第十四条","txt":"资产评估机构从事资产评估业务，应当遵守资产评估准则，履行资产评估程序，加强内部审核，严格控制执业风险。 资产评估机构开展法定资产评估业务，应当指定至少两名资产评估师承办。不具备两名以上资产评估师条件的资产评估机构，不得开展法定资产评估业务。"},{"i":15,"n":"第十五条","txt":"法定资产评估业务资产评估报告应当由两名以上承办业务的资产评估师签署，并履行内部程序后加盖资产评估机构印章，资产评估机构及签字资产评估师依法承担责任。"},{"i":16,"n":"第十六条","txt":"资产评估机构应当遵守独立性原则和资产评估准则规定的资产评估业务回避要求，不得受理与其合伙人或者股东存在利害关系的业务。"},{"i":17,"n":"第十七条","txt":"资产评估机构应当建立健全质量控制制度和内部管理制度。其中，内部管理制度包括资产评估业务管理制度、业务档案管理制度、人事管理制度、继续教育制度、财务管理制度等。"},{"i":18,"n":"第十八条","txt":"资产评估机构应当指定一名取得资产评估师资格的本机构合伙人或者股东专门负责执业质量控制。"},{"i":19,"n":"第十九条","txt":"资产评估机构根据业务需要建立职业风险基金管理制度，或者自愿购买职业责任保险，完善职业风险防范机制。 资产评估机构建立职业风险基金管理制度的，按照财政部的具体规定提取、管理和使用职业风险基金。"},{"i":20,"n":"第二十条","txt":"实行集团化发展的资产评估机构，应当在质量控制、内部管理、客户服务、企业形象、信息化等方面，对设立的分支机构实行统一管理，或者对集团成员实行统一政策。 分支机构应当在资产评估机构授权范围内，依法从事资产评估业务，并以资产评估机构的名义出具资产评估报告。"},{"i":21,"n":"第二十一条","txt":"资产评估机构和分支机构加入资产评估协会，平等享有章程规定的权利，履行章程规定的义务。"},{"i":22,"n":"第二十二条","txt":"资产评估机构和分支机构应当在每年3月31日之前，分别向所加入的资产评估协会报送下列材料： （一）资产评估机构或分支机构基本情况； （二）上年度资产评估项目重要信息； （三）资产评估机构建立职业风险基金或者购买职业责任保险情况。购买职业责任保险的，应当提供职业责任保险保单复印件。"},{"i":23,"n":"第二十三条","txt":"省级财政部门负责本地区资产评估机构和分支机构的备案管理。"},{"i":24,"n":"第二十四条","txt":"资产评估机构应当自领取营业执照之日起30日内，通过备案信息管理系统向所在地省级财政部门备案，同时提交下列纸质材料： （一）资产评估机构备案表； （二）营业执照复印件； （三）经工商行政管理机关登记的合伙协议或公司章程； （四）资产评估机构合伙人或者股东以及执行合伙事务的合伙人或者法定代表人三年以上从业经历、最近三年接受处罚信息等基本情况； （五）在该机构从业的资产评估师、其他专业领域的评估师和其他资产评估从业人员情况； （六）资产评估机构质量控制制度和内部管理制度。"},{"i":25,"n":"第二十五条","txt":"资产评估机构的备案信息不齐全或者备案材料不符合要求的，省级财政部门应当在接到备案材料5个工作日内一次性告知需要补正的全部内容，并给予指导。资产评估机构应当根据要求，在15个工作日内补正。逾期不补正的，视同未备案。"},{"i":26,"n":"第二十六条","txt":"备案材料完备且符合要求的，省级财政部门收齐备案材料即完成备案，并在20个工作日内将下列信息以公函编号向社会公开： （一）资产评估机构名称及组织形式； （二）资产评估机构的合伙人或者股东的基本情况； （三）资产评估机构执行合伙事务的合伙人或者法定代表人； （四）申报的资产评估专业人员基本情况。 对于资产评估机构申报的资产评估师信息，省级财政部门应当在公开前向有关资产评估协会核实。"},{"i":27,"n":"第二十七条","txt":"资产评估机构设立分支机构的，应当比照本办法第二十四条至第二十六条的规定，由资产评估机构向其分支机构所在地省级财政部门备案，同时提交下列纸质材料： （一）资产评估机构设立分支机构备案表； （二）分支机构营业执照复印件； （三）资产评估机构授权分支机构的业务范围； （四）分支机构负责人三年以上从业经历、最近三年接受处罚信息等基本情况； （五）在该分支机构从业的资产评估师、其他专业领域评估师和其他资产评估从业人员情况。 完成分支机构备案的省级财政部门应当将分支机构备案情况向社会公开，同时告知资产评估机构所在地省级财政部门。"},{"i":28,"n":"第二十八条","txt":"资产评估机构的名称、执行合伙事务的合伙人或者法定代表人、合伙人或者股东、分支机构的名称或者负责人发生变更，以及发生机构分立、合并、转制、撤销等重大事项，应当自变更之日起15个工作日内，比照本办法第二十四条至第二十六条的规定，向有关省级财政部门办理变更手续。需要变更工商登记的，自工商变更登记完成之日起15个工作日内向有关省级财政部门办理变更手续。"},{"i":29,"n":"第二十九条","txt":"资产评估机构办理合并或者分立变更手续的，应当提供合并或者分立协议。合并或者分立协议应当包括以下事项： （一）合并或者分立前资产评估机构评估业务档案保管方案； （二）合并或者分立前资产评估机构职业风险基金或者执业责任保险的处理方案； （三）合并或者分立前资产评估机构资产评估业务、执业责任的承继关系。"},{"i":30,"n":"第三十条","txt":"合伙制资产评估机构转为公司制资产评估机构，或者公司制资产评估机构转为合伙制资产评估机构，办理变更手续应当提供合伙人会议或股东（大）会审议通过的转制决议。 转制决议应当载明转制后机构与转制前机构的债权债务、档案保管、资产评估业务、执业责任等承继关系。"},{"i":31,"n":"第三十一条","txt":"资产评估机构跨省级行政区划迁移经营场所，应当书面告知迁出地省级财政部门。 资产评估机构在办理完迁入地工商登记手续后15个工作日内，比照本办法第二十四条至第二十六条的规定，向迁入地省级财政部门办理迁入备案手续。 迁入地省级财政部门办理迁入备案手续后通知迁出地的省级财政部门，迁出地的省级财政部门应同时予以公告。"},{"i":32,"n":"第三十二条","txt":"已完成备案的资产评估机构或者分支机构有下列行为之一的，省级财政部门予以注销备案，并向社会公开： （一） 注销工商登记的； （二） 被工商行政管理机关吊销营业执照的； （三） 主动要求注销备案的。"},{"i":33,"n":"第三十三条","txt":"注销备案的资产评估机构及其分支机构的资产评估业务档案，应当按照《中华人民共和国档案法》和资产评估档案管理的有关规定予以妥善保存。"},{"i":34,"n":"第三十四条","txt":"财政部建立统一的备案信息管理系统。备案信息管理系统实行全国联网，并与其他相关行政管理部门实行信息共享。"},{"i":35,"n":"第三十五条","txt":"资产评估机构未按本办法规定备案的，依法承担法律责任。"},{"i":36,"n":"第三十六条","txt":"资产评估协会是资产评估机构和资产评估专业人员的自律性组织，接受有关财政部门的监督，不得损害国家利益和社会公共利益，不得损害会员的合法权益。"},{"i":37,"n":"第三十七条","txt":"资产评估协会通过制定章程规范协会内部管理和活动。协会章程应当由会员代表大会制定，经登记管理机关核准后，报有关财政部门备案。"},{"i":38,"n":"第三十八条","txt":"资产评估协会应当依法履行职责，向有关财政部门提供资产评估师信息，及时向有关财政部门报告会员信用档案、会员自律检查情况及奖惩情况。"},{"i":39,"n":"第三十九条","txt":"资产评估协会对资产评估机构及其资产评估专业人员进行自律检查。资产评估机构及其资产评估专业人员应当配合资产评估协会组织实施的自律检查。 资产评估协会应当重点检查资产评估机构及其资产评估专业人员的执业质量和职业风险防范机制。"},{"i":40,"n":"第四十条","txt":"资产评估协会应当结合自律检查工作，对资产评估机构及其分支机构按照本办法第二十二条规定报送的材料进行分析，发现不符合法律、行政法规和本办法规定的情况，及时向有关财政部门报告。"},{"i":41,"n":"第四十一条","txt":"资产评估协会应当与其他评估专业领域行业协会加强沟通协作，建立会员、执业、惩戒等相关信息的共享机制。 中国资产评估协会应当会同其他评估专业领域行业协会根据需要制定共同的行为规范，促进评估行业健康有序发展。"},{"i":42,"n":"第四十二条","txt":"财政部统一部署对资产评估行业的监督检查，主要负责以下工作： （一）制定资产评估专业人员、资产评估机构、资产评估协会和相关资产评估业务监督检查的具体办法； （二）组织开展资产评估执业质量专项检查； （三）监督检查资产评估机构从事证券期货相关资产评估业务情况； （四）检查中国资产评估协会履行资产评估法第三十六条规定的职责情况，并根据工作需要，对地方资产评估协会履行职责情况进行抽查； （五）指导和督促地方财政部门对资产评估行业的监督检查，并对其检查情况予以抽查。 对本条第一款第三项进行监督检查，必要时，财政部可以会同其他有关部门进行。"},{"i":43,"n":"第四十三条","txt":"省级财政部门开展监督检查，包括年度检查和必要的专项检查，对本行政区域内资产评估机构包括分支机构下列内容进行重点检查，并将检查结果予以公开，同时向财政部报告： （一）资产评估机构持续符合资产评估法第十五条规定条件的情况； （二）办理备案情况； （三）资产评估执业质量情况。 对本条第一款第一项进行检查，必要时，有关财政部门可以会同其他相关评估行政管理部门进行。"},{"i":44,"n":"第四十四条","txt":"省级财政部门对地方资产评估协会实施监督检查，并将检查情况向财政部汇报，重点检查资产评估协会履行以下职责情况： （一）地方资产评估协会章程的制定、修改情况； （二）指导会员落实准则情况； （三）检查会员执业质量情况； （四）开展会员继续教育、信用档案、风险防范等情况； （五）机构会员年度信息管理情况。"},{"i":45,"n":"第四十五条","txt":"财政部门开展资产评估行业监督检查，应当由本部门两名以上执法人员组成检查组。具体按照财政检查工作的有关规定执行。"},{"i":46,"n":"第四十六条","txt":"检查时，财政部门认定虚假资产评估报告和重大遗漏资产评估报告，应当以资产评估准则为依据，组织相关专家进行专业技术论证，也可以委托资产评估协会组织专家提供专业技术支持。"},{"i":47,"n":"第四十七条","txt":"检查过程中，财政部和省级财政部门发现资产评估专业人员、资产评估机构和资产评估协会存在违法情形的，应当依照资产评估法等法律、行政法规和本办法的规定处理、处罚。涉嫌犯罪的，移送司法机关处理。 当事人对行政处理、行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":48,"n":"第四十八条","txt":"资产评估委托人或资产评估报告使用人对资产评估机构或资产评估专业人员的下列行为，可以向对该资产评估机构备案的省级财政部门进行投诉、举报，其他公民、法人或其他组织可以向对该资产评估机构备案的省级财政部门举报： （一）违法开展法定资产评估业务的； （二）资产评估专业人员违反资产评估法第十四条规定的； （三）资产评估机构未按照本办法规定备案或备案后未持续符合资产评估法第十五条规定条件的； （四）资产评估机构违反资产评估法第二十条规定的； （五）资产评估机构违反本办法第十六条规定的； （六）资产评估机构违反本办法第二十条第二款规定的。 资产评估委托人或资产评估报告使用人投诉、举报资产评估机构出具虚假资产评估报告或者重大遗漏的资产评估报告的，可以先与资产评估机构进行沟通。"},{"i":49,"n":"第四十九条","txt":"在法定资产评估业务中，委托人或被评估单位有资产评估法第五十二条规定行为的，资产评估的相关当事人可以向委托人或被评估单位所在地省级财政部门进行投诉、举报，其他公民、法人或其他组织可以向委托人或被评估单位所在地省级财政部门举报。 由于委托人或被评估单位的行政管理层级不匹配或存在其他原因超出省级财政部门处理权限的，省级财政部门可以申请由财政部受理。 向财政部门投诉、举报事项涉及资产评估机构从事证券期货相关资产评估业务的，由财政部受理。"},{"i":50,"n":"第五十条","txt":"投诉、举报应当通过书面形式实名进行，并如实反映情况，提供相关证明材料。"},{"i":51,"n":"第五十一条","txt":"财政部门接到投诉、举报的事项，应当在15个工作日内作出是否受理的书面决定。投诉、举报事项属于财政部门职责的，财政部门应当予以受理。不予受理的，应当说明理由，及时告知实名投诉人、举报人。"},{"i":52,"n":"第五十二条","txt":"投诉、举报事项属于下列情形的，财政部门不予受理： （一）投诉、举报事项不属于财政部门职责的； （二）已由公安机关、检察机关立案调查或者进入司法程序的； （三）属于资产评估协会自律管理的。 投诉人、举报人就同一事项向财政部门和资产评估协会投诉、举报的，财政部门按照本办法第五十一条和本条第一款的规定处理。"},{"i":53,"n":"第五十三条","txt":"财政部门受理投诉、举报，应当采用书面审查的方式及时进行处理，必要时可以成立由本部门两名以上执法人员和聘用的专家组成的调查组，进行调查取证。有关当事人应当如实反映情况，提供相关材料。 调查组成员与当事人有直接利害关系的,应当回避；对调查工作中知悉的国家秘密和商业秘密，应当保密。 受理的投诉、举报事项同时涉及其他行政管理部门职责的，应当会同其他行政管理部门进行处理。"},{"i":54,"n":"第五十四条","txt":"对投诉、举报的调查，调查组有权进入被投诉举报单位现场调查，查阅、复印有关凭证、文件等资料，询问被投诉举报单位有关人员，必要时按照资产评估业务延伸调查，并将调查内容与事项予以记录和摘录，编制调查工作底稿。 调查组在调查中取得的证据、材料以及工作底稿，应当有提供者或者被调查人的签名或者盖章。未取得提供者或者被调查人签名或者盖章的材料，调查组应当注明原因。"},{"i":55,"n":"第五十五条","txt":"在有关证据可能灭失或者以后难以取得的情况下，经财政部门负责人批准，调查组可以先行登记保存，并应当在7个工作日内及时作出处理决定。被调查人或者有关人员不得销毁或者转移证据。"},{"i":56,"n":"第五十六条","txt":"针对资产评估协会的投诉、举报，财政部和省级财政部门应当及时调查处理。"},{"i":57,"n":"第五十七条","txt":"调查时，财政部门认定虚假资产评估报告和重大遗漏资产评估报告，按照本办法第四十六条规定执行。"},{"i":58,"n":"第五十八条","txt":"经调查发现资产评估专业人员、资产评估机构和资产评估协会存在违法情形的，财政部和省级财政部门按照本办法第四十七条规定予以处理。"},{"i":59,"n":"第五十九条","txt":"财政部门根据调查处理具体情况，应当采取书面形式答复实名投诉人、举报人。"},{"i":60,"n":"第六十条","txt":"对其他有关部门移送的资产评估违法线索或案件，或者资产评估协会按照本办法第四十条规定报告的情况，有关财政部门应当比照本办法第五十二条至第五十八条的规定依法调查处理，并将处理结果告知移送部门或者资产评估协会。"},{"i":61,"n":"第六十一条","txt":"资产评估专业人员有下列行为之一的，由有关省级财政部门予以警告，可以责令停止从业六个月以上一年以下；有违法所得的，没收违法所得；情节严重的，责令停止从业一年以上五年以下；构成犯罪的，移送司法机关处理： （一）违反本办法第十条第一款的规定，同时在两个以上资产评估机构从事业务的； （二）违反本办法第十一条第一款的规定，签署本人未承办业务的资产评估报告或者有重大遗漏的资产评估报告的。 资产评估专业人员违反本办法第十二条第一款、第三十九条第一款规定，不接受行业自律管理的，由资产评估协会予以惩戒，记入信用档案；情节严重的，由资产评估协会按照规定取消会员资格，并予以公告。"},{"i":62,"n":"第六十二条","txt":"有下列行为之一的，由对其备案的省级财政部门对资产评估机构予以警告，可以责令停业一个月以上六个月以下；有违法所得的，没收违法所得，并处违法所得一倍以上五倍以下罚款；情节严重的，通知工商行政管理部门依法处理；构成犯罪的，移送司法机关处理： （一）违反本办法第十一条第二款规定，未取得资产评估师资格的人员签署法定资产评估业务资产评估报告的； （二）违反本办法第十五条规定，承办并出具法定资产评估业务资产评估报告的资产评估师人数不符合法律规定的； （三）违反本办法第十六条规定，受理与其合伙人或者股东存在利害关系业务的。"},{"i":63,"n":"第六十三条","txt":"资产评估机构违反本办法第十七条、第十八条、第十九条、第二十条第一款、第二十八条、第三十一条第一款和第二款规定的，由资产评估机构所在地省级财政部门责令改正，并予以警告。"},{"i":64,"n":"第六十四条","txt":"资产评估机构违反本办法第二十条第二款规定造成不良后果的，由其分支机构所在地的省级财政部门责令改正，对资产评估机构及其法定代表人或执行合伙事务的合伙人分别予以警告；没有违法所得的，可以并处资产评估机构一万元以下罚款；有违法所得的，可以并处资产评估机构违法所得一倍以上三倍以下、最高不超过三万元的罚款；同时通知资产评估机构所在地省级财政部门。"},{"i":65,"n":"第六十五条","txt":"资产评估机构未按照本办法第二十四条规定备案或者备案后不符合资产评估法第十五条规定条件的，由资产评估机构所在地省级财政部门责令改正；拒不改正的，责令停业，可以并处一万元以上五万元以下罚款，并通报工商行政管理部门。 资产评估机构未按照本办法第二十七条第一款规定办理分支机构备案的，由其分支机构所在地的省级财政部门责令改正，并对资产评估机构及其法定代表人或者执行合伙事务的合伙人分别予以警告，同时通知资产评估机构所在地的省级财政部门。"},{"i":66,"n":"第六十六条","txt":"资产评估协会有下列行为之一的，由有关财政部门予以警告，责令改正；拒不改正的，可以通报登记管理机关依法处理： （一）章程不符合资产评估法和本办法规定的； （二）资产评估协会未依照资产评估法、本办法和其章程的规定履行职责的。"},{"i":67,"n":"第六十七条","txt":"有关财政部门对资产评估机构、资产评估专业人员和资产评估协会的财政处理、处罚情况，应当在15个工作日内向社会公开。"},{"i":68,"n":"第六十八条","txt":"财政部门工作人员在资产评估行业监督管理工作中滥用职权、玩忽职守、徇私舞弊的，按照《中华人民共和国公务员法》、《中华人民共和国行政监察法》等国家有关规定追究相应责任；涉嫌犯罪的，移送司法机关处理。"},{"i":69,"n":"第六十九条","txt":"本办法所称资产评估行业、资产评估专业人员、资产评估机构和资产评估协会是指根据资产评估法和国务院规定，按照职责分工由财政部门监管的资产评估行业、资产评估专业人员、资产评估机构和资产评估协会。"},{"i":70,"n":"第七十条","txt":"外商投资者在中华人民共和国境内设立、参股、入伙资产评估机构或者开展法定资产评估业务，应当依法履行国家安全审查程序。"},{"i":71,"n":"第七十一条","txt":"省级财政部门可结合实际制定具体的实施办法。设区的市级财政部门可以对本行政区域内资产评估行业实施监督管理，具体由省级财政部门根据当地资产评估行业发展状况和设区的市级财政部门具备的监管条件确定。"},{"i":72,"n":"第七十二条","txt":"本办法自2017年6月1日起施行。财政部2011年8月11日发布的《资产评估机构审批和监督管理办法》(财政部令第64号)同时废止。"}],"daolujiaotongshigushehuijiuzhujijinguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强道路交通事故社会救助基金管理，对道路交通事故中受害人依法进行救助，根据《中华人民共和国道路交通安全法》、《机动车交通事故责任强制保险条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"道路交通事故社会救助基金的筹集、使用和管理适用本办法。 本办法所称道路交通事故社会救助基金（以下简称救助基金），是指依法筹集用于垫付机动车道路交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用的社会专项基金。"},{"i":3,"n":"第三条","txt":"救助基金实行统一政策、地方筹集、分级管理、分工负责。 救助基金管理应当坚持扶危救急、公开透明、便捷高效的原则，保障救助基金安全高效和可持续运行。"},{"i":4,"n":"第四条","txt":"省、自治区、直辖市、计划单列市人民政府（以下统称省级人民政府）应当设立救助基金。 省级救助基金主管部门会同有关部门报省级人民政府确定省级以下救助基金的设立以及管理级次，并推进省级以下救助基金整合，逐步实现省级统筹。"},{"i":5,"n":"第五条","txt":"财政部门是救助基金的主管部门。 财政部负责会同有关部门制定救助基金的有关政策，并对省级救助基金的筹集、使用和管理进行指导。 县级以上地方财政部门根据救助基金设立情况，依法监督检查救助基金的筹集、使用和管理，按照规定确定救助基金管理机构，并对其管理情况进行考核。"},{"i":6,"n":"第六条","txt":"国务院保险监督管理机构的派出机构负责对保险公司缴纳救助基金情况实施监督检查。 县级以上地方公安机关交通管理部门负责通知救助基金管理机构垫付道路交通事故中受害人的抢救费用，并协助救助基金管理机构做好相关救助基金垫付费用的追偿工作。 县级以上地方农业机械化主管部门负责协助救助基金管理机构做好相关救助基金垫付费用的追偿工作。 县级以上地方卫生健康主管部门负责监督医疗机构按照道路交通事故受伤人员临床诊疗相关指南和规范及时抢救道路交通事故中的受害人以及依法申请救助基金垫付抢救费用。"},{"i":7,"n":"第七条","txt":"县级以上财政部门、公安机关交通管理部门、卫生健康主管部门、农业机械化主管部门以及国务院保险监督管理机构及其派出机构，应当通过多种渠道加强救助基金有关政策的宣传和提示，为道路交通事故受害人及其亲属申请使用救助基金提供便利。"},{"i":8,"n":"第八条","txt":"救助基金主管部门可以通过政府采购等方式依法确定救助基金管理机构。 保险公司或者其他能够独立承担民事责任的专业机构可以作为救助基金管理机构，具体负责救助基金运行管理。"},{"i":9,"n":"第九条","txt":"救助基金的来源包括： （一）按照机动车交通事故责任强制保险（以下简称交强险）的保险费的一定比例提取的资金； （二）对未按照规定投保交强险的机动车的所有人、管理人的罚款； （三）依法向机动车道路交通事故责任人追偿的资金； （四）救助基金孳息； （五）地方政府按照规定安排的财政临时补助； （六）社会捐款； （七）其他资金。"},{"i":10,"n":"第十条","txt":"每年5月1日前，财政部会同国务院保险监督管理机构根据上一年度救助基金的收支情况，按照收支平衡的原则，合理确定当年从交强险保险费中提取救助基金的比例幅度。省级人民政府在幅度范围内确定本地区具体提取比例。 以省级为单位，救助基金累计结余达到上一年度支出金额3倍以上的，本年度暂停从交强险保险费中提取。"},{"i":11,"n":"第十一条","txt":"办理交强险业务的保险公司应当按照确定的比例，从交强险保险费中提取资金，并在每季度结束后10个工作日内，通过银行转账方式足额转入省级救助基金账户。"},{"i":12,"n":"第十二条","txt":"县级以上地方财政部门应当根据当年预算在每季度结束后10个工作日内，将未按照规定投保交强险的罚款全额划拨至省级救助基金账户。"},{"i":13,"n":"第十三条","txt":"县级以上地方财政部门向救助基金安排临时补助的，应当依照《中华人民共和国预算法》等预算管理法律法规的规定及时拨付。"},{"i":14,"n":"第十四条","txt":"有下列情形之一时，救助基金垫付道路交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用： （一）抢救费用超过交强险责任限额的； （二）肇事机动车未参加交强险的； （三）机动车肇事后逃逸的。 救助基金一般垫付受害人自接受抢救之时起7日内的抢救费用，特殊情况下超过7日的抢救费用，由医疗机构书面说明理由。具体费用应当按照规定的收费标准核算。"},{"i":15,"n":"第十五条","txt":"依法应当由救助基金垫付受害人丧葬费用、部分或者全部抢救费用的，由道路交通事故发生地的救助基金管理机构及时垫付。"},{"i":16,"n":"第十六条","txt":"发生本办法第十四条所列情形之一需要救助基金垫付部分或者全部抢救费用的，公安机关交通管理部门应当在处理道路交通事故之日起3个工作日内书面通知救助基金管理机构。"},{"i":17,"n":"第十七条","txt":"医疗机构在抢救受害人结束后，对尚未结算的抢救费用，可以向救助基金管理机构提出垫付申请，并提供需要垫付抢救费用的相关材料。 受害人或者其亲属对尚未支付的抢救费用，可以向救助基金管理机构提出垫付申请，医疗机构应当予以协助并提供需要垫付抢救费用的相关材料。"},{"i":18,"n":"第十八条","txt":"救助基金管理机构收到公安机关交通管理部门的抢救费用垫付通知或者申请人的抢救费用垫付申请以及相关材料后，应当在3个工作日内按照本办法有关规定、道路交通事故受伤人员临床诊疗相关指南和规范，以及规定的收费标准，对下列内容进行审核，并将审核结果书面告知处理该道路交通事故的公安机关交通管理部门或者申请人： （一）是否属于本办法第十四条规定的救助基金垫付情形； （二）抢救费用是否真实、合理； （三）救助基金管理机构认为需要审核的其他内容。 对符合垫付要求的，救助基金管理机构应当在2个工作日内将相关费用结算划入医疗机构账户。对不符合垫付要求的，不予垫付，并向处理该交通事故的公安机关交通管理部门或者申请人书面说明理由。"},{"i":19,"n":"第十九条","txt":"发生本办法第十四条所列情形之一需要救助基金垫付丧葬费用的，由受害人亲属凭处理该道路交通事故的公安机关交通管理部门出具的《尸体处理通知书》向救助基金管理机构提出书面垫付申请。 对无主或者无法确认身份的遗体，由县级以上公安机关交通管理部门会同有关部门按照规定处理。"},{"i":20,"n":"第二十条","txt":"救助基金管理机构收到丧葬费用垫付申请和相关材料后，对符合垫付要求的，应当在3个工作日内按照有关标准垫付丧葬费用；对不符合垫付要求的，不予垫付，并向申请人书面说明理由。救助基金管理机构应当同时将审核结果书面告知处理该道路交通事故的公安机关交通管理部门。"},{"i":21,"n":"第二十一条","txt":"救助基金管理机构对抢救费用和丧葬费用的垫付申请进行审核时，可以向公安机关交通管理部门、医疗机构和保险公司等有关单位核实情况，有关单位应当予以配合。"},{"i":22,"n":"第二十二条","txt":"救助基金管理机构与医疗机构或者其他单位就垫付抢救费用、丧葬费用问题发生争议时，由救助基金主管部门会同卫生健康主管部门或者其他有关部门协调解决。"},{"i":23,"n":"第二十三条","txt":"救助基金管理机构应当保持相对稳定，一经确定，除本办法另有规定外，3年内不得变更。"},{"i":24,"n":"第二十四条","txt":"救助基金管理机构履行下列管理职责： （一）接收救助基金资金； （二）制作、发放宣传材料，积极宣传救助基金申请使用和管理有关政策； （三）受理、审核垫付申请，并及时垫付； （四）追偿垫付款，向人民法院、公安机关等单位通报拒不履行偿还义务的机动车道路交通事故责任人信息； （五）如实报告救助基金业务事项； （六）管理救助基金的其他职责。"},{"i":25,"n":"第二十五条","txt":"救助基金管理机构应当建立符合救助基金筹集、使用和管理要求的信息系统，建立数据信息交互机制，规范救助基金网上申请和审核流程，提高救助基金使用和管理效率。 救助基金管理机构应当设立热线电话，建立24小时值班制度，确保能够及时受理、审核垫付申请。"},{"i":26,"n":"第二十六条","txt":"救助基金管理机构应当公开以下信息： （一）救助基金有关政策文件； （二）救助基金管理机构的电话、地址和救助网点； （三）救助基金申请流程以及所需提供的材料清单； （四）救助基金筹集、使用、追偿和结余信息，但涉及国家秘密、商业秘密的除外； （五）救助基金主管部门对救助基金管理机构的考核结果； （六）救助基金主管部门规定的其他信息。 救助基金管理机构、有关部门及其工作人员对被救助人的个人隐私和个人信息，应当依法予以保密。"},{"i":27,"n":"第二十七条","txt":"救助基金账户应当按照国家有关银行账户管理规定开立。 救助基金实行单独核算、专户管理，并按照本办法第十四条的规定使用，不得用于担保、出借、投资或者其他用途。"},{"i":28,"n":"第二十八条","txt":"救助基金管理机构根据本办法垫付抢救费用和丧葬费用后，应当依法向机动车道路交通事故责任人进行追偿。 发生本办法第十四条第三项情形救助基金垫付丧葬费用、部分或者全部抢救费用的，道路交通事故案件侦破后，处理该道路交通事故的公安机关交通管理部门应当及时通知救助基金管理机构。 有关单位、受害人或者其继承人应当协助救助基金管理机构进行追偿。"},{"i":29,"n":"第二十九条","txt":"道路交通事故受害人或者其继承人已经从机动车道路交通事故责任人或者通过其他方式获得赔偿的，应当退还救助基金垫付的相应费用。 对道路交通事故死亡人员身份无法确认或者其受益人不明的，救助基金管理机构可以在扣除垫付的抢救费用和丧葬费用后，代为保管死亡人员所得赔偿款，死亡人员身份或者其受益人身份确定后，应当依法处理。"},{"i":30,"n":"第三十条","txt":"救助基金管理机构已经履行追偿程序和职责，但有下列情形之一导致追偿未果的，可以提请救助基金主管部门批准核销： （一）肇事逃逸案件超过3年未侦破的； （二）机动车道路交通事故责任人死亡（被宣告死亡）、被宣告失踪或者终止，依法认定无财产可供追偿的； （三）机动车道路交通事故责任人、应当退还救助基金垫付费用的受害人或者其继承人家庭经济特别困难，依法认定无财产可供追偿或者退还的。 省级救助基金主管部门会同有关部门根据本省实际情况，遵循账销案存权存的原则，制定核销实施细则。"},{"i":31,"n":"第三十一条","txt":"救助基金管理机构应当于每季度结束后15个工作日内，将上一季度的财务会计报告报送至救助基金主管部门；于每年2月1日前，将上一年度工作报告和财务会计报告报送至救助基金主管部门，并接受救助基金主管部门依法实施的年度考核、监督检查。"},{"i":32,"n":"第三十二条","txt":"救助基金管理机构变更或者终止时，应当委托会计师事务所依法进行审计，并对救助基金进行清算。"},{"i":33,"n":"第三十三条","txt":"救助基金主管部门应当每年向社会公告救助基金的筹集、使用、管理和追偿情况。"},{"i":34,"n":"第三十四条","txt":"救助基金主管部门应当委托会计师事务所对救助基金年度财务会计报告依法进行审计，并将审计结果向社会公告。"},{"i":35,"n":"第三十五条","txt":"救助基金主管部门应当根据救助基金管理机构年度服务数量和质量结算管理费用。 救助基金的管理费用列入本级预算，不得在救助基金中列支。"},{"i":36,"n":"第三十六条","txt":"救助基金主管部门在确定救助基金管理机构时，应当书面约定有下列情形之一的，救助基金主管部门可以变更救助基金管理机构，并依法追究有关单位和人员的责任： （一）未按照本办法规定受理、审核救助基金垫付申请并进行垫付的； （二）提供虚假工作报告、财务会计报告的； （三）违反本办法规定使用救助基金的； （四）违规核销的； （五）拒绝或者妨碍有关部门依法实施监督检查的； （六）可能严重影响救助基金管理的其他情形。"},{"i":37,"n":"第三十七条","txt":"省级救助基金主管部门应当于每年3月1日前，将本地区上一年度救助基金的筹集、使用、管理、追偿以及救助基金管理机构相关情况报送至财政部和国务院保险监督管理机构。"},{"i":38,"n":"第三十八条","txt":"办理交强险业务的保险公司未依法从交强险保险费中提取资金并及时足额转入救助基金账户的，由国务院保险监督管理机构的派出机构进行催缴，超过3个工作日仍未足额上缴的，给予警告，并予以公告。"},{"i":39,"n":"第三十九条","txt":"医疗机构提供虚假抢救费用材料或者拒绝、推诿、拖延抢救道路交通事故受害人的，由卫生健康主管部门按照有关规定予以处理。"},{"i":40,"n":"第四十条","txt":"救助基金主管部门和有关部门工作人员，在工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分；涉嫌犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本办法所称受害人，是指机动车发生道路交通事故造成人身伤亡的人员。"},{"i":42,"n":"第四十二条","txt":"本办法所称抢救费用，是指机动车发生道路交通事故导致人员受伤时，医疗机构按照道路交通事故受伤人员临床诊疗相关指南和规范，对生命体征不平稳和虽然生命体征平稳但如果不采取必要的救治措施会产生生命危险，或者导致残疾、器官功能障碍，或者导致病程明显延长的受伤人员，采取必要的救治措施所发生的医疗费用。"},{"i":43,"n":"第四十三条","txt":"本办法所称丧葬费用，是指丧葬所必需的遗体接运、存放、火化、骨灰寄存和安葬等服务费用。具体垫付费用标准由救助基金主管部门会同有关部门结合当地实际，参考有关规定确定。"},{"i":44,"n":"第四十四条","txt":"机动车在道路以外的地方通行时发生事故，造成人身伤亡的，参照适用本办法。"},{"i":45,"n":"第四十五条","txt":"省级救助基金主管部门应当依据本办法有关规定，会同本地区有关部门制定实施细则，明确有关主体的职责，细化垫付等具体工作流程和规则，并将实施细则报财政部和有关部门备案。"},{"i":46,"n":"第四十六条","txt":"本办法自2022年1月1日起施行。《道路交通事故社会救助基金管理试行办法》（财政部 保监会 公安部 卫生部 农业部令第56号）同时废止。"}],"daolujiaotongshigushehuijiuzhujijinguanlishixingba1f620f":[{"i":1,"n":"第一条","txt":"为加强道路交通事故社会救助基金管理，对道路交通事故中受害人依法进行救助，根据《中华人民共和国道路交通安全法》、《机动车交通事故责任强制保险条例》，制定本办 法。"},{"i":2,"n":"第二条","txt":"道路交通事故社会救助基金的筹集、使用和管理适用本办法。 本办法所称道路交通事故社会救助基金（以下简称救助基金），是指依法筹集用于垫付机动车道路交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用的社会专项基金。"},{"i":3,"n":"第三条","txt":"救助基金实行统一政策、地方筹集、分级管理、分工负责。 财政部会同有关部门制定救助基金的有关政策，并对各省、自治区、直辖市（以下简称省级）救助基金的筹集、使用和管理进行指导和监督。 省级人民政府应当设立救助基金。救助基金主管部门及省级以下救助基金管理级次由省级人民政府确定。"},{"i":4,"n":"第四条","txt":"地方财政部门 负责对同级救助基金的筹集、使用和管理进行指导和监督。 地方保险监督管理机构负责对保险公司是否按照规定及时足额向救助基金管理机构缴纳救助基金实施监督检查。 地方公安机关交通管理部门负责通知救助基金管理机构垫付道路交通事故中受害人的抢救费用。 地方农业机械化主管部门负责协助救助基金管理机构向涉及农业机械的道路交通事故责任人追偿。 地方卫生主管部门负责监督医疗机构按照《道路交通事故受伤人员临床诊疗指南》及时抢救道路交通事故中的受害人及依法申请救助基金垫付抢救费用。"},{"i":5,"n":"第五条","txt":"救助基金主管部门依法确定救助基金管理机构，并对救助基金管理机构筹集、使用和管理救助基金情况实施监督检查。"},{"i":6,"n":"第六条","txt":"救助基金的来源包括： （一）按照机动车交通 事故责任强制保险（以下简称交强险）的保险费的一定比例提取的资金； （二）地方政府按照保险公司经营交强险缴纳营业税数额给予的财政补助； （三）对未按照规定投保交强险的机动车的所有人、管理人的罚款； （四）救助基金孳息； （五）救助基金管理机构依法向机动车道路交通事故责任人追偿的资金； （六）社会捐款； （七）其他资金。"},{"i":7,"n":"第七条","txt":"每年3月1日前，财政部会同中国保险监督管理委员会（以下称中国 保监会）根据上一年度救助基金的收支情况，按照收支平衡的原则，确定当年从交强险保险费收入提取救助基金的比例幅度。省级人民政府在幅度范围内确定本地区具体提取比例。"},{"i":8,"n":"第八条","txt":"办理交强险业务的保险公司应当按照确定的比例，从交强险保险费中提取资金，并在每季度结束后10个工作日内，通过银 行转账方式全额转入省级救助基金特设专户。"},{"i":9,"n":"第九条","txt":"省级财政部门应当根据当年预算于每季度结束后10个工作日内，按照上一个季度保险公司交纳交强险营业税数额和救助基 金收支情况，向本地省级救助基金拨付财政补助。"},{"i":10,"n":"第十条","txt":"财政部门应当根据当年预算在每季度结束后10个工作日内，将未按照规定投保交强险的罚款全额划拨至省级救助基金特设 专户。"},{"i":11,"n":"第十一条","txt":"省级救助基金与省级以下救助基金的财务关系由省级人民政府另行规定。"},{"i":12,"n":"第十二条","txt":"有下列情形之一时，救助基金垫付道路交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用： （一）抢救费用超过交强险责任限额的； （二）肇事机动车未参加交强险的； （三）机动车肇事后逃逸的。 依法应当由救助基金垫付受害人丧葬费用、部分或者全部抢救费用的，由道路交通事故发生地的救助基金管理机构及时垫付。 救助基金一般垫付受害人自接受抢救之时起72小时内的抢救费用，特殊情况下超过72小时的抢救费用由医疗机构书面说明理由。具体应当按照机动车道路交通事故发生地物价部门核定的收费标准核算。"},{"i":13,"n":"第十三条","txt":"发生本办法第十二条所列情形之一需要救助基金垫付部分或者全部抢救费用的，公安机关交通管理部门应当在3个工作日 内书面通知救助基金管理机构。"},{"i":14,"n":"第十四条","txt":"医疗机构在抢救受害人结束后，对尚未结算的抢救费用，可以向救助基金管理机构提出垫付申请，并提供有关抢救费用的证明材料。"},{"i":15,"n":"第十五条","txt":"救助基金管理机构收到公安机关交通管理部门垫付通知和医疗机构垫付尚未结算抢救费用的申请及相关材料后，应当在5个工作日内，按照本办法有关规定、《道路交通事故受伤人员临床诊疗指南》和当地物价部门制定的收费标准，对下列内容进行审核，并将 审核结果书面告知处理该道路交通事故的公安机关交通管理部门和医疗机构： （一）是否属于本办法第十二条规定的救助基金垫付情形； （二）抢救费用是否真实、合理； （三）救助基金管理机构认为需要审核的其他内容。 对符合垫付要求的，救助基金管理机构应当将相关费用划入医疗机构账户。对不符合垫付要求的，不予垫付，并向医疗机构说明理由。"},{"i":16,"n":"第十六条","txt":"救助基金管理机构与医疗机构就垫付抢救费用问题发生争议时，由救助基金主管部门会同卫生主管部门协调解决。"},{"i":17,"n":"第十七条","txt":"发生本办法第十二条所列情形之一需要救助基金垫付丧葬费用的，由受害人亲属凭处理该道路交通事故的公安机关交通管理部门出具的《尸体处理通知书》和本人身份证明向救 助基金管理机构提出书面垫付申请。 对无主或者无法确认身份的遗体，由公安部门按照有关规定处理。"},{"i":18,"n":"第十八条","txt":"救助基金管理机构收到丧葬费用垫付申请和有关证明材料后，对符合垫付要求的，应当在3个工作日内按照有关标准垫付 丧葬费用，并书面告知处理该道路交通事故的公安机关交通管理部门。对不符合垫付要求的，不予垫付，并向申请人说明理由。"},{"i":19,"n":"第十九条","txt":"救助基金管理机构对抢救费用和丧葬费用的垫付申请进行审核时，可以向公安机关交通管理部门、医疗机构和保险公司等有关单位核实情况，有关单位应当予以配合。"},{"i":20,"n":"第二十条","txt":"救助基金管理机构履行以下职责： （一）依法筹集救助基金； （二）受理、审核垫付申请，并依法垫付； （三）依法追偿垫付款； （四）其他管理救助基金的职责。"},{"i":21,"n":"第二十一条","txt":"救助基金管理机构应当向社会公布其电话、地址、联系人等信息。"},{"i":22,"n":"第二十二条","txt":"救助基金管理机构的费用支出，包括人员费用、办公费用、追偿费用、委托代理费用等，应当按照有关规定，由同级财政部门在年度预算中予以安排，不得在救助基金中列 支。"},{"i":23,"n":"第二十三条","txt":"救助基金管理机构应当按照国家有关银行账户管理规定开立救助基金特设专户。 救助基金实行单独核算、专户管理，并应当按照规定用途使用。"},{"i":24,"n":"第二十四条","txt":"救助基金管理机构根据本办法垫付抢救费用和丧葬费用后，应当依法向机动车道路交通事故责任人进行追偿。 发生本办法第十二条第（三）项情形救助基金垫付丧葬费用、部分或者全部抢救费用的，道路交通事故案件侦破后，处理该道路交通事故的公安机关交通管理部门应当及时通知救助基金管 理机构。 有关单位、受害人或者其继承人有义务协助救助基金管理机构进行追偿。"},{"i":25,"n":"第二十五条","txt":"救助基金管理机构应当于每季度终了后15个工作日内，将上季度的财务会计报告报送同级救助基金主管部门，并于每 年2月1日前将上一年度工作报告和财务会计报告，报送同级救助基金主 管部门。"},{"i":26,"n":"第二十六条","txt":"救助基金管理机构应当如实报告救助基金业务事项，不得有虚假记载。"},{"i":27,"n":"第二十七条","txt":"救助基金管理机构每年应当向同级财政部门报告救助基金的筹集、使用和管理情况，接受同级财政部门依法实施的监督检查。"},{"i":28,"n":"第二十八条","txt":"救助基金管理机构变更或终止时，应当依法进行审计、清算。"},{"i":29,"n":"第二十九条","txt":"救助基金主管部门履行以下职责： （一）制订本地区救助基金具体管理办法； （二）依法确定救助基金管理机构； （三）依法监督检查救助基金的筹集、垫付、追偿情况，并定期予以公告； （四）依法委托会计师事务所对救助基金年度财务会计报告进行审计，并予以公告； （五）依法对救助基金管理机构及其工作人员的违法行为进行处理、处罚。"},{"i":30,"n":"第三十条","txt":"省级救助基金主管部门应当于每年3月1日前，将本地区上一年度 救助基金的筹集、垫付、追偿等情况报送财政部和中国保监会。"},{"i":31,"n":"第三十一条","txt":"办理交强险业务的保险公司未依法从交强险保险费中提取资金并及时足额转入救助基金特设专户的，由地方保险监督管理机构进行催缴，超过3个工作日仍未足额上缴的，给予警告，并予以公告。"},{"i":32,"n":"第三十二条","txt":"医疗机构提供虚假抢救费用的，由卫生主管部门给予警告，并对直接责任人按照有关规定予以处理。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，由救助基金主管部门对救助基金管理机构及其负责人按照相关规定进行处理，并可以根据情形决定是否撤换救助基金管理机构： （一）未按照本办法规 定受理、审核救助基金垫付申请并进行垫付的； （二）提供虚假工作报 告、财务会计报告的； （三）违反本办法的规 定使用救助基金的； （四）拒绝或者妨碍主 管部门或者有关部门依法实施监督检查的。"},{"i":34,"n":"第三十四条","txt":"救助基金主管部门和有关部门工作人员，在工作中滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分，涉嫌犯罪的，依法移送司法机关。"},{"i":35,"n":"第三十五条","txt":"本办法所称受害人，是指机动车发生道路交通事故造成除被保险机动车本车人员、被保险人以外的受害人。"},{"i":36,"n":"第三十六条","txt":"本办法所称抢救费用，是指机动车发生道路交通事故导致人员受伤时，医疗机构按照《道路交通事故受伤人员临床诊疗指南》，对生命体征不平稳和虽然生命体征平稳但如果 不采取处理措施会产生生命危险，或者导致残疾、器官功能障碍，或者导致病程明显延长的受伤人员，采取必要的处理措施所发生的医疗费用。"},{"i":37,"n":"第三十七条","txt":"本办法所称丧葬费用，是指丧葬所必需的遗体运送、停放、冷藏、火化的服务费用。具体费用应当按照机动车道路交通事故发生地物价部门制定的收费标准确定。"},{"i":38,"n":"第三十八条","txt":"机动车在道路以外的地方通行时发生事故，造成人身伤亡的，比照适用本办法。"},{"i":39,"n":"第三十九条","txt":"省级救助基金主管部门应当依据本办法有关规定，会同本地区有关部门制订实施细则，并报财政部和有关部门备案。"},{"i":40,"n":"第四十条","txt":"本办法自2010年1月1日起施行。"}],"jinrongqiyeguoyouzichanpinggujianduguanlizanxingbaf0f214":[{"i":1,"n":"第一条","txt":"为了加强对金融企业国有资产评估的监督管理，规范金融企业国有资产评估行为，维护国有资产所有者合法权益，根据有关法律、行政法规和国务院相关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内依法设立，并占有国有资产的金融企业、金融控股公司、担保公司（以下简称金融企业）的资产评估，适用本办法。 金融资产管理公司不良资产处置评估另有规定的从其规定。"},{"i":3,"n":"第三条","txt":"县级以上人民政府财政部门（以下简称财政部门）按照统一政策、分级管理的原则，对本级金融企业资产评估工作进行监督管理。 上级财政部门对下级财政部门监督管理金融企业资产评估工作进行指导和监督。"},{"i":4,"n":"第四条","txt":"资产评估机构进行资产评估应当遵守有关法律、法规、部门规章，以及资产评估准则和执业规范，对评估报告的合法性、真实性和合理性负责，并承担责任。 资产评估委托方和提供资料的相关当事方，应当对所提供资料的真实性、合法性和完整性负责。"},{"i":5,"n":"第五条","txt":"金融企业不得委托同一中介机构对同一经济行为进行资产评估、审计、会计业务服务。金融企业有关负责人与中介机构存在可能影响公正执业的利害关系时，应当予以回避。"},{"i":6,"n":"第六条","txt":"金融企业有下列情形之一的，应当委托资产评估机构进行资产评估： （一）整体或者部分改制为有限责任公司或者股份有限公司的； （二）以非货币性资产对外投资的； （三）合并、分立、清算的； （四）非上市金融企业国有股东股权比例变动的； （五）产权转让的； （六）资产转让、置换、拍卖的； （七）债权转股权的； （八）债务重组的； （九）接受非货币性资产抵押或者质押的； （十）处置不良资产的； （十一）以非货币性资产抵债或者接受抵债的； （十二）收购非国有单位资产的； （十三）接受非国有单位以非货币性资产出资的； （十四）确定涉讼资产价值的； （十五）法律、行政法规规定的应当进行评估的其他情形。"},{"i":7,"n":"第七条","txt":"金融企业有下列情形之一的，对相关的资产可以不进行资产评估： （一）县级以上人民政府或者其授权部门批准其所属企业或者企业的部分资产实施无偿划转的； （二）国有独资企业与其下属的独资企业之间，或者其下属独资企业之间的合并，以及资产或者产权置换、转让和无偿划转的； （三）发生多次同类型的经济行为时，同一资产在评估报告使用有效期内，并且资产、市场状况未发生重大变化的； （四）上市公司可流通的股权转让。"},{"i":8,"n":"第八条","txt":"需要资产评估时，应当按照下列情况进行委托： （一）经济行为涉及的评估对象属于金融企业法人财产权的，或者金融企业接受非国有资产的，资产评估由金融企业委托； （二）经济行为涉及的评估对象属于金融企业出资人权利的，资产评估由金融企业出资人或者其上级单位委托。"},{"i":9,"n":"第九条","txt":"金融企业有关经济行为的资产评估报告，自评估基准日起 1年内有效。"},{"i":10,"n":"第十条","txt":"金融企业资产评估项目实行核准制和备案制。"},{"i":11,"n":"第十一条","txt":"金融企业下列经济行为涉及资产评估的，资产评估项目实行核准： （一）经批准进行改组改制、拟在境内或者境外上市、以非货币性资产与外商合资经营或者合作经营的经济行为； （二）经县级以上人民政府批准的其他涉及国有资产产权变动的经济行为。 中央金融企业资产评估项目报财政部核准。地方金融企业资产评估项目报本级财政部门核准。"},{"i":12,"n":"第十二条","txt":"需要核准的资产评估项目，金融企业应当在资产评估前向财政部门报告下列情况： （一）相关经济行为的批准情况； （二）评估基准日的选择情况； （三）资产评估范围的确定情况； （四）资产评估机构的选择情况； （五）资产评估的进度安排情况。"},{"i":13,"n":"第十三条","txt":"对资产评估机构出具的评估报告，金融企业应当逐级上报审核，自评估基准日起8个月内向财政部门提出资产评估项目核准申请。"},{"i":14,"n":"第十四条","txt":"金融企业申请资产评估项目核准时，应当向财政部门报送下列材料： （一）资产评估项目核准申请文件； （二）金融企业资产评估项目核准表（包括：资产评估项目基本情况和资产评估结果，见附件1，一式一份）； （三）与资产评估目的相对应的经济行为批准文件及实施方案； （四）资产评估报告及电子文档； （五）按照规定应当进行审计的审计报告。 拟在境外和香港特别行政区上市的，还应当报送符合相关规定的资产评估报告。"},{"i":15,"n":"第十五条","txt":"财政部门收到核准申请后，对申请材料不齐全或者不符合法定形式的，应当在5个工作日内书面一次性告知申请人需要补正的全部内容。对申请材料齐全、符合法定形式，或者申请人按照要求全部补正申请材料的应当受理。 受理申请或者不予受理申请，应当向申请人出具注明日期的书面凭证（见附件2）。"},{"i":16,"n":"第十六条","txt":"财政部门受理申请后，应当对申请材料进行审查。申请材料符合下列要求的，财政部门应当组织专家对资产评估报告进行评审： （一）资产评估项目所涉及的经济行为已获得批准； （二）资产评估基准日的选择适当； （三）资产评估依据适当； （四）资产评估范围与经济行为批准文件确定的资产范围一致； （五）资产评估程序符合相关评估准则的规定； （六）资产评估报告的有效期已明示； （七）委托方和提供资料的相关当事方已就所提供的资产权属证明文件及其他资料的真实性、合法性和完整性做出承诺。 财政部门应当在受理申请后的20个工作日内作出是否予以核准的书面决定。作出不予核准的书面决定的，应当说明理由。 组织专家评审所需时间不计算在前款规定的期限内。"},{"i":17,"n":"第十七条","txt":"除本办法第十一条第一款规定的经济行为以外的其他经济行为，应当进行资产评估的，资产评估项目实行备案。"},{"i":18,"n":"第十八条","txt":"中央直接管理的金融企业资产评估项目报财政部备案。中央直接管理的金融企业子公司、省级分公司或分行、金融资产管理公司办事处账面资产总额大于或者等于5000万元人民币的资产评估项目，由中央直接管理的金融企业审核后报财政部备案。中央直接管理的金融企业子公司、省级分公司或分行、金融资产管理公司办事处账面资产总额小于5000万元人民币的资产评估项目，以及下属公司、银行地（市、县）级支行的资产评估项目，报中央直接管理的金融企业备案。 地方金融企业资产评估项目备案，由省级财政部门根据本地区实际情况具体确定。"},{"i":19,"n":"第十九条","txt":"对资产评估机构出具的评估报告，金融企业应当逐级上报审核，自评估基准日起9个月内向财政部门（或者金融企业）提出资产评估项目备案申请。"},{"i":20,"n":"第二十条","txt":"金融企业申请资产评估项目备案时，应当报送下列材料： （一）金融企业资产评估项目备案表（包括：资产评估项目基本情况和资产评估结果，见附件3，一式三份）； （二）与资产评估目的相对应的经济行为批准文件； （三）资产评估报告及电子文档； （四）按照规定应当进行审计的审计报告。"},{"i":21,"n":"第二十一条","txt":"财政部门（或者金融企业）收到备案材料后，应当在 20个工作日内决定是否办理备案手续。 对材料齐全、符合下列要求的，财政部门（或者金融企业）应当办理备案手续，并将资产评估项目备案表退资产占有企业和报送企业留存： （一）资产评估项目所涉及的经济行为已获得批准； （二）资产评估范围与经济行为批准文件确定的资产范围一致； （三）资产评估程序符合相关评估准则的规定； （四）委托方和提供资料的相关当事方已就所提供的资产权属证明文件及其他资料的真实性、合法性和完整性做出承诺。 对材料不齐全或者不符合上述要求的，财政部门（或者金融企业）不予办理备案手续，并书面说明理由。 必要时财政部门（或者金融企业）可以组织有关专家进行评审。组织专家评审所需时间不计算在本条第一款规定的期限内。"},{"i":22,"n":"第二十二条","txt":"涉及多个产权投资主体的，按照金融企业国有股最大股东的财务隶属关系申请核准或者备案。国有股东持股比例相等的，经协商可以委托其中一方按照其财务隶属关系申请核准或者备案。 申请核准或者备案的金融企业应当及时将核准或者备案情况告知产权投资主体。"},{"i":23,"n":"第二十三条","txt":"财政部门准予资产评估项目核准文件和经财政部门（或者金融企业）备案的资产评估项目备案表是金融企业办理产权登记、股权设置和产权转让等相关手续的必备材料。"},{"i":24,"n":"第二十四条","txt":"金融企业发生与资产评估相对应的经济行为时，应当以经核准或者备案的资产评估结果为作价参考依据。当交易价格与资产评估结果相差10%以上时，应当就差异原因向财政部门（或者金融企业）作出书面说明。"},{"i":25,"n":"第二十五条","txt":"金融企业应当建立健全金融企业资产评估管理工作制度，完善档案管理，加强统计分析工作。"},{"i":26,"n":"第二十六条","txt":"省级以上财政部门应当对金融企业资产评估工作进行监督检查，必要时可以对资产评估机构进行延伸检查。"},{"i":27,"n":"第二十七条","txt":"省级财政部门应当于每年的 3月31日前 ，将对本地区金融企业上一年度资产评估工作的监督检查情况、存在的问题及处理情况报财政部。"},{"i":28,"n":"第二十八条","txt":"省级以上财政部门应当将监督检查中发现的问题，及时向相关监管部门进行通报。"},{"i":29,"n":"第二十九条","txt":"金融企业在资产评估中有违法行为的，依照有关法律、行政法规的规定处理、处罚。"},{"i":30,"n":"第三十条","txt":"金融企业违反本办法有关规定，由财政部门责令限期改正。有下列情形之一的，由财政部门给予警告： （一）应当进行资产评估而未进行评估的； （二）应当申请资产评估项目核准或者备案而未申请的； （三）委托没有资产评估执业资格的机构或者人员从事资产评估的，或者委托同一中介机构对同一经济行为进行资产评估、审计、会计业务服务的。"},{"i":31,"n":"第三十一条","txt":"资产评估机构或者人员在金融企业资产评估中违反有关规定的，由省级以上财政部门依法进行处理、处罚。"},{"i":32,"n":"第三十二条","txt":"财政部门工作人员在资产评估监督管理工作中滥用职权、玩忽职守、徇私舞弊，或者泄漏金融企业商业秘密的，依法给予行政处分，涉嫌犯罪的，依法移送司法机关。"},{"i":33,"n":"第三十三条","txt":"省级财政部门可以依照本办法，结合本地区实际情况，制订具体实施办法。"},{"i":34,"n":"第三十四条","txt":"对中国人民银行总行所属企业资产评估的监督管理，参照本办法执行。"},{"i":35,"n":"第三十五条","txt":"本办法自 2008年1月1日起施行。 附件：1.金融企业资产评估项目核准表 2－1.受理资产评估项目核准申请通知书 2－2.不予受理资产评估项目核准申请通知书 3.金融企业资产评估项目备案表"}],"jinrongqiyeguoyouzichanzhuanrangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范金融企业国有资产转让行为，加强国有资产交易的监督管理，维护国有资产出资人的合法权益，防止国有资产流失，根据有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称金融企业国有资产，是指各级人民政府及其授权投资主体对金融企业各种形式的出资所形成的权益。 本办法所称金融企业，包括所有获得金融业务许可证的企业和金融控股（集团）公司。"},{"i":3,"n":"第三条","txt":"县级以上人民政府财政部门（以下简称财政部门）和县级以上人民政府或者财政部门授权投资主体转让所持金融企业国有资产，国有及国有控股金融企业（以下统称转让方）转让所持国有资产给境内外法人、自然人或者其他组织（以下统称受让方），适用本办法。"},{"i":4,"n":"第四条","txt":"金融企业国有资产转让应当遵守法律、行政法规和产业政策规定。"},{"i":5,"n":"第五条","txt":"金融企业国有资产转让包括非上市企业国有产权转让和上市公司国有股份转让。 金融企业国有资产转让以通过产权交易机构、证券交易系统交易为主要方式。符合本办法规定条件的，可以采取直接协议方式转让金融企业国有资产。"},{"i":6,"n":"第六条","txt":"拟转让的金融企业国有资产权属关系应当明晰。权属关系不明确或者存在权属纠纷以及法律、行政法规和国家有关政策规定禁止转让的金融企业国有资产不得转让。 转让已经设立担保物权的金融企业国有资产，应当符合《中华人民共和国物权法》、《中华人民共和国担保法》等有关法律、行政法规的规定。"},{"i":7,"n":"第七条","txt":"金融企业国有资产转让按照统一政策、分级管理的原则，由财政部门负责监督管理。财政部门转让金融企业国有资产，应当报本级人民政府批准。政府授权投资主体转让金融企业国有资产，应当报本级财政部门批准。 金融企业国有资产转让过程中，涉及政府社会公共管理和金融行业监督管理事项的，应当根据国家规定，报经政府有关部门批准。 以境外投资人为受让方的，应当符合国家有关外商投资的监督管理规定，由转让方按照有关规定报经政府有关部门批准。"},{"i":8,"n":"第八条","txt":"财政部门是金融企业国有资产转让的监督管理部门。 财政部负责制定金融企业国有资产转让监督管理制度，并对中央管理的金融企业及其子公司的国有资产转让工作实施监督管理。 地方县级以上财政部门对本级管理的金融企业及其子公司国有资产转让实施监督管理。 上级财政部门指导和监督下级财政部门的金融企业国有资产转让监督管理工作。"},{"i":9,"n":"第九条","txt":"财政部门对金融企业国有资产转让履行下列监督管理职责： （一）决定或者批准金融企业国有资产转让事项，审核重大资产转让事项并报本级人民政府批准； （二）确定承办金融企业国有资产交易业务的产权交易机构备选名单； （三）负责金融企业国有资产转让情况的监督检查工作； （四）负责金融企业国有资产转让信息的收集、汇总、分析和上报工作； （五）本级人民政府授权的其他职责。"},{"i":10,"n":"第十条","txt":"国有及国有控股金融企业在境内外依法设立子公司或者向企业投资的，由该国有及国有控股金融企业按本办法规定负责所设立子公司和投资企业的国有资产的转让工作，并履行下列职责： （一）按照本办法及国家有关规定，制定企业所属分支机构、子公司的国有资产转让管理办法和工作程序，并报本级财政部门备案； （二）研究资产转让行为是否有利于促进企业的持续发展； （三）审议所属一级子公司的资产转让事项，监督一级子公司以下的资产转让事项； （四）向财政部门、相关金融监督管理部门和其他有关部门报告有关资产转让情况。"},{"i":11,"n":"第十一条","txt":"非上市企业国有产权的转让应当在依法设立的省级以上（含省级，下同）产权交易机构公开进行，不受地区、行业、出资或者隶属关系的限制。"},{"i":12,"n":"第十二条","txt":"国有及国有控股金融企业转让一级子公司的产权，应当报财政部门审批。除国家明确规定需要报国务院批准外，中央管理的国有及国有控股金融企业转让一级子公司的产权应当报财政部审批；地方管理的金融企业国有资产转让的审批权限，由省级财政部门确定。 国有及国有控股金融企业一级子公司（省级分公司或者分行、金融资产管理公司办事处）转让所持子公司产权，由控股（集团）公司审批。其中，涉及重要行业、重点子公司的重大国有产权转让，或者导致转让标的企业所持金融企业或者其他重点子公司控股权转移的，应当报财政部门审批。"},{"i":13,"n":"第十三条","txt":"转让方应当制定转让方案，并按照内部决策程序交股东会或者股东大会、董事会或者其他决策部门审议，形成书面决议。 转让方案包括转让标的企业产权的基本情况、转让行为的论证情况、产权转让公告以及其他主要内容。 转让标的企业涉及职工安置问题的，应当按照国家有关规定办理职工安置工作。"},{"i":14,"n":"第十四条","txt":"转让方应当依照国家有关规定，委托资产评估机构对转让标的企业的整体价值进行评估。"},{"i":15,"n":"第十五条","txt":"非上市企业国有产权转让需要报财政部门审批的，转让方应当在进场交易前报送以下材料： （一）产权转让的申请书，包括转让原因，是否进场交易等内容； （二）产权转让方案及内部决策文件； （三）转让方基本情况及上一年度经会计师事务所审计的财务会计报告； （四）转让标的企业基本情况、当期财务会计报告和最近一期经会计师事务所审计的财务会计报告； （五）转让方和转让标的企业国有资产产权证明文件； （六）转让标的企业资产评估核准或者备案文件； （七）拟选择的产权交易机构； （八）意向受让方应当具备的基本条件、支付方式； （九）律师事务所出具的法律意见书； （十）财政部门认为必要的其他文件。 转让金融企业产权的，应当对是否符合相关金融监督管理部门的规定进行说明。"},{"i":16,"n":"第十六条","txt":"从事金融企业国有产权交易活动的产权交易机构，应当符合下列基本条件： （一）遵守有关法律、法规、规章； （二）具备相应的交易场所、信息发布渠道和专业人员，能够满足金融企业国有产权交易活动的需要； （三）具有健全的内部管理制度，产权交易操作规范； （四）能够履行产权交易机构的职责，依法审查产权交易主体的资格和条件； （五）连续3年没有违法、违规记录； （六）按照国家有关规定公开披露产权交易信息，并能够按要求及时向省级以上财政部门报告场内金融企业国有产权交易情况。"},{"i":17,"n":"第十七条","txt":"转让方在确定进场交易的产权交易机构后，应当委托该产权交易机构在省级以上公开发行的经济或者金融类报刊和产权交易机构的网站上刊登产权转让公告，公开披露有关非上市企业产权转让信息，征集意向受让方。 产权转让公告期不得少于20个工作日。"},{"i":18,"n":"第十八条","txt":"转让方披露的非上市企业产权转让信息应当包括下列内容： （一）转让标的企业的基本情况； （二）转让标的企业的产权构成情况； （三）产权转让行为的内部决策情况； （四）转让标的企业最近一期经会计师事务所审计的主要财务指标数据； （五）转让标的企业资产评估核准或者备案情况； （六）受让方应当具备的基本条件； （七）其他需要披露的事项。 需要按本办法办理审批手续的，还应当披露产权转让行为的批准情况。"},{"i":19,"n":"第十九条","txt":"意向受让方一般应当具备下列条件： （一）具有良好的财务状况和支付能力； （二）具有良好的商业信用； （三）受让方为自然人的，应当具有完全民事行为能力； （四）国家规定的其他条件。 在不违反相关监督管理要求和公平竞争原则下，转让方可以对意向受让方的资质、商业信誉、行业准入、资产规模、经营情况、财务状况、管理能力等提出具体要求。"},{"i":20,"n":"第二十条","txt":"在产权交易过程中，首次挂牌价格不得低于经核准或者备案的资产评估结果。 首次挂牌未能征集到意向受让方的，转让方可以根据转让标的企业情况确定新的挂牌价格并重新公告。如新的挂牌价格低于资产评估结果的90%，应当重新报批。"},{"i":21,"n":"第二十一条","txt":"经公开征集，产生2个以上（含2个）意向受让方时，转让方应当会同产权交易机构共同对意向受让方进行资格审核，根据转让标的企业的具体情况采取拍卖、招投标或者国家规定的其他公开竞价方式实施产权交易。 采取拍卖方式转让非上市企业产权的，应当按照《中华人民共和国拍卖法》及其他有关规定组织实施。 采取招投标方式转让非上市企业产权的，应当按照《中华人民共和国招标投标法》及其他有关规定组织实施。"},{"i":22,"n":"第二十二条","txt":"经产权交易机构公开征集只产生1个符合条件的意向受让方时，产权转让可以采取场内协议转让方式进行，但转让价格不得低于挂牌价格。 采取场内协议转让方式的，转让方应当与受让方进行充分协商，依法妥善处理转让中所涉及的相关事项后，签订产权转让协议（合同，下同）。"},{"i":23,"n":"第二十三条","txt":"确定受让方后，转让方应当与受让方签订产权转让协议。 转让协议应当包括下列内容： （一）转让与受让双方的名称与住所； （二）转让标的企业产权的基本情况； （三）转让方式、转让价格、价款支付时间和方式及付款条件； （四）产权交割事项； （五）转让涉及的有关税费负担； （六）协议争议的解决方式； （七）协议各方的违约责任； （八）协议变更和解除的条件； （九）转让和受让双方认为必要的其他条款。"},{"i":24,"n":"第二十四条","txt":"转让方应当按照产权转让协议的约定及时收取产权转让的全部价款，转让价款原则上应当采取货币性资产一次性收取。如金额较大、一次付清确有困难的，可以约定分期付款方式，但分期付款期限不得超过１年。 采用分期付款方式的，受让方首期付款不得低于总价款的30%，并在协议生效之日起5个工作日内支付；其余款项应当办理合法的价款支付保全手续，并按同期金融机构基准贷款利率向转让方支付分期付款期间利息。在全部转让价款支付完毕前或者未办理价款支付保全手续前，转让方不得申请办理国有产权登记和工商变更登记手续。 受让方以非货币性资产支付产权转让价款的，转让方应当按照有关规定委托资产评估机构进行资产评估，确定非货币性资产的价值。"},{"i":25,"n":"第二十五条","txt":"财政部门应当对转让方报送的材料进行认真审核，确定是否批准相关产权转让事项。 转让事项经批准后，如转让和受让双方调整产权转让比例或者产权转让方案有重大变化，造成与批准事项不符的，应当按照规定程序重新报批。"},{"i":26,"n":"第二十六条","txt":"非上市企业产权转让过程中涉及国有土地（海域）使用权、探矿权、采矿权的，应当按照国家有关规定另行办理相关手续。"},{"i":27,"n":"第二十七条","txt":"非上市企业产权转让完成后，转让和受让双方应当凭产权交易机构出具的产权交易凭证，按照国家有关规定及时办理相关国有产权登记手续。"},{"i":28,"n":"第二十八条","txt":"转让上市金融企业国有股份和金融企业转让上市公司国有股份应当通过依法设立的证券交易系统进行。"},{"i":29,"n":"第二十九条","txt":"转让方应当根据有关规定，办理上市公司股份转让的信息披露事项。"},{"i":30,"n":"第三十条","txt":"转让方为上市公司控股股东，应当将股份转让方案报财政部门审批后实施。 涉及国民经济关键行业的，应当得到相关部门的批准。"},{"i":31,"n":"第三十一条","txt":"转让方为上市公司参股股东，在1个完整会计年度内累计净转让股份（累计减持股份扣除累计增持股份后的余额，下同）比例未达到上市公司总股本5%的，由转让方按照内部决策程序决定，并在每年1月10日前将上一年度转让上市公司股份的情况报财政部门；达到或者超过上市公司总股本5%的，应当事先将转让方案报财政部门批准后实施。"},{"i":32,"n":"第三十二条","txt":"转让方转让上市公司国有股份需要报财政部门审批的，报送材料应当包括： （一）转让上市公司股份的申请书，包括转让原因、转让股份数量、持股成本、转让价格确定等内容； （二）上市公司股份转让方案和内部决策文件； （三）转让方基本情况及上一年度经会计师事务所审计的财务会计报告； （四）上市公司基本情况及最近一期年度财务会计报告和经会计师事务所审计的财务会计报告； （五）转让上市公司股份对公司控制权、公司股价和资本市场的影响； （六）财政部门规定的其他文件。 财政部门应当对转让方报送的材料进行认真审核，确定是否同意上市公司股份转让事项。"},{"i":33,"n":"第三十三条","txt":"转让方采取大宗交易方式转让上市公司股份的，股份转让价格不得低于该上市公司股票当天交易的加权平均价格；当日无成交的，不得低于前1个交易日的加权平均价格。"},{"i":34,"n":"第三十四条","txt":"上市公司股份转让完成后，转让方应当按照国家有关规定及时办理国有产权登记手续。"},{"i":35,"n":"第三十五条","txt":"有下列情况之一，经国务院批准或者财政部门批准，转让方可以采取直接协议转让方式转让非上市企业国有产权和上市公司国有股份。 （一）国家有关规定对受让方有特殊要求； （二）控股（集团）公司进行内部资产重组； （三）其他特殊原因 拟采取直接协议转让方式对控股（集团）公司内部进行资产重组的，中央管理的金融企业一级子公司的产权转让工作由财政部负责；一级以下子公司的产权转让由控股（集团）公司负责，其中：拟直接协议转让控股上市公司股份的，应当将转让方案报财政部审批。"},{"i":36,"n":"第三十六条","txt":"转让方采用直接协议方式转让非上市企业产权的，应当按照本办法第十三条、第十四条、第十五条、第二十三条和第二十四条的规定，组织转让方案制定、资产评估、审核材料报送、转让协议签署和转让价款收取等项工作。"},{"i":37,"n":"第三十七条","txt":"非上市企业产权直接协议转让的价格不得低于经核准或者备案的资产评估结果。 国有金融企业在实施内部资产重组过程中，拟采取直接协议方式转让产权、且转让方和受让方为控股（集团）公司所属独资子公司的，可以不对转让标的企业进行整体评估，但转让价格不得低于最近一期经审计确认的净资产值。"},{"i":38,"n":"第三十八条","txt":"财政部门对金融企业以直接协议转让形式转让非上市企业产权的审核按照本办法第二十五条规定执行。"},{"i":39,"n":"第三十九条","txt":"转让方拟直接协议转让上市公司股份的，应当按照内部决策程序交股东大会、董事会或者其他决策部门进行审议，形成书面决议，并及时报告财政部门。 转让方应当将拟直接协议转让股份的信息书面告知上市公司，由上市公司依法向社会公众进行提示性公告，公告中应当注明，本次股份拟直接协议转让事项应当经财政部门审批。"},{"i":40,"n":"第四十条","txt":"转让方直接协议转让上市公司股份，应当向财政部门提交下列材料： （一）协议转让上市公司股份的申请书，包括转让原因、转让股份数量、持股成本等内容； （二）协议转让上市公司股份的内部决策文件及可行性研究报告； （三）拟公开发布的股份协议转让信息内容； （四）财政部门规定的其他文件。"},{"i":41,"n":"第四十一条","txt":"财政部门收到转让方提交的直接协议转让上市公司股份材料后，应当认真进行审核，确定是否批准协议转让事项，并在15个工作日内予以答复。 转让方收到财政部门出具的意见后2个工作日内，应当书面告知上市公司，由上市公司依法公开披露国有股东拟直接协议转让上市公司股份的信息。"},{"i":42,"n":"第四十二条","txt":"转让方直接协议转让上市公司股份信息应当包括以下内容： （一）转让股份数量及所涉及的上市公司名称及基本情况； （二）受让方应当具备的资格条件； （三）受让方递交受让申请的截止日期； （四）财政部门和相关部门的批复意见。"},{"i":43,"n":"第四十三条","txt":"具有下列情形之一的，经财政部门批准后，转让方可以不披露上市公司股份协议转让信息： （一）国民经济关键行业、领域中对受让方有特殊要求的； （二）转让方作为国有控股股东，为实施国有资源整合或者资产重组，在控股公司或者集团企业内部进行协议转让的； （三）上市公司连续2年亏损并存在退市风险或者严重财务危机，受让方提出重大资产重组计划及具体时间表的； （四）上市公司回购股份涉及转让方所持股份的。"},{"i":44,"n":"第四十四条","txt":"转让方作为上市公司控股股东，拟采取直接协议转让方式转让股份并失去控股权的，应当聘请具有相应资质的专业中介机构担任财务顾问和法律顾问，并提出书面意见。财务顾问和法律顾问应当具有良好的信誉及近3年内无重大违法违规记录。转让方认为必要时，可委托具有证券评估资格的资产评估机构对转让标的资产进行评估。"},{"i":45,"n":"第四十五条","txt":"转让方直接协议转让上市公司股份的，转让价格应当按照上市公司股份转让信息公告日（经批准不须公开股份转让信息的，以股份转让协议签署日为准）前30个交易日每日加权平均价格的加权平均价格或者前1个交易日加权平均价格孰高的原则确定。 转让方作为上市公司国有控股股东，为实施国有资源整合或者资产重组，在内部进行协议转让，且拥有的上市公司权益并不因此减少的，转让价格应当根据上市公司最近一期经审计的净资产、净资产收益率、市盈率等因素合理协商确定。"},{"i":46,"n":"第四十六条","txt":"受让上市公司股份后，受让方拥有上市公司实际控制权的，应当具备以下条件： （一）具有法人资格； （二）设立3年以上，最近2年连续盈利且无重大违法违规行为； （三）具有促进上市公司持续发展和改善上市公司法人治理结构的能力。"},{"i":47,"n":"第四十七条","txt":"受让方确定后，转让方应当及时与受让方签署股份转让协议。 转让协议应当包括但不限于以下内容： （一）转让方、上市公司、受让方企业名称、法定代表人姓名及住所； （二）转让方持股数量、拟转让股份数量及价格； （三）转让方、受让方的权利和义务； （四）股份转让价款支付方式及期限； （五）股份登记过户条件； （六）协议变更和解除条件； （七）协议争议解决方式； （八）协议各方的违约责任； （九）协议生效条件。"},{"i":48,"n":"第四十八条","txt":"上市公司股份的转让方为国有及国有控股金融企业的，转让方在确定受让方后，应当及时向财政部门报送以下材料： （一）转让方案的实施及选择受让方的有关情况； （二）上一年度经会计师事务所审计的财务会计报告； （三）受让方基本情况、公司章程及最近一期经会计师事务所审计的财务会计报告； （四）上市公司基本情况、最近一期中期财务会计报告及经会计师事务所审计年度财务会计报告； （五）股份转让协议及股份转让价格的定价说明； （六）受让方与国有股东、上市公司之间在最近12个月内股权转让、资产置换、投资等重大情况及债权债务情况； （七）律师事务所出具的法律意见书； （八）转让上市公司股份对公司股价和资本市场的影响； （九）财政部门规定的其他文件。"},{"i":49,"n":"第四十九条","txt":"财政部门应当对转让方报送的材料进行认真审核，并出具股份转让批复文件。"},{"i":50,"n":"第五十条","txt":"转让方应当按照本办法第二十四条的规定，收取转让价款，并按照国家有关规定及时办理相关国有产权登记手续。"},{"i":51,"n":"第五十一条","txt":"金融企业国有资产转让过程中出现下列情形之一的，财政部门可以要求转让方立即中止或者终止资产转让活动： （一）未按本办法有关规定在产权交易机构中进行交易的； （二）转让方不履行相应的内部决策程序、批准程序或者超越权限，或者未按规定报经财政部门和相关部门审批，擅自转让资产的； （三）转让方、转让标的企业故意隐匿应当纳入评估范围的资产，或者向中介机构提供虚假会计资料，导致审计、评估结果失真，以及未经审计、评估，造成国有资产流失的； （四）转让方与受让方串通，低价转让国有资产，造成国有资产流失的； （五）转让方未按规定落实转让标的企业的债权债务，非法转移债权或者逃避债务清偿责任的；以金融企业国有资产作为担保的，转让该部分资产时，未经担保债权人同意的； （六）受让方采取欺诈、隐瞒等手段影响转让方的选择以及资产转让协议签订的； （七）受让方在产权转让竞价过程中，恶意串通压低价格，造成国有资产流失的。"},{"i":52,"n":"第五十二条","txt":"转让方、转让标的企业有本办法第五十一条规定的情形，由财政部门给予警告，并建议有关部门对负有直接责任的人员和其他直接责任人员给予行政处分；造成国有资产损失的，应当建议有关部门依法追究金融企业董事、监事、高级管理人员的责任；由于受让方的责任造成国有资产流失的，受让方应当依法赔偿转让方的经济损失。涉嫌犯罪的，应当移送司法机关。"},{"i":53,"n":"第五十三条","txt":"会计师事务所、资产评估机构、律师事务所、财务顾问机构等社会中介机构在国有资产转让的审计、评估、法律和咨询服务中违规执业的，财政部门应当向其行业主管部门通报有关情况，建议依法给予相应处理。"},{"i":54,"n":"第五十四条","txt":"产权交易机构在金融企业国有资产交易中弄虚作假或者玩忽职守，损害国家利益或者交易双方合法权益的，财政部门可以停止其从事金融企业国有资产交易的相关业务，建议有关部门依法追究产权交易机构及直接责任人员的责任。"},{"i":55,"n":"第五十五条","txt":"金融企业国有资产转让批准机构及其有关人员违反法律、行政法规及本办法规定，造成国有资产流失的，由有关部门依法给予纪律处分；涉嫌犯罪的，移送司法机关。"},{"i":56,"n":"第五十六条","txt":"省、自治区、直辖市、计划单列市的财政厅（局）可以根据本办法，制定本地区金融企业国有资产转让管理实施办法，并报财政部备案。"},{"i":57,"n":"第五十七条","txt":"国有及国有控股金融企业因依法行使债权或者担保物权，而受偿于债务人、担保人或者第三人的非上市企业产权转让，比照本办法第二章在产权交易机构进行。 国有及国有控股金融企业因依法行使债权或者担保物权，而受偿于债务人、担保人或者第三人的上市公司股份转让，比照本办法第三章的规定在证券交易系统中进行。"},{"i":58,"n":"第五十八条","txt":"国有及国有控股金融企业持有的国有资产涉及诉讼的，根据人民法院具有法律效力的文件，办理相关转让手续。"},{"i":59,"n":"第五十九条","txt":"国有及国有控股的证券公司、基金管理公司、资产管理公司、信托公司和保险资产管理公司等金融企业出售其所持有的以自营为目的的上市公司股份按照相关规定办理。"},{"i":60,"n":"第六十条","txt":"金融资产管理公司转让不良资产和债转股股权资产的，国家相关政策另有规定的，从其规定。 本办法所称金融资产管理公司，是指中国华融资产管理公司、中国长城资产管理公司、中国东方资产管理公司和中国信达资产管理公司。"},{"i":61,"n":"第六十一条","txt":"中国人民银行总行所属企业、中国投资有限责任公司（含中央汇金投资有限责任公司）、信用担保公司以及其他金融类企业的国有资产转让监督管理工作，比照本办法执行。"},{"i":62,"n":"第六十二条","txt":"本办法自2009年5月1日起施行。 2009.3.17"}],"jinrongqiyeguoyouzibenbaozhizengzhijieguoquerenzan992325":[{"i":1,"n":"第一条","txt":"为了加强对金融企业国有资本的监督管理，反映金融企业国有资本运营状况，规范金融企业国有资本保值增值结果确认工作，维护国家所有者权益，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内依法设立的国有及国有控股金融企业、金融控股公司、担保公司（以下简称金融企业）国有资本保值增值结果的确认，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称国有资本，是指国家对金融企业各种形式的投资和投资所形成的权益，以及依法认定为国家所有的其他权益。 国有独资金融企业，国有资本为该金融企业的所有者权益，以及依法认定为国家所有的其他权益。国有控股金融企业，国有资本为该金融企业所有者权益中国家应当享有的份额，以及依法认定为国家所有的其他权益。"},{"i":4,"n":"第四条","txt":"县级以上人民政府财政部门（以下简称财政部门）应当依据经会计师事务所审计的金融企业年度财务会计报告，在全面分析年度内国有资本增减变动因素的基础上，按照统一政策、分级管理的原则，对本级直接管理的金融企业国有资本保值增值结果进行确认。 上级财政部门对下级财政部门的工作进行指导和监督。"},{"i":5,"n":"第五条","txt":"金融企业应当如实编制年度财务会计报告，认真分析和核实年度内国有资本增减变化的各项因素，真实反映国有资本运营结果。"},{"i":6,"n":"第六条","txt":"金融企业国有资本保值增值确认结果，应当作为财政部门对金融企业进行绩效评价的重要依据。"},{"i":7,"n":"第七条","txt":"除本办法第十三条 规定的情形外，金融企业国有资本保值增值结果通过国有资本保值增值率指标反映，同时参考相关分析指标。指标计算应当以金融企业年度财务报表为依据。对外提供合并财务报表的，应当以合并财务报表为依据。"},{"i":8,"n":"第八条","txt":"本办法所称国有资本保值增值率，是指金融企业年末国有资本剔除年度内客观增减因素影响额后与年初国有资本的比率，计算公式为： 国有资本保值增值率=［（年末国有资本±客观增减因素影响额）÷年初国有资本］×100%"},{"i":9,"n":"第九条","txt":"金融企业国有资本因下列客观因素影响而增加的，在计算国有资本保值增值率时应当减去相应的增加额： （一）国家投资，指国家对金融企业投入而增加的国有资本； （二）无偿划入，指按照国家有关规定将其他企业的国有资产全部或者部分划入而增加的国有资本； （三）资产评估，指因改制、上市等原因按照国家有关规定进行资产评估而增加的国有资本； （四）清产核资，指按照国家有关规定进行清产核资而增加的国有资本； （五）产权界定，指按照国家有关规定进行产权界定而增加的国有资本； （六）税收政策，指按照国家有关税收政策而增加的国有资本； （七） 资本（股票）溢价，指金融企业整体或者以主要资产溢价发行股票或者配股而增加的国有资本； （八）会计调整，指因会计政策和会计估计发生重大变更、会计差错调整等原因，导致金融企业年度内经营成果发生重大变动而增加的国有资本； （九）其他客观因素，指除本条 第（一）项至第（八）项客观因"},{"i":10,"n":"第十条","txt":"金融企业国有资本因下列客观因素影响而减少的，在计算国有资本保值增值率时应当加上相应的减少额： （一）无偿划出，指按照国家有关规定将金融企业的国有资产全部或者部分划入其他企业而减少的国有资本； （二）资产评估，指因改制、上市等原因按照国家有关规定进行资产评估而减少的国有资本； （三）清产核资，指按照国家有关规定进行清产核资而减少的国有资本； （四）产权界定，指按照国家有关规定进行产权界定而减少的国有资本； （五）政策性亏损，指年度内因承担国家政策性业务形成亏损并经财政部门认定而减少的国有资本； （六）会计调整，指因会计政策和会计估计发生重大变更、会计差错调整等原因，导致金融企业年度内经营成果发生重大变动而减少的国有资本； （七）不可抗力，指因自然灾害等不可抗力因素而减少的国有资本； （八）其他客观因素，指除本条 第（一）项至第（七）项客观因素外，经财政部门按照有关规定认定的其他客观因素而"},{"i":11,"n":"第十一条","txt":"金融企业国有资本保值增值分析指标分为一般性指标和行业性指标。一般性指标包括净资产收益率、利润增长率、总资产报酬率、不良资产率等，适用于各类金融企业。行业性指标包括资本充足率、不良贷款率、偿付能力充足率、净资本负债率等。资本充足率、不良贷款率适用于银行类金融企业；偿付能力充足率适用于保险类金融企业；净资本负债率适用于证券类金融企业。"},{"i":12,"n":"第十二条","txt":"金融企业国有资本保值增值率大于100%为国有资本增值；国有资本保值增值率等于100%为国有资本保值；国有资本保值增值率小于100%为国有资本减值。"},{"i":13,"n":"第十三条","txt":"下列情形不计算国有资本保值增值率，直接确定国有资本保值增值结果： (一)国有资本年初数为负值、剔除客观增减因素后年末数为正值，国有资本保值增值结果为增值； (二)国有资本年初数为正值、剔除客观增减因素后年末数为负值，国有资本保值增值结果为减值； (三) 国有资本年初数为负值、剔除客观增减因素后年末数为负值且绝对值大于年初数，国有资本保值增值结果为减值； （四）国有资本年初数为负值、剔除客观增减因素后年末数为负值且绝对数小于年初数，国有资本保值增值结果为增值。"},{"i":14,"n":"第十四条","txt":"中央直接管理的金融企业应当于每年5月15日前，将下列材料报送财政部： （一）金融企业国有资本保值增值数据和情况说明，包括国有资本保值增值完成情况及与上年度确认结果的对比分析、客观增减因素说明、年初数据调整口径的说明、分析指标大幅波动或者异常变动的说明，以及其他需要报告的情况； （二）客观增减因素相关证明材料，包括国家有关部门的文件。地方金融企业向本级财政部门报送材料和时间的要求，由省级财政部门另行规定。"},{"i":15,"n":"第十五条","txt":"省级财政部门应当于每年5月15日前，将本地区上一年度金融企业分户金融企业国有资本保值增值数据和情况说明报送财政部。"},{"i":16,"n":"第十六条","txt":"金融企业报送国有资本保值增值材料应当真实、完整，填报口径符合有关规定。"},{"i":17,"n":"第十七条","txt":"金融企业负责人应当对本企业报送的国有资本保值增值材料的真实性、完整性负责。"},{"i":18,"n":"第十八条","txt":"财政部收到省级财政部门和中央直接管理的金融企业报送的材料后，应当根据材料测算全国金融企业分行业的保值增值结果确认标准值，并于每年 6月20日前印发省级财政部门和中央直接管理的金融企业。分行业的保值增值结果确认标准值分为优秀、良好、中等、较低、较差5个档次。"},{"i":19,"n":"第十九条","txt":"财政部门收到金融企业报送的材料后，应当按照本办法的有关规定，对材料进行审核，确认国有资本保值增值结果，并根据确认结果、标准值，参考分析指标，确定金融企业国有资本保值增值结果的档次。"},{"i":20,"n":"第二十条","txt":"财政部门应当于每年7月30日前，将金融企业保值增值的确认结果和档次反馈给金融企业及有关部门。"},{"i":21,"n":"第二十一条","txt":"省级财政部门应当于每年8月30日前，将本地区金融企业国有资本保值增值结果确认情况及汇总分析报送财政部。"},{"i":22,"n":"第二十二条","txt":"金融企业对外提供国有资本保值增值结果的，应当以本级财政部门确认的结果为准。"},{"i":23,"n":"第二十三条","txt":"金融企业未按照本办法规定报送国有资本保值增值材料的，由本级财政部门责令限期改正。"},{"i":24,"n":"第二十四条","txt":"金融企业在报送国有资本保值增值材料中，存在故意漏报、瞒报以及提供虚假材料等情况的，由本级财政部门责令限期改正，并给予警告。"},{"i":25,"n":"第二十五条","txt":"会计师事务所及注册会计师出具虚假报告，造成国有资本保值增值结果严重不实的，由财政部门依法进行处理。"},{"i":26,"n":"第二十六条","txt":"财政部门工作人员在国有资本保值增值结果确认过程中滥用职权、玩忽职守、徇私舞弊，或者泄露金融企业商业秘密的，依法给予行政处分。"},{"i":27,"n":"第二十七条","txt":"金融资产管理公司国有资本保值增值结果确认办法另行规定。"},{"i":28,"n":"第二十八条","txt":"省级财政部门可以依照本办法，结合本地区实际情况制订具体实施办法，报财政部备案。"},{"i":29,"n":"第二十九条","txt":"本办法自2007年3月1日起施行。"}],"jinrongqiyecaiwuguize":[{"i":1,"n":"第一条","txt":"为了加强金融企业财务管理，规范金融企业财务行为，促进金融企业法人治理结构的建立和完善，防范金融企业财务风险，保护金融企业及其相关方合法权益，维护社会经济秩序，根据有关法律、行政法规和国务院相关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内依法设立的国有及国有控股金融企业、金融控股公司、担保公司，城市商业银行、农村商业银行、农村合作银行、信用社（以下简称金融企业）适用本规则。其他金融企业参照本规则执行。"},{"i":3,"n":"第三条","txt":"金融企业应当根据本规则的规定，以及自身发展的需要，建立健全内部财务管理制度，设置财务管理职能部门，配备专业财务管理人员，综合运用规划、预测、计划、预算、控制、监督、考核、评价和分析等方法，筹集资金，营运资产，控制成本，分配收益，配置资源，反映经营状况，防范和化解财务风险，实现持续经营和价值最大化。"},{"i":4,"n":"第四条","txt":"各级人民政府财政部门（以下简称财政部门）依法指导、管理和监督本级金融企业的财务管理工作。省级以上人民政府财政部门的派出机构，应当在规定职责范围内依法履行指导、管理和监督金融企业财务管理工作的职责。 金融企业在完成工商登记后30日内，应当向同级财政部门提交设立批准证书、营业执照、验资证明、章程等文件的复印件。 金融企业发生分立、合并、设立分支机构，以及主要工商登记事项发生变更时，在依法完成工商变更登记后30日内，应当向同级财政部门提交有关的变更文件复印件。"},{"i":5,"n":"第五条","txt":"金融企业应当依法纳税。金融企业财务处理与税收法律、行政法规规定不一致的，纳税时应当依法进行调整。"},{"i":6,"n":"第六条","txt":"财政部门履行下列财务管理职责: （一）监督金融企业执行本规则以及其他的财务管理规定，指导、督促金融企业建立健全内部财务管理制度; （二）指导、督促金融企业建立健全财务风险控制体系，监测金融企业财务风险及其营运状况，监督金融企业的财务行为; （三）加强金融企业财务信息管理，实施金融企业财务评价 ; （四）监督金融企业接受社会审计和资产评估; （五）制定并实施促进金融企业改革和发展的财政、财务政策，组织金融企业财务管理人员的业务培训; （六）有关法律、行政法规规定的其他财务管理职责。"},{"i":7,"n":"第七条","txt":"金融企业的投资者（以下简称投资者）一般通过股东（大）会、董事会或者其他形式的治理机构行使下列财务管理职权: （一）执行并督促经营者执行国家有关金融企业财务管理的规定 ; （二）决定内部财务管理制度，明确经营者的财务管理权限 ; （三）决定财务管理职能部门的设置; （四）决定财务计划和财务预算，决定筹资、投资、处置重大资产、依法提供除主营担保业务范围以外的担保、捐赠、重组、经营者报酬、利润分配等重大财务事项; （五）对经营者实施财务监督和财务考核，决定聘任或者解聘财务负责人 ; （六）决定聘用或者解聘承办社会审计和资产评估等业务的社会中介机构 ; （七）按照章程的规定，行使其他财务管理职权。 投资者可以通过制度规范、章程约定等方式，将投资者财务管理职权全部或者部分授予经营者。 金融企业按规定可以向其控股的企业委派或者推荐财务总监。"},{"i":8,"n":"第八条","txt":"金融企业的经营者（以下简称经营者）按照规定行使下列财务管理职权 : （一）执行国家有关金融企业财务管理的规定; （二）拟订内部财务管理制度，经投资者议定后报同级财政部门备案，并具体组织实施 ; （三）组织财务预测，编制财务计划和财务预算草案，实施财务控制、分析和考核 ; （四）组织实施筹资、投资、处置重大资产、担保、捐赠、重组和利润分配等财务管理方案; （五）组织财务事项审批; （六）组织缴纳税金、规费; （七）执行国家有关职工劳动报酬和劳动保护的规定，依法缴纳社会保险费、住房公积金等，保障职工合法权益; （八）归集财务信息，依法组织编制和报送财务会计报告; （九）提请聘任或者解聘财务负责人; （十）配合有关机构依法实施的审计、评估和监督检查; （十一）按照章程的规定，以及股东（大）会或者董事会的要求，行使其他财务管理职权。"},{"i":9,"n":"第九条","txt":"金融企业应当根据本规则的规定，以及内部财务管理制度的要求，建立健全包括识别、计量、监测和控制等内容的财务风险控制体系，明确财务风险管理的权限、程序、应急方案和具体措施，以及财务风险形成当事人应承担的责任，防范和化解财务风险。"},{"i":10,"n":"第十条","txt":"金融企业应当建立规范有效的资本补充机制，保持业务规模与资本规模相适应，在资本充足率、偿付能力等方面满足有关法律、法规的要求。 从事商业银行业务的金融企业，资本充足率不得低于8%，核心资本充足率不得低于 4%;从事保险业务的金融企业，偿付能力充足率不得低于规定的数额;从事证券业务的金融企业，净资本负债率应满足规定的数额要求。"},{"i":11,"n":"第十一条","txt":"金融企业应当按照保障相关各方利益、保证支付能力、实现持续经营的原则，根据有关法律、法规的规定，控制资产负债比例，足额提留用于清偿债务的资金。 从事银行业务的金融企业，应按规定交存存款准备金，留足备付金 ;从事保险业务的金融企业，应按注册资本的 20%提取资本保证金，存入指定银行，除清算时用于清偿债务外，不得动用;从事证券业务的金融企业，负债与净资产的比例应满足规定的数额要求。"},{"i":12,"n":"第十二条","txt":"金融企业应当定期或者至少于每年年终对各类资产进行评价，并逐步实现动态评价，按照规定进行风险分类，对可收回金额低于账面价值的部分，按照国家有关规定计提资产减值准备。 金融企业对计提减值准备的资产，应当落实监管责任。对能够收回或者继续使用的，应当收回或者使用;对已经损失的，应当按照规定的程序核销 ;对已经核销的，应当实行账销案存管理。"},{"i":13,"n":"第十三条","txt":"金融企业应当及时分析市场利率、汇率波动情况，预计可能发生的风险，并按照规定的程序，运用金融衍生工具，减少利率、汇率风险损失。"},{"i":14,"n":"第十四条","txt":"金融企业发生关联交易，必须履行规定的程序，并按照规定控制总量和规模，遵循公开、公平、公正的原则，确定并及时结算资源、劳务或者义务的价款，不得利用关联交易操纵利润、逃避税收。"},{"i":15,"n":"第十五条","txt":"金融企业委托其他机构理财或者从事其他业务，应当进行风险评估，依法签订书面合同，明确业务授权和具体操作程序，定期对账，制定风险防范的具体措施。 金融企业委托其他机构理财或者从事其他业务，投入的资金不得影响主营业务的开展，取得的收入应当纳入账内核算。"},{"i":16,"n":"第十六条","txt":"金融企业依法受托发放贷款、经营衍生产品、进行证券期货交易、买卖黄金、管理资产以及开展其他业务，应当与自营业务分开管理，按照合同约定分配收益、承担责任，不得挪用客户资金，不得转嫁经营风险。"},{"i":17,"n":"第十七条","txt":"金融企业对外提供担保应当符合法律、行政法规的规定，根据被担保对象的资信及偿债能力，采取相应的风险控制措施，并设立备查账簿登记，及时跟踪监督。金融企业提供除主营担保业务范围以外的担保，应当由股东（大）会或者董事会决议 ;为金融企业投资者或者实际控制人提供担保的，应当由股东（大）会决议。"},{"i":18,"n":"第十八条","txt":"金融企业应当根据资本规模控制表外业务总量。金融企业应当按照风险程度对表外业务进行授权，并严格按照授权执行，禁止违规操作。 金融企业应当及时、完整记录所有表外业务，跟踪检查表外业务变动情况，预计可能发生的损失，并按照有关规定进行披露。"},{"i":19,"n":"第十九条","txt":"金融企业设立分支机构，应当按照规定拨付与分支机构经营规模相适应的营运资金，并不得超过规定的限额。 金融企业应当对分支机构实行统一核算，统一调度资金，分级管理的财务管理制度。条 件具备的，可以实行统一核算，统一调度资金，业务单元制管理的财务管理制度。 金融企业应当加强对分支机构的财务监管，关注资金异常变动，监督并跟踪分析分支机构财务指标的情况，督促境外分支机构遵守所在国家（地区）关于金融企业财务管理的规定。"},{"i":20,"n":"第二十条","txt":"金融企业筹集资本金，应当符合国家有关资本金管理的规定，根据发展战略和经营规划拟定筹资方案，履行规定的程序。 金融企业在国家法律、行政法规允许的范围内，可以接受货币出资，也可以接受实物、知识产权、土地使用权等可以用货币估价并可以依法转让的非货币财产出资，或者采取发行股票等方式筹集资本金。 金融企业接受非货币财产出资，应当进行评估作价，核实财产，按照评估确认或者合同约定的价值计价;采取发行股票方式筹集的资本金，按照股票面值计价。 金融企业筹集资本金，应当聘请会计师事务所验资。办理工商登记后，应当向投资者出具出资证明书。"},{"i":21,"n":"第二十一条","txt":"金融企业筹集的资本金，在持续经营期间，投资者除依法进行转让外，不得以任何方式抽走。 金融企业在筹集资本金活动中，投资者缴付的出资额超出资本金的差额（包括发行股票的溢价净收入），计入资本公积。经投资者决议后，资本公积用于转增资本金。"},{"i":22,"n":"第二十二条","txt":"金融企业以借款、吸收存款、发行债券、融资租赁、向人民银行再贷款等方式筹集资金，应当符合国家有关规定，明确筹资目的，考虑资金需求和债务风险，签订书面合同，不得擅自提高或者变相提高利率以及付费标准，并应适时合理调整负债结构，降低筹资成本。"},{"i":23,"n":"第二十三条","txt":"金融企业取得国家投资、财政补助等财政资金，区分以下情况处理 : （一）属于国家直接投资的，按照国家有关规定增加国家资本金或者资本公积 ; （二）属于投资补助的，增加资本公积或者资本金。国家拨款时对权属有规定的，按规定执行。没有规定的，由全体投资者共同享有; （三）属于贷款贴息、专项经费补助的，作为收益处理; （四）属于弥补亏损、救助损失或者其他用途的，作为收益处理 ; （五）属于政府转贷、偿还性资助的，作为负债管理。"},{"i":24,"n":"第二十四条","txt":"金融企业应当统一管理资金账户，明确资金调度的条 件、权限和程序。调度资金应当按照内部财务管理制度，依据有效合同和合法凭证办理手续，不得私存私放资金。 向境外调度资金必须符合国家外汇管理的有关规定，并履行相应的审批程序。"},{"i":25,"n":"第二十五条","txt":"金融企业管理库存现金、库存金银、存放中央银行与同业的款项，以及其他形式的现金资产，应当满足流动性要求，并控制现金资产总量。"},{"i":26,"n":"第二十六条","txt":"金融企业应当按照内部财务管理制度对合同进行财务审核，跟踪履约情况，明确债权，制定收账政策，及时清收应收款项。"},{"i":27,"n":"第二十七条","txt":"金融企业在法律、法规允许的范围内，经股东（大）会或者董事会决议，可以用货币对外投资，也可以用实物、知识产权、土地使用权等可以用货币估价并可以依法转让的非货币财产对外投资，但不得以国家授予的特许经营权对外投资。 用非货币财产对外投资的，应当聘请资产评估机构进行评估并按评估确认后的价值计价。 对外投资应当签订书面合同，明确投资权益，按照内部财务管理制度规定的程序支付投资款项，所需资金纳入财务预算管理，不得在成本费用或者营业外支出中列支，并及时监控和考核投资项目的效益，落实项目决策者和实施者的责任。 向境外投资的，应当符合国家境外投资项目核准和外汇管理等相关规定。"},{"i":28,"n":"第二十八条","txt":"金融企业收取、保管和处置抵债资产，应当按照内部财务管理制度规定的工作程序办理。收取抵债资产应当按照规定确定接收价格，核实产权。 保管抵债资产应当按照安全、完整、有效的原则，及时进行账务处理，定期检查、账实核对。 处置抵债资产应当按照公开、透明的原则，聘请资产评估机构评估作价。一般采用公开拍卖的方式进行处置。采用其他方式的，应当引入竞争机制选择抵债资产买受人。 抵债资产不得转为自用。因客观条 件需要转为自用的，应当履行规定的程序后，纳入相应的资产进行管理。"},{"i":29,"n":"第二十九条","txt":"金融企业应当按照内部财务管理制度规定，定期清查核实各类固定资产，落实使用和管理责任。 购建重要固定资产、实施重大技术改造，应当进行可行性论证，并落实决策和执行责任。 固定资产折旧可以依据产业发展态势和技术进步的要求，结合固定资产经济寿命及其使用状况，确定折旧年限，选用折旧方法，按季（月）计提。固定资产折旧政策一经选用，一般不得变更，确需变更的，应当经股东（大）会或者董事会决议后执行。有关法律、行政法规规定必须披露变更理由的，应当及时披露。 已交付使用而未办理竣工决算的在建工程项目，应当比照固定资产进行管理。 金融企业固定资产账面价值和在建工程账面价值之和占净资产的比重，从事银行业务的最高不得超过40%，从事保险及其他非银行业务的最高不得超过50%。国家另有规定的，从其规定。"},{"i":30,"n":"第三十条","txt":"金融企业通过自创、购买、接受投资等方式取得的商标权、著作权、专利权及专有技术等无形资产，应当依法明确权属，落实经营和管理责任。 变更无形资产权属时应当进行评估，并签订书面合同。"},{"i":31,"n":"第三十一条","txt":"金融企业发生的资产损失，包括信贷资产损失、坏账损失、投资损失、固定资产及在建工程损失等，应当及时核实，查清责任，追偿损失，并按照国家有关规定进行处理。 金融企业以出售、出租、抵押、置换、报废等方式处置资产，应当根据有关法律、法规的规定，履行相应程序。 处置主营业务所用资产，涉及业务调整或者资产重组的，应当根据发展战略和经营规划，制订业务调整或者资产重组方案，履行规定的程序后执行。 金融企业对外捐赠应当符合有关法律、法规的规定，明确捐赠的范围和条 件，落实执行责任，严格办理捐赠资产的交接手续。"},{"i":32,"n":"第三十二条","txt":"金融企业应当结合自身特点，按照内部财务管理制度，强化成本费用预算约束，实行成本费用全员管理和全过程控制。 金融企业的成本费用支出应当按照国家规定纳入账内核算，不得违反规定进行调整。"},{"i":33,"n":"第三十三条","txt":"金融企业在经营过程中发生的与经营有关的支出，包括各项利息支出（含贴息）扣除允许资本化的部分、手续费支出、佣金支出、业务给付支出、业务赔款支出、保护（保障、保险）基金支出、应计入损益的各种准备金和其他有关支出，应当按照国家有关规定计入当期损益。"},{"i":34,"n":"第三十四条","txt":"金融企业的成本核算，应当严格区分本期成本与下期成本的界限、成本支出与营业外支出的界限、收益性支出与资本性支出的界限。 金融企业的成本核算，应当以季（月）、年为计算期。同一计算期内，核算成本和营业收入的起止日期、计算范围和口径应当一致。"},{"i":35,"n":"第三十五条","txt":"金融企业应当注重费用支出与经济效益的配比，实行费用支出的归口、分级管理和预算控制，确定必要的费用支出范围、标准和报销审批程序。 除国家规定的专用账户外，金融企业每一独立核算单位分币种只能设立一个费用存款专户，除税金及附加、折旧、资产摊销、准备金和坏账损失以外的各项费用，应当从费用专户中开支。 金融企业应当强化费用支出约束，对业务宣传费、业务招待费、差旅费、会议费、通讯费、维修费、出国经费、董事会经费、捐赠等实行重点监控。 金融企业的业务宣传费、委托代办手续费、防预费、业务招待费一律按规定据实列支，不得预提。"},{"i":36,"n":"第三十六条","txt":"金融企业技术研发和实施科技成果产业化所需经费应当纳入财务预算，形成的资产应当纳入相应的资产进行管理。"},{"i":37,"n":"第三十七条","txt":"金融企业应当按照国家有关规定，以及与职工签订的劳动合同，核定和计发职工薪酬。 金融企业根据有关法律、法规和政策的规定，经股东（大）会或者董事会决议，可以对经营者、核心技术人员和核心管理人员实行与其他职工不同的薪酬办法。 金融企业经股东（大）会或者董事会决议，可以在工资计划中安排一定数额，对研发核心技术、促进安全营运、开拓市场等作出突出贡献的职工给予奖励。"},{"i":38,"n":"第三十八条","txt":"金融企业根据有关法律、法规和政策的规定，为职工缴纳的基本医疗保险、基本养老保险、失业保险和工伤保险等社会保险费用，应当据实列入成本（费用）。 参加基本医疗保险、基本养老保险且按时足额缴费的金融企业，具有持续盈利能力和支付能力的，可以根据有关法律、法规的规定，为职工建立补充医疗保险和补充养老保险（企业年金）制度，相关费用应当按照国家有关规定列支。"},{"i":39,"n":"第三十九条","txt":"金融企业为职工缴纳住房公积金以及职工住房货币化分配的处理，按照国家有关规定执行。 工会经费按照国家规定的比例提取，拨交工会使用。 职工教育经费按照国家规定的比例提取，用于职工教育和职业培训。"},{"i":40,"n":"第四十条","txt":"金融企业应当依法缴纳行政事业性收费、政府性基金以及使用或者占用国有资源的费用等。 金融企业有权拒绝没有法律、法规和规章依据，或者超过法律、法规和规章规定范围和标准的收费。"},{"i":41,"n":"第四十一条","txt":"金融企业根据经营情况支付必要的佣金、手续费等支出，应当签订合同，明确支出标准和执行责任。除对个人代理人外，不得以现金支付。"},{"i":42,"n":"第四十二条","txt":"金融企业经营业务范围内的各项收入和其他营业收入、营业外收入，应当在依法设置的会计账簿上按照国家有关规定统一登记、核算，不得存放其他单位，或者以任何理由坐支。 投资者、经营者及其他职工履行本单位职务所得收入，包括业务收入以及对方给予的佣金、手续费等，全部属于金融企业，应当纳入账内核算，不得隐匿、转移、私存私放、坐支或者擅自用于职工福利。"},{"i":43,"n":"第四十三条","txt":"金融企业发生年度亏损的，可以用下一年度的税前利润弥补 ;下一年度的税前利润不足以弥补的，可以逐年延续弥补;延续弥补期超过法定税前弥补期限的，可以用缴纳所得税后的利润弥补。"},{"i":44,"n":"第四十四条","txt":"金融企业本年实现净利润（减弥补亏损，下同），应当按照提取法定盈余公积金、提取一般（风险）准备金、向投资者分配利润的顺序进行分配。法律、行政法规另有规定的从其规定。 法定盈余公积金按照本年实现净利润的10%提取，法定盈余公积金累计达到注册资本的 50%时，可不再提取。 从事银行业务的，应当于每年年终根据承担风险和损失的资产余额的一定比例提取一般准备金，用于弥补尚未识别的可能性损失;从事其他业务的，应当按照国家有关规定从本年实现净利润中提取风险准备金，用于补偿风险损失。 以前年度未分配的利润，并入本年实现净利润向投资者分配。其中，股份有限公司按照下列顺序分配: （一）支付优先股股利; （二）提取任意盈余公积金; （三）支付普通股股利; （四）转作资本（股本）。 资本充足率、偿付能力充足率、净资本负债率未达到有关法律、行政法规规定标准的，不得向投资者分配利润。 任意盈余公积金按照公司章程或者"},{"i":45,"n":"第四十五条","txt":"金融企业根据有关法律、法规的规定，经股东（大）会决议，可以对经营者和核心技术人员、核心管理人员实行股权激励。 经营者及其他职工以劳动、技术、管理等要素参与收益分配的，分配办法应当符合有关法律、法规和政策的规定，经股东（大）会决议后，区别以下情况处理: （一）取得股权的，与其他投资者一同分配利润; （二）没有取得股权的，在相关业务实现的利润限额和分配标准内，从当期费用中列支。"},{"i":46,"n":"第四十六条","txt":"金融企业根据有关法律、法规的规定，可以通过分立、合并等方式进行重组。 实施重组应当进行可行性论证，履行规定程序，组织开展财产清查，聘请会计师事务所进行审计、资产评估机构进行资产评估，组织与债权人协商，制订债务处置或者承继、股权设置、资本重组的实施方案。"},{"i":47,"n":"第四十七条","txt":"金融企业分立，应当按照资产相关性或者业务相关性原则分割财产、承担债务，并明确分立后的产权关系。 对不能分割的财产，在评估的基础上，经各方协商，由拥有财产的一方给予其他方经济补偿。"},{"i":48,"n":"第四十八条","txt":"金融企业合并，应当由合并后存续的金融企业或者新设的金融企业承继合并各方的债权、债务，并明确合并后的产权关系。 金融企业合并净资产超出注册资本的部分，作为资本公积;少于注册资本的部分，应当变更注册资本或者由投资者补足出资。 对资不抵债金融企业以承担债务方式合并的，合并方应当采取重整措施，按照合并方案履行偿债义务。"},{"i":49,"n":"第四十九条","txt":"金融企业实行托管经营，应当签订托管经营合同，明确被托管企业的财务状况、托管经营目标、托管财产处置权限以及收益分配办法等，并落实财务监管责任。 受托金融企业应当根据托管经营合同制定相关方案，重组托管金融企业的财产与债务、调整业务、安置职工。 托管经营合同没有约定且未经托管金融企业股东（大）会同意，受托金融企业不得擅自改组、改制、转让托管金融企业，不得非法转移托管金融企业的财产和业务，不得以托管金融企业名义或者以托管财产对外担保。"},{"i":50,"n":"第五十条","txt":"金融企业进行重组时，对已占用的国有划拨土地应当按照有关规定进行评估，履行相关手续后，区别以下情况处理: （一）继续采取划拨方式的，可以不纳入资产管理，但应当明确划拨土地使用权权益，并按规定用途使用，设立备查账簿登记; （二）采取作价入股方式的，将应缴纳的土地出让金转作国家资本，形成的国有股权由重组前的国有资本持有单位或者财政部门确认的单位持有; （三）采取出让方式的，由金融企业购买土地使用权，支付出让费用 ; （四）采取租赁方式的，由金融企业租赁使用，租金水平参照银行同期贷款利率确定，并在租赁合同中约定。 金融企业进行重组时，对已占用的特许经营权等国有资源，依法可以转让的，比照前款处理。"},{"i":51,"n":"第五十一条","txt":"金融企业重组过程中，对拖欠职工的工资和医疗、伤残补助、抚恤费用以及欠缴的基本社会保险费、住房公积金、工会经费等，应当以金融企业现有资产优先清偿。"},{"i":52,"n":"第五十二条","txt":"金融企业被责令关闭、依法破产或者经营期限届满终止经营或者解散的，应当按照国家法律、行政法规和金融企业章程的规定实施清算。 金融企业自愿清算的，由金融企业股东（大）会决议后执行。金融企业依法进行清算，应当对非货币财产进行资产评估。"},{"i":53,"n":"第五十三条","txt":"金融企业的清算财产支付清算费用后，按照国家有关法律、行政法规规定的顺序清偿债务。"},{"i":54,"n":"第五十四条","txt":"金融企业清算完毕，应当编制清算报告，聘用会计师事务所审计，并将清算报告和审计报告报投资者决议或者人民法院确认后，向相关部门、债权人以及其他利益相关人通告。"},{"i":55,"n":"第五十五条","txt":"金融企业与职工解除劳动合同，应当按照国家有关规定支付职工经济补偿金，除正常经营期间发生的列入当期费用以外，应当区别以下情况处理: （一）重组中发生的，依次从未分配利润、盈余公积、资本公积、实收资本中支付 ; （二）清算时发生的，以扣除清算费用后的清算财产优先清偿。"},{"i":56,"n":"第五十六条","txt":"金融企业应当在会计电算化的基础上，整合业务和信息流程，推行财务管理信息化，逐步实现财务、业务相关信息一次性处理和实时共享。第五十七条 金融企业应当根据有关法律、行政法规的规定，以及财政部的统一要求编制中期财务会计报告和年度财务会计报告，并通过内部审核，在规定期限内向财政部门以及其他与金融企业有关的使用者报送，不得拒绝、拖延财务信息的披露。"},{"i":57,"n":"第五十八条","txt":"金融企业报送的年度财务会计报告应当经会计师事务所审计。 金融企业不得编制和对外提供虚假的或者隐瞒重要事实的财务信息。金融企业负责人对本企业财务信息的真实性、完整性负责。"},{"i":58,"n":"第五十九条","txt":"财政部门应当建立健全金融企业财务评价制度，对金融企业资本充足状况、偿付能力状况、资产质量状况、盈利状况和社会贡献等进行评价。评价结果作为制定有关金融企业财务管理政策和考核有关金融企业的依据。 金融企业应当按财务评价制度的要求，对财务状况和经营成果进行总结、评价和考核。"},{"i":59,"n":"第六十条","txt":"财政部门及其工作人员应当履行保密义务，谨慎、合法地保管、使用金融企业提供的财务信息，不得利用未公开的财务信息牟取利益或者损害金融企业利益。"},{"i":60,"n":"第六十一条","txt":"金融企业有下列情形之一的，由财政部门责令限期改正，或者予以通报批评 : （一）不按规定提交设立、变更文件的; （二）财务风险控制未达到规定要求的; （三）筹集和运用资金不符合规定要求的; （四）不按规定开设和管理资金账户的; （五）资产管理不符合规定，形成账外资产的; （六）不按规定列支经营成本、费用的; （七）不按规定确认经营收益的; （八）不按规定计提减值准备、提留准备金、分配利润的; （九）不按规定处理财政资金、国有资源的; （十）不按规定顺序清偿债务、处理财产的; （十一）不按规定处理职工社会保险费、经济补偿金的; （十二）其他违反金融企业财务管理有关规定的。"},{"i":61,"n":"第六十二条","txt":"金融企业有下列情形之一的，由财政部门责令限期改正，并对金融企业及其负责人和其他直接责任人员给予警告: （一）不按照规定建立内部财务管理制度的; （二）内部财务管理制度明显与国家法律、法规和统一的财务管理规章制度相抵触，且不按财政部门要求修改的; （三）不按照规定提供财务信息的; （四）拒绝、阻扰依法实施的财务监督的。"},{"i":62,"n":"第六十三条","txt":"金融企业违反本规则，有关法律、法规另有规定的，依照其规定处理、处罚。 财政部门在依法实施财务监督中，对不属于本部门职责范围的事项，应当依法移送相关管理部门。"},{"i":63,"n":"第六十四条","txt":"财政部门工作人员在履行财务管理职责过程中滥用职权、玩忽职守、徇私舞弊，或者泄露国家秘密、商业秘密的，依法进行处理。"},{"i":64,"n":"第六十五条","txt":"各省、自治区、直辖市、计划单列市财政部门可以依据本规则和财政部的其他规定，结合本地区金融企业实际，制订具体的实施办法，报财政部备案。"},{"i":65,"n":"第六十六条","txt":"本规则自2007年1月1日起施行，《金融保险企业财务制度》（（93）财商字第11号）、《保险公司财务制度》（财债字［1999］8号）、《证券公司财务制度》（财债字［1999］215号）、《金融资产管理公司财务制度（试行）》（财金［2000］17号）同时废止。"}]};
